static void nativeUiSetFrameTimerInterval(
  HWND hwnd,
  UINT intervalMs)
{
  if (!hwnd) return;
  intervalMs = std::max<UINT>(1, intervalMs);
  if (g_nativeUiFrameTimerIntervalMs == intervalMs) return;
  KillTimer(hwnd, kNativeUiFrameTimerId);
  SetTimer(hwnd, kNativeUiFrameTimerId, intervalMs, nullptr);
  g_nativeUiFrameTimerIntervalMs = intervalMs;
}
