#ifdef _WIN32
using native_socket_t = SOCKET;
static const native_socket_t kInvalidNativeSocket = INVALID_SOCKET;
static void nativeCloseSocket(native_socket_t s) { if (s != INVALID_SOCKET) closesocket(s); }
static void nativeShutdownSocket(native_socket_t s) { if (s != INVALID_SOCKET) shutdown(s, SD_BOTH); }
#else
using native_socket_t = int;
static const native_socket_t kInvalidNativeSocket = -1;
static void nativeCloseSocket(native_socket_t s) { if (s >= 0) close(s); }
static void nativeShutdownSocket(native_socket_t s) { if (s >= 0) shutdown(s, SHUT_RDWR); }
#endif

static void nativeConfigureClientSocketTimeouts(native_socket_t socketHandle)
{
#ifdef _WIN32
  const DWORD receiveTimeoutMs = 1000;
  const DWORD sendTimeoutMs = 3500;
  setsockopt(socketHandle, SOL_SOCKET, SO_RCVTIMEO,
    reinterpret_cast<const char*>(&receiveTimeoutMs),
    sizeof(receiveTimeoutMs));
  setsockopt(socketHandle, SOL_SOCKET, SO_SNDTIMEO,
    reinterpret_cast<const char*>(&sendTimeoutMs),
    sizeof(sendTimeoutMs));
#else
  timeval receiveTimeout{};
  receiveTimeout.tv_sec = 1;
  timeval sendTimeout{};
  sendTimeout.tv_sec = 3;
  sendTimeout.tv_usec = 500000;
  setsockopt(
    socketHandle, SOL_SOCKET, SO_RCVTIMEO,
    &receiveTimeout, sizeof(receiveTimeout));
  setsockopt(
    socketHandle, SOL_SOCKET, SO_SNDTIMEO,
    &sendTimeout, sizeof(sendTimeout));
#ifdef __APPLE__
  // Evita que um cliente que feche a conexão durante uma resposta grande
  // derrube o processo do REAPER com SIGPIPE.
  const int noSigPipe = 1;
  setsockopt(
    socketHandle, SOL_SOCKET, SO_NOSIGPIPE,
    &noSigPipe, sizeof(noSigPipe));
#endif
#endif
}

static std::atomic<bool> g_nativeRunning{false};

static bool nativeSendAll(
  native_socket_t socketHandle,
  const char* data,
  size_t size)
{
  if (socketHandle == kInvalidNativeSocket || !data) return false;
  size_t sentTotal = 0;
#ifndef _WIN32
  const auto sendDeadline =
    std::chrono::steady_clock::now() +
    std::chrono::milliseconds(4000);
#endif
  while (sentTotal < size && g_nativeRunning.load()) {
#ifdef _WIN32
    const int remaining = static_cast<int>(std::min<size_t>(
      size - sentTotal,
      static_cast<size_t>(std::numeric_limits<int>::max())));
    const int sent = send(
      socketHandle, data + sentTotal, remaining, 0);
    if (sent == SOCKET_ERROR || sent <= 0) return false;
#else
    const ssize_t sent = send(
      socketHandle, data + sentTotal, size - sentTotal, 0);
    if (sent < 0 && errno == EINTR) continue;
    if (sent < 0 &&
        (errno == EAGAIN || errno == EWOULDBLOCK) &&
        std::chrono::steady_clock::now() < sendDeadline) {
      std::this_thread::sleep_for(std::chrono::milliseconds(2));
      continue;
    }
    if (sent <= 0) return false;
#endif
    sentTotal += static_cast<size_t>(sent);
  }
  return sentTotal == size;
}

static std::mutex g_nativeMutex;
static std::mutex g_nativeServerMutex;
static std::thread g_nativeThread;
static native_socket_t g_nativeServerSocket = kInvalidNativeSocket;
static native_socket_t g_nativeActiveClientSocket = kInvalidNativeSocket;
static std::string g_nativeStateJson;
static std::string g_nativeSnapshotSignature;
static std::string g_nativeLuaLiveFragment;
static std::deque<std::string> g_nativeCommandQueue;
// A thread HTTP nunca pode chamar a API do REAPER. Ela apenas deposita os
// comandos aqui; o startupTimer consome a fila na thread principal.
static std::deque<std::string> g_nativeHttpCommandQueue;
static std::deque<std::string> g_nativeTunerCommandQueue;
static std::vector<std::string> g_nativeCommandHistory;
static uint64_t g_nativeCommandSequence = 0;

struct NativeTimecodeLanEvent {
  uint64_t sequence = 0;
  int64_t createdAtMs = 0;
  std::string command;
};

struct NativeTimecodeLanTransport {
  uint64_t sequence = 0;
  // Sobe somente quando o transporte/cursor muda por uma acao local. A Hook
  // Center usa esta revisao para transferir a autoridade do Project Sync sem
  // deixar os dois computadores corrigirem o relogio um do outro.
  uint64_t controlSequence = 0;
  int playState = 0;
  double position = 0.0;
  int64_t sampledAtMs = 0;
  double frameRate = 30.0;
  bool dropFrame = false;
  // Estado do dispositivo de audio, separado do transporte. Se a interface
  // cair, o REAPER pode mudar sozinho de Play para Stop; esse Stop tecnico
  // nao e uma intencao do operador e nao deve parar o PC B/SW8.
  bool audioHealthy = true;
};

// O MTC e emitido somente para uma porta MIDI que ja exista. A extensao nunca
// cria nem remove endpoints: no Windows eles continuam sendo administrados
// pelo Hook MIDI e no macOS pelo Driver IAC. O timer principal mantem a API do
// REAPER na thread correta e distribui os quarter-frames pela porta escolhida.
struct NativeMtcBridgeState {
  bool requested = false;
  bool playing = false;
  bool paused = false;
  double anchorPosition = 0.0;
  std::chrono::steady_clock::time_point anchorAt;
  double frameRate = 30.0;
  bool dropFrame = false;
  int quarterFrameIndex = 0;
  double quarterFrameBudget = 0.0;
  std::chrono::steady_clock::time_point lastTick;
  std::chrono::steady_clock::time_point lastPacketAt;
  std::chrono::steady_clock::time_point nextDeviceScan;
  int outputDevice = -1;
  std::string outputName;
  std::string activeSource;
};

// O relogio de parede dos dois computadores pode ter qualquer diferenca. Para
// estimar somente a idade de cada pulso, o receptor aprende o menor offset de
// chegada observado na sessao. Assim uma amostra de transporte repetida por
// alguns ciclos e extrapolada ate o instante atual, em vez de parecer um drift
// e provocar seeks periodicos durante um Play perfeitamente sincronizado.
struct NativeTimecodeLanRemoteClock {
  bool valid = false;
  bool transportStateValid = false;
  int64_t minimumArrivalOffsetMs = 0;
  int64_t minimumWindowStartedAtMs = 0;
  int64_t lastSampledAtMs = 0;
  uint64_t lastSequence = 0;
  uint64_t lastControlSequence = 0;
  int lastPlayState = 0;
};

