  g_nativeManualStopFadeoutLastCancelAt;

static void nativeUiReadManualStopFadeoutVisualState(
  bool& active,
  bool& restorePending,
  double& progress,
  double& durationSec)
{
  std::lock_guard<std::mutex> lock(
    g_nativeManualStopFadeoutMutex);
  active = g_nativeManualStopFadeoutRuntime.active;
  restorePending =
    g_nativeManualStopFadeoutRuntime.restorePending;
  durationSec = std::max(0.05,
    g_nativeManualStopFadeoutRuntime.durationSec);
  progress = g_nativeManualStopFadeoutRuntime.progress;
  if (active) {
    // O motor atualiza os volumes no timer principal da extensão. Para a barra
    // não repetir a mesma largura entre dois ciclos e depois saltar, a animação
    // visual acompanha diretamente o relógio contínuo iniciado pelo Fadeout.
    const double visualElapsed =
      std::chrono::duration<double>(
        std::chrono::steady_clock::now() -
        g_nativeManualStopFadeoutRuntime.startedAt).count();
    progress = std::max(progress,
      visualElapsed / durationSec);
  }
  progress = std::max(0.0, std::min(1.0, progress));
}

static void nativeProjectSyncScheduleMissingPeaks(int delayMs = 180)
{
  if (!Main_OnCommand_ptr) return;
  g_nativeProjectSyncMissingPeaksPending = true;
  g_nativeProjectSyncMissingPeaksDueAtMs =
    nativeSteadyNowMs() + std::max(0, delayMs);
}

static void nativeProjectSyncProcessMissingPeaksOnMainThread()
{
  if (!g_nativeProjectSyncMissingPeaksPending || !Main_OnCommand_ptr ||
      nativeSteadyNowMs() < g_nativeProjectSyncMissingPeaksDueAtMs) {
    return;
  }
  g_nativeProjectSyncMissingPeaksPending = false;
  g_nativeProjectSyncMissingPeaksDueAtMs = 0;
  // REAPER action 40047: Build any missing peaks. Ela preserva selecao e
  // agenda somente peaks ausentes; os que ja existem nao sao reconstruidos.
  Main_OnCommand_ptr(40047, 0);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
}

