static std::string nativeLower(std::string value)
{
  std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
  return value;
}

static std::string nativeJsonExtractString(const std::string& json, const std::string& key)
{
  const std::string pat = std::string("\"") + key + "\"";
  size_t p = json.find(pat);
  if (p == std::string::npos) return std::string();
  p = json.find(':', p + pat.size());
  if (p == std::string::npos) return std::string();
  ++p;
  while (p < json.size() && (json[p] == ' ' || json[p] == '\t' || json[p] == '\r' || json[p] == '\n')) ++p;
  if (p >= json.size()) return std::string();
  if (json[p] == '"') {
    ++p;
    std::string out;
    while (p < json.size()) {
      char c = json[p++];
      if (c == '"') break;
      if (c == '\\' && p < json.size()) {
        char n = json[p++];
        if (n == 'n') out += '\n';
        else if (n == 'r') out += '\r';
        else if (n == 't') out += '\t';
        else out += n;
      } else out += c;
    }
    return out;
  }
  size_t e = p;
  while (e < json.size() && json[e] != ',' && json[e] != '}' && json[e] != ']' && json[e] != '\r' && json[e] != '\n') ++e;
  return nativeTrim(json.substr(p, e - p));
}

// Unlike nativeJsonExtractString(), this preserves an object/array as JSON.
// Project Sync uses it for the structured diff returned by Hook Center.
static std::string nativeJsonExtractRawValue(
  const std::string& json,
  const std::string& key)
{
  const std::string pattern = std::string("\"") + key + "\"";
  size_t position = json.find(pattern);
  if (position == std::string::npos) return {};
  position = json.find(':', position + pattern.size());
  if (position == std::string::npos) return {};
  ++position;
  while (position < json.size() &&
         std::isspace(static_cast<unsigned char>(json[position]))) {
    ++position;
  }
  if (position >= json.size()) return {};
  const size_t start = position;
  if (json[position] == '"') {
    bool escaped = false;
    for (++position; position < json.size(); ++position) {
      const char value = json[position];
      if (escaped) {
        escaped = false;
      } else if (value == '\\') {
        escaped = true;
      } else if (value == '"') {
        return json.substr(start, position - start + 1);
      }
    }
    return {};
  }
  if (json[position] == '{' || json[position] == '[') {
    const char opening = json[position];
    const char closing = opening == '{' ? '}' : ']';
    int depth = 0;
    bool inString = false;
    bool escaped = false;
    for (; position < json.size(); ++position) {
      const char value = json[position];
      if (inString) {
        if (escaped) escaped = false;
        else if (value == '\\') escaped = true;
        else if (value == '"') inString = false;
        continue;
      }
      if (value == '"') {
        inString = true;
      } else if (value == opening) {
        ++depth;
      } else if (value == closing && --depth == 0) {
        return json.substr(start, position - start + 1);
      }
    }
    return {};
  }
  while (position < json.size() && json[position] != ',' &&
         json[position] != '}' && json[position] != ']') {
    ++position;
  }
  return nativeTrim(json.substr(start, position - start));
}

static void nativeTimecodeLanMarkPendingTransportIntent(int command)
{
  if (command != kReaperTransportPlayCommandId &&
      command != kReaperTransportPauseCommandId &&
      command != kReaperTransportStopCommandId &&
      command != kReaperTransportPlayStopCommandId &&
      command != kReaperTransportRecordCommandId) {
    return;
  }
  // Main_OnCommand executado por um pacote recebido tambem atravessa os hooks
  // do REAPER. Ele nao e um gesto local e jamais pode criar nova autoridade.
  if (g_nativeApplyingTimecodeLanRemoteCommand) return;
  const auto now = std::chrono::steady_clock::now();
  // hookcommand e hookcommand2 podem observar a mesma action. Conserva o
  // estado anterior capturado pelo primeiro hook em vez de arma-la duas vezes.
  if (g_nativeTimecodeLanPendingTransportIntent.command == command &&
      g_nativeTimecodeLanPendingTransportIntent.markedAt
        .time_since_epoch().count() != 0 &&
      std::chrono::duration_cast<std::chrono::milliseconds>(
        now - g_nativeTimecodeLanPendingTransportIntent.markedAt).count()
        <= 20) {
    return;
  }
  ReaProject* project = getCurrentProject(nullptr, 0);
  const int playState = GetPlayStateEx_ptr && project
    ? GetPlayStateEx_ptr(project) : 0;
  const double position = playState != 0
    ? (GetPlayPositionEx_ptr && project
        ? GetPlayPositionEx_ptr(project) : 0.0)
    : (GetCursorPositionEx_ptr && project
        ? GetCursorPositionEx_ptr(project) : 0.0);
  g_nativeTimecodeLanPendingTransportIntent.command = command;
  g_nativeTimecodeLanPendingTransportIntent.beforePlayState = playState;
  g_nativeTimecodeLanPendingTransportIntent.beforePosition = position;
  g_nativeTimecodeLanPendingTransportIntent.markedAt = now;
  g_nativeTimecodeLanPendingTransportIntent.expiresAt =
    now + std::chrono::milliseconds(900);
}

static int64_t nativeSystemNowMs()
{
  return std::chrono::duration_cast<std::chrono::milliseconds>(
    std::chrono::system_clock::now().time_since_epoch()).count();
}

static const std::string& nativeTimecodeLanSessionId()
{
  // Muda a cada carga da DLL. A Hook Center usa este ID para nunca comparar a
  // sequencia de uma instancia nova com ACKs guardados da instancia anterior.
  static const std::string sessionId = []() {
    const uint64_t seed =
      static_cast<uint64_t>(
        std::chrono::high_resolution_clock::now()
          .time_since_epoch().count()) ^
      static_cast<uint64_t>(reinterpret_cast<std::uintptr_t>(
        &g_nativeTimecodeLanMutex));
    std::mt19937_64 random(seed);
    std::ostringstream value;
    value << std::hex << nativeSystemNowMs() << '-'
          << static_cast<unsigned long long>(random()) << '-'
          << static_cast<unsigned long long>(random());
    return value.str();
  }();
  return sessionId;
}

static bool nativeTimecodeLanCodeIsValid(const std::string& value)
{
  return value.size() == 6 &&
    std::all_of(value.begin(), value.end(),
      [](unsigned char character) {
        return character >= '0' && character <= '9';
      });
}

static void nativeTimecodeLanRefreshConfigOnMainThread()
{
  std::string mode = getTimecodeMode();
  std::string projectSyncRole = getProjectSyncRole();
  std::string code;
  std::string selectedPeerId;
  std::string rejectedPeerId;
  if (GetExtState_ptr) {
    const char* raw = GetExtState_ptr(
      kExtStateSection, kTimecodePairCodeKey);
    code = raw ? raw : "";
    const char* selectedRaw = GetExtState_ptr(
      kExtStateSection, kTimecodeSelectedPeerKey);
    const char* rejectedRaw = GetExtState_ptr(
      kExtStateSection, kTimecodeRejectedPeerKey);
    selectedPeerId = selectedRaw ? nativeTrim(selectedRaw) : "";
    rejectedPeerId = rejectedRaw ? nativeTrim(rejectedRaw) : "";
  }
  if (!nativeTimecodeLanCodeIsValid(code)) {
    mode.clear();
    code.clear();
    projectSyncRole.clear();
    selectedPeerId.clear();
    rejectedPeerId.clear();
  }
  if (mode != "project_sync") {
    projectSyncRole.clear();
  }
  if (mode.empty()) {
    selectedPeerId.clear();
    rejectedPeerId.clear();
  }
  std::string parallelMode;
  std::string parallelCode;
  std::string parallelSelectedPeerId;
  std::string parallelRejectedPeerId;
  if (GetExtState_ptr) {
    const char* rawMode = GetExtState_ptr(
      kExtStateSection, kParallelTimecodeModeKey);
    const char* rawCode = GetExtState_ptr(
      kExtStateSection, kParallelTimecodePairCodeKey);
    parallelMode = rawMode ? nativeLower(nativeTrim(rawMode)) : "";
    parallelCode = rawCode ? nativeTrim(rawCode) : "";
    const char* selectedRaw = GetExtState_ptr(
      kExtStateSection, kParallelTimecodeSelectedPeerKey);
    const char* rejectedRaw = GetExtState_ptr(
      kExtStateSection, kParallelTimecodeRejectedPeerKey);
    parallelSelectedPeerId = selectedRaw
      ? nativeTrim(selectedRaw) : "";
    parallelRejectedPeerId = rejectedRaw
      ? nativeTrim(rejectedRaw) : "";
  }
  if (parallelMode != "receive" && parallelMode != "transmitter") {
    parallelMode.clear();
  }
  if (!nativeTimecodeLanCodeIsValid(parallelCode)) {
    parallelMode.clear();
    parallelCode.clear();
    parallelSelectedPeerId.clear();
    parallelRejectedPeerId.clear();
  }
  if (parallelMode.empty()) {
    parallelSelectedPeerId.clear();
    parallelRejectedPeerId.clear();
  }
  // PC A e PC B podem manter um segundo canal como Transmitter para o PC C.
  // O switch do C prioriza A e usa B somente na falha, sem misturar dois MTCs.
  if (mode == "project_sync" &&
      ((projectSyncRole != "primary" &&
        projectSyncRole != "secondary") ||
       parallelMode != "transmitter")) {
    const bool hadInvalidParallel =
      !parallelMode.empty() || !parallelCode.empty();
    parallelMode.clear();
    parallelCode.clear();
    parallelSelectedPeerId.clear();
    parallelRejectedPeerId.clear();
    if (hadInvalidParallel && SetExtState_ptr) {
      SetExtState_ptr(kExtStateSection,
        kParallelTimecodeModeKey, "", true);
      SetExtState_ptr(kExtStateSection,
        kParallelTimecodePairCodeKey, "", true);
      SetExtState_ptr(kExtStateSection,
        kParallelTimecodeSelectedPeerKey, "", true);
      SetExtState_ptr(kExtStateSection,
        kParallelTimecodeRejectedPeerKey, "", true);
    }
  }

  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  const bool mainTopologyChanged = mode != g_nativeTimecodeLanMode ||
    code != g_nativeTimecodeLanCode ||
    projectSyncRole != g_nativeTimecodeLanProjectSyncRole;
  const bool mainSelectionChanged =
    selectedPeerId != g_nativeTimecodeLanSelectedPeerId ||
    rejectedPeerId != g_nativeTimecodeLanRejectedPeerId;
  const bool parallelTopologyChanged =
    parallelMode != g_nativeParallelTimecodeMode ||
    parallelCode != g_nativeParallelTimecodeCode;
  const bool parallelSelectionChanged =
    parallelSelectedPeerId !=
      g_nativeParallelTimecodeSelectedPeerId ||
    parallelRejectedPeerId !=
      g_nativeParallelTimecodeRejectedPeerId;
  const bool mainChanged =
    mainTopologyChanged || mainSelectionChanged;
  const bool parallelChanged =
    parallelTopologyChanged || parallelSelectionChanged;
  if (!mainChanged && !parallelChanged) {
    return;
  }
  if (parallelChanged) {
    g_nativeParallelTimecodeMode = parallelMode;
    g_nativeParallelTimecodeCode = parallelCode;
    g_nativeParallelTimecodeSelectedPeerId =
      parallelSelectedPeerId;
    g_nativeParallelTimecodeRejectedPeerId =
      parallelRejectedPeerId;
    if (parallelTopologyChanged) {
      g_nativeParallelTimecodePeerConnected = false;
      g_nativeParallelTimecodePeerName.clear();
      g_nativeParallelTimecodeLanOutbox.clear();
      g_nativeParallelTimecodeLanEventSequence = 0;
      g_nativeParallelTimecodeLanRemoteClock =
        NativeTimecodeLanRemoteClock{};
    }
  }
  if (!mainChanged) return;
  g_nativeTimecodeLanMode = mode;
  g_nativeTimecodeLanCode = code;
  g_nativeTimecodeLanProjectSyncRole = projectSyncRole;
  g_nativeTimecodeLanSelectedPeerId = selectedPeerId;
  g_nativeTimecodeLanRejectedPeerId = rejectedPeerId;
  if (!mainTopologyChanged) return;
  g_nativeTimecodeLanPeerConnected = false;
  g_nativeTimecodeLanPeerName.clear();
  g_nativeTimecodeLanOutbox.clear();
  g_nativeTimecodeLanRemoteClock = NativeTimecodeLanRemoteClock{};
  g_nativeTimecodeLanEditCursorProject = nullptr;
  g_nativeTimecodeLanEditCursorBaseline = 0.0;
  g_nativeTimecodeLanEditCursorBaselineValid = false;
  g_nativeTimecodeLanEditCursorSequence = 0;
  g_nativeTimecodeLanLastPublishedProjectSignature.clear();
  g_nativeTimecodeLanSuppressedRemoteProjectSignature.clear();
  g_lastCursorMoveSeq.store(0);
  g_nativePendingTransportEditCursorProject = nullptr;
  g_nativePendingTransportEditCursorPosition = 0.0;
  g_nativePendingTransportEditCursorRestorePasses = 0;
  g_nativeRemoteSemanticSeekSuppressUntil =
    std::chrono::steady_clock::time_point{};
  g_nativeProjectSyncTrackBaseline.clear();
  g_nativeProjectSyncTrackProject = nullptr;
  g_nativeProjectSyncTrackMode.clear();
  g_nativeProjectSyncPublishInitialTrackSnapshot = false;
  g_nativeProjectSyncLastTrackPoll =
    std::chrono::steady_clock::time_point{};
  g_nativeProjectSyncLiveTrackBaseline.clear();
  g_nativeProjectSyncLiveItemBaseline.clear();
  g_nativeProjectSyncLiveProject = nullptr;
  g_nativeProjectSyncLiveChangeCount = -1;
  g_nativeProjectSyncPublishInitialLiveSnapshot = false;
  g_nativeProjectSyncPublishInitialPlaylistSnapshot = false;
  g_nativeProjectSyncLiveRevision = 0;
  g_nativeProjectSyncLiveAppliedRevisions.clear();
  g_nativeProjectSyncLastLivePoll =
    std::chrono::steady_clock::time_point{};
  g_nativeProjectSyncViewportBaseline = NativeProjectSyncViewportState{};
  g_nativeProjectSyncViewportProject = nullptr;
  g_nativeProjectSyncLastViewportPoll =
    std::chrono::steady_clock::time_point{};
  g_nativeProjectSyncViewportSuppressUntil =
    std::chrono::steady_clock::time_point{};
  g_nativeProjectSyncTimelineBaselineHash.clear();
  g_nativeProjectSyncPreflight = NativeProjectSyncPreflightState{};
  g_nativeProjectSyncBundle = NativeProjectSyncBundleState{};
  g_nativeProjectSyncApply = NativeProjectSyncApplyState{};
  g_nativeProjectSyncQueuedAutomaticPlan.clear();
  g_nativeProjectSyncQueuedAutomaticRevision.clear();
  g_nativeProjectSyncPendingOpen = NativeProjectSyncPendingOpen{};
  g_nativeProjectSyncPendingPrepareConfirmation =
    NativeProjectSyncPendingPrepareConfirmation{};
  g_nativeProjectSyncPendingBundleReady =
    NativeProjectSyncPendingBundleReady{};
  g_nativeProjectSyncConfigurationAuthorized = false;
  g_nativeProjectSyncStructuralManifest.clear();
  g_nativeProjectSyncManifestProject = nullptr;
  g_nativeProjectSyncManifestChangeCount = -1;
  g_nativeProjectSyncManifestProjectSignature.clear();
  g_nativeProjectSyncLastPublishedConfigRevision.clear();
  g_nativeProjectSyncLastAppliedConfigRevision.clear();
  g_nativeProjectSyncPublishInitialConfig =
    mode == "project_sync" && projectSyncRole == "primary";
  g_nativeProjectSyncLastManifestRefresh =
    std::chrono::steady_clock::time_point{};
  g_nativeProjectSyncMissingPeaksPending = false;
  g_nativeProjectSyncMissingPeaksDueAtMs = 0;
  g_nativeTimecodeLanPendingTransportIntent =
    NativeTimecodeLanPendingTransportIntent{};
  if (mode != "transmitter" && mode != "project_sync") {
    g_nativeTimecodeLanEventSequence = 0;
  }
}

static void nativeTimecodeLanRecordCommand(
  const std::string& commandBody)
{
  if (commandBody.empty() || commandBody.size() > 512 * 1024) return;
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  if (g_nativeApplyingTimecodeLanRemoteCommand ||
      (g_nativeTimecodeLanMode != "transmitter" &&
       g_nativeTimecodeLanMode != "project_sync") ||
      (g_nativeTimecodeLanMode == "project_sync" &&
       g_nativeTimecodeLanProjectSyncRole != "primary")) return;

  // Volumes e drag no grid podem produzir dezenas de valores por segundo.
  // Conserva somente o estado absoluto mais novo por entidade; a sequencia
  // nova permanece monotona, portanto retry/ACK nunca transforma um valor
  // antigo no estado final.
  const std::string commandType = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "type")));
  const bool liveItemCommand =
    commandType == "project_sync_live_item_state" ||
    commandType == "project_sync_live_item_upsert" ||
    commandType == "project_sync_live_item_delete";
  const bool liveTrackCommand =
    commandType == "project_sync_live_track_upsert" ||
    commandType == "project_sync_live_track_delete";
  const bool liveSingletonCommand =
    commandType == "project_sync_live_timeline" ||
    commandType == "project_sync_viewport_v1" ||
    commandType == "project_sync_live_resync";
  const bool semanticSingletonCommand =
    commandType == "playlist_snapshot_sync" ||
    commandType == "ui_music_selection_snapshot";
  if (commandType == "project_sync_track_state" ||
      commandType == "project_sync_config_snapshot" ||
      liveItemCommand || liveTrackCommand || liveSingletonCommand ||
      semanticSingletonCommand) {
    const std::string trackId = nativeTrim(
      nativeJsonExtractString(commandBody, "trackId"));
    const std::string itemId = nativeTrim(
      nativeJsonExtractString(commandBody, "itemId"));
    if (commandType == "project_sync_config_snapshot" ||
        liveSingletonCommand || semanticSingletonCommand ||
        !trackId.empty() || !itemId.empty()) {
      g_nativeTimecodeLanOutbox.erase(
        std::remove_if(
          g_nativeTimecodeLanOutbox.begin(),
          g_nativeTimecodeLanOutbox.end(),
          [&](const NativeTimecodeLanEvent& pending) {
            const std::string pendingType = nativeLower(nativeTrim(
              nativeJsonExtractString(pending.command, "type")));
            if (commandType == "project_sync_config_snapshot") {
              return pendingType == commandType;
            }
            if (liveSingletonCommand || semanticSingletonCommand) {
              return pendingType == commandType;
            }
            const std::string pendingTrackId = nativeTrim(
              nativeJsonExtractString(pending.command, "trackId"));
            const std::string pendingItemId = nativeTrim(
              nativeJsonExtractString(pending.command, "itemId"));
            if (commandType == "project_sync_track_state") {
              return pendingType == commandType &&
                pendingTrackId == trackId;
            }
            if (liveItemCommand && pendingItemId == itemId) {
              if (commandType == "project_sync_live_item_state") {
                return pendingType == commandType;
              }
              return pendingType == "project_sync_live_item_state" ||
                pendingType == "project_sync_live_item_upsert" ||
                pendingType == "project_sync_live_item_delete";
            }
            if (liveTrackCommand && pendingTrackId == trackId) {
              if (commandType == "project_sync_live_track_delete" &&
                  pendingType == "project_sync_track_state") {
                return true;
              }
              return pendingType == "project_sync_live_track_upsert" ||
                pendingType == "project_sync_live_track_delete";
            }
            return false;
          }),
        g_nativeTimecodeLanOutbox.end());
    }
  }

  // O mesmo comando pode passar pelo despachante HTTP e pela função nativa
  // específica no mesmo ciclo. Não publica a cópia idêntica duas vezes.
  if (!g_nativeTimecodeLanOutbox.empty()) {
    const NativeTimecodeLanEvent& previous =
      g_nativeTimecodeLanOutbox.back();
    if (previous.command == commandBody &&
        nativeSystemNowMs() - previous.createdAtMs <= 15) {
      return;
    }
  }

  const int64_t createdAtMs = nativeSystemNowMs();
  NativeTimecodeLanEvent event;
  event.sequence = ++g_nativeTimecodeLanEventSequence;
  event.createdAtMs = createdAtMs;
  event.command = commandBody;
  if (g_nativeTimecodeLanOutbox.size() >= 4096) {
    g_nativeTimecodeLanOutbox.pop_front();
  }
  g_nativeTimecodeLanOutbox.push_back(std::move(event));

  // No PC A, o canal paralelo alimenta o terceiro computador (PC C). Comandos
  // internos de replicacao estrutural pertencem exclusivamente ao Project
  // Sync A -> B; as acoes de operacao do VS Hook seguem para ambos.
  const bool semanticCommandForParallel =
    commandType.rfind("project_sync_", 0) != 0 &&
    commandType != "timecode_peer_status" &&
    commandType != "timecode_transport_sync";
  if (g_nativeParallelTimecodeMode == "transmitter" &&
      semanticCommandForParallel) {
    if (semanticSingletonCommand) {
      g_nativeParallelTimecodeLanOutbox.erase(
        std::remove_if(
          g_nativeParallelTimecodeLanOutbox.begin(),
          g_nativeParallelTimecodeLanOutbox.end(),
          [&](const NativeTimecodeLanEvent& pending) {
            return nativeLower(nativeTrim(nativeJsonExtractString(
              pending.command, "type"))) == commandType;
          }),
        g_nativeParallelTimecodeLanOutbox.end());
    }
    if (!g_nativeParallelTimecodeLanOutbox.empty()) {
      const NativeTimecodeLanEvent& previous =
        g_nativeParallelTimecodeLanOutbox.back();
      if (previous.command == commandBody &&
          createdAtMs - previous.createdAtMs <= 15) {
        return;
      }
    }
    NativeTimecodeLanEvent parallelEvent;
    parallelEvent.sequence =
      ++g_nativeParallelTimecodeLanEventSequence;
    parallelEvent.createdAtMs = createdAtMs;
    parallelEvent.command = commandBody;
    if (g_nativeParallelTimecodeLanOutbox.size() >= 4096) {
      g_nativeParallelTimecodeLanOutbox.pop_front();
    }
    g_nativeParallelTimecodeLanOutbox.push_back(
      std::move(parallelEvent));
  }
}

static bool nativeTimecodeLanAudioDeviceHealthy()
{
  // Em uma versao de transicao que nao exponha essas APIs, conserva o
  // comportamento anterior. No REAPER 7.65+ ambas estao disponiveis.
  if (!Audio_IsRunning_ptr && !GetAudioDeviceInfo_ptr) return true;
  if (Audio_IsRunning_ptr && Audio_IsRunning_ptr() == 0) return false;
  if (GetAudioDeviceInfo_ptr) {
    char mode[128] = "";
    if (!GetAudioDeviceInfo_ptr(
          "MODE", mode, static_cast<int>(sizeof(mode)))) {
      return false;
    }
  }
  return true;
}

static void nativeTimecodeLanUpdateTransportOnMainThread()
{
  ReaProject* project = getCurrentProject(nullptr, 0);
  const int playState = GetPlayStateEx_ptr && project
    ? GetPlayStateEx_ptr(project)
    : 0;
  const double position = playState != 0
    ? (GetPlayPositionEx_ptr && project
        ? GetPlayPositionEx_ptr(project) : 0.0)
    : (GetCursorPositionEx_ptr && project
        ? GetCursorPositionEx_ptr(project) : 0.0);
  const bool audioHealthy =
    nativeTimecodeLanAudioDeviceHealthy();
  bool dropFrame = false;
  double frameRate = TimeMap_curFrameRate_ptr && project
    ? TimeMap_curFrameRate_ptr(project, &dropFrame) : 30.0;
  if (!std::isfinite(frameRate) || frameRate < 20.0 || frameRate > 61.0) {
    frameRate = 30.0;
    dropFrame = false;
  }

  const int64_t nowMs = nativeSystemNowMs();
  const auto steadyNow = std::chrono::steady_clock::now();
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  NativeTimecodeLanTransport& state =
    g_nativeTimecodeLanTransport;
  const bool previousActive = state.playState != 0;
  const bool currentActive = playState != 0;
  const bool previousPaused = (state.playState & 2) == 2;
  const bool currentPaused = (playState & 2) == 2;
  const double elapsedSec = state.sampledAtMs > 0
    ? std::max(0.0, static_cast<double>(nowMs - state.sampledAtMs) / 1000.0)
    : 0.0;
  double expectedPosition = state.position;
  if (previousActive && !previousPaused) expectedPosition += elapsedSec;
  const bool playStateChanged = state.sampledAtMs > 0 &&
    state.playState != playState;
  const bool transportStateChanged = state.sampledAtMs > 0 &&
    (previousActive != currentActive || previousPaused != currentPaused ||
     playStateChanged);
  const bool stoppedCursorMoved = state.sampledAtMs > 0 &&
    !previousActive && !currentActive &&
    std::fabs(position - state.position) > 0.003;
  const bool activePositionJumped = state.sampledAtMs > 0 &&
    previousActive && currentActive &&
    std::fabs(position - expectedPosition) > 0.080;
  bool explicitIntentObserved = false;
  NativeTimecodeLanPendingTransportIntent& pending =
    g_nativeTimecodeLanPendingTransportIntent;
  if (pending.command != 0) {
    if (steadyNow > pending.expiresAt) {
      pending = NativeTimecodeLanPendingTransportIntent{};
    } else {
      const int before = pending.beforePlayState;
      const bool beforeActive = before != 0;
      const bool beforePaused = (before & 2) == 2;
      const bool pendingPlayStateChanged = playState != before;
      double expectedPendingPosition = pending.beforePosition;
      if (beforeActive && !beforePaused) {
        expectedPendingPosition += std::max(0.0,
          std::chrono::duration<double>(
            steadyNow - pending.markedAt).count());
      }
      // Desconta o avanco natural do Play. So um salto fora dessa previsao (ou
      // um cursor movido enquanto parado) confirma uma intencao de posicao.
      const double pendingPositionThreshold =
        beforeActive && !beforePaused ? 0.080 : 0.003;
      const bool pendingPositionJumped =
        std::fabs(position - expectedPendingPosition) >
          pendingPositionThreshold;
      switch (pending.command) {
        case kReaperTransportPlayCommandId:
          explicitIntentObserved =
            (pendingPlayStateChanged && currentActive && !currentPaused) ||
            pendingPositionJumped;
          break;
        case kReaperTransportPauseCommandId:
          explicitIntentObserved =
            (pendingPlayStateChanged &&
             (beforePaused != currentPaused)) ||
            pendingPositionJumped;
          break;
        case kReaperTransportStopCommandId:
          explicitIntentObserved =
            // Stop e tambem uma ordem valida quando A ja foi parado por uma
            // falha tecnica. Nesse caso nao existe delta local para observar,
            // mas o gesto capturado pelo hook precisa autorizar o Stop em B.
            (!beforeActive && !currentActive) ||
            (pendingPlayStateChanged && !currentActive) ||
            pendingPositionJumped;
          break;
        case kReaperTransportPlayStopCommandId:
          // Play/Stop pode sair de Pause para Play conforme a preferencia do
          // REAPER. Qualquer mudanca real de playState e um resultado coerente.
          explicitIntentObserved = pendingPlayStateChanged ||
            pendingPositionJumped;
          break;
        case kReaperTransportRecordCommandId:
          explicitIntentObserved =
            (((before & 4) == 4) != ((playState & 4) == 4)) ||
            pendingPositionJumped;
          break;
        default:
          break;
      }
      // Uma mudanca diferente da esperada nao recebe autoridade. Normalmente
      // isto significa que a action foi bloqueada e o audio mudou por fora.
      if (explicitIntentObserved || pendingPlayStateChanged ||
          pendingPositionJumped) {
        pending = NativeTimecodeLanPendingTransportIntent{};
      }
    }
  }
  // Uma action local confirmada e autoritativa mesmo quando o REAPER fecha a
  // placa ao parar. Sem essa confirmacao, so um dispositivo saudavel pode
  // elevar controlSequence; uma queda tecnica continua sem parar o PC B.
  if (explicitIntentObserved ||
      (audioHealthy && steadyNow >=
         g_nativeTimecodeLanSuppressLocalTransportIntentUntil &&
       (transportStateChanged || stoppedCursorMoved ||
        activePositionJumped))) {
    ++state.controlSequence;
  }
  if (!explicitIntentObserved &&
      state.playState == playState &&
      std::fabs(state.position - position) < 0.0005 &&
      state.audioHealthy == audioHealthy &&
      std::fabs(state.frameRate - frameRate) < 0.000001 &&
      state.dropFrame == dropFrame &&
      nowMs - state.sampledAtMs < 100) {
    return;
  }
  state.playState = playState;
  state.position = position;
  state.sampledAtMs = nowMs;
  state.audioHealthy = audioHealthy;
  state.frameRate = frameRate;
  state.dropFrame = dropFrame;
  ++state.sequence;
}

static void nativeTimecodeLanPollEditCursorOnMainThread()
{
  ReaProject* project = getCurrentProject(nullptr, 0);
  if (!project || !GetCursorPositionEx_ptr) {
    g_nativeTimecodeLanEditCursorProject = nullptr;
    g_nativeTimecodeLanEditCursorBaselineValid = false;
    return;
  }

  bool canPublish = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    canPublish = g_nativeTimecodeLanMode == "transmitter" ||
      (g_nativeTimecodeLanMode == "project_sync" &&
       g_nativeTimecodeLanProjectSyncRole == "primary");
  }
  const double position = std::max(0.0,
    GetCursorPositionEx_ptr(project));
  if (project != g_nativeTimecodeLanEditCursorProject ||
      !g_nativeTimecodeLanEditCursorBaselineValid) {
    g_nativeTimecodeLanEditCursorProject = project;
    g_nativeTimecodeLanEditCursorBaseline = position;
    g_nativeTimecodeLanEditCursorBaselineValid = true;
    return;
  }
  const int playState = GetPlayStateEx_ptr
    ? GetPlayStateEx_ptr(project) : 0;
  const bool transportPlaying =
    ((playState & 1) == 1) || ((playState & 4) == 4);
  if (transportPlaying) {
    // Durante Play o cursor de edicao deixa de ser um estado replicado. Parts,
    // fila/AT e markers continuam usando seus comandos semanticos proprios;
    // um clique manual no grid nao pode disputar o cursor com o transporte.
    // Absorve a posicao local para nao publicar um movimento antigo ao parar.
    g_nativeTimecodeLanEditCursorBaseline = position;
    return;
  }
  if (!canPublish ||
      std::fabs(position - g_nativeTimecodeLanEditCursorBaseline) <= 0.001) {
    return;
  }

  g_nativeTimecodeLanEditCursorBaseline = position;
  std::ostringstream command;
  command << "{\"type\":\"edit_cursor_move\",\"position\":"
          << std::setprecision(15) << position
          << ",\"exactPosition\":true,\"noSeek\":true"
          << ",\"cursorMoveSeq\":"
          << ++g_nativeTimecodeLanEditCursorSequence << '}';
  nativeTimecodeLanRecordCommand(command.str());
}

// Replica a aba ativa como um gesto da extensao, tanto no Timecode comum
// (Transmitter -> Receive) quanto no Project Sync (PC A -> PC B).  O caminho
// do RPP nao e usado para decidir no destino porque os computadores podem
// ter pastas diferentes; nome e indice tornam a troca deterministica.
static void nativeTimecodeLanPublishActiveProjectTabOnMainThread(
  const std::string& projectSignature)
{
  if (projectSignature.empty()) return;
  bool canPublish = false;
  bool peerConnected = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    canPublish = g_nativeTimecodeLanMode == "transmitter" ||
      (g_nativeTimecodeLanMode == "project_sync" &&
       g_nativeTimecodeLanProjectSyncRole == "primary");
    peerConnected = g_nativeTimecodeLanPeerConnected;
  }
  if (!canPublish || !peerConnected) return;

  if (projectSignature == g_nativeTimecodeLanSuppressedRemoteProjectSignature) {
    g_nativeTimecodeLanLastPublishedProjectSignature = projectSignature;
    g_nativeTimecodeLanSuppressedRemoteProjectSignature.clear();
    return;
  }
  if (projectSignature == g_nativeTimecodeLanLastPublishedProjectSignature) {
    return;
  }

  char pathBuf[2048] = "";
  ReaProject* active = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!active || !EnumProjects_ptr) return;
  int activeIndex = -1;
  for (int index = 0; index < 64; ++index) {
    if (EnumProjects_ptr(index, nullptr, 0) == active) {
      activeIndex = index;
      break;
    }
  }
  if (activeIndex < 0) return;
  const std::string projectPath = normalizeSlashes(pathBuf);
  std::string projectName = nativeBasenameNoRpp(projectPath);
  if (projectName.empty()) projectName = "Projeto " +
    std::to_string(activeIndex + 1);

  std::ostringstream command;
  command << "{\"type\":\"select_project_tab\","
          << "\"projectTabIndex\":" << activeIndex << ","
          << "\"projectName\":" << nativeJsonString(projectName)
          << "}";
  nativeTimecodeLanRecordCommand(command.str());
  g_nativeTimecodeLanLastPublishedProjectSignature = projectSignature;
}

static void nativeRestoreTransportEditCursorOnMainThread()
{
  if (g_nativePendingTransportEditCursorRestorePasses <= 0) return;
  ReaProject* project = g_nativePendingTransportEditCursorProject;
  if (!project || project != getCurrentProject(nullptr, 0) ||
      !SetEditCurPos2_ptr) {
    g_nativePendingTransportEditCursorProject = nullptr;
    g_nativePendingTransportEditCursorRestorePasses = 0;
    return;
  }
  SetEditCurPos2_ptr(project,
    g_nativePendingTransportEditCursorPosition, false, false);
  --g_nativePendingTransportEditCursorRestorePasses;
  if (g_nativePendingTransportEditCursorRestorePasses <= 0) {
    g_nativePendingTransportEditCursorProject = nullptr;
  }
  if (UpdateArrange_ptr) UpdateArrange_ptr();
}

