static int64_t nativeJsonInt64(
  const std::string& json,
  const char* key,
  int64_t fallback = 0)
{
  const std::string value = nativeTrim(
    nativeJsonExtractString(json, key ? key : ""));
  if (value.empty()) return fallback;
  char* end = nullptr;
  const long long parsed = std::strtoll(value.c_str(), &end, 10);
  return end && end != value.c_str() && *end == '\0'
    ? static_cast<int64_t>(parsed)
    : fallback;
}

static bool nativeJsonBoolValue(
  const std::string& json,
  const char* key,
  bool fallback)
{
  const std::string value = nativeLower(nativeTrim(
    nativeJsonExtractString(json, key ? key : "")));
  if (value == "true" || value == "1" ||
      value == "yes" || value == "on") {
    return true;
  }
  if (value == "false" || value == "0" ||
      value == "no" || value == "off") {
    return false;
  }
  return fallback;
}

static std::string nativeTechnicalNoticeText(std::string value)
{
  value = nativeTrim(value);
  constexpr size_t maxBytes = 500;
  if (value.size() <= maxBytes) return value;
  value.resize(maxBytes);
  while (!value.empty() &&
         (static_cast<unsigned char>(value.back()) & 0xC0u) == 0x80u) {
    value.pop_back();
  }
  return nativeTrim(value);
}

static std::string nativeTechnicalNoticeImagePath(
  std::string value)
{
  value = nativeTrim(value);
  if (value.empty() || value.size() > 4096) {
    return std::string();
  }
  const size_t separator = value.find_last_of("/\\");
  const size_t dot = value.find_last_of('.');
  if (dot == std::string::npos ||
      (separator != std::string::npos && dot < separator)) {
    return std::string();
  }
  std::string extension = nativeLower(value.substr(dot + 1));
  static const std::array<const char*, 6> allowed = {
    "png", "jpg", "jpeg", "webp", "gif", "bmp"
  };
  const bool supported = std::any_of(
    allowed.begin(), allowed.end(),
    [&](const char* candidate) {
      return extension == candidate;
    });
  if (!supported) return std::string();
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(value);
  if (widePath.empty()) return std::string();
  std::FILE* image = _wfopen(widePath.c_str(), L"rb");
  if (!image) return std::string();
  std::fclose(image);
  return value;
#else
  std::ifstream image(value, std::ios::in | std::ios::binary);
  return image.good() ? value : std::string();
#endif
}

static std::string nativeTechnicalNoticeColor(
  std::string value,
  const char* fallback)
{
  value = nativeTrim(value);
  if (value.size() == 7 && value[0] == '#') {
    const bool valid = std::all_of(
      value.begin() + 1, value.end(),
      [](unsigned char c) {
        return std::isxdigit(c) != 0;
      });
    if (valid) {
      std::transform(
        value.begin(), value.end(), value.begin(),
        [](unsigned char c) {
          return static_cast<char>(std::tolower(c));
        });
      return value;
    }
  }
  return fallback ? std::string(fallback) : std::string("#000000");
}

static std::string nativeTechnicalNoticeFont(std::string value)
{
  value = nativeTrim(value);
  static const std::array<const char*, 7> allowed = {
    "Arial", "Segoe UI", "Verdana", "Tahoma",
    "Georgia", "Trebuchet MS", "Impact"
  };
  for (const char* font : allowed) {
    if (value == font) return value;
  }
  return "Arial";
}

static std::string nativeTechnicalNoticeSource(std::string source)
{
  source = nativeLower(nativeTrim(source));
  if (source == "director" || source == "diretor") {
    return "director";
  }
  if (source == "hooklyrics" ||
      source == "hook-lyrics" ||
      source == "lyrics") {
    return "hooklyrics";
  }
  return "recados";
}

static int nativeTechnicalNoticePriority(
  const std::string& source)
{
  const std::string normalized =
    nativeTechnicalNoticeSource(source);
  if (normalized == "recados") return 4;
  if (normalized == "director") return 3;
  return 1;
}

static bool nativeTechnicalNoticeIsActiveLocked(int64_t nowMs)
{
  return (!g_nativeTechnicalNotice.text.empty() ||
          !g_nativeTechnicalNotice.imagePath.empty()) &&
    g_nativeTechnicalNotice.expiresAtMs > nowMs;
}

