static std::string nativeTechnicalNoticeJsonLocked(
  int64_t nowMs)
{
  if (!nativeTechnicalNoticeIsActiveLocked(nowMs)) {
    return "null";
  }
  const NativeTechnicalNotice& notice =
    g_nativeTechnicalNotice;
  std::ostringstream json;
  json << "{";
  json << "\"id\":" << nativeJsonString(notice.id) << ",";
  json << "\"text\":" << nativeJsonString(notice.text) << ",";
  json << "\"message\":" << nativeJsonString(notice.text) << ",";
  json << "\"imagePath\":"
       << nativeJsonString(notice.imagePath) << ",";
  json << "\"imageUrl\":"
       << nativeJsonString(
            notice.imagePath.empty()
              ? std::string()
              : std::string("/media?path=") +
                  nativeUrlEncode(notice.imagePath))
       << ",";
  json << "\"source\":" << nativeJsonString(notice.source) << ",";
  json << "\"priority\":" << notice.priority << ",";
  json << "\"createdAt\":" << notice.createdAtMs << ",";
  json << "\"updatedAt\":" << notice.updatedAtMs << ",";
  json << "\"expiresAt\":" << notice.expiresAtMs << ",";
  json << "\"durationMs\":" << notice.durationMs << ",";
  json << "\"pausedRemainingMs\":"
       << notice.pausedRemainingMs << ",";
  json << "\"pinned\":"
       << (notice.pinned ? "true" : "false");
  json << "}";
  return json.str();
}

