static void nativeTechnicalNoticeApplySettingsJsonLocked(
  const std::string& json)
{
  NativeTechnicalNoticeSettings& settings =
    g_nativeTechnicalNoticeSettings;
  const std::string textColor =
    nativeJsonExtractString(json, "textColor");
  const std::string backgroundColor =
    nativeJsonExtractString(json, "backgroundColor");
  const std::string flashColor =
    nativeJsonExtractString(json, "flashColor");
  const std::string fontFamily =
    nativeJsonExtractString(json, "fontFamily");
  const std::string emoji =
    nativeTrim(nativeJsonExtractString(json, "emoji"));
  if (!textColor.empty()) {
    settings.textColor = nativeTechnicalNoticeColor(
      textColor, "#ffea00");
  }
  if (!backgroundColor.empty()) {
    settings.backgroundColor = nativeTechnicalNoticeColor(
      backgroundColor, "#000000");
  }
  if (!flashColor.empty()) {
    settings.flashColor = nativeTechnicalNoticeColor(
      flashColor, "#ff0000");
  }
  if (!fontFamily.empty()) {
    settings.fontFamily =
      nativeTechnicalNoticeFont(fontFamily);
  }
  if (!emoji.empty()) {
    settings.emoji = emoji.size() > 32
      ? emoji.substr(0, 32)
      : emoji;
  }
  settings.window1Enabled = nativeJsonBoolValue(
    json, "window1Enabled", settings.window1Enabled);
  settings.window2Enabled = nativeJsonBoolValue(
    json, "window2Enabled", settings.window2Enabled);
  settings.emojiEnabled = nativeJsonBoolValue(
    json, "emojiEnabled", settings.emojiEnabled);
  settings.cleanDisplay = nativeJsonBoolValue(
    json, "cleanDisplay", settings.cleanDisplay);
}

static NativeTechnicalNotice
nativeTechnicalNoticeFromJson(const std::string& json)
{
  NativeTechnicalNotice notice;
  notice.id = nativeJsonExtractString(json, "id");
  notice.text = nativeTechnicalNoticeText(
    nativeJsonExtractString(json, "text"));
  if (notice.text.empty()) {
    notice.text = nativeTechnicalNoticeText(
      nativeJsonExtractString(json, "message"));
  }
  notice.imagePath = nativeTechnicalNoticeImagePath(
    nativeJsonExtractString(json, "imagePath"));
  notice.source = nativeTechnicalNoticeSource(
    nativeJsonExtractString(json, "source"));
  notice.priority = static_cast<int>(nativeJsonInt64(
    json, "priority",
    nativeTechnicalNoticePriority(notice.source)));
  notice.createdAtMs = nativeJsonInt64(
    json, "createdAt", 0);
  notice.updatedAtMs = nativeJsonInt64(
    json, "updatedAt", notice.createdAtMs);
  notice.expiresAtMs = nativeJsonInt64(
    json, "expiresAt", 0);
  notice.durationMs = nativeJsonInt64(
    json, "durationMs", 20000);
  notice.pausedRemainingMs = std::max<int64_t>(
    0, nativeJsonInt64(json, "pausedRemainingMs", 0));
  notice.pinned = nativeJsonBoolValue(
    json, "pinned", false);
  return notice;
}

static void nativeTechnicalNoticeLoadState()
{
  if (g_nativeTechnicalNoticeLoaded) return;
  NativeTechnicalNoticeSettings settings;
  NativeTechnicalNotice notice;
  if (GetExtState_ptr) {
    const char* rawSettings = GetExtState_ptr(
      kNativeTelepromptSettingsSection,
      kNativeTechnicalNoticeSettingsKey);
    if (rawSettings && *rawSettings) {
      g_nativeTechnicalNoticeSettings = settings;
      nativeTechnicalNoticeApplySettingsJsonLocked(
        rawSettings);
      settings = g_nativeTechnicalNoticeSettings;
    }
    for (size_t index = 0;
         index < settings.templates.size(); ++index) {
      const char* value = GetExtState_ptr(
        kNativeTelepromptSettingsSection,
        kNativeRecadosTemplateKeys[index]);
      if (value) {
        settings.templates[index] =
          nativeTechnicalNoticeText(value);
      }
      const char* imageValue = GetExtState_ptr(
        kNativeTelepromptSettingsSection,
        kNativeRecadosImageKeys[index]);
      if (imageValue) {
        settings.templateImages[index] =
          nativeTechnicalNoticeImagePath(imageValue);
      }
    }
    const char* rawNotice = GetExtState_ptr(
      kNativeTelepromptSettingsSection,
      kNativeTechnicalNoticeActiveKey);
    if (rawNotice && *rawNotice) {
      notice = nativeTechnicalNoticeFromJson(rawNotice);
    }
  }
  const int64_t nowMs = nativeSystemNowMs();
  if (notice.expiresAtMs <= nowMs ||
      (notice.text.empty() &&
       notice.imagePath.empty())) {
    notice = NativeTechnicalNotice{};
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeTechnicalNoticeSettings = settings;
    g_nativeTechnicalNotice = notice;
    g_nativeTechnicalNoticeLoaded = true;
  }
}

static void nativeTechnicalNoticeRefreshAuthCache(
  const std::string& directorHash,
  const std::string& recadosHash)
{
  std::lock_guard<std::mutex> lock(g_nativeMutex);
  g_nativeDirectorAuthHashCache = directorHash;
  g_nativeRecadosAuthHashCache = recadosHash;
}

static bool nativeTechnicalNoticeAuthorized(
  const std::string& body,
  const std::string& source)
{
  const std::string normalized =
    nativeTechnicalNoticeSource(source);
  std::string configuredHash;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    configuredHash = normalized == "director"
      ? g_nativeDirectorAuthHashCache
      : g_nativeRecadosAuthHashCache;
  }
  if (configuredHash.empty()) return true;
  std::string providedHash =
    nativeTrim(nativeJsonExtractString(body, "passwordHash"));
  if (providedHash.empty()) {
    providedHash =
      nativeTrim(nativeJsonExtractString(body, "authHash"));
  }
  if (normalized == "director") {
    const std::string sessionHash =
      nativeTrim(nativeJsonExtractString(body, "sessionHash"));
    if (!sessionHash.empty() &&
        sessionHash == configuredHash) {
      return true;
    }
  }
  if (!providedHash.empty() &&
      providedHash == configuredHash) {
    return true;
  }
  std::string password =
    nativeJsonExtractString(body, "password");
  if (password.empty()) {
    password = nativeJsonExtractString(body, "pass");
  }
  return !password.empty() &&
    nativeDirectorPasswordHash(password) == configuredHash;
}

static void nativeTechnicalNoticeExpireOnMainThread()
{
  const int64_t nowMs = nativeSystemNowMs();
  bool expired = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if ((!g_nativeTechnicalNotice.text.empty() ||
         !g_nativeTechnicalNotice.imagePath.empty()) &&
        g_nativeTechnicalNotice.expiresAtMs <= nowMs) {
      g_nativeTechnicalNotice = NativeTechnicalNotice{};
      expired = true;
    }
  }
  if (expired) {
    g_nativeTechnicalNoticeActiveDirty.store(true);
    g_nativeForceStateBuild.store(true);
  }
}

static void nativeTechnicalNoticeFlushPersistenceOnMainThread()
{
  if (!SetExtState_ptr) return;
  if (g_nativeTechnicalNoticeSettingsDirty.exchange(false)) {
    std::string settingsJson;
    std::array<std::string, 3> templates;
    std::array<std::string, 3> templateImages;
    {
      std::lock_guard<std::mutex> lock(g_nativeMutex);
      settingsJson =
        nativeTechnicalNoticeSettingsJsonLocked();
      templates =
        g_nativeTechnicalNoticeSettings.templates;
      templateImages =
        g_nativeTechnicalNoticeSettings.templateImages;
    }
    SetExtState_ptr(
      kNativeTelepromptSettingsSection,
      kNativeTechnicalNoticeSettingsKey,
      settingsJson.c_str(), true);
    for (size_t index = 0;
         index < templates.size(); ++index) {
      SetExtState_ptr(
        kNativeTelepromptSettingsSection,
        kNativeRecadosTemplateKeys[index],
        templates[index].c_str(), true);
      SetExtState_ptr(
        kNativeTelepromptSettingsSection,
        kNativeRecadosImageKeys[index],
        templateImages[index].c_str(), true);
    }
  }
  if (g_nativeTechnicalNoticeActiveDirty.exchange(false)) {
    std::string noticeJson;
    {
      std::lock_guard<std::mutex> lock(g_nativeMutex);
      noticeJson = nativeTechnicalNoticeJsonLocked(
        nativeSystemNowMs());
    }
    if (noticeJson == "null") noticeJson.clear();
    SetExtState_ptr(
      kNativeTelepromptSettingsSection,
      kNativeTechnicalNoticeActiveKey,
      noticeJson.c_str(), true);
  }
}

static bool nativeApplyTechnicalNoticeSettingsCommand(
  const std::string& commandBody)
{
  const std::string type = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "type")));
  if (type != "technical_notice_settings" &&
      type != "recados_settings" &&
      type != "save_technical_notice_settings") {
    return false;
  }
  nativeTimecodeLanRecordCommand(commandBody);
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    nativeTechnicalNoticeApplySettingsJsonLocked(
      commandBody);
  }
  g_nativeTechnicalNoticeSettingsDirty.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static bool nativeTechnicalNoticeSnapshot(
  int slot,
  NativeTechnicalNotice& noticeOut,
  NativeTechnicalNoticeSettings& settingsOut)
{
  const int64_t nowMs = nativeSystemNowMs();
  std::lock_guard<std::mutex> lock(g_nativeMutex);
  settingsOut = g_nativeTechnicalNoticeSettings;
  const bool enabled = slot == 2
    ? settingsOut.window2Enabled
    : settingsOut.window1Enabled;
  if (!enabled ||
      !nativeTechnicalNoticeIsActiveLocked(nowMs)) {
    noticeOut = NativeTechnicalNotice{};
    return false;
  }
  noticeOut = g_nativeTechnicalNotice;
  return true;
}

static int nativeHandleRecadosTemplatesPost(
  const std::string& requestBody,
  std::string& responseJson)
{
  const std::string source = nativeTechnicalNoticeSource(
    nativeJsonExtractString(requestBody, "source"));
  if (!nativeTechnicalNoticeAuthorized(
        requestBody, source)) {
    responseJson =
      "{\"ok\":false,\"error\":\"Senha inválida.\"}";
    return 401;
  }
  const int64_t index = nativeJsonInt64(
    requestBody, "index", -1);
  if (index < 0 || index > 2) {
    responseJson =
      "{\"ok\":false,\"error\":\"Recado inválido.\"}";
    return 400;
  }
  const std::string text = nativeTechnicalNoticeText(
    nativeJsonExtractString(requestBody, "text"));
  const bool updateText = nativeJsonBoolValue(
    requestBody, "updateText",
    requestBody.find("\"text\"") != std::string::npos);
  const bool updateImage = nativeJsonBoolValue(
    requestBody, "updateImage", false);
  const std::string requestedImagePath =
    nativeTrim(nativeJsonExtractString(
      requestBody, "imagePath"));
  const std::string imagePath =
    nativeTechnicalNoticeImagePath(requestedImagePath);
  if (updateImage &&
      !requestedImagePath.empty() &&
      imagePath.empty()) {
    responseJson =
      "{\"ok\":false,\"error\":\"A imagem não foi encontrada ou o formato não é aceito.\"}";
    return 400;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (updateText) {
      g_nativeTechnicalNoticeSettings.templates[
        static_cast<size_t>(index)] = text;
    }
    if (updateImage) {
      g_nativeTechnicalNoticeSettings.templateImages[
        static_cast<size_t>(index)] = imagePath;
    }
  }
  g_nativeTechnicalNoticeSettingsDirty.store(true);
  g_nativeForceStateBuild.store(true);
  responseJson = nativeRecadosTemplatesResponseJson();
  return 200;
}

static int nativeHandleTechnicalNoticePost(
  const std::string& requestBody,
  std::string& responseJson)
{
  const std::string source = nativeTechnicalNoticeSource(
    nativeJsonExtractString(requestBody, "source"));
  const int priority =
    nativeTechnicalNoticePriority(source);
  if (!nativeTechnicalNoticeAuthorized(
        requestBody, source)) {
    responseJson =
      "{\"ok\":false,\"error\":\"Senha inválida.\"}";
    return 401;
  }
  const std::string action = nativeLower(nativeTrim(
    nativeJsonExtractString(requestBody, "action")));
  const int64_t nowMs = nativeSystemNowMs();
  if (action == "cancel" || action == "clear" ||
      action == "remove") {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (nativeTechnicalNoticeIsActiveLocked(nowMs) &&
        g_nativeTechnicalNotice.priority > priority) {
      responseJson =
        std::string("{\"ok\":true,\"ignoredDuePriority\":true,\"notice\":") +
        nativeTechnicalNoticeJsonLocked(nowMs) +
        ",\"now\":" + std::to_string(nowMs) + "}";
      return 200;
    }
    g_nativeTechnicalNotice = NativeTechnicalNotice{};
    responseJson = std::string(
      "{\"ok\":true,\"cancelled\":true,\"notice\":null,\"now\":") +
      std::to_string(nowMs) + "}";
    g_nativeTechnicalNoticeActiveDirty.store(true);
    g_nativeForceStateBuild.store(true);
    return 200;
  }
  if (action == "pin" || action == "unpin") {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (!nativeTechnicalNoticeIsActiveLocked(nowMs)) {
      responseJson =
        "{\"ok\":false,\"error\":\"Nenhum recado ativo.\"}";
      return 404;
    }
    if (g_nativeTechnicalNotice.priority > priority) {
      responseJson =
        std::string("{\"ok\":true,\"ignoredDuePriority\":true,\"notice\":") +
        nativeTechnicalNoticeJsonLocked(nowMs) +
        ",\"now\":" + std::to_string(nowMs) + "}";
      return 200;
    }
    const bool pinned = action == "pin";
    const int64_t configuredDuration = std::max<int64_t>(
      1000, g_nativeTechnicalNotice.durationMs > 0
        ? g_nativeTechnicalNotice.durationMs
        : 20000);
    const int64_t remaining = pinned
      ? std::max<int64_t>(
          0, g_nativeTechnicalNotice.expiresAtMs - nowMs)
      : std::max<int64_t>(
          0, g_nativeTechnicalNotice.pausedRemainingMs > 0
            ? g_nativeTechnicalNotice.pausedRemainingMs
            : configuredDuration);
    g_nativeTechnicalNotice.pinned = pinned;
    g_nativeTechnicalNotice.durationMs = pinned
      ? configuredDuration : remaining;
    g_nativeTechnicalNotice.pausedRemainingMs =
      pinned ? remaining : 0;
    g_nativeTechnicalNotice.updatedAtMs = nowMs;
    g_nativeTechnicalNotice.expiresAtMs = pinned
      ? nowMs + 315360000000LL
      : nowMs + remaining;
    responseJson =
      std::string("{\"ok\":true,\"notice\":") +
      nativeTechnicalNoticeJsonLocked(nowMs) +
      ",\"now\":" + std::to_string(nowMs) + "}";
    g_nativeTechnicalNoticeActiveDirty.store(true);
    g_nativeForceStateBuild.store(true);
    return 200;
  }

  std::string text = nativeTechnicalNoticeText(
    nativeJsonExtractString(requestBody, "text"));
  if (text.empty()) {
    text = nativeTechnicalNoticeText(
      nativeJsonExtractString(requestBody, "message"));
  }
  const std::string requestedImagePath =
    nativeTrim(nativeJsonExtractString(
      requestBody, "imagePath"));
  const std::string imagePath =
    nativeTechnicalNoticeImagePath(requestedImagePath);
  if (!requestedImagePath.empty() &&
      imagePath.empty()) {
    responseJson =
      "{\"ok\":false,\"error\":\"A imagem não foi encontrada ou o formato não é aceito.\"}";
    return 400;
  }
  if (text.empty() && imagePath.empty()) {
    responseJson =
      "{\"ok\":false,\"error\":\"Digite um recado ou escolha uma imagem antes de enviar.\"}";
    return 400;
  }
  int64_t durationMs = nativeJsonInt64(
    requestBody, "durationMs", 20000);
  durationMs = std::max<int64_t>(
    1000, std::min<int64_t>(60000, durationMs));
  const bool pinned = nativeJsonBoolValue(
    requestBody, "pinned", false);
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (nativeTechnicalNoticeIsActiveLocked(nowMs) &&
        g_nativeTechnicalNotice.priority > priority) {
      responseJson =
        std::string("{\"ok\":true,\"ignoredDuePriority\":true,\"notice\":") +
        nativeTechnicalNoticeJsonLocked(nowMs) +
        ",\"now\":" + std::to_string(nowMs) + "}";
      return 200;
    }
    NativeTechnicalNotice notice;
    const uint64_t sequence =
      ++g_nativeTechnicalNoticeSequence;
    notice.id = std::to_string(nowMs) + "-" +
      std::to_string(sequence);
    notice.imagePath = imagePath;
    // Texto e imagem permanecem salvos separadamente nos slots. Durante a
    // exibição, porém, a imagem tem prioridade e o recado nunca mistura os
    // dois conteúdos.
    notice.text = imagePath.empty()
      ? text : std::string();
    notice.source = source;
    notice.priority = priority;
    notice.createdAtMs = nowMs;
    notice.updatedAtMs = nowMs;
    notice.durationMs = durationMs;
    notice.pausedRemainingMs =
      pinned ? durationMs : 0;
    notice.expiresAtMs = pinned
      ? nowMs + 315360000000LL
      : nowMs + durationMs;
    notice.pinned = pinned;
    g_nativeTechnicalNotice = notice;
    responseJson =
      std::string("{\"ok\":true,\"notice\":") +
      nativeTechnicalNoticeJsonLocked(nowMs) +
      ",\"now\":" + std::to_string(nowMs) + "}";
  }
  g_nativeTechnicalNoticeActiveDirty.store(true);
  g_nativeForceStateBuild.store(true);
  return 200;
}


static std::string nativeMediaItemNotes(MediaItem* item)
{
  if (!item || !GetSetMediaItemInfo_String_ptr) return std::string();
  std::string buf(65536, '\0');
  if (!GetSetMediaItemInfo_String_ptr(item, "P_NOTES", buf.data(), false)) return std::string();
  const size_t n = buf.find('\0');
  if (n != std::string::npos) buf.resize(n);
  return nativeTrim(buf);
}

static std::string nativeCollectLyricsForRange(ReaProject* project, double start, double end)
{
  if (!project || !CountTracks_ptr || !GetTrack_ptr || !GetTrackNumMediaItems_ptr || !GetTrackMediaItem_ptr || !GetMediaItemInfo_Value_ptr) return std::string();
  std::string best;
  const int trackCount = CountTracks_ptr(project);
  for (int ti = 0; ti < trackCount; ++ti) {
    MediaTrack* track = GetTrack_ptr(project, ti);
    if (!track) continue;
    const int itemCount = GetTrackNumMediaItems_ptr(track);
    for (int ii = 0; ii < itemCount; ++ii) {
      MediaItem* item = GetTrackMediaItem_ptr(track, ii);
      if (!item) continue;
      const double pos = GetMediaItemInfo_Value_ptr(item, "D_POSITION");
      const double len = std::max(0.0, GetMediaItemInfo_Value_ptr(item, "D_LENGTH"));
      const double itemEnd = pos + len;
      const bool startsInside = pos >= start - 0.0005 && pos < end - 0.0005;
      const bool overlaps = itemEnd > start + 0.0005 && pos < end - 0.0005;
      if (!startsInside && !overlaps) continue;
      const std::string notes = nativeMediaItemNotes(item);
      if (!notes.empty()) {
        // Prioriza texto que começa dentro da música; se só atravessa, guarda como fallback.
        if (startsInside) return notes;
        if (best.empty()) best = notes;
      }
    }
  }
  return best;
}

static bool nativeItemStartsInRange(MediaItem* item, double start, double end)
{
  if (!item || !GetMediaItemInfo_Value_ptr) return false;
  const double pos = GetMediaItemInfo_Value_ptr(item, "D_POSITION");
  return pos >= start - 0.0005 && pos < end - 0.0005;
}

static bool nativeItemOverlapsRange(MediaItem* item, double start, double end)
{
  if (!item || !GetMediaItemInfo_Value_ptr) return false;
  const double pos = GetMediaItemInfo_Value_ptr(item, "D_POSITION");
  const double len = std::max(0.0, GetMediaItemInfo_Value_ptr(item, "D_LENGTH"));
  const double itemEnd = pos + len;
  return itemEnd > start + 0.0005 && pos < end - 0.0005;
}

