static std::string nativeBuildProjectsJson(ReaProject* activeProject, std::string& activeProjectNameOut, std::string& activeProjectPathOut, int& activeIndexOut)
{
  std::ostringstream oss;
  oss << "[";
  bool first = true;
  activeIndexOut = 0;
  if (!EnumProjects_ptr) {
    oss << "]";
    return oss.str();
  }

  for (int i = 0; i < 64; ++i) {
    char pathBuf[2048] = "";
    ReaProject* project = EnumProjects_ptr(i, pathBuf, static_cast<int>(sizeof(pathBuf)));
    if (!project) break;
    const std::string projectPath = normalizeSlashes(pathBuf);
    std::string projectName = nativeBasenameNoRpp(projectPath);
    if (projectName.empty()) projectName = std::string("Projeto ") + std::to_string(i + 1);
    const bool active = project == activeProject;
    if (active) {
      activeIndexOut = i;
      activeProjectNameOut = projectName;
      activeProjectPathOut = projectPath;
    }
    if (!first) oss << ",";
    first = false;
    const std::string id = std::to_string(reinterpret_cast<std::uintptr_t>(project));
    const int projectPlayState = GetPlayStateEx_ptr
      ? GetPlayStateEx_ptr(project) : 0;
    const bool projectTransportActive =
      projectPlayState != 0;
    const bool projectPlaying =
      (projectPlayState & 1) == 1 ||
      (projectPlayState & 4) == 4;
    const bool projectPaused =
      (projectPlayState & 2) == 2;
    oss << "{";
    oss << "\"id\":" << nativeJsonString(id) << ",";
    oss << "\"index\":" << i << ",";
    oss << "\"name\":" << nativeJsonString(projectName) << ",";
    oss << "\"projectName\":" << nativeJsonString(projectName) << ",";
    oss << "\"projectPath\":" << nativeJsonString(projectPath) << ",";
    oss << "\"active\":" << (active ? "true" : "false") << ",";
    oss << "\"isCurrent\":" << (active ? "true" : "false") << ",";
    oss << "\"transportActive\":"
        << (projectTransportActive ? "true" : "false") << ",";
    oss << "\"playing\":"
        << (projectPlaying ? "true" : "false") << ",";
    oss << "\"paused\":"
        << (projectPaused ? "true" : "false");
    oss << "}";
  }
  oss << "]";
  return oss.str();
}

static bool nativeAnyOpenProjectTransportActive()
{
  if (!EnumProjects_ptr || !GetPlayStateEx_ptr) return false;
  for (int index = 0; index < 64; ++index) {
    ReaProject* project =
      EnumProjects_ptr(index, nullptr, 0);
    if (!project) break;
    if (GetPlayStateEx_ptr(project) != 0) return true;
  }
  return false;
}

static bool nativeOtherOpenProjectTransportActive(
  ReaProject* currentProject)
{
  if (!EnumProjects_ptr || !GetPlayStateEx_ptr) return false;
  for (int index = 0; index < 64; ++index) {
    ReaProject* project =
      EnumProjects_ptr(index, nullptr, 0);
    if (!project) break;
    if (project == currentProject) continue;
    if (GetPlayStateEx_ptr(project) != 0) return true;
  }
  return false;
}

