// Mantem a descoberta do App disponivel sem acordar o motor completo.
// Este snapshot nao percorre tracks, markers, regioes, Parts, Premix ou Mixer;
// apenas enumera as abas de projeto e publica a autenticacao necessaria para a
// tela de entrada do Diretor. O heartbeat do app ativa o snapshot completo.
static std::string nativeTelepromptProjectMediaDirectory(
  ReaProject* project);

static void nativePublishStandbyDiscoveryState()
{
  if (!EnumProjects_ptr) return;

  char activePathBuf[2048] = "";
  ReaProject* activeProject = getCurrentProject(activePathBuf, static_cast<int>(sizeof(activePathBuf)));
  std::string activeProjectName;
  std::string activeProjectPath;
  int activeProjectIndex = 0;
  const std::string projectsJson = nativeBuildProjectsJson(
    activeProject, activeProjectName, activeProjectPath, activeProjectIndex);
  if (activeProjectName.empty()) activeProjectName = nativeBasenameNoRpp(activePathBuf);
  if (activeProjectPath.empty()) activeProjectPath = normalizeSlashes(activePathBuf);
  const std::string activeProjectMediaPath = activeProject
    ? nativeTelepromptProjectMediaDirectory(activeProject)
    : std::string();

  const std::string directorPassword = nativeReadDirectorPassword();
  const std::string directorAuthHash = nativeDirectorPasswordHash(directorPassword);
  const bool directorAuthEnabled = !directorAuthHash.empty();
  const std::string recadosAuthHash =
    nativeDirectorPasswordHash(nativeReadRecadosPassword());
  const bool recadosAuthEnabled = !recadosAuthHash.empty();
  nativeTechnicalNoticeRefreshAuthCache(
    directorAuthHash, recadosAuthHash);
  std::string directorAuthRevision;
  if (GetExtState_ptr) {
    const char* rawRevision = GetExtState_ptr(kNativeExtStateSection, kDirectorAuthRevisionKey);
    if (rawRevision && *rawRevision) directorAuthRevision = rawRevision;
  }

  const std::string nowIso = nativeIsoNow();
  std::ostringstream json;
  json << "{";
  json << "\"ok\":true,";
  json << "\"nativeBridge\":true,";
  json << "\"bridgeVersion\":2,";
  json << "\"extensionVersion\":" << nativeJsonString(VSHOOK_EXTENSION_VERSION) << ",";
  json << "\"connected\":true,";
  json << "\"standby\":true,";
  json << "\"runtimeControlActive\":false,";
  json << "\"app\":\"VS Hook\",";
  json << "\"appName\":\"VS Hook Diretor\",";
  json << "\"directorAuthEnabled\":" << (directorAuthEnabled ? "true" : "false") << ",";
  json << "\"authEnabled\":" << (directorAuthEnabled ? "true" : "false") << ",";
  json << "\"accessAuthEnabled\":" << (directorAuthEnabled ? "true" : "false") << ",";
  json << "\"directorAuthHash\":" << nativeJsonString(directorAuthHash) << ",";
  json << "\"authHash\":" << nativeJsonString(directorAuthHash) << ",";
  json << "\"accessAuthHash\":" << nativeJsonString(directorAuthHash) << ",";
  json << "\"directorPasswordHash\":" << nativeJsonString(directorAuthHash) << ",";
  json << "\"recadosAuthEnabled\":"
       << (recadosAuthEnabled ? "true" : "false") << ",";
  json << "\"technicalNoticeAuthEnabled\":"
       << (recadosAuthEnabled ? "true" : "false") << ",";
  json << "\"recadosAuthHash\":"
       << nativeJsonString(recadosAuthHash) << ",";
  json << "\"technicalNoticeAuthHash\":"
       << nativeJsonString(recadosAuthHash) << ",";
  json << nativeTechnicalNoticeStateFieldsJson() << ",";
  json << "\"directorAuthRevision\":" << nativeJsonString(directorAuthRevision) << ",";
  json << "\"authRevision\":" << nativeJsonString(directorAuthRevision) << ",";
  json << "\"accessAuthRevision\":" << nativeJsonString(directorAuthRevision) << ",";
  json << "\"appActive\":false,";
  json << "\"directorAppActive\":false,";
  json << "\"directorActive\":false,";
  json << "\"luaControlActive\":false,";
  json << "\"updatedAt\":" << nativeJsonString(nowIso) << ",";
  json << "\"heartbeatAt\":" << nativeJsonString(nowIso) << ",";
  json << "\"projectName\":" << nativeJsonString(activeProjectName) << ",";
  json << "\"currentProjectName\":" << nativeJsonString(activeProjectName) << ",";
  json << "\"projectPath\":" << nativeJsonString(activeProjectPath) << ",";
  json << "\"projectMediaPath\":"
       << nativeJsonString(activeProjectMediaPath) << ",";
  json << "\"projectDirty\":"
       << ((activeProject && IsProjectDirty_ptr &&
            IsProjectDirty_ptr(activeProject) != 0) ? "true" : "false") << ",";
  json << "\"projects\":" << projectsJson << ",";
  json << "\"projectTabs\":" << projectsJson << ",";
  json << "\"openProjects\":" << projectsJson << ",";
  json << "\"activeProjectTabIndex\":" << activeProjectIndex << ",";
  json << "\"regions\":[],\"markers\":[],\"playlists\":[]";
  json << "}";

  const std::string payload = json.str();
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeStateJson = payload;
  }
  if (SetExtState_ptr) {
    SetExtState_ptr(kNativeExtStateSection, "NATIVE_STATE_JSON_V1", payload.c_str(), false);
  }
}

static int nativeGetRegionRulerLaneNumber(ReaProject* project, int enumIndex)
{
  if (!project || enumIndex < 0 || !GetRegionOrMarker_ptr || !GetRegionOrMarkerInfo_Value_ptr) return -1;
  void* regionHandle = GetRegionOrMarker_ptr(project, enumIndex, "");
  if (!regionHandle) return -1;
  const double lane = GetRegionOrMarkerInfo_Value_ptr(project, regionHandle, "I_LANENUMBER");
  return std::isfinite(lane) ? static_cast<int>(std::floor(lane)) : -1;
}

static std::string nativeRegionOrderIdentityName(std::string name)
{
  name = nativeTrim(name);
  size_t first = 0;
  while (first < name.size() &&
         std::isspace(static_cast<unsigned char>(name[first]))) {
    ++first;
  }
  size_t afterDigits = first;
  while (afterDigits < name.size() &&
         std::isdigit(static_cast<unsigned char>(name[afterDigits]))) {
    ++afterDigits;
  }
  if (afterDigits > first && afterDigits < name.size() &&
      std::isspace(static_cast<unsigned char>(name[afterDigits]))) {
    while (afterDigits < name.size() &&
           std::isspace(static_cast<unsigned char>(name[afterDigits]))) {
      ++afterDigits;
    }
    name = name.substr(afterDigits);
  }
  name = nativeTrim(name);
  if (nativeStartsWith(name, "--")) {
    name = nativeTrim(name.substr(2));
  }
  return name;
}

static std::string nativeRegionOrderIdentity(
  const NativeSongWindow& song)
{
  return nativeNumber(song.start, 6) + "|" +
    nativeNumber(song.end, 6) + "|" +
    nativeRegionOrderIdentityName(song.name);
}

static void nativeNormalizeRegionFamilies(
  std::vector<NativeSongWindow>& songs)
{
  if (songs.size() < 2) return;

  std::set<std::string> parentIds;
  std::map<std::string, std::vector<NativeSongWindow>>
    childrenByParent;
  for (const auto& song : songs) {
    if (song.isHashParent && !song.id.empty()) {
      parentIds.insert(song.id);
    }
    if (song.isHashChild && !song.parentId.empty()) {
      childrenByParent[song.parentId].push_back(song);
    }
  }
  if (parentIds.empty()) return;

  for (auto& entry : childrenByParent) {
    std::stable_sort(
      entry.second.begin(), entry.second.end(),
      [](const NativeSongWindow& a,
         const NativeSongWindow& b) {
        if (std::fabs(a.start - b.start) > 0.0005) {
          return a.start < b.start;
        }
        if (std::fabs(a.end - b.end) > 0.0005) {
          return a.end < b.end;
        }
        return a.sourceNumber < b.sourceNumber;
      });
  }

  std::vector<NativeSongWindow> normalized;
  normalized.reserve(songs.size());
  std::set<std::string> emittedFamilies;
  for (const auto& song : songs) {
    if (song.isHashChild &&
        parentIds.find(song.parentId) != parentIds.end()) {
      // O filho será inserido junto ao pai, nunca solto pela ordem antiga.
      continue;
    }
    normalized.push_back(song);
    if (!song.isHashParent || song.id.empty() ||
        !emittedFamilies.insert(song.id).second) {
      continue;
    }
    const auto children = childrenByParent.find(song.id);
    if (children == childrenByParent.end()) continue;
    normalized.insert(
      normalized.end(),
      children->second.begin(), children->second.end());
  }
  if (normalized.size() == songs.size()) {
    songs.swap(normalized);
  }
}

static void nativeApplySavedRegionOrder(
  ReaProject* project,
  std::vector<NativeSongWindow>& songs)
{
  if (!project || songs.size() < 2) return;
  const std::string raw = nativeGetProjExtStateString(
    project, kPlaylistExtSection, kRegionOrderExtKey);
  if (raw.empty()) {
    nativeNormalizeRegionFamilies(songs);
    return;
  }

  std::map<std::string, size_t> byIdentity;
  for (size_t index = 0; index < songs.size(); ++index) {
    const std::string identity =
      nativeRegionOrderIdentity(songs[index]);
    if (byIdentity.find(identity) == byIdentity.end()) {
      byIdentity[identity] = index;
    }
  }

  std::vector<NativeSongWindow> reordered;
  reordered.reserve(songs.size());
  std::vector<bool> used(songs.size(), false);
  for (const std::string& line : nativeSplit(raw, '\n')) {
    const auto found = byIdentity.find(line);
    if (found == byIdentity.end() || used[found->second]) continue;
    reordered.push_back(songs[found->second]);
    used[found->second] = true;
  }
  for (size_t index = 0; index < songs.size(); ++index) {
    if (!used[index]) reordered.push_back(songs[index]);
  }
  if (reordered.size() == songs.size()) songs.swap(reordered);
  // REGION_ORDER_V1 é uma ordem plana e versões anteriores podiam separar
  // filhos do pai. A família sempre volta a ser uma unidade e seus filhos
  // seguem a posição real na timeline.
  nativeNormalizeRegionFamilies(songs);
}

static bool nativeSaveRegionOrder(
  ReaProject* project,
  const std::vector<NativeSongWindow>& songs)
{
  if (!project || !SetProjExtState_ptr || songs.empty()) return false;
  std::ostringstream order;
  for (size_t index = 0; index < songs.size(); ++index) {
    if (index) order << "\n";
    order << nativeRegionOrderIdentity(songs[index]);
  }
  const std::string encoded = order.str();
  if (nativeGetProjExtStateString(project,
        kPlaylistExtSection, kRegionOrderExtKey) == encoded) {
    return true;
  }
  SetProjExtState_ptr(project, kPlaylistExtSection,
    kRegionOrderExtKey, encoded.c_str());
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static std::vector<NativeSongWindow> nativeCollectProjectSongs(ReaProject* project, std::string& markersJsonOut)
{
  std::vector<NativeSongWindow> songs;
  struct MarkerEntry { bool region=false; double start=0.0; double end=0.0; std::string name; int number=0; int color=0; int enumIndex=-1; int rulerLane=-1; };
  std::vector<MarkerEntry> regions;
  std::vector<MarkerEntry> markers;

  markersJsonOut = "[]";
  if (!CountProjectMarkers_ptr || !EnumProjectMarkers3_ptr) return songs;

  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;

  for (int i = 0; i < total; ++i) {
    bool isRegion = false;
    double pos = 0.0;
    double end = 0.0;
    const char* name = "";
    int number = 0;
    int color = 0;
    const int ok = EnumProjectMarkers3_ptr(project, i, &isRegion, &pos, &end, &name, &number, &color);
    if (!ok) continue;
    MarkerEntry entry;
    entry.region = isRegion;
    entry.start = pos;
    entry.end = isRegion ? end : pos;
    entry.name = name ? name : "";
    entry.number = number;
    entry.color = color;
    entry.enumIndex = i;
    entry.rulerLane = isRegion ? nativeGetRegionRulerLaneNumber(project, i) : -1;
    if (entry.name.rfind("!", 0) == 0) continue;
    if (isRegion) regions.push_back(entry); else markers.push_back(entry);
  }

  std::sort(regions.begin(), regions.end(), [](const MarkerEntry& a, const MarkerEntry& b){ return a.start < b.start; });
  std::sort(markers.begin(), markers.end(), [](const MarkerEntry& a, const MarkerEntry& b){ return a.start < b.start; });

  std::ostringstream markersJson;
  markersJson << "[";
  for (size_t i = 0; i < markers.size(); ++i) {
    if (i) markersJson << ",";
    markersJson << "{";
    markersJson << "\"id\":" << nativeJsonString(std::string("m") + std::to_string(markers[i].number)) << ",";
    markersJson << "\"number\":" << markers[i].number << ",";
    markersJson << "\"name\":" << nativeJsonString(nativeCleanSongName(markers[i].name)) << ",";
    markersJson << "\"label\":" << nativeJsonString(nativeCleanSongName(markers[i].name)) << ",";
    markersJson << "\"pos\":" << nativeNumber(markers[i].start) << ",";
    markersJson << "\"position\":" << nativeNumber(markers[i].start);
    markersJson << "}";
  }
  markersJson << "]";
  markersJsonOut = markersJson.str();

  const double familyEpsilon = 0.0005;
  const auto regionIsNestedChildOfParent = [familyEpsilon](const MarkerEntry& child, const MarkerEntry& parent) {
    if (!child.region || !parent.region || child.enumIndex == parent.enumIndex) return false;
    const double childLength = child.end - child.start;
    const double parentLength = parent.end - parent.start;
    if (childLength <= familyEpsilon || parentLength <= familyEpsilon) return false;
    const double overlap = std::min(child.end, parent.end) - std::max(child.start, parent.start);
    if (overlap <= familyEpsilon) return false;
    if (child.rulerLane >= 0 || parent.rulerLane >= 0) {
      if (child.rulerLane != 1 || parent.rulerLane != 0) return false;
      return (overlap / childLength) >= 0.50;
    }
    return (overlap / childLength) >= 0.50;
  };

  const auto regionHasLaneTwoChildren = [&](const MarkerEntry& parent) {
    if (parent.rulerLane != 0) return false;
    for (const auto& child : regions) {
      if (child.rulerLane == 1 && regionIsNestedChildOfParent(child, parent)) return true;
    }
    return false;
  };

  const auto regionIsFamilyChild = [&](const MarkerEntry& child) {
    if (child.rulerLane != 1) return false;
    for (const auto& parent : regions) {
      if (parent.rulerLane == 0 && regionIsNestedChildOfParent(child, parent)) return true;
    }
    return false;
  };

  for (const auto& r : regions) {
    // A faixa Musicas/Filhos aparece apenas dentro da gaveta da regiao-pai.
    if (regionIsFamilyChild(r)) continue;

    const std::string clean = nativeCleanSongName(r.name);
    if (clean.empty()) continue;
    const bool hasLegacyMarkerChildren = nativeTrim(r.name).rfind("--", 0) == 0;
    const bool isHashParent = hasLegacyMarkerChildren || regionHasLaneTwoChildren(r);
    NativeSongWindow parent;
    parent.id = std::to_string(r.number);
    parent.name = clean;
    parent.type = isHashParent ? "hash_parent" : "song";
    parent.start = r.start;
    parent.end = r.end;
    parent.sourceNumber = r.number;
    parent.isHashParent = isHashParent;
    parent.enumIndex = r.enumIndex;
    parent.premixNumber = r.number;
    songs.push_back(parent);

    if (hasLegacyMarkerChildren) {
      std::vector<MarkerEntry> inside;
      for (const auto& m : markers) {
        if (m.start >= r.start - 0.0005 && m.start < r.end - 0.0005) {
          if (!m.name.empty() && m.name.rfind("$", 0) != 0 && m.name.rfind("*", 0) != 0) inside.push_back(m);
        }
      }
      for (size_t i = 0; i < inside.size(); ++i) {
        const auto& m = inside[i];
        const double childEnd = (i + 1 < inside.size()) ? inside[i + 1].start : r.end;
        if (childEnd <= m.start + 0.0005) continue;
        NativeSongWindow child;
        child.id = std::to_string(m.number);
        child.name = nativeCleanSongName(m.name);
        child.type = "hash_child";
        child.start = m.start;
        child.end = childEnd;
        child.sourceNumber = m.number;
        child.isHashChild = true;
        child.parentId = std::to_string(r.number);
        child.parentName = clean;
        child.enumIndex = m.enumIndex;
        child.parentEnumIndex = r.enumIndex;
        const int markerUid = m.enumIndex >= 0 ? m.enumIndex : m.number;
        child.premixNumber = 900000 + std::max(0, markerUid);
        if (!child.name.empty()) songs.push_back(child);
      }
    }

    if (isHashParent) {
      for (const auto& childRegion : regions) {
        if (childRegion.rulerLane != 1 || !regionIsNestedChildOfParent(childRegion, r)) continue;
        NativeSongWindow child;
        child.id = std::to_string(childRegion.number);
        child.name = nativeCleanSongName(childRegion.name);
        child.type = "hash_child";
        child.start = childRegion.start;
        child.end = childRegion.end;
        child.sourceNumber = childRegion.number;
        child.isHashChild = true;
        child.isRegionChild = true;
        child.parentId = std::to_string(r.number);
        child.parentName = clean;
        child.enumIndex = childRegion.enumIndex;
        child.parentEnumIndex = r.enumIndex;
        child.premixNumber = childRegion.number;
        if (!child.name.empty() && child.end > child.start + familyEpsilon) songs.push_back(child);
      }
    }
  }

  std::sort(songs.begin(), songs.end(), [](const NativeSongWindow& a, const NativeSongWindow& b){
    if (a.start == b.start) {
      if (a.isHashParent != b.isHashParent) return a.isHashParent;
      if (a.isHashChild != b.isHashChild) return !a.isHashChild;
      return a.end < b.end;
    }
    return a.start < b.start;
  });

  // A aba Musicas respeita a mesma ordem persistida pelo drag/drop do Lua.
  // Isso tambem faz a extensao nova manter a ordem depois de fechar o REAPER.
  nativeApplySavedRegionOrder(project, songs);

  // A extensão entrega a letra dos Empty Items direto para Diretor/Músicos.
  // O Lua não precisa mais escrever JSON pesado só para teleprompt/letras.
  for (auto& s : songs) {
    if (!s.isBlock) s.lyricsText = nativeCollectLyricsForRange(project, s.start, s.end);
  }
  return songs;
}


static std::string nativeUpperAscii(std::string value)
{
  std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c){ return static_cast<char>(std::toupper(c)); });
  return value;
}

static MediaTrack* nativeFindTrackByExactName(ReaProject* project, const std::string& wantedName, int* trackIndexOut = nullptr)
{
  if (trackIndexOut) *trackIndexOut = -1;
  if (!project || !CountTracks_ptr || !GetTrack_ptr || !GetTrackName_ptr) return nullptr;
  const std::string wanted = nativeUpperAscii(nativeTrim(wantedName));
  const int count = CountTracks_ptr(project);
  for (int i = 0; i < count; ++i) {
    MediaTrack* tr = GetTrack_ptr(project, i);
    if (!tr) continue;
    char nameBuf[512] = {0};
    if (!GetTrackName_ptr(tr, nameBuf, static_cast<int>(sizeof(nameBuf)))) continue;
    if (nativeUpperAscii(nativeTrim(nameBuf)) == wanted) {
      if (trackIndexOut) *trackIndexOut = i;
      return tr;
    }
  }
  return nullptr;
}

static void nativeDestroyBpmScanAccessor()
{
  if (g_nativeBpmScanJob.accessor && DestroyAudioAccessor_ptr) {
    DestroyAudioAccessor_ptr(g_nativeBpmScanJob.accessor);
  }
  g_nativeBpmScanJob = NativeBpmScanJob{};
}

static double nativeBpmNormalizeCandidate(double bpm)
{
  if (!std::isfinite(bpm) || bpm <= 0.0) return 0.0;
  while (bpm > 210.0) bpm *= 0.5;
  while (bpm < 55.0) bpm *= 2.0;
  return bpm >= 40.0 && bpm <= 240.0 ? bpm : 0.0;
}

static bool nativeEstimateBpmFromOnsetAutocorrelation(
  const std::vector<double>& onset,
  double onsetRate,
  double& bpmOut,
  int& confidenceOut)
{
  bpmOut = 0.0;
  confidenceOut = 0;
  if (onsetRate <= 0.0 || onset.size() < 32) return false;

  double maxOnset = 0.0;
  std::vector<double> sortedOnset = onset;
  for (double value : onset) maxOnset = std::max(maxOnset, value);
  if (maxOnset <= 0.000000001) return false;
  const size_t p95Index = std::min(
    sortedOnset.size() - 1,
    static_cast<size_t>(sortedOnset.size() * 0.95));
  std::nth_element(sortedOnset.begin(),
    sortedOnset.begin() + static_cast<long>(p95Index),
    sortedOnset.end());
  // Limitar os ataques muito fortes impede uma contagem ou uma virada isolada
  // de valer mais do que dezenas de batidas regulares do click.
  const double cap = std::max(maxOnset * 0.08,
    sortedOnset[p95Index] * 3.0);
  const size_t analysisFrames = std::min(onset.size(),
    static_cast<size_t>(std::ceil(onsetRate * 240.0)));
  std::vector<double> normalized(analysisFrames, 0.0);
  double mean = 0.0;
  for (size_t index = 0; index < analysisFrames; ++index) {
    normalized[index] = std::sqrt(std::max(0.0,
      std::min(onset[index], cap) / std::max(cap, 0.000000001)));
    mean += normalized[index];
  }
  mean /= static_cast<double>(analysisFrames);

  const int minLag = std::max(1, static_cast<int>(
    std::floor(onsetRate * 60.0 / 210.0)));
  const int maxLag = std::min(
    static_cast<int>(analysisFrames) - 2,
    static_cast<int>(std::ceil(onsetRate * 60.0 / 55.0)));
  if (maxLag <= minLag) return false;
  std::vector<double> scores(static_cast<size_t>(maxLag + 1), -1.0);
  int bestLag = 0;
  double bestScore = -1.0;
  for (int lag = minLag; lag <= maxLag; ++lag) {
    double cross = 0.0;
    double leftEnergy = 0.0;
    double rightEnergy = 0.0;
    for (size_t index = static_cast<size_t>(lag);
         index < analysisFrames; ++index) {
      const double left = normalized[index] - mean;
      const double right = normalized[index - static_cast<size_t>(lag)] - mean;
      cross += left * right;
      leftEnergy += left * left;
      rightEnergy += right * right;
    }
    const double energy = std::sqrt(leftEnergy * rightEnergy);
    const double score = energy > 0.000000001 ? cross / energy : -1.0;
    scores[static_cast<size_t>(lag)] = score;
    if (score > bestScore) {
      bestScore = score;
      bestLag = lag;
    }
  }
  if (bestLag <= 0 || bestScore < 0.015) return false;

  // Se a metade do atraso tem praticamente a mesma periodicidade, ela e a
  // batida real e o atraso maior e apenas o meio-tempo do mesmo click.
  for (int divisor = 2; divisor <= 3; ++divisor) {
    const int fasterLag = static_cast<int>(std::lround(
      static_cast<double>(bestLag) / divisor));
    if (fasterLag < minLag || fasterLag > maxLag) continue;
    const double fasterScore = scores[static_cast<size_t>(fasterLag)];
    if (fasterScore >= bestScore * 0.88) {
      bestLag = fasterLag;
      bestScore = fasterScore;
    }
  }

  double refinedLag = static_cast<double>(bestLag);
  if (bestLag > minLag && bestLag < maxLag) {
    const double left = scores[static_cast<size_t>(bestLag - 1)];
    const double center = scores[static_cast<size_t>(bestLag)];
    const double right = scores[static_cast<size_t>(bestLag + 1)];
    const double denominator = left - 2.0 * center + right;
    if (std::fabs(denominator) > 0.000000001) {
      refinedLag += std::max(-0.5, std::min(0.5,
        0.5 * (left - right) / denominator));
    }
  }
  const double bpm = nativeBpmNormalizeCandidate(
    60.0 * onsetRate / refinedLag);
  if (bpm <= 0.0) return false;

  double competingScore = -1.0;
  for (int lag = minLag; lag <= maxLag; ++lag) {
    if (std::abs(lag - bestLag) <= 4) continue;
    competingScore = std::max(competingScore,
      scores[static_cast<size_t>(lag)]);
  }
  const double separation = std::max(0.0,
    bestScore - std::max(0.0, competingScore));
  bpmOut = std::round(bpm);
  confidenceOut = std::max(1, std::min(100,
    static_cast<int>(std::lround(100.0 *
      (0.82 * std::max(0.0, bestScore) +
       0.18 * std::min(1.0, separation * 4.0))))));
  return true;
}

static bool nativeEstimateStableBpmFromPeaks(
  const std::vector<size_t>& peaks,
  double peakRate,
  double& bpmOut,
  int& confidenceOut,
  bool& tempoVariableOut)
{
  bpmOut = 0.0;
  confidenceOut = 0;
  tempoVariableOut = false;
  if (peakRate <= 0.0 || peaks.size() < 4) return false;

  struct TimedInterval {
    double seconds = 0.0;
    double midpointFrame = 0.0;
  };
  std::vector<TimedInterval> intervals;
  intervals.reserve(peaks.size() - 1);
  for (size_t index = 1; index < peaks.size(); ++index) {
    const double frames = static_cast<double>(
      peaks[index] - peaks[index - 1]);
    const double seconds = frames / peakRate;
    if (seconds < 0.16 || seconds > 2.5) continue;
    intervals.push_back({seconds,
      (static_cast<double>(peaks[index]) +
       static_cast<double>(peaks[index - 1])) * 0.5});
  }
  if (intervals.size() < 3) return false;

  auto robustIntervalMean = [](
      const std::vector<double>& values,
      double& meanOut,
      double& inlierRatioOut) -> bool {
    meanOut = 0.0;
    inlierRatioOut = 0.0;
    if (values.size() < 3) return false;
    std::vector<double> sorted = values;
    std::sort(sorted.begin(), sorted.end());
    const double median = sorted[sorted.size() / 2];
    if (!std::isfinite(median) || median <= 0.0) return false;
    const double minimum = median * 0.78;
    const double maximum = median * 1.22;
    double sum = 0.0;
    size_t count = 0;
    for (double value : values) {
      if (value < minimum || value > maximum) continue;
      sum += value;
      ++count;
    }
    if (count < 3) return false;
    meanOut = sum / static_cast<double>(count);
    inlierRatioOut = static_cast<double>(count) /
      static_cast<double>(values.size());
    return std::isfinite(meanOut) && meanOut > 0.0;
  };

  // Mede o tempo em janelas curtas e sobrepostas. Usar somente percentis de
  // janelas de 16 s deixava uma seção curta em outro andamento desaparecer
  // quando o BPM principal ocupava a maior parte da música.
  const double windowFrames = peakRate * 8.0;
  const double windowStepFrames = peakRate * 4.0;
  const double firstFrame = static_cast<double>(peaks.front());
  const double lastFrame = static_cast<double>(peaks.back());
  std::vector<double> windowBpms;
  for (double windowStart = firstFrame;
       windowStart < lastFrame;
       windowStart += windowStepFrames) {
    const double windowEnd = windowStart + windowFrames;
    std::vector<double> localIntervals;
    for (const TimedInterval& interval : intervals) {
      if (interval.midpointFrame >= windowStart &&
          interval.midpointFrame < windowEnd) {
        localIntervals.push_back(interval.seconds);
      }
    }
    if (localIntervals.size() < 4) continue;
    double localMean = 0.0;
    double localInlierRatio = 0.0;
    if (!robustIntervalMean(localIntervals,
          localMean, localInlierRatio) ||
        localInlierRatio < 0.62) {
      continue;
    }
    const double localBpm = nativeBpmNormalizeCandidate(
      60.0 / localMean);
    if (localBpm > 0.0) windowBpms.push_back(localBpm);
  }

  double windowSpread = 0.0;
  if (windowBpms.size() >= 3) {
    std::vector<double> sortedWindowBpms = windowBpms;
    std::sort(sortedWindowBpms.begin(), sortedWindowBpms.end());
    const size_t lowIndex = static_cast<size_t>(std::floor(
      static_cast<double>(sortedWindowBpms.size() - 1) * 0.20));
    const size_t highIndex = static_cast<size_t>(std::ceil(
      static_cast<double>(sortedWindowBpms.size() - 1) * 0.80));
    const double windowMedian =
      sortedWindowBpms[sortedWindowBpms.size() / 2];
    windowSpread =
      sortedWindowBpms[highIndex] - sortedWindowBpms[lowIndex];
    const double variableThreshold = std::max(
      2.0, windowMedian * 0.015);

    // Duas janelas sobrepostas equivalem a uma alteração sustentada por
    // aproximadamente 8 segundos. Uma única janela divergente é ignorada
    // como virada/contagem; duas ou mais já caracterizam outro andamento,
    // mesmo que todas as demais janelas pertençam ao BPM principal.
    int divergentWindows = 0;
    int consecutiveDivergent = 0;
    int maximumConsecutiveDivergent = 0;
    for (double localBpm : windowBpms) {
      if (std::fabs(localBpm - windowMedian) > variableThreshold) {
        ++divergentWindows;
        maximumConsecutiveDivergent = std::max(
          maximumConsecutiveDivergent, ++consecutiveDivergent);
      } else {
        consecutiveDivergent = 0;
      }
    }
    if (maximumConsecutiveDivergent >= 2 ||
        divergentWindows >= 3) {
      tempoVariableOut = true;
      return false;
    }
  }

  std::vector<double> allIntervals;
  allIntervals.reserve(intervals.size());
  for (const TimedInterval& interval : intervals) {
    allIntervals.push_back(interval.seconds);
  }
  double stableMean = 0.0;
  double stableRatio = 0.0;
  if (!robustIntervalMean(
        allIntervals, stableMean, stableRatio) ||
      stableRatio < 0.55) {
    return false;
  }
  const double bpm = nativeBpmNormalizeCandidate(60.0 / stableMean);
  if (bpm <= 0.0) return false;

  const double consistency = windowBpms.size() < 4
    ? 0.65
    : std::max(0.0, std::min(1.0,
        1.0 - windowSpread / std::max(2.0, bpm * 0.015)));
  const double countScore = std::min(1.0,
    static_cast<double>(intervals.size()) / 64.0);
  bpmOut = std::round(bpm);
  confidenceOut = std::max(1, std::min(100,
    static_cast<int>(std::lround(100.0 *
      (0.50 * stableRatio + 0.30 * consistency +
       0.20 * countScore)))));
  return true;
}

static NativeBpmScanResult nativeAnalyzeClickRegion(
  AudioAccessor* accessor,
  const NativeSongWindow& region)
{
  NativeBpmScanResult result;
  result.id = region.id;
  result.name = region.name;
  result.start = region.start;
  result.end = region.end;
  if (!accessor || !GetAudioAccessorSamples_ptr) {
    result.error = "audio_accessor_indisponivel";
    return result;
  }

  // 2 kHz eliminava grande parte do espectro de clicks agudos durante o
  // resample do accessor. 12 kHz preserva o ataque sem carregar o áudio na
  // resolução integral de 44.1/48 kHz.
  constexpr int sampleRate = 12000;
  constexpr int chunkSamples = 32768;
  constexpr double maxAnalysisSeconds = 600.0;
  const double duration = std::min(
    maxAnalysisSeconds,
    std::max(0.0, region.end - region.start));
  if (duration < 1.0) {
    result.error = "regiao_muito_curta";
    return result;
  }

  const size_t totalSamples = static_cast<size_t>(
    std::ceil(duration * sampleRate));
  std::vector<double> samples(totalSamples, 0.0);
  std::vector<double> interleaved(
    static_cast<size_t>(chunkSamples) * 2, 0.0);
  size_t offset = 0;
  bool anyAudioBlock = false;
  while (offset < totalSamples) {
    const int count = static_cast<int>(std::min<size_t>(
      chunkSamples, totalSamples - offset));
    const int read = GetAudioAccessorSamples_ptr(
      accessor, sampleRate, 2,
      region.start + static_cast<double>(offset) / sampleRate,
      count, interleaved.data());
    if (read < 0) {
      result.error = "falha_leitura_audio";
      return result;
    }
    if (read > 0) {
      anyAudioBlock = true;
      for (int index = 0; index < count; ++index) {
        samples[offset + static_cast<size_t>(index)] = std::max(
          std::fabs(interleaved[static_cast<size_t>(index) * 2]),
          std::fabs(interleaved[static_cast<size_t>(index) * 2 + 1]));
      }
    }
    offset += static_cast<size_t>(count);
  }
  if (!anyAudioBlock) {
    result.error = "sem_audio_na_regiao";
    return result;
  }

  // Envelope de 5 ms: mantém o ataque curto do click e reduz drasticamente
  // a quantidade de pontos usados pela detecção de transientes.
  constexpr int envelopeWindowSamples = 60;
  std::vector<double> envelope;
  envelope.reserve(
    (totalSamples + envelopeWindowSamples - 1) /
      envelopeWindowSamples);
  double maxAmplitude = 0.0;
  for (size_t begin = 0; begin < totalSamples;
       begin += envelopeWindowSamples) {
    const size_t end = std::min(
      totalSamples, begin + envelopeWindowSamples);
    double peak = 0.0;
    for (size_t index = begin; index < end; ++index) {
      peak = std::max(peak, std::fabs(samples[index]));
    }
    maxAmplitude = std::max(maxAmplitude, peak);
    envelope.push_back(peak);
  }
  samples.clear();
  samples.shrink_to_fit();
  if (maxAmplitude < 0.000001 || envelope.size() < 8) {
    result.error = "audio_sem_picos";
    return result;
  }

  constexpr double envelopeRate =
    static_cast<double>(sampleRate) / envelopeWindowSamples;
  // Mede a subida em relação aos 100 ms anteriores, em vez de exigir que o
  // click seja uma porcentagem fixa do maior pico da música. Isso mantém o
  // click detectável em arquivos CLICK BASE e diante de uma contagem forte.
  constexpr size_t baselineFrames = 20;
  std::vector<double> onset(envelope.size(), 0.0);
  double baselineSum = 0.0;
  double maxOnset = 0.0;
  for (size_t index = 0; index < envelope.size(); ++index) {
    const size_t baselineCount = std::min(index, baselineFrames);
    const double baseline = baselineCount > 0
      ? baselineSum / static_cast<double>(baselineCount)
      : envelope[index];
    onset[index] = std::max(0.0, envelope[index] - baseline);
    maxOnset = std::max(maxOnset, onset[index]);
    baselineSum += envelope[index];
    if (index >= baselineFrames) {
      baselineSum -= envelope[index - baselineFrames];
    }
  }
  if (maxOnset <= 0.000000001) {
    result.error = "audio_sem_picos";
    return result;
  }
  std::vector<double> sortedOnset = onset;
  const size_t p90Index = std::min(
    sortedOnset.size() - 1,
    static_cast<size_t>(sortedOnset.size() * 0.90));
  const size_t p98Index = std::min(
    sortedOnset.size() - 1,
    static_cast<size_t>(sortedOnset.size() * 0.98));
  std::nth_element(sortedOnset.begin(),
    sortedOnset.begin() + static_cast<long>(p90Index),
    sortedOnset.end());
  const double p90 = sortedOnset[p90Index];
  std::nth_element(sortedOnset.begin(),
    sortedOnset.begin() + static_cast<long>(p98Index),
    sortedOnset.end());
  const double p98 = sortedOnset[p98Index];
  const double threshold = std::max(maxOnset * 0.003,
    std::min(maxOnset * 0.25, p90 + (p98 - p90) * 0.20));

  const size_t refractoryFrames = static_cast<size_t>(
    std::ceil(0.075 * envelopeRate));
  std::vector<size_t> peaks;
  std::vector<double> peakStrengths;
  for (size_t index = 2; index + 2 < onset.size(); ++index) {
    const double value = onset[index];
    if (value < threshold || value < onset[index - 1] ||
        value < onset[index + 1] ||
        value < onset[index - 2] ||
        value < onset[index + 2]) {
      continue;
    }
    if (!peaks.empty() && index - peaks.back() < refractoryFrames) {
      if (value > peakStrengths.back()) {
        peaks.back() = index;
        peakStrengths.back() = value;
      }
      continue;
    }
    peaks.push_back(index);
    peakStrengths.push_back(value);
  }
  result.detectedPeaks = static_cast<int>(peaks.size());
  bool tempoVariable = false;
  if (nativeEstimateStableBpmFromPeaks(
        peaks, envelopeRate, result.bpm,
        result.confidence, tempoVariable)) {
    return result;
  }
  if (tempoVariable) {
    // Não existe um BPM único correto. Mantém o aviso, mas fornece um ponto
    // de partida editável para a coluna BPM e para os controles +/-.
    result.bpm = 120.0;
    result.confidence = 0;
    result.error = "alteracao_bpm_nao_encontrada";
    return result;
  }
  if (peaks.size() < 4) {
    if (nativeEstimateBpmFromOnsetAutocorrelation(
          onset, envelopeRate, result.bpm, result.confidence)) {
      return result;
    }
    result.error = "picos_insuficientes";
    return result;
  }

  std::vector<double> candidates;
  candidates.reserve(peaks.size() - 1);
  std::map<int, int> histogram;
  for (size_t index = 1; index < peaks.size(); ++index) {
    const double interval =
      static_cast<double>(peaks[index] - peaks[index - 1]) /
        envelopeRate;
    if (interval < 0.16 || interval > 2.5) continue;
    const double candidate = nativeBpmNormalizeCandidate(60.0 / interval);
    if (candidate <= 0.0) continue;
    candidates.push_back(candidate);
    ++histogram[static_cast<int>(std::lround(candidate * 2.0))];
  }
  if (candidates.size() < 3 || histogram.empty()) {
    if (nativeEstimateBpmFromOnsetAutocorrelation(
          onset, envelopeRate, result.bpm, result.confidence)) {
      return result;
    }
    result.error = "ritmo_insuficiente";
    return result;
  }

  int bestBin = histogram.begin()->first;
  int bestVotes = -1;
  for (const auto& entry : histogram) {
    int nearbyVotes = 0;
    for (int delta = -3; delta <= 3; ++delta) {
      const auto nearby = histogram.find(entry.first + delta);
      if (nearby != histogram.end()) nearbyVotes += nearby->second;
    }
    if (nearbyVotes > bestVotes ||
        (nearbyVotes == bestVotes && entry.first < bestBin)) {
      bestVotes = nearbyVotes;
      bestBin = entry.first;
    }
  }

  const double coarseBpm = static_cast<double>(bestBin) / 2.0;
  std::vector<double> inliers;
  for (double candidate : candidates) {
    if (std::fabs(candidate - coarseBpm) <= 2.0) {
      inliers.push_back(candidate);
    }
  }
  if (inliers.size() < 3) {
    if (nativeEstimateBpmFromOnsetAutocorrelation(
          onset, envelopeRate, result.bpm, result.confidence)) {
      return result;
    }
    result.error = "ritmo_inconsistente";
    return result;
  }
  std::sort(inliers.begin(), inliers.end());
  double bpm = inliers[inliers.size() / 2];
  if ((inliers.size() % 2) == 0) {
    bpm = (inliers[inliers.size() / 2 - 1] + bpm) * 0.5;
  }

  std::vector<double> deviations;
  deviations.reserve(inliers.size());
  for (double value : inliers) {
    deviations.push_back(std::fabs(value - bpm) /
      std::max(1.0, bpm));
  }
  std::sort(deviations.begin(), deviations.end());
  const double medianDeviation = deviations[deviations.size() / 2];
  const double inlierRatio = static_cast<double>(inliers.size()) /
    static_cast<double>(candidates.size());
  const double consistency = std::max(0.0,
    std::min(1.0, 1.0 - medianDeviation / 0.035));
  const double countScore = std::min(1.0,
    static_cast<double>(candidates.size()) / 16.0);
  const double prominence = std::max(0.0, std::min(1.0,
    (maxOnset - threshold) / std::max(0.000001, maxOnset)));

  result.bpm = std::round(bpm);
  result.confidence = std::max(1, std::min(100,
    static_cast<int>(std::lround(100.0 *
      (0.55 * inlierRatio + 0.25 * consistency +
       0.15 * countScore + 0.05 * prominence)))));
  return result;
}

static bool nativeApplyBpmScanCommand(const std::string& commandBody)
{
  const std::string type = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "type")));
  if (type != "bpm_scan_regions" &&
      type != "scan_click_bpm") {
    return false;
  }

  nativeDestroyBpmScanAccessor();
  g_nativeBpmScanResults.clear();
  g_nativeBpmScanResultProject = nullptr;
  g_nativeBpmScanError.clear();
  g_nativeBpmScanTotal = 0;
  g_nativeBpmReplaceAllTempoMarkersOnApply = false;
  g_nativeBpmScanRequestId = nativeJsonExtractString(
    commandBody, "scanRequestId");
  ++g_nativeBpmScanRevision;
  g_nativeBpmScanRunning = false;

  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) {
    g_nativeBpmScanError = "projeto_indisponivel";
    g_nativeForceStateBuild.store(true);
    return true;
  }
  g_nativeBpmScanResultProject = project;
  const bool forceRescan =
    commandBody.find("\"forceRescan\":true") != std::string::npos;
  g_nativeBpmReplaceAllTempoMarkersOnApply = forceRescan;

  const std::vector<std::string> rawIds = nativeSplit(
    nativeJsonExtractString(commandBody, "regionIds"), '|');
  std::set<std::string> requestedIds;
  for (const std::string& rawId : rawIds) {
    const std::string id = nativeTrim(rawId);
    if (!id.empty()) requestedIds.insert(id);
  }

  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  std::vector<NativeSongWindow> selectedSongs;
  for (const NativeSongWindow& song : songs) {
    // Região filha segue exatamente a mesma análise de uma região solta.
    // Somente o pai fica fora: cada filha receberá seu marcador próprio.
    if (song.isBlock || song.isHashParent ||
        song.end <= song.start + 0.0005) {
      continue;
    }
    if (requestedIds.find(song.id) == requestedIds.end()) continue;
    selectedSongs.push_back(song);
  }
  if (selectedSongs.empty()) {
    g_nativeBpmScanError = "nenhuma_regiao_selecionada";
    g_nativeForceStateBuild.store(true);
    return true;
  }
  g_nativeBpmScanTotal = selectedSongs.size();

  const std::map<std::string, NativeBpmScanResult> cache =
    nativeLoadBpmScanCache(project);
  for (const NativeSongWindow& song : selectedSongs) {
    const auto cached = cache.find(song.id);
    const bool sameSong = cached != cache.end();
    if (!forceRescan && sameSong) {
      NativeBpmScanResult result = cached->second;
      // A posição e o nome vêm sempre da região atual. O valor analisado é
      // reaproveitado mesmo quando a região foi movida no projeto.
      result.name = song.name;
      result.start = song.start;
      result.end = song.end;
      g_nativeBpmScanResults.push_back(result);
    } else {
      g_nativeBpmScanJob.regions.push_back(song);
    }
  }
  if (g_nativeBpmScanJob.regions.empty()) {
    g_nativeBpmScanRunning = false;
    ++g_nativeBpmScanRevision;
    g_nativeForceStateBuild.store(true);
    return true;
  }

  MediaTrack* clickTrack = nativeFindTrackByExactName(project, "CLICK");
  if (!clickTrack) {
    nativePublishGenericBpmScanResults(project,
      g_nativeBpmScanJob.regions, "pista_click_nao_encontrada");
    return true;
  }
  if (!CreateTrackAudioAccessor_ptr || !DestroyAudioAccessor_ptr ||
      !GetAudioAccessorSamples_ptr) {
    nativePublishGenericBpmScanResults(project,
      g_nativeBpmScanJob.regions, "audio_accessor_indisponivel");
    return true;
  }

  AudioAccessor* accessor = CreateTrackAudioAccessor_ptr(clickTrack);
  if (!accessor) {
    nativePublishGenericBpmScanResults(project,
      g_nativeBpmScanJob.regions, "falha_abrir_pista_click");
    return true;
  }
  g_nativeBpmScanJob.project = project;
  g_nativeBpmScanJob.clickTrack = clickTrack;
  g_nativeBpmScanJob.accessor = accessor;
  g_nativeBpmScanJob.nextIndex = 0;
  g_nativeBpmScanRunning = true;
  g_nativeForceStateBuild.store(true);
  return true;
}

static void nativeProcessBpmScanJobOnMainThread()
{
  if (!g_nativeBpmScanRunning) return;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || project != g_nativeBpmScanJob.project) {
    g_nativeBpmScanError = "projeto_trocado_durante_scan";
    g_nativeBpmScanRunning = false;
    ++g_nativeBpmScanRevision;
    nativeDestroyBpmScanAccessor();
    g_nativeForceStateBuild.store(true);
    return;
  }
  if (g_nativeBpmScanJob.nextIndex >=
      g_nativeBpmScanJob.regions.size()) {
    g_nativeBpmScanRunning = false;
    ++g_nativeBpmScanRevision;
    nativeDestroyBpmScanAccessor();
    g_nativeForceStateBuild.store(true);
    return;
  }

  const NativeSongWindow region =
    g_nativeBpmScanJob.regions[g_nativeBpmScanJob.nextIndex];
  NativeBpmScanResult result =
    nativeAnalyzeClickRegion(g_nativeBpmScanJob.accessor, region);
  nativeEnsureGenericBpmFallback(result);
  if (nativeBpmScanResultHasUsableValue(result)) {
    result.originalBpm = std::round(result.bpm);
  }
  auto existing = std::find_if(g_nativeBpmScanResults.begin(),
    g_nativeBpmScanResults.end(), [&](const NativeBpmScanResult& item) {
      return item.id == result.id;
    });
  if (existing == g_nativeBpmScanResults.end()) {
    g_nativeBpmScanResults.push_back(result);
  } else {
    *existing = result;
  }
  nativeSaveBpmScanCacheResult(project, result);
  ++g_nativeBpmScanJob.nextIndex;
  ++g_nativeBpmScanRevision;
  if (g_nativeBpmScanJob.nextIndex >=
      g_nativeBpmScanJob.regions.size()) {
    g_nativeBpmScanRunning = false;
    nativeDestroyBpmScanAccessor();
  }
  g_nativeForceStateBuild.store(true);
}

using NativeTempoMarkerBpmValues =
  std::vector<std::pair<double, double>>;

// Ao editar um ponto de tempo diretamente na régua, o REAPER pode
// normalizar sua posição com uma pequena diferença de ponto flutuante. A
// associação da música não pode desaparecer por causa desses poucos ms.
static constexpr double kNativeBpmTempoMarkerMatchToleranceSec = 0.050;

static NativeTempoMarkerBpmValues nativeCollectTempoMarkerBpmValues(
  ReaProject* project)
{
  NativeTempoMarkerBpmValues values;
  if (!project || !CountTempoTimeSigMarkers_ptr ||
      !GetTempoTimeSigMarker_ptr) {
    return values;
  }
  const int count = CountTempoTimeSigMarkers_ptr(project);
  values.reserve(static_cast<size_t>(std::max(0, count)));
  for (int index = 0; index < count; ++index) {
    double position = 0.0;
    double beatPosition = 0.0;
    double bpm = 0.0;
    int measurePosition = 0;
    int numerator = 0;
    int denominator = 0;
    bool linearTempo = false;
    if (!GetTempoTimeSigMarker_ptr(project, index, &position,
          &measurePosition, &beatPosition, &bpm, &numerator,
          &denominator, &linearTempo) ||
        !std::isfinite(position) || !std::isfinite(bpm) || bpm <= 0.0) {
      continue;
    }
    values.emplace_back(position, bpm);
  }
  return values;
}

static uint64_t nativeTempoMarkerBpmValuesSignature(
  const NativeTempoMarkerBpmValues& values)
{
  uint64_t hash = 1469598103934665603ull;
  const auto mixDouble = [&](double value) {
    uint64_t bits = 0;
    static_assert(sizeof(bits) == sizeof(value),
      "double e uint64_t precisam ter o mesmo tamanho");
    std::memcpy(&bits, &value, sizeof(bits));
    hash ^= bits;
    hash *= 1099511628211ull;
  };
  hash ^= static_cast<uint64_t>(values.size());
  hash *= 1099511628211ull;
  for (const auto& value : values) {
    mixDouble(value.first);
    mixDouble(value.second);
  }
  return hash;
}

static bool nativeTempoMarkerBpmAtOrBeforePosition(
  const NativeTempoMarkerBpmValues& values,
  double position,
  double& bpmOut,
  double* markerPositionOut = nullptr)
{
  if (!std::isfinite(position)) return false;
  double nearestPosition = -std::numeric_limits<double>::infinity();
  bool found = false;
  for (const auto& value : values) {
    // Nunca herda um ponto que já esteja dentro da região. A margem de meio
    // milissegundo cobre apenas a normalização numérica do próprio início.
    if (value.first > position + 0.0005 ||
        value.first < nearestPosition) {
      continue;
    }
    nearestPosition = value.first;
    bpmOut = value.second;
    found = true;
  }
  if (found && markerPositionOut) {
    *markerPositionOut = nearestPosition;
  }
  return found;
}

static bool nativeTempoMarkerBpmAtOrBeforePosition(
  ReaProject* project,
  double position,
  double& bpmOut,
  double* markerPositionOut = nullptr)
{
  return nativeTempoMarkerBpmAtOrBeforePosition(
    nativeCollectTempoMarkerBpmValues(project), position, bpmOut,
    markerPositionOut);
}

static std::vector<NativeSongWindow> nativeUiBpmScanEligibleSongs()
{
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  songs.erase(std::remove_if(songs.begin(), songs.end(),
    [](const NativeSongWindow& song) {
      return song.isBlock || song.isHashParent ||
        song.end <= song.start + 0.0005;
    }), songs.end());
  return songs;
}

static bool nativeUiFindBpmScanSong(
  const std::string& id,
  NativeSongWindow& songOut)
{
  if (id.empty()) return false;
  for (const NativeSongWindow& song :
       nativeUiBpmScanEligibleSongs()) {
    if (song.id != id) continue;
    songOut = song;
    return true;
  }
  return false;
}

static bool nativeUiSelectBpmScanResult(const std::string& id)
{
  NativeSongWindow song;
  if (!nativeUiFindBpmScanSong(id, song)) return false;
  g_nativeUiBpmScanSelectedId = song.id;
  std::ostringstream command;
  command << "{\"type\":\"select_region\",\"targetId\":"
          << nativeJsonString(song.id)
          << ",\"songId\":" << nativeJsonString(song.id)
          << ",\"startPos\":" << std::setprecision(15) << song.start
          << ",\"endPos\":" << std::setprecision(15) << song.end
          << ",\"activeTab\":\"regions\",\"page\":\"regions\"}";
  return nativeApplySelectionCommand(command.str());
}

static bool nativeUiToggleBpmScanPreviewPlayback()
{
  NativeSongWindow song;
  if (!nativeUiFindBpmScanSong(
        g_nativeUiBpmScanSelectedId, song)) {
    nativeUiShowTemporaryPopup(
      "SELECIONE UMA MÚSICA NO RESULTADO", 1.6);
    return true;
  }

  const bool transportActive = nativeUiTransportActive();
  if (!nativePlayProtectionShouldAllow(
        transportActive ? "stop" : "play")) {
    return true;
  }

  // Remove qualquer fila anterior antes da audição e mantém o bloqueio ativo
  // enquanto esse transporte estiver rodando. O estado do Auto não é alterado.
  nativeApplyQueueCommand("{\"type\":\"clear_queue\"}");
  g_nativeBpmScanPreviewPlaybackActive = true;
  std::ostringstream command;
  command << "{\"type\":\""
          << (transportActive ? "stop" : "play_start") << "\""
          << ",\"targetId\":" << nativeJsonString(song.id)
          << ",\"songId\":" << nativeJsonString(song.id)
          << ",\"startPos\":" << std::setprecision(15) << song.start
          << ",\"endPos\":" << std::setprecision(15) << song.end
          << ",\"activeTab\":\"regions\",\"page\":\"regions\""
          << ",\"suppressAutoQueue\":true}";
  return nativeApplyTransportCommand(command.str());
}

static std::string nativeUiBpmScanErrorText(const std::string& error)
{
  if (error == "projeto_indisponivel") return "PROJETO INDISPONÍVEL";
  if (error == "nenhuma_regiao_selecionada") return "NENHUMA REGIÃO SELECIONADA";
  if (error == "pista_click_nao_encontrada") return "PISTA CLICK NÃO ENCONTRADA";
  if (error == "audio_accessor_indisponivel") return "LEITURA DE ÁUDIO INDISPONÍVEL";
  if (error == "falha_abrir_pista_click") return "NÃO FOI POSSÍVEL ABRIR A PISTA CLICK";
  if (error == "projeto_trocado_durante_scan") return "A SESSÃO MUDOU DURANTE O SCAN";
  if (error == "regiao_muito_curta") return "REGIÃO MUITO CURTA";
  if (error == "falha_leitura_audio") return "FALHA AO LER O ÁUDIO";
  if (error == "sem_audio_na_regiao") return "SEM ÁUDIO NA PISTA CLICK";
  if (error == "audio_sem_picos") return "NENHUM PICO ENCONTRADO";
  if (error == "picos_insuficientes") return "POUCOS PICOS ENCONTRADOS";
  if (error == "ritmo_insuficiente") return "RITMO INSUFICIENTE";
  if (error == "ritmo_inconsistente") return "RITMO INCONSISTENTE";
  if (error == "alteracao_bpm_nao_encontrada") {
    return "TEMPO VARIÁVEL, NÃO ENCONTRADO";
  }
  return error;
}

static std::vector<NativeBpmScanResult>
nativeUiLoadScannedBpmResults(ReaProject* project)
{
  std::vector<NativeBpmScanResult> results;
  if (!project) return results;
  const std::map<std::string, NativeBpmScanResult> cache =
    nativeLoadBpmScanCache(project);
  const NativeTempoMarkerBpmValues tempoMarkers =
    nativeCollectTempoMarkerBpmValues(project);
  for (const NativeSongWindow& song : nativeUiBpmScanEligibleSongs()) {
    const auto found = cache.find(song.id);
    NativeBpmScanResult result;
    const bool cached = found != cache.end();
    if (cached) result = found->second;
    result.name = song.name;
    result.id = song.id;
    result.start = song.start;
    result.end = song.end;
    double markerBpm = 0.0;
    const bool markerFound =
      nativeTempoMarkerBpmAtOrBeforePosition(
        tempoMarkers, song.start, markerBpm);
    if (!cached && !markerFound) continue;
    if (markerFound) {
      result.bpm = std::round(markerBpm);
      if (!cached) {
        // Um marcador existente é uma leitura exata do projeto, não um
        // fallback genérico. Ele entra em SCANEADAS com confiança total.
        result.originalBpm = result.bpm;
        result.confidence = 100;
        result.detectedPeaks = 0;
        result.error.clear();
      }
    }
    results.push_back(result);
  }
  return results;
}

static void nativeUiRefreshScannedBpmAvailability()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  g_nativeUiBpmScannedAvailable =
    !nativeUiLoadScannedBpmResults(project).empty();
}

static bool nativeUiOpenScannedBpmResults()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  std::vector<NativeBpmScanResult> results =
    nativeUiLoadScannedBpmResults(project);
  g_nativeUiBpmScannedAvailable = !results.empty();
  if (results.empty()) {
    nativeUiShowTemporaryPopup(
      "NENHUMA MÚSICA ESCANEADA AINDA", 1.8);
    return false;
  }

  g_nativeBpmScanRunning = false;
  nativeDestroyBpmScanAccessor();
  g_nativeBpmReplaceAllTempoMarkersOnApply = false;
  g_nativeBpmScanResults = std::move(results);
  g_nativeBpmScanResultProject = project;
  g_nativeBpmScanError.clear();
  g_nativeBpmScanTotal = g_nativeBpmScanResults.size();
  g_nativeUiBpmScanSelectedId.clear();
  g_nativeUiBpmScanScroll = 0;
  g_nativeMainModalKind = NativeMainModalKind::BpmScanResults;
  return true;
}

static void nativeUiOpenBpmScan(bool forceRescan = false)
{
  g_nativeBpmScanRunning = false;
  nativeDestroyBpmScanAccessor();
  g_nativeBpmScanResults.clear();
  g_nativeBpmScanResultProject = nullptr;
  g_nativeBpmScanError.clear();
  g_nativeBpmScanTotal = 0;
  g_nativeUiBpmScanSelection.clear();
  g_nativeUiBpmScanSelectedId.clear();
  g_nativeUiBpmScanForceRescan = forceRescan;
  g_nativeBpmReplaceAllTempoMarkersOnApply = false;
  nativeUiRefreshScannedBpmAvailability();
  g_nativeUiBpmScanScroll = 0;
  g_nativeMainModalKind = NativeMainModalKind::BpmScanSelect;
}

static bool nativeUiStartBpmScan()
{
  if (g_nativeUiBpmScanSelection.empty()) {
    nativeUiShowTemporaryPopup("SELECIONE PELO MENOS UMA MÚSICA", 1.5);
    return false;
  }
  std::ostringstream ids;
  bool first = true;
  for (const NativeSongWindow& song : nativeUiBpmScanEligibleSongs()) {
    if (g_nativeUiBpmScanSelection.find(song.id) ==
        g_nativeUiBpmScanSelection.end()) continue;
    if (!first) ids << '|';
    first = false;
    ids << song.id;
  }
  if (first) {
    nativeUiShowTemporaryPopup("NENHUMA REGIÃO DISPONÍVEL", 1.5);
    return false;
  }
  std::ostringstream command;
  command << "{\"type\":\"bpm_scan_regions\",\"regionIds\":"
          << nativeJsonString(ids.str()) << ",\"scanRequestId\":"
          << nativeJsonString(std::to_string(
               std::chrono::duration_cast<std::chrono::milliseconds>(
                 std::chrono::steady_clock::now().time_since_epoch()).count()))
          << ",\"forceRescan\":"
          << (g_nativeUiBpmScanForceRescan ? "true" : "false")
          << "}";
  nativeApplyBpmScanCommand(command.str());
  g_nativeUiBpmScanForceRescan = false;
  g_nativeUiBpmScanScroll = 0;
  g_nativeMainModalKind = NativeMainModalKind::BpmScanResults;
  return true;
}

static int nativeFindTempoMarkerAtPosition(
  ReaProject* project,
  double position)
{
  if (!project || !CountTempoTimeSigMarkers_ptr ||
      !GetTempoTimeSigMarker_ptr) {
    return -1;
  }
  const int count = CountTempoTimeSigMarkers_ptr(project);
  int nearestIndex = -1;
  double nearestDistance =
    kNativeBpmTempoMarkerMatchToleranceSec + 1.0;
  for (int index = 0; index < count; ++index) {
    double markerPosition = 0.0;
    double beatPosition = 0.0;
    double bpm = 0.0;
    int measurePosition = 0;
    int numerator = 0;
    int denominator = 0;
    bool linearTempo = false;
    if (!GetTempoTimeSigMarker_ptr(project, index, &markerPosition,
          &measurePosition, &beatPosition, &bpm, &numerator,
          &denominator, &linearTempo)) {
      continue;
    }
    const double distance = std::fabs(markerPosition - position);
    if (distance <= kNativeBpmTempoMarkerMatchToleranceSec &&
        distance < nearestDistance) {
      nearestDistance = distance;
      nearestIndex = index;
    }
  }
  return nearestIndex;
}

static int nativeFindTempoMarkerAtOrBeforePosition(
  ReaProject* project,
  double position)
{
  if (!project || !CountTempoTimeSigMarkers_ptr ||
      !GetTempoTimeSigMarker_ptr || !std::isfinite(position)) {
    return -1;
  }
  const int count = CountTempoTimeSigMarkers_ptr(project);
  int nearestIndex = -1;
  double nearestPosition = -std::numeric_limits<double>::infinity();
  for (int index = 0; index < count; ++index) {
    double markerPosition = 0.0;
    double beatPosition = 0.0;
    double bpm = 0.0;
    int measurePosition = 0;
    int numerator = 0;
    int denominator = 0;
    bool linearTempo = false;
    if (!GetTempoTimeSigMarker_ptr(project, index, &markerPosition,
          &measurePosition, &beatPosition, &bpm, &numerator,
          &denominator, &linearTempo)) {
      continue;
    }
    if (markerPosition <= position + 0.0005 &&
        markerPosition >= nearestPosition) {
      nearestPosition = markerPosition;
      nearestIndex = index;
    }
  }
  return nearestIndex;
}

static bool nativeUpdateTempoMarkerBpmByIndex(
  ReaProject* project,
  int markerIndex,
  double bpm)
{
  if (!project || markerIndex < 0 || !GetTempoTimeSigMarker_ptr ||
      !SetTempoTimeSigMarker_ptr || !std::isfinite(bpm) || bpm <= 0.0) {
    return false;
  }
  double markerPosition = 0.0;
  double beatPosition = 0.0;
  double oldBpm = 0.0;
  int measurePosition = 0;
  int numerator = 0;
  int denominator = 0;
  bool linearTempo = false;
  if (!GetTempoTimeSigMarker_ptr(project, markerIndex,
        &markerPosition, &measurePosition, &beatPosition, &oldBpm,
        &numerator, &denominator, &linearTempo)) {
    return false;
  }
  return SetTempoTimeSigMarker_ptr(project, markerIndex,
    markerPosition, -1, -1.0, bpm, numerator, denominator,
    linearTempo);
}

static bool nativeSetTempoMarkerAtPosition(
  ReaProject* project,
  double position,
  double bpm)
{
  if (!project || !SetTempoTimeSigMarker_ptr ||
      !std::isfinite(position) || !std::isfinite(bpm) || bpm <= 0.0) {
    return false;
  }
  const int existingIndex = nativeFindTempoMarkerAtPosition(
    project, position);
  if (existingIndex < 0) {
    return SetTempoTimeSigMarker_ptr(project, -1, position,
      -1, -1.0, bpm, 0, 0, false);
  }

  double oldPosition = position;
  double oldBeatPosition = 0.0;
  double oldBpm = bpm;
  int oldMeasurePosition = -1;
  int numerator = 0;
  int denominator = 0;
  bool linearTempo = false;
  if (!GetTempoTimeSigMarker_ptr(project, existingIndex,
        &oldPosition, &oldMeasurePosition, &oldBeatPosition, &oldBpm,
        &numerator, &denominator, &linearTempo)) {
    return false;
  }
  return SetTempoTimeSigMarker_ptr(project, existingIndex, position,
    -1, -1.0, bpm, numerator, denominator, linearTempo);
}

static bool nativeSetProjectItemsTimebase(
  ReaProject* project,
  int timebase)
{
  if (!project || !projectconfig_var_getoffs_ptr ||
      !projectconfig_var_addr_ptr || timebase < 0 || timebase > 2) {
    return false;
  }
  int valueSize = 0;
  const int offset = projectconfig_var_getoffs_ptr(
    "itemtimelock", &valueSize);
  if (offset == 0 || valueSize != static_cast<int>(sizeof(int))) {
    return false;
  }
  void* address = projectconfig_var_addr_ptr(project, offset);
  if (!address) return false;
  *reinterpret_cast<int*>(address) = timebase;

  // PROJECT_TIMEBASE é somente leitura, mas serve para confirmar que a
  // alteração da variável de projeto realmente entrou antes de continuar.
  if (GetSetProjectInfo_ptr) {
    const int confirmed = static_cast<int>(std::lround(
      GetSetProjectInfo_ptr(project, "PROJECT_TIMEBASE", 0.0, false)));
    return confirmed == timebase;
  }
  return true;
}

static bool nativeUiBpmSongIsCurrentlyPlaying(const std::string& id)
{
  return g_nativeCurrentTransportPlaying && !id.empty() &&
    id == g_nativeCurrentPlayingId;
}

static bool nativeUiApplyBpmScanResults()
{
  if (g_nativeBpmScanRunning) {
    nativeUiShowTemporaryPopup("AGUARDE O SCAN TERMINAR", 1.5);
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || project != g_nativeBpmScanResultProject) {
    nativeUiShowTemporaryPopup(
      "O RESULTADO PERTENCE A OUTRA SESSÃO", 2.0);
    return false;
  }
  if (!CountTempoTimeSigMarkers_ptr ||
      !GetTempoTimeSigMarker_ptr || !SetTempoTimeSigMarker_ptr) {
    nativeUiShowTemporaryPopup(
      "API DE MARCADORES DE TEMPO INDISPONÍVEL", 2.0);
    return false;
  }
  const bool replaceAllTempoMarkers =
    g_nativeBpmReplaceAllTempoMarkersOnApply;
  if (replaceAllTempoMarkers && !DeleteTempoTimeSigMarker_ptr) {
    nativeUiShowTemporaryPopup(
      "API PARA RECRIAR MARCADORES INDISPONÍVEL", 2.2);
    return false;
  }
  if (replaceAllTempoMarkers && nativeUiTransportActive()) {
    nativeUiShowTemporaryPopup(
      "PARE A REPRODUÇÃO ANTES DE RECRIAR OS MARCADORES", 2.2);
    return false;
  }

  std::vector<NativeBpmScanResult> applicable;
  for (const NativeBpmScanResult& result : g_nativeBpmScanResults) {
    if (!nativeBpmScanResultHasUsableValue(result) ||
        !std::isfinite(result.start) ||
        nativeUiBpmSongIsCurrentlyPlaying(result.id)) {
      continue;
    }
    applicable.push_back(result);
  }
  if (applicable.empty()) {
    nativeUiShowTemporaryPopup("NENHUM BPM VÁLIDO PARA APLICAR", 1.8);
    return false;
  }
  std::sort(applicable.begin(), applicable.end(),
    [](const NativeBpmScanResult& left,
       const NativeBpmScanResult& right) {
      return left.start < right.start;
  });

  if (Undo_BeginBlock2_ptr) Undo_BeginBlock2_ptr(project);
  // Durante a criação do mapa as posições precisam ficar ancoradas em tempo.
  // itemtimelock: 0=Time, 1=Beats (position, length, rate), 2=position only.
  if (!nativeSetProjectItemsTimebase(project, 0)) {
    if (Undo_EndBlock2_ptr) {
      Undo_EndBlock2_ptr(project,
        "VS Hook: aplicar BPMs detectados", -1);
    }
    nativeUiShowTemporaryPopup(
      "NÃO FOI POSSÍVEL MUDAR O TIMEBASE PARA TIME", 2.2);
    return false;
  }
  if (replaceAllTempoMarkers) {
    bool deletedAll = true;
    for (int markerIndex = CountTempoTimeSigMarkers_ptr(project) - 1;
         markerIndex >= 0; --markerIndex) {
      if (!DeleteTempoTimeSigMarker_ptr(project, markerIndex)) {
        deletedAll = false;
        break;
      }
    }
    if (!deletedAll) {
      nativeSetProjectItemsTimebase(project, 1);
      if (Undo_EndBlock2_ptr) {
        Undo_EndBlock2_ptr(project,
          "VS Hook: recriar marcadores de BPM", -1);
      }
      if (UpdateTimeline_ptr) UpdateTimeline_ptr();
      if (UpdateArrange_ptr) UpdateArrange_ptr();
      nativeUiShowTemporaryPopup(
        "NÃO FOI POSSÍVEL APAGAR TODOS OS MARCADORES", 2.4);
      return false;
    }
  }

  int applied = 0;
  std::vector<NativeBpmScanResult> appliedResults;
  for (const NativeBpmScanResult& result : applicable) {
    if (nativeSetTempoMarkerAtPosition(
          project, result.start, std::round(result.bpm))) {
      ++applied;
      appliedResults.push_back(result);
    }
  }
  const bool restoredBeats = nativeSetProjectItemsTimebase(project, 1);
  if (replaceAllTempoMarkers) {
    std::map<std::string, NativeBpmScanResult> rebuiltCache;
    for (const NativeBpmScanResult& result : appliedResults) {
      rebuiltCache[result.id] = result;
    }
    nativeWriteBpmScanCache(project, rebuiltCache);
  }
  if (applied > 0 && MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  if (Undo_EndBlock2_ptr) {
    Undo_EndBlock2_ptr(project,
      "VS Hook: aplicar BPMs detectados", -1);
  }
  if (UpdateTimeline_ptr) UpdateTimeline_ptr();
  if (UpdateArrange_ptr) UpdateArrange_ptr();

  if (!restoredBeats) {
    nativeUiShowTemporaryPopup(
      "BPMS APLICADOS, MAS NÃO FOI POSSÍVEL VOLTAR PARA BEATS", 2.8);
    return false;
  }

  if (applied <= 0) {
    nativeUiShowTemporaryPopup(
      "NÃO FOI POSSÍVEL CRIAR OS MARCADORES", 2.0);
    return false;
  }
  if (replaceAllTempoMarkers) {
    g_nativeBpmReplaceAllTempoMarkersOnApply = false;
  }
  nativeUiShowTemporaryPopup(
    std::to_string(applied) +
      (applied == 1 ? " BPM APLICADO" : " BPMS APLICADOS"),
    1.8);
  return true;
}

static bool nativeUiCachedBpmForSong(
  ReaProject* project,
  const std::string& id,
  const std::string& name,
  double currentStart,
  NativeBpmScanResult& resultOut)
{
  if (!project || id.empty()) return false;
  const auto cache = nativeLoadBpmScanCache(project);
  const auto found = cache.find(id);
  const bool cached = found != cache.end();
  if (cached) resultOut = found->second;
  resultOut.id = id;
  resultOut.name = name;
  if (std::isfinite(currentStart)) resultOut.start = currentStart;
  double markerBpm = 0.0;
  const bool markerFound =
    nativeTempoMarkerBpmAtOrBeforePosition(
      project, resultOut.start, markerBpm);
  if (!cached && !markerFound) return false;
  if (markerFound) {
    // O cache guarda o BPM original do Scan. O valor atual vem sempre do
    // marcador real mais próximo à esquerda, inclusive em projetos antigos.
    resultOut.bpm = std::round(markerBpm);
    if (!cached) {
      resultOut.originalBpm = resultOut.bpm;
      resultOut.confidence = 100;
      resultOut.error.clear();
    }
  }
  return true;
}

static void nativeUiUpdateVisibleBpmResult(
  const NativeBpmScanResult& result)
{
  for (NativeBpmScanResult& visible : g_nativeBpmScanResults) {
    if (visible.id == result.id) visible = result;
  }
  g_nativeUiBpmScannedAvailable = true;
  ++g_nativeBpmScanRevision;
  // O App do Diretor lê o BPM nas cópias de regiões/repertório do snapshot
  // pesado. Depois de um ajuste, reconstrói essas cópias imediatamente para
  // confirmar no app exatamente o mesmo valor exibido pela extensão.
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
}

static bool nativeUiStoreBpmValue(
  const std::string& id,
  const std::string& name,
  double start,
  double end,
  int bpm)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || id.empty() || bpm < 10 || bpm > 960) return false;
  if (nativeUiBpmSongIsCurrentlyPlaying(id)) {
    nativeUiShowTemporaryPopup(
      "NÃO É POSSÍVEL ALTERAR O BPM DA MÚSICA TOCANDO", 2.0);
    return false;
  }

  // Captura a base antes de alterar o marcador. Para projetos antigos sem
  // cache, esse é o BPM original usado pelo indicador +1/-1.
  NativeBpmScanResult result;
  nativeUiCachedBpmForSong(project, id, name, start, result);

  // A coluna controla o marcador mais próximo à esquerda do início da música,
  // inclusive quando ele já existia antes da instalação do VS Hook. Sem
  // marcador anterior, ela continua editando o resultado que será aplicado.
  const int tempoMarkerIndex = nativeFindTempoMarkerAtOrBeforePosition(
    project, start);
  if (tempoMarkerIndex >= 0) {
    if (Undo_BeginBlock2_ptr) Undo_BeginBlock2_ptr(project);
    // O marcador precisa ser alterado enquanto o projeto está em Beats
    // (position, length, rate). Assim os itens acompanham o novo andamento e
    // aceleram ou desaceleram; em Time suas durações ficariam preservadas.
    const bool changedToBeats = nativeSetProjectItemsTimebase(project, 1);
    const bool markerUpdated = changedToBeats &&
      nativeUpdateTempoMarkerBpmByIndex(
        project, tempoMarkerIndex, static_cast<double>(bpm));
    if (markerUpdated && MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
    if (Undo_EndBlock2_ptr) {
      Undo_EndBlock2_ptr(project,
        "VS Hook: alterar BPM da música", -1);
    }
    if (markerUpdated) {
      if (UpdateTimeline_ptr) UpdateTimeline_ptr();
      if (UpdateArrange_ptr) UpdateArrange_ptr();
    }
    if (!markerUpdated) {
      nativeUiShowTemporaryPopup(
        "NÃO FOI POSSÍVEL ALTERAR O MARCADOR DE BPM", 2.0);
      return false;
    }
  }

  result.id = id;
  result.name = name;
  result.start = start;
  result.end = end;
  if (!std::isfinite(result.originalBpm) || result.originalBpm <= 0.0) {
    result.originalBpm = result.bpm > 0.0
      ? std::round(result.bpm)
      : static_cast<double>(bpm);
  }
  result.bpm = static_cast<double>(bpm);
  // Se o Scan usou o fallback genérico, mantém essa origem depois de uma
  // edição manual. Somente um novo Scan bem-sucedido muda o valor para azul.
  nativeSaveBpmScanCacheResult(project, result);
  nativeUiUpdateVisibleBpmResult(result);
  return true;
}

static bool nativeUiAdjustBpmValue(const NativeMainBpmHit& hit)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  NativeBpmScanResult result;
  if (nativeUiBpmSongIsCurrentlyPlaying(hit.id)) {
    nativeUiShowTemporaryPopup(
      "NÃO É POSSÍVEL ALTERAR O BPM DA MÚSICA TOCANDO", 2.0);
    return false;
  }
  if (!nativeUiCachedBpmForSong(
        project, hit.id, hit.name, hit.start, result) ||
      !nativeBpmScanResultHasUsableValue(result)) {
    nativeUiShowTemporaryPopup("BPM NÃO ENCONTRADO", 1.5);
    return false;
  }
  const int current = static_cast<int>(std::lround(result.bpm));
  const int next = std::max(10, std::min(960,
    current + (hit.delta < 0 ? -1 : 1)));
  return nativeUiStoreBpmValue(hit.id, hit.name,
    hit.start, hit.end, next);
}

static size_t nativeUiTextCursorFromPoint(
  HWND hwnd,
  const RECT& rect,
  const std::string& text,
  int pointX,
  int leftPadding,
  UINT flags);

static void nativeUiOpenBpmValueEdit(
  const NativeMainBpmHit& hit,
  int pointX = -1)
{
  if (nativeUiBpmSongIsCurrentlyPlaying(hit.id)) {
    nativeUiShowTemporaryPopup(
      "NÃO É POSSÍVEL ALTERAR O BPM DA MÚSICA TOCANDO", 2.0);
    return;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  NativeBpmScanResult result;
  const bool found = nativeUiCachedBpmForSong(
    project, hit.id, hit.name, hit.start, result) &&
    nativeBpmScanResultHasUsableValue(result);
  g_nativeMainBpmEditOpen = true;
  g_nativeMainBpmEditId = hit.id;
  g_nativeMainBpmEditName = hit.name;
  g_nativeMainBpmEditStart = hit.start;
  g_nativeMainBpmEditEnd = hit.end;
  g_nativeMainBpmEditRect = hit.rect;
  g_nativeMainBpmEditInput = found
    ? std::to_string(static_cast<int>(std::lround(result.bpm)))
    : std::string();
  g_nativeMainBpmEditCursor = pointX >= 0
    ? nativeUiTextCursorFromPoint(
        g_nativeAppActivePanelHwnd, hit.rect,
        g_nativeMainBpmEditInput, pointX, 4, DT_CENTER)
    : g_nativeMainBpmEditInput.size();
  g_nativeUiTextSelectionKind = NativeUiTextInputKind::BpmValue;
  g_nativeUiTextSelectionAnchor = g_nativeMainBpmEditCursor;
}

static void nativeUiCancelBpmValueEdit()
{
  g_nativeMainBpmEditOpen = false;
  g_nativeMainBpmEditId.clear();
  g_nativeMainBpmEditName.clear();
  g_nativeMainBpmEditInput.clear();
  g_nativeMainBpmEditCursor = 0;
  g_nativeMainBpmEditRect = RECT{0, 0, 0, 0};
  if (g_nativeUiTextSelectionKind == NativeUiTextInputKind::BpmValue) {
    g_nativeUiTextSelectionKind = NativeUiTextInputKind::None;
    g_nativeUiTextSelectionAnchor = 0;
  }
}

static bool nativeUiCommitBpmValueEdit()
{
  if (!g_nativeMainBpmEditOpen) return true;
  const int bpm = std::atoi(g_nativeMainBpmEditInput.c_str());
  if (g_nativeMainBpmEditInput.size() < 2 || bpm < 10 || bpm > 960) {
    nativeUiShowTemporaryPopup("INFORME UM BPM ENTRE 10 E 960", 1.8);
    return false;
  }
  const bool stored = nativeUiStoreBpmValue(
    g_nativeMainBpmEditId, g_nativeMainBpmEditName,
    g_nativeMainBpmEditStart, g_nativeMainBpmEditEnd, bpm);
  if (stored) nativeUiCancelBpmValueEdit();
  return stored;
}

static bool nativeApplyBpmCommand(const std::string& commandBody)
{
  const std::string type = nativeLower(
    nativeJsonExtractString(commandBody, "type"));
  if (type != "bpm_set" && type != "bpm_adjust" &&
      type != "bpm_focus" && type != "set_bpm_visibility") {
    return false;
  }
  nativeTimecodeLanRecordCommand(commandBody);
  if (type == "bpm_focus" || type == "set_bpm_visibility") {
    const bool visible = type == "bpm_focus" || nativeBoolFromText(
      nativeJsonExtractString(commandBody, "visible"), false);
    nativeSetBpmColumnVisible(visible);
    return true;
  }

  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return true;
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  const NativeSongWindow* song = nativeResolveTunerSong(
    songs, commandBody);
  if (!song || nativeUiBpmSongIsCurrentlyPlaying(song->id)) {
    return true;
  }

  NativeBpmScanResult result;
  if (!nativeUiCachedBpmForSong(
        project, song->id, song->name, song->start, result) ||
      !nativeBpmScanResultHasUsableValue(result)) {
    return true;
  }
  int next = static_cast<int>(std::lround(result.bpm));
  if (type == "bpm_adjust") {
    next += std::atoi(
      nativeJsonExtractString(commandBody, "delta").c_str());
  } else {
    std::string value = nativeJsonExtractString(commandBody, "value");
    if (value.empty()) value = nativeJsonExtractString(commandBody, "bpm");
    if (value.empty()) return true;
    next = std::atoi(value.c_str());
  }
  next = std::max(10, std::min(960, next));
  const bool changed = nativeUiStoreBpmValue(
    song->id, song->name, song->start, song->end, next);
  if (changed) {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    nativeBumpSharedRevisionLocked("director");
  }
  return true;
}

static std::string nativeReadMediaItemNotes(MediaItem* item)
{
  if (!item || !GetSetMediaItemInfo_String_ptr) return std::string();
  std::string buf(65536, '\0');
  if (!GetSetMediaItemInfo_String_ptr(item, "P_NOTES", buf.data(), false)) return std::string();
  const size_t n = buf.find('\0');
  if (n != std::string::npos) buf.resize(n);
  return nativeTrim(buf);
}

static std::string nativeReadTakeText(MediaItem_Take* take)
{
  if (!take) return std::string();
  if (GetSetMediaItemTakeInfo_String_ptr) {
    std::string buf(65536, '\0');
    if (GetSetMediaItemTakeInfo_String_ptr(take, "P_NAME", buf.data(), false)) {
      const size_t n = buf.find('\0');
      if (n != std::string::npos) buf.resize(n);
      buf = nativeTrim(buf);
      if (!buf.empty()) return buf;
    }
  }
  if (GetTakeName_ptr) {
    const char* name = GetTakeName_ptr(take);
    if (name && *name) return nativeTrim(name);
  }
  return std::string();
}

static std::string nativeReadItemTelepromptText(MediaItem* item)
{
  if (!item) return std::string();
  const std::string notes = nativeReadMediaItemNotes(item);
  if (!notes.empty()) return notes;
  MediaItem_Take* take = GetActiveTake_ptr ? GetActiveTake_ptr(item) : nullptr;
  return nativeReadTakeText(take);
}

static std::string nativeReadTakeSourcePath(MediaItem_Take* take)
{
  if (!take || !GetMediaItemTake_Source_ptr ||
      !GetMediaSourceFileName_ptr) {
    return std::string();
  }
  PCM_source* source = GetMediaItemTake_Source_ptr(take);
  std::string path;
  PCM_source* visited[8]{};
  int visitedCount = 0;
  for (int depth = 0; source && depth < 8; ++depth) {
    bool alreadyVisited = false;
    for (int index = 0; index < visitedCount; ++index) {
      if (visited[index] == source) {
        alreadyVisited = true;
        break;
      }
    }
    if (alreadyVisited) break;
    visited[visitedCount++] = source;

    char buf[4096] = {0};
    GetMediaSourceFileName_ptr(
      source, buf, static_cast<int>(sizeof(buf)));
    const std::string candidate = nativeTrim(std::string(buf));
    // O source raiz possui o nome fisico. Wrappers SECTION/reverse podem
    // devolver vazio ou apenas repetir a referencia do filho, portanto o
    // ultimo caminho nao vazio encontrado e o mais autoritativo.
    if (!candidate.empty()) path = candidate;

    if (!GetMediaSourceParent_ptr) break;
    PCM_source* parent = GetMediaSourceParent_ptr(source);
    if (!parent || parent == source) break;
    source = parent;
  }
  return path;
}

static bool nativeTelepromptPathIsAbsolute(const std::string& rawPath)
{
  const std::string path = nativeTrim(rawPath);
  if (path.empty()) return false;
  if (path[0] == '/' || path[0] == '\\') return true;
#ifdef _WIN32
  return path.size() >= 3 &&
    std::isalpha(static_cast<unsigned char>(path[0])) &&
    path[1] == ':' && (path[2] == '/' || path[2] == '\\');
#else
  return false;
#endif
}

static std::string nativeTelepromptProjectFileDirectory(
  ReaProject* project)
{
  if (!project || !EnumProjects_ptr) return std::string();
  char pathBuf[4096] = "";
  ReaProject* active = EnumProjects_ptr(
    -1, pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (active != project || !pathBuf[0]) {
    pathBuf[0] = '\0';
    for (int index = 0; ; ++index) {
      char candidate[4096] = "";
      ReaProject* enumerated = EnumProjects_ptr(
        index, candidate, static_cast<int>(sizeof(candidate)));
      if (!enumerated) break;
      if (enumerated == project) {
        std::strncpy(pathBuf, candidate, sizeof(pathBuf) - 1);
        pathBuf[sizeof(pathBuf) - 1] = '\0';
        break;
      }
    }
  }
  std::string path = normalizeSlashes(nativeTrim(pathBuf));
  const size_t separator = path.find_last_of('/');
  return separator == std::string::npos
    ? std::string() : path.substr(0, separator);
}

static std::string nativeTelepromptProjectMediaDirectory(
  ReaProject* project)
{
  if (!project || !GetProjectPathEx_ptr) return std::string();
  char pathBuf[4096] = "";
  GetProjectPathEx_ptr(
    project, pathBuf, static_cast<int>(sizeof(pathBuf)));
  return normalizeSlashes(nativeTrim(pathBuf));
}

static std::string nativeResolveTelepromptMediaPath(
  const std::string& rawPath,
  const std::string& projectFileDirectory,
  const std::string& projectMediaDirectory)
{
  const std::string clean = nativeTrim(rawPath);
  if (clean.empty() || nativeTelepromptPathIsAbsolute(clean)) {
    return clean;
  }
  const std::string relative = normalizeSlashes(clean);
  const std::string projectCandidate = projectFileDirectory.empty()
    ? std::string() : joinPath(projectFileDirectory, relative);
  if (!projectCandidate.empty() && fileExists(projectCandidate)) {
    return projectCandidate;
  }
  const std::string mediaCandidate = projectMediaDirectory.empty()
    ? std::string() : joinPath(projectMediaDirectory, relative);
  if (!mediaCandidate.empty() && fileExists(mediaCandidate)) {
    return mediaCandidate;
  }
  // Mantem uma resolucao deterministica mesmo para arquivo offline. Assim o
  // diagnostico e o endpoint /media apontam para o local que o RPP referencia,
  // em vez de aceitar por engano um homonimo no current working directory do
  // processo do REAPER.
  if (!projectCandidate.empty()) return projectCandidate;
  if (!mediaCandidate.empty()) return mediaCandidate;
  return relative;
}

static std::string nativeUrlEncode(const std::string& value)
{
  std::ostringstream out;
  out << std::uppercase << std::hex;
  for (unsigned char c : value) {
    if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~') {
      out << static_cast<char>(c);
    } else {
      out << '%' << std::setw(2) << std::setfill('0') << static_cast<int>(c);
    }
  }
  return out.str();
}

static std::string nativeFileExtensionLower(const std::string& path)
{
  const size_t dot = path.find_last_of('.');
  if (dot == std::string::npos || dot + 1 >= path.size()) return std::string();
  std::string ext = path.substr(dot + 1);
  std::transform(ext.begin(), ext.end(), ext.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
  return ext;
}

static std::string nativeDetectTelepromptMediaType(const std::string& path)
{
  const std::string ext = nativeFileExtensionLower(path);
  if (ext == "png" || ext == "jpg" || ext == "jpeg" || ext == "webp" || ext == "gif" || ext == "bmp") return "image";
  if (ext == "mp4" || ext == "mov" || ext == "m4v" || ext == "webm" || ext == "mkv" || ext == "avi") return "video";
  return "text";
}

static bool nativeTelepromptLabelLooksLikeMediaPath(
  const std::string& rawValue)
{
  const std::string value = nativeTrim(rawValue);
  if (value.empty()) return false;
  if (value.find('/') != std::string::npos ||
      value.find('\\') != std::string::npos ||
      value.find(':') != std::string::npos) {
    return true;
  }
  // Um SOURCE VIDEO ainda adormecido pode nao publicar o caminho pela API e
  // deixar somente o nome do take (por exemplo, "Slide2.PNG"). Esse nome
  // simples continua sendo uma referencia valida: o resolvedor abaixo tenta
  // primeiro a pasta do RPP e depois a pasta de midia do projeto.
  const std::string mediaType =
    nativeDetectTelepromptMediaType(value);
  return mediaType == "image" || mediaType == "video";
}

static MediaItem* nativeFindCurrentItemOnTrack(MediaTrack* track, double pos, int* itemIndexOut = nullptr, double* itemStartOut = nullptr, double* itemEndOut = nullptr)
{
  if (itemIndexOut) *itemIndexOut = -1;
  if (itemStartOut) *itemStartOut = 0.0;
  if (itemEndOut) *itemEndOut = 0.0;
  if (!track || !GetTrackNumMediaItems_ptr || !GetTrackMediaItem_ptr || !GetMediaItemInfo_Value_ptr) return nullptr;
  const int count = GetTrackNumMediaItems_ptr(track);
  for (int i = 0; i < count; ++i) {
    MediaItem* item = GetTrackMediaItem_ptr(track, i);
    if (!item) continue;
    const double itemStart = GetMediaItemInfo_Value_ptr(item, "D_POSITION");
    const double itemLen = std::max(0.0, GetMediaItemInfo_Value_ptr(item, "D_LENGTH"));
    const double itemEnd = itemStart + itemLen;
    if (pos >= itemStart - 0.0005 && pos < itemEnd - 0.0005) {
      if (itemIndexOut) *itemIndexOut = i;
      if (itemStartOut) *itemStartOut = itemStart;
      if (itemEndOut) *itemEndOut = itemEnd;
      return item;
    }
  }
  return nullptr;
}

static std::string nativeFindSongNameAtPosition(const std::vector<NativeSongWindow>& songs, double pos, const std::string& fallback)
{
  for (const auto& s : songs) {
    if (s.isBlock) continue;
    if (pos >= s.start - 0.0005 && pos < s.end - 0.0005 && !s.name.empty()) return s.name;
  }
  return fallback;
}

static std::string nativeBuildTelepromptStateJson(ReaProject* project, const std::vector<NativeSongWindow>& songs, int slot, const std::string& trackName, bool transportPlaying, double playPos, const std::string& playingName)
{
  const double pos = (transportPlaying && GetPlayPositionEx_ptr) ? playPos : (GetCursorPositionEx_ptr ? GetCursorPositionEx_ptr(project) : playPos);
  double nextChangePosition =
    std::numeric_limits<double>::infinity();
  auto rememberNextChange = [&](double position) {
    if (std::isfinite(position) &&
        position > pos + 0.0005) {
      nextChangePosition =
        std::min(nextChangePosition, position);
    }
  };
  for (const auto& song : songs) {
    if (song.isBlock) continue;
    rememberNextChange(song.start);
    rememberNextChange(song.end);
  }
  int trackIndex = -1;
  MediaTrack* track = nativeFindTrackByExactName(project, trackName, &trackIndex);

  // FIX105: resolve todos os itens ativos na mesma posição da pista TELEPROMPT.
  // Regra de prioridade na mesma posição:
  // 1) texto/letra continua visível por cima;
  // 2) vídeo ganha de imagem;
  // 3) imagem entra se não houver vídeo.
  bool itemFound = false;
  int chosenItemIndex = -1;
  double chosenItemStart = 0.0;
  double chosenItemEnd = 0.0;

  int chosenMediaPriority = 0; // 0 nenhum, 1 imagem, 2 vídeo
  int chosenMediaIndex = -1;
  double chosenMediaStart = 0.0;
  double chosenMediaEnd = 0.0;
  double chosenMediaOffset = 0.0;
  double chosenMediaPlayrate = 1.0;
  double chosenMediaSourceLength = 0.0;
  bool chosenMediaLoopsSource = false;
  std::string mediaSourcePath;
  std::string mediaPath;
  std::string mediaType = "text";
  std::string mediaExt;
  bool nextMediaFound = false;
  int nextMediaPriority = 0;
  int nextMediaIndex = -1;
  double nextMediaStart = 0.0;
  double nextMediaEnd = 0.0;
  double nextMediaOffset = 0.0;
  double nextMediaPlayrate = 1.0;
  std::string nextMediaSourcePath;
  std::string nextMediaPath;
  std::string nextMediaType = "text";
  std::string nextMediaExt;

  // GetMediaSourceFileName pode devolver exatamente o valor relativo salvo no
  // RPP. Resolve uma vez contra o diretorio do projeto para que decoder, cache
  // e /media nao dependam do current working directory do processo do REAPER.
  const std::string projectFileDirectory =
    nativeTelepromptProjectFileDirectory(project);
  const std::string projectMediaDirectory =
    nativeTelepromptProjectMediaDirectory(project);

  std::vector<std::string> textParts;
  int chosenTextIndex = -1;
  double chosenTextStart = 0.0;
  double chosenTextEnd = 0.0;

  auto appendTextPart = [&](const std::string& value) {
    const std::string clean = nativeTrim(value);
    if (clean.empty()) return;
    for (const auto& existing : textParts) {
      if (existing == clean) return;
    }
    textParts.push_back(clean);
  };

  if (track && GetTrackNumMediaItems_ptr && GetTrackMediaItem_ptr && GetMediaItemInfo_Value_ptr) {
    const int count = GetTrackNumMediaItems_ptr(track);
    for (int i = 0; i < count; ++i) {
      MediaItem* currentItem = GetTrackMediaItem_ptr(track, i);
      if (!currentItem) continue;
      const double itemStart = GetMediaItemInfo_Value_ptr(currentItem, "D_POSITION");
      const double itemLen = std::max(0.0, GetMediaItemInfo_Value_ptr(currentItem, "D_LENGTH"));
      const double itemEnd = itemStart + itemLen;
      rememberNextChange(itemStart);
      rememberNextChange(itemEnd);

      MediaItem_Take* currentTake = currentItem && GetActiveTake_ptr ? GetActiveTake_ptr(currentItem) : nullptr;
      std::string currentMediaSourcePath =
        nativeReadTakeSourcePath(currentTake);
      const std::string takeLabel = nativeReadTakeText(currentTake);
      if (currentMediaSourcePath.empty() &&
          nativeTelepromptLabelLooksLikeMediaPath(takeLabel)) {
        currentMediaSourcePath = takeLabel;
      }

      const std::string currentMediaPath =
        nativeResolveTelepromptMediaPath(
          currentMediaSourcePath,
          projectFileDirectory,
          projectMediaDirectory);

      const std::string currentMediaType = currentMediaPath.empty() ? std::string("text") : nativeDetectTelepromptMediaType(currentMediaPath);
      const int currentPriority = currentMediaType == "video" ? 2 : (currentMediaType == "image" ? 1 : 0);

      // Publica também a próxima mídia da pista. O app pode começar o
      // download enquanto a mídia atual ainda está tocando e apenas revelar o
      // player já preparado quando o cursor realmente chegar ao item.
      if (currentPriority > 0 && itemStart > pos + 0.0005) {
        const bool earlier =
          !nextMediaFound || itemStart < nextMediaStart - 0.0005;
        const bool sameStartAndPreferred =
          nextMediaFound &&
          std::fabs(itemStart - nextMediaStart) <= 0.0005 &&
          (currentPriority > nextMediaPriority ||
           (currentPriority == nextMediaPriority &&
            i >= nextMediaIndex));
        if (earlier || sameStartAndPreferred) {
          nextMediaFound = true;
          nextMediaPriority = currentPriority;
          nextMediaIndex = i;
          nextMediaStart = itemStart;
          nextMediaEnd = itemEnd;
          nextMediaSourcePath = currentMediaSourcePath;
          nextMediaPath = currentMediaPath;
          nextMediaType = currentMediaType;
          nextMediaExt =
            nativeFileExtensionLower(nextMediaPath);
          nextMediaOffset = 0.0;
          nextMediaPlayrate = 1.0;
          if (currentTake &&
              GetMediaItemTakeInfo_Value_ptr) {
            nextMediaOffset =
              GetMediaItemTakeInfo_Value_ptr(
                currentTake, "D_STARTOFFS");
            nextMediaPlayrate =
              GetMediaItemTakeInfo_Value_ptr(
                currentTake, "D_PLAYRATE");
            if (nextMediaPlayrate <= 0.0) {
              nextMediaPlayrate = 1.0;
            }
          }
        }
      }

      if (pos < itemStart - 0.0005 ||
          pos >= itemEnd - 0.0005) {
        continue;
      }

      itemFound = true;
      if (chosenItemIndex < 0) {
        chosenItemIndex = i;
        chosenItemStart = itemStart;
        chosenItemEnd = itemEnd;
      }

      std::string currentText = nativeReadItemTelepromptText(currentItem);
      const bool textLooksOnlyLikeMediaFileName = !currentText.empty()
        && currentText.find('/') == std::string::npos
        && currentText.find('\\') == std::string::npos
        && currentText.find(':') == std::string::npos
        && (nativeDetectTelepromptMediaType(currentText) == "image" || nativeDetectTelepromptMediaType(currentText) == "video");
      if (textLooksOnlyLikeMediaFileName) currentText.clear();
      if (!nativeTrim(currentText).empty()) {
        appendTextPart(currentText);
        if (chosenTextIndex < 0) {
          chosenTextIndex = i;
          chosenTextStart = itemStart;
          chosenTextEnd = itemEnd;
        }
      }

      if (currentPriority > 0 && (currentPriority > chosenMediaPriority || (currentPriority == chosenMediaPriority && i >= chosenMediaIndex))) {
        chosenMediaPriority = currentPriority;
        chosenMediaIndex = i;
        chosenMediaStart = itemStart;
        chosenMediaEnd = itemEnd;
        mediaSourcePath = currentMediaSourcePath;
        mediaPath = currentMediaPath;
        mediaType = currentMediaType;
        mediaExt = nativeFileExtensionLower(mediaPath);
        chosenMediaOffset = 0.0;
        chosenMediaPlayrate = 1.0;
        chosenMediaSourceLength = 0.0;
        chosenMediaLoopsSource =
          GetMediaItemInfo_Value_ptr(currentItem, "B_LOOPSRC") > 0.5;
        if (currentTake && GetMediaItemTakeInfo_Value_ptr) {
          chosenMediaOffset =
            GetMediaItemTakeInfo_Value_ptr(currentTake, "D_STARTOFFS");
          chosenMediaPlayrate = GetMediaItemTakeInfo_Value_ptr(currentTake, "D_PLAYRATE");
          if (chosenMediaPlayrate <= 0.0) chosenMediaPlayrate = 1.0;
        }
        if (currentTake &&
            GetMediaItemTake_Source_ptr &&
            GetMediaSourceLength_ptr) {
          PCM_source* source =
            GetMediaItemTake_Source_ptr(currentTake);
          bool sourceLengthIsQuarterNotes = false;
          const double sourceLength =
            source
              ? GetMediaSourceLength_ptr(
                  source, &sourceLengthIsQuarterNotes)
              : 0.0;
          if (!sourceLengthIsQuarterNotes &&
              std::isfinite(sourceLength) &&
              sourceLength > 0.000001) {
            chosenMediaSourceLength = sourceLength;
          }
        }
      }
    }
  }

  if (chosenMediaPriority > 0) {
    chosenItemIndex = chosenMediaIndex;
    chosenItemStart = chosenMediaStart;
    chosenItemEnd = chosenMediaEnd;
  } else if (chosenTextIndex >= 0) {
    chosenItemIndex = chosenTextIndex;
    chosenItemStart = chosenTextStart;
    chosenItemEnd = chosenTextEnd;
    mediaType = "text";
    mediaSourcePath.clear();
    mediaPath.clear();
    mediaExt.clear();
  }

  std::string text;
  for (size_t i = 0; i < textParts.size(); ++i) {
    if (i > 0) text += "\n";
    text += textParts[i];
  }

  const double itemLength = std::max(0.0, chosenItemEnd - chosenItemStart);
  // A mídia mantém seu próprio intervalo para escolher o quadro do vídeo.
  // Quando existe um Empty Item com letra por cima, é a duração desse texto
  // que deve controlar exclusivamente a barra de progresso da letra.
  const double progressStart =
    chosenTextIndex >= 0 ? chosenTextStart : chosenItemStart;
  const double progressEnd =
    chosenTextIndex >= 0 ? chosenTextEnd : chosenItemEnd;
  double mediaCurrentTime = 0.0;
  if (chosenMediaPriority > 0) {
    const double linearSourceTime =
      chosenMediaOffset +
      (std::max(0.0, pos - chosenMediaStart) *
        chosenMediaPlayrate);
    if (chosenMediaLoopsSource &&
        chosenMediaSourceLength > 0.000001) {
      mediaCurrentTime =
        std::fmod(linearSourceTime, chosenMediaSourceLength);
      if (mediaCurrentTime < 0.0) {
        mediaCurrentTime += chosenMediaSourceLength;
      }
    } else {
      mediaCurrentTime = std::max(0.0, linearSourceTime);
    }
  }
  const std::string songName = nativeFindSongNameAtPosition(songs, pos, playingName);
  std::ostringstream out;
  out << "{";
  out << "\"source\":\"vs_hook_extension\",";
  out << "\"slot\":" << slot << ",";
  out << "\"updatedAt\":" << nativeJsonString(nativeIsoNow()) << ",";
  out << "\"song\":" << nativeJsonString(songName) << ",";
  out << "\"songName\":" << nativeJsonString(songName) << ",";
  out << "\"currentSongName\":" << nativeJsonString(songName) << ",";
  out << "\"trackName\":" << nativeJsonString(trackName) << ",";
  out << "\"trackFound\":" << (track ? "true" : "false") << ",";
  out << "\"trackIndex\":" << trackIndex << ",";
  out << "\"itemFound\":" << (itemFound ? "true" : "false") << ",";
  out << "\"itemIndex\":" << chosenItemIndex << ",";
  out << "\"itemGuid\":\"\",";
  out << "\"itemStart\":" << nativeNumber(chosenItemStart) << ",";
  out << "\"itemEnd\":" << nativeNumber(chosenItemEnd) << ",";
  out << "\"progressStart\":" << nativeNumber(progressStart) << ",";
  out << "\"progressEnd\":" << nativeNumber(progressEnd) << ",";
  out << "\"position\":" << nativeNumber(pos) << ",";
  out << "\"playing\":" << (transportPlaying ? "true" : "false") << ",";
  out << "\"telepromptType\":" << nativeJsonString(mediaType) << ",";
  out << "\"mediaType\":" << nativeJsonString(mediaType) << ",";
  out << "\"mediaSourcePath\":" << nativeJsonString(mediaSourcePath) << ",";
  out << "\"mediaPath\":" << nativeJsonString(mediaPath) << ",";
  out << "\"mediaUrl\":" << nativeJsonString(mediaPath.empty() ? std::string() : std::string("/media?path=") + nativeUrlEncode(mediaPath)) << ",";
  out << "\"mediaExt\":" << nativeJsonString(mediaExt) << ",";
  out << "\"mediaCurrentTime\":" << nativeNumber(mediaCurrentTime) << ",";
  out << "\"mediaOffset\":" << nativeNumber(chosenMediaOffset) << ",";
  out << "\"mediaPlayrate\":" << nativeNumber(chosenMediaPlayrate) << ",";
  out << "\"mediaSourceLength\":" << nativeNumber(chosenMediaSourceLength) << ",";
  out << "\"mediaLoopsSource\":" << (chosenMediaLoopsSource ? "true" : "false") << ",";
  out << "\"nextChangePosition\":"
      << nativeNumber(
           std::isfinite(nextChangePosition)
             ? nextChangePosition
             : -1.0)
      << ",";
  out << "\"nextMediaFound\":" << (nextMediaFound ? "true" : "false") << ",";
  out << "\"nextMediaType\":" << nativeJsonString(nextMediaType) << ",";
  out << "\"nextMediaSourcePath\":" << nativeJsonString(nextMediaSourcePath) << ",";
  out << "\"nextMediaPath\":" << nativeJsonString(nextMediaPath) << ",";
  out << "\"nextMediaUrl\":" << nativeJsonString(nextMediaPath.empty() ? std::string() : std::string("/media?path=") + nativeUrlEncode(nextMediaPath)) << ",";
  out << "\"nextMediaExt\":" << nativeJsonString(nextMediaExt) << ",";
  out << "\"nextMediaItemIndex\":" << nextMediaIndex << ",";
  out << "\"nextMediaStart\":" << nativeNumber(nextMediaStart) << ",";
  out << "\"nextMediaEnd\":" << nativeNumber(nextMediaEnd) << ",";
  out << "\"nextMediaOffset\":" << nativeNumber(nextMediaOffset) << ",";
  out << "\"nextMediaPlayrate\":" << nativeNumber(nextMediaPlayrate) << ",";
  out << "\"itemLength\":" << nativeNumber(itemLength) << ",";
  out << "\"overlayText\":" << nativeJsonString(text) << ",";
  out << "\"lyricsText\":" << nativeJsonString(text) << ",";
  out << "\"lyrics\":" << nativeJsonString(text);
  out << "}";
  return out.str();
}

static std::string nativeBuildRegionsJson(const std::vector<NativeSongWindow>& songs)
{
  std::ostringstream oss;
  oss << "[";
  bool first = true;
  int index = 1;
  for (const auto& s : songs) {
    if (s.isBlock) continue;
    if (!first) oss << ",";
    first = false;
    NativeSongWindow copy = s; if (copy.playlistOrder <= 0) copy.playlistOrder = index; oss << nativeSongToJson(copy, index++);
  }
  oss << "]";
  return oss.str();
}

static double nativeRawDurationSec(const NativeSongWindow& item)
{
  return std::max(0.0, item.end - item.start);
}

static double nativeComputeRegionsTotalSec(const std::vector<NativeSongWindow>& songs)
{
  double total = 0.0;
  for (const auto& s : songs) {
    if (s.isBlock || s.isHashChild) continue;
    total += nativeRawDurationSec(s);
  }
  return total;
}

static double nativeComputePlaylistTotalSec(const std::vector<NativeSongWindow>& items)
{
  double total = 0.0;
  for (const auto& item : items) {
    // Mesma regra do Lua: blocos não contam e qualquer filho de região "--"
    // é ignorado, porque o tempo do pai já cobre os filhos.
    if (item.isBlock || item.isHashChild) continue;
    total += nativeRawDurationSec(item);
  }
  return total;
}

static std::string nativeFormatTotalTextFromSeconds(double seconds)
{
  if (!std::isfinite(seconds) || seconds < 0.0) seconds = 0.0;
  const long long total = static_cast<long long>(std::floor(seconds + 0.5));
  const long long h = total / 3600;
  const int m = static_cast<int>((total % 3600) / 60);
  const int sec = static_cast<int>(total % 60);
  char buf[32] = "";
  std::snprintf(buf, sizeof(buf), "%02lld:%02d:%02d", h, m, sec);
  return std::string(buf);
}

static std::vector<double> nativeComputeStoredPlaylistTotals(const std::string& data)
{
  std::vector<double> totals;
  int playlistIndex = -1;
  const auto lines = nativeSplit(data, '\n');
  for (size_t rawLineIndex = 0;
       rawLineIndex < lines.size(); ++rawLineIndex) {
    const std::string& rawLine = lines[rawLineIndex];
    if (rawLine.empty()) continue;
    const auto fields = nativeSplit(rawLine, '\t');
    if (fields.empty()) continue;
    const std::string tag = fields[0];
    if (tag == "PLAYLIST") {
      totals.push_back(0.0);
      playlistIndex = static_cast<int>(totals.size()) - 1;
      continue;
    }
    if (tag != "ITEM" || playlistIndex < 0) continue;

    const std::string itemType = fields.size() > 1 ? fields[1] : "";
    const int sourceNumber = fields.size() > 2 ? std::atoi(fields[2].c_str()) : 0;
    const double startPos = fields.size() > 3 ? std::atof(fields[3].c_str()) : 0.0;
    const double endPos = fields.size() > 4 ? std::atof(fields[4].c_str()) : 0.0;
    const bool storedHashChild = fields.size() > 9 && fields[9] == "1";
    const bool isBlock = itemType == "block" || sourceNumber < 0;

    // Mesma fonte da aba Repertórios do Lua: usa os limites gravados no
    // repertório e arredonda apenas o total final.
    if (!isBlock && !storedHashChild) {
      totals[static_cast<size_t>(playlistIndex)] += std::max(0.0, endPos - startPos);
    }
  }
  return totals;
}

static std::string nativeBuildPlaylistsJson(ReaProject* project, const std::vector<NativeSongWindow>& projectSongs, int& activePlaylistIndexOut, std::string& activePlaylistNameOut, std::vector<NativeSongWindow>* activeItemsOut = nullptr, double* activeStoredTotalOut = nullptr)
{
  activePlaylistIndexOut = 0;
  activePlaylistNameOut.clear();
  if (activeItemsOut) activeItemsOut->clear();
  if (activeStoredTotalOut) *activeStoredTotalOut = 0.0;
  const std::string savedPlaylistName = nativeTrim(nativeGetProjExtStateString(project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1"));
  const std::string data = nativeGetProjExtStateString(project, kPlaylistExtSection, kPlaylistExtKey);
  if (data.empty()) {
    // Sem repertório persistido não existe uma lista implícita. A aba
    // Repertório deve permanecer vazia; as regiões reais pertencem somente à
    // aba Músicas.
    return "[]";
  }

  const std::vector<double> storedPlaylistTotals = nativeComputeStoredPlaylistTotals(data);
  if (activeStoredTotalOut && !storedPlaylistTotals.empty()) *activeStoredTotalOut = storedPlaylistTotals.front();

  auto findActualSong = [&](int primary, int fallback, bool childWanted) -> const NativeSongWindow* {
    if (primary != 0) {
      for (const auto& s : projectSongs) {
        if (s.sourceNumber == primary && (!childWanted || s.isHashChild)) return &s;
      }
      for (const auto& s : projectSongs) {
        if (s.sourceNumber == primary) return &s;
      }
    }
    if (fallback != 0) {
      for (const auto& s : projectSongs) {
        if (s.sourceNumber == fallback && !s.isHashChild) return &s;
      }
    }
    return nullptr;
  };

  std::ostringstream out;
  out << "[";
  bool firstPlaylist = true;
  int playlistIndex = 0;
  bool inPlaylist = false;
  int itemIndex = 0;
  std::string currentBlockColorHex;
  bool currentPlaylistActive = false;

  const auto lines = nativeSplit(data, '\n');
  std::map<size_t, double> blockDurationByLine;
  for (size_t lineIndex = 0;
       lineIndex < lines.size(); ++lineIndex) {
    const auto blockFields =
      nativeSplit(lines[lineIndex], '\t');
    if (blockFields.size() < 3 ||
        blockFields[0] != "ITEM") {
      continue;
    }
    const int blockSourceNumber =
      std::atoi(blockFields[2].c_str());
    if (blockFields[1] != "block" &&
        blockSourceNumber >= 0) {
      continue;
    }

    double blockDurationSec = 0.0;
    for (size_t songLineIndex = lineIndex + 1;
         songLineIndex < lines.size();
         ++songLineIndex) {
      const auto songFields =
        nativeSplit(lines[songLineIndex], '\t');
      if (songFields.empty()) continue;
      if (songFields[0] == "PLAYLIST" ||
          songFields[0] == "END") {
        break;
      }
      if (songFields[0] != "ITEM" ||
          songFields.size() < 5) {
        continue;
      }

      const int songSourceNumber =
        std::atoi(songFields[2].c_str());
      if (songFields[1] == "block" ||
          songSourceNumber < 0) {
        break;
      }
      const bool storedHashChild =
        songFields.size() > 9 &&
        songFields[9] == "1";
      if (storedHashChild) continue;

      const int markerNumber =
        songFields.size() > 10
          ? std::atoi(songFields[10].c_str())
          : 0;
      const NativeSongWindow* actual =
        findActualSong(
          markerNumber != 0
            ? markerNumber
            : songSourceNumber,
          songSourceNumber, false);
      if (actual && !actual->isHashChild) {
        blockDurationSec +=
          nativeRawDurationSec(*actual);
      } else if (!actual) {
        const double storedStart =
          std::atof(songFields[3].c_str());
        const double storedEnd =
          std::atof(songFields[4].c_str());
        blockDurationSec +=
          std::max(0.0,
            storedEnd - storedStart);
      }
    }
    blockDurationByLine[lineIndex] =
      blockDurationSec;
  }

  for (size_t rawLineIndex = 0;
       rawLineIndex < lines.size();
       ++rawLineIndex) {
    const std::string& rawLine =
      lines[rawLineIndex];
    if (rawLine.empty()) continue;
    const auto fields = nativeSplit(rawLine, '\t');
    if (fields.empty()) continue;
    const std::string tag = fields[0];
    if (tag == "PLAYLIST") {
      if (inPlaylist) out << "]}";
      if (!firstPlaylist) out << ",";
      firstPlaylist = false;
      inPlaylist = true;
      itemIndex = 0;
      currentBlockColorHex.clear();
      ++playlistIndex;
      const std::string name = fields.size() > 1 ? nativeUnescapeExtField(fields[1]) : std::string("Repertório ") + std::to_string(playlistIndex);
      const bool activeThis = (savedPlaylistName.empty() && playlistIndex == 1) || (!savedPlaylistName.empty() && nativeTrim(name) == savedPlaylistName);
      const double storedTotalSec = (playlistIndex > 0 && static_cast<size_t>(playlistIndex - 1) < storedPlaylistTotals.size())
        ? storedPlaylistTotals[static_cast<size_t>(playlistIndex - 1)]
        : 0.0;
      currentPlaylistActive = activeThis;
      if (activeThis) {
        activePlaylistIndexOut = playlistIndex;
        activePlaylistNameOut = name;
        if (activeStoredTotalOut) *activeStoredTotalOut = storedTotalSec;
      }
      out << "{\"id\":" << nativeJsonString(std::to_string(playlistIndex))
          << ",\"name\":" << nativeJsonString(name)
          << ",\"active\":" << (activeThis ? "true" : "false")
          << ",\"current\":" << (activeThis ? "true" : "false")
          << ",\"activePlaylistTotalSec\":" << nativeNumber(storedTotalSec)
          << ",\"playlistTotalSec\":" << nativeNumber(storedTotalSec)
          << ",\"totalSec\":" << nativeNumber(storedTotalSec)
          << ",\"activePlaylistTotalText\":" << nativeJsonString(nativeFormatTotalTextFromSeconds(storedTotalSec))
          << ",\"playlistTotalText\":" << nativeJsonString(nativeFormatTotalTextFromSeconds(storedTotalSec))
          << ",\"totalText\":" << nativeJsonString(nativeFormatTotalTextFromSeconds(storedTotalSec))
          << ",\"songs\":[";
    } else if (tag == "ITEM" && inPlaylist) {
      const std::string itemType = fields.size() > 1 ? fields[1] : "";
      const int sourceNumber = fields.size() > 2 ? std::atoi(fields[2].c_str()) : 0;
      const double startPos = fields.size() > 3 ? std::atof(fields[3].c_str()) : 0.0;
      const double endPos = fields.size() > 4 ? std::atof(fields[4].c_str()) : 0.0;
      const std::string name = fields.size() > 5 ? nativeUnescapeExtField(fields[5]) : "";
      const std::string blockColorKey = fields.size() > 6 ? nativeUnescapeExtField(fields[6]) : "";
      const bool storedHashParent = fields.size() > 8 && fields[8] == "1";
      const bool storedHashChild = fields.size() > 9 && fields[9] == "1";
      const int markerNumber = fields.size() > 10 ? std::atoi(fields[10].c_str()) : 0;
      const bool isBlock = itemType == "block" || sourceNumber < 0;

      NativeSongWindow item;
      if (isBlock) {
        item.id = std::to_string(sourceNumber);
        item.name = name.empty() ? (std::string("BLOCO ") + std::to_string(std::abs(sourceNumber))) : name;
        item.type = "block";
        item.isBlock = true;
        item.sourceNumber = sourceNumber;
        int blockNumber = std::abs(sourceNumber);
        if (blockNumber <= 0) {
          const size_t p = item.name.find("BLOCO");
          blockNumber = (p != std::string::npos) ? std::atoi(item.name.c_str() + p + 5) : (itemIndex + 1);
        }
        item.blockColorKey = blockColorKey;
        item.blockColorHex = nativeBlockColorHexFromKey(blockColorKey, blockNumber);
        const auto duration =
          blockDurationByLine.find(rawLineIndex);
        if (duration != blockDurationByLine.end()) {
          item.blockDurationSec =
            duration->second;
        }
        currentBlockColorHex = item.blockColorHex;
      } else {
        const NativeSongWindow* actual = findActualSong(storedHashChild && markerNumber ? markerNumber : sourceNumber, sourceNumber, storedHashChild);
        // Se era filho antigo e o marker nao existe mais, nao envia filho fantasma para o app.
        if (!actual) continue;
        item = *actual;
        item.inheritedBlockColorHex = currentBlockColorHex;
        // Se a região deixou de ser pai no projeto, força tratamento como música solta.
        if (!actual->isHashParent && storedHashParent) {
          item.isHashParent = false;
          item.isHashChild = false;
          item.type = "song";
          item.parentId.clear();
          item.parentName.clear();
        }
        // Se era filho salvo mas o projeto atual já não traz esse filho, não mantém flag velha.
        if (!actual->isHashChild && storedHashChild) {
          item.isHashChild = false;
          item.parentId.clear();
          item.parentName.clear();
          item.type = actual->isHashParent ? "hash_parent" : "song";
        }
        (void)startPos; (void)endPos;
      }

      item.playlistOrder = itemIndex + 1;
      item.playlistEntryId = std::to_string(playlistIndex) + ":" + std::to_string(itemIndex + 1) + ":" + item.id;
      if (currentPlaylistActive && activeItemsOut) activeItemsOut->push_back(item);
      if (itemIndex > 0) out << ",";
      out << nativeSongToJson(item, itemIndex + 1);
      ++itemIndex;
    } else if (tag == "END" && inPlaylist) {
      out << "]}";
      inPlaylist = false;
      currentPlaylistActive = false;
    }
  }
  if (inPlaylist) out << "]}";
  out << "]";
  return out.str();
}


static bool nativeLooksNumeric(const std::string& value);

static std::string nativeResolvePlaylistNameByIndex(ReaProject* project, int targetIndex)
{
  if (!project || targetIndex <= 0) return std::string();
  const std::string data = nativeGetProjExtStateString(project, kPlaylistExtSection, kPlaylistExtKey);
  if (data.empty()) return std::string();

  int playlistIndex = 0;
  const auto lines = nativeSplit(data, '\n');
  for (const std::string& rawLine : lines) {
    if (rawLine.empty()) continue;
    const auto fields = nativeSplit(rawLine, '\t');
    if (fields.empty() || fields[0] != "PLAYLIST") continue;
    ++playlistIndex;
    if (playlistIndex != targetIndex) continue;
    return fields.size() > 1
      ? nativeTrim(nativeUnescapeExtField(fields[1]))
      : std::string("Repertório ") + std::to_string(playlistIndex);
  }
  return std::string();
}

static bool nativeApplyPlaylistMultiCommand(
  const std::string& commandBody)
{
  const std::string type =
    nativeJsonExtractString(commandBody, "type");
  if (type != "multi_project_playlists_set" &&
      type != "playlist_multi_set" &&
      type != "playlist_multi_toggle") {
    return false;
  }
  nativeTimecodeLanRecordCommand(commandBody);

  const bool current =
    g_nativeMultiProjectPlaylistsEnabled.load();
  bool enabled = !current;
  if (type != "playlist_multi_toggle") {
    std::string desired =
      nativeJsonExtractString(commandBody, "enabled");
    if (desired.empty()) {
      desired = nativeJsonExtractString(
        commandBody, "desiredState");
    }
    if (desired.empty()) {
      desired = nativeJsonExtractString(
        commandBody, "multiEnabled");
    }
    if (desired.empty()) {
      desired = nativeJsonExtractString(
        commandBody, "showAllProjectPlaylists");
    }
    enabled = nativeBoolFromText(desired, current);
  }
  if (enabled &&
      !nativeRefreshMultiProjectPlaylistsAvailability()) {
    enabled = false;
  }

  if (enabled != current) {
    g_nativeMultiProjectPlaylistsEnabled.store(enabled);
    g_nativeUiPlaylistFilterDirty.store(true);
    g_nativeForceSnapshotBuild.store(true);
    g_nativeForceStateBuild.store(true);
  }
  return true;
}

static bool nativeApplyPlaylistCommand(const std::string& commandBody)
{
  const std::string type = nativeJsonExtractString(commandBody, "type");
  if (type != "select_playlist" && type != "playlist_select" &&
      type != "set_playlist" && type != "set_active_playlist" &&
      type != "playlist_snapshot_sync") return false;
  nativeTimecodeLanRecordCommand(commandBody);
  if (!SetProjExtState_ptr) return false;

  char pathBuf[2048] = "";
  ReaProject* currentProject = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!currentProject) return false;

  if (type == "playlist_snapshot_sync") {
    const std::string data =
      nativeJsonExtractString(commandBody, "data");
    if (data.size() > 480 * 1024) return true;
    const std::string activeName = nativeTrim(
      nativeJsonExtractString(commandBody, "activePlaylistName"));
    SetProjExtState_ptr(currentProject, kPlaylistExtSection,
      kPlaylistExtKey, data.c_str());
    if (!activeName.empty()) {
      SetProjExtState_ptr(currentProject, kPlaylistExtSection,
        "LAST_PLAYLIST_NAME_V1", activeName.c_str());
    }
    if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(currentProject);
    g_nativeUiRowsSourceSignatureValid = false;
    g_nativeUiPlaylistFilterDirty.store(true);
    g_nativeForceSnapshotBuild.store(true);
    g_nativeForceStateBuild.store(true);
    if (g_nativeAppActivePanelHwnd &&
        IsWindow(g_nativeAppActivePanelHwnd)) {
      InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
    }
    return true;
  }

  std::string projectIndexValue =
    nativeJsonExtractString(
      commandBody, "projectTabIndex");
  if (projectIndexValue.empty()) {
    projectIndexValue = nativeJsonExtractString(
      commandBody, "projectIndex");
  }
  std::string projectIdValue =
    nativeJsonExtractString(commandBody, "projectId");
  const std::string projectPathValue =
    normalizeSlashes(nativeJsonExtractString(
      commandBody, "projectPath"));
  const std::string projectNameValue =
    nativeJsonExtractString(commandBody, "projectName");
  const bool hasProjectTarget =
    !projectIndexValue.empty() ||
    !projectIdValue.empty() ||
    !projectPathValue.empty() ||
    !projectNameValue.empty();
  ReaProject* project = currentProject;
  if (hasProjectTarget && EnumProjects_ptr) {
    ReaProject* target = nullptr;
    if (nativeLooksNumeric(projectIndexValue)) {
      target = EnumProjects_ptr(
        std::atoi(projectIndexValue.c_str()),
        nullptr, 0);
    }
    if (!target) {
      for (int index = 0; index < 64; ++index) {
        char candidatePathBuf[2048] = "";
        ReaProject* candidate = EnumProjects_ptr(
          index, candidatePathBuf,
          static_cast<int>(sizeof(candidatePathBuf)));
        if (!candidate) break;
        const std::string candidateId =
          std::to_string(reinterpret_cast<
            std::uintptr_t>(candidate));
        const std::string candidatePath =
          normalizeSlashes(candidatePathBuf);
        const std::string candidateName =
          nativeBasenameNoRpp(candidatePath);
        if ((!projectIdValue.empty() &&
             projectIdValue == candidateId) ||
            (!projectPathValue.empty() &&
             projectPathValue == candidatePath) ||
            (!projectNameValue.empty() &&
             projectNameValue == candidateName)) {
          target = candidate;
          break;
        }
      }
    }
    if (!target) return true;
    project = target;
  }

  if (project != currentProject) {
    // Nunca troca de aba enquanto qualquer projeto estiver com o transporte
    // ativo. Isso impede preparar fila ou disparar música em outro projeto
    // enquanto uma aba já toca.
    if (nativeAnyOpenProjectTransportActive()) {
      nativeNotifyProjectPlaylistSwitchBlocked();
      return true;
    }
    if (!SelectProjectInstance_ptr) return true;
    SelectProjectInstance_ptr(project);
  }

  std::string playlistName = nativeJsonExtractString(commandBody, "playlistName");
  if (playlistName.empty()) playlistName = nativeJsonExtractString(commandBody, "activePlaylistName");
  if (playlistName.empty()) playlistName = nativeJsonExtractString(commandBody, "currentPlaylistName");
  if (playlistName.empty()) playlistName = nativeJsonExtractString(commandBody, "name");
  playlistName = nativeTrim(playlistName);

  std::string playlistId = nativeJsonExtractString(commandBody, "playlistId");
  if (playlistId.empty()) playlistId = nativeJsonExtractString(commandBody, "activePlaylistId");
  if (playlistId.empty()) playlistId = nativeJsonExtractString(commandBody, "targetId");
  if (playlistId.empty()) playlistId = nativeJsonExtractString(commandBody, "id");
  const int playlistIndex = nativeLooksNumeric(playlistId) ? std::atoi(playlistId.c_str()) : 0;

  if (playlistName.empty()) playlistName = nativeResolvePlaylistNameByIndex(project, playlistIndex);
  if (playlistName.empty()) return true;

  SetProjExtState_ptr(project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1", playlistName.c_str());

  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    // A selecao visual antiga nao pode prender o app no repertorio anterior.
    g_nativeSelectedId.clear();
    g_nativeSelectedTab.clear();
    g_nativeSelectedStart = 0.0;
    g_nativeSelectedEnd = 0.0;
    g_nativeDirectorActivePage = "playlist";
    ++g_nativeDirectorListScrollRevision;
  }
  nativeUiClearMainRowSelection();

  g_nativeUiRowsSourceSignatureValid = false;
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static std::string nativeEscapeExtField(const std::string& value)
{
  std::string out;
  out.reserve(value.size() + 8);
  for (char c : value) {
    if (c == '\\') out += "\\\\";
    else if (c == '|') out += "\\p";
    else if (c == '\t') out += "\\t";
    else if (c == '\n') out += "\\n";
    else if (c != '\r') out += c;
  }
  return out;
}

static std::string nativeUpperNamePtBr(std::string value)
{
  static const std::pair<const char*, const char*> replacements[] = {
    {"á", "Á"}, {"à", "À"}, {"â", "Â"}, {"ã", "Ã"}, {"ä", "Ä"},
    {"é", "É"}, {"è", "È"}, {"ê", "Ê"}, {"ë", "Ë"},
    {"í", "Í"}, {"ì", "Ì"}, {"î", "Î"}, {"ï", "Ï"},
    {"ó", "Ó"}, {"ò", "Ò"}, {"ô", "Ô"}, {"õ", "Õ"}, {"ö", "Ö"},
    {"ú", "Ú"}, {"ù", "Ù"}, {"û", "Û"}, {"ü", "Ü"},
    {"ç", "Ç"}, {"ñ", "Ñ"}
  };
  for (const auto& replacement : replacements) {
    const std::string from = replacement.first;
    const std::string to = replacement.second;
    size_t pos = 0;
    while ((pos = value.find(from, pos)) != std::string::npos) {
      value.replace(pos, from.size(), to);
      pos += to.size();
    }
  }
  for (char& c : value) {
    const unsigned char byte = static_cast<unsigned char>(c);
    if (byte >= 'a' && byte <= 'z') c = static_cast<char>(byte - 'a' + 'A');
  }
  return value;
}

static std::string nativeUpperNamePtBrKeepParentheses(
  const std::string& value)
{
  std::string out;
  std::string outside;
  int depth = 0;
  const auto flushOutside = [&]() {
    if (outside.empty()) return;
    out += nativeUpperNamePtBr(outside);
    outside.clear();
  };
  for (char c : value) {
    if (c == '(') {
      if (depth == 0) flushOutside();
      ++depth;
      out += c;
    } else if (c == ')' && depth > 0) {
      out += c;
      --depth;
    } else if (depth > 0) {
      out += c;
    } else {
      outside += c;
    }
  }
  flushOutside();
  return out;
}

static std::string nativeUtf8Lower(std::string value)
{
  size_t offset = 0;
  while (offset < value.size()) {
    const unsigned char first =
      static_cast<unsigned char>(value[offset]);
    int charLength = 1;
    if (first >= 0x80) {
      charLength = wdl_utf8_parsechar(
        value.c_str() + offset, nullptr);
      if (charLength < 1 ||
          offset + static_cast<size_t>(charLength) > value.size()) {
        charLength = 1;
      }
    }
    wdl_utf8_set_char_case(&value[offset], -1);
    offset += static_cast<size_t>(charLength);
  }
  return value;
}

static std::vector<NativeUiPlaylistRecord> nativeUiReadPlaylistRecords(
  ReaProject* project)
{
  std::vector<NativeUiPlaylistRecord> playlists;
  if (!project) return playlists;
  const std::string data =
    nativeGetProjExtStateString(project, kPlaylistExtSection, kPlaylistExtKey);
  NativeUiPlaylistRecord* current = nullptr;
  const auto lines = nativeSplit(data, '\n');
  for (const std::string& rawLine : lines) {
    if (rawLine.empty()) continue;
    const auto fields = nativeSplit(rawLine, '\t');
    if (fields.empty()) continue;
    if (fields[0] == "PLAYLIST") {
      playlists.push_back(NativeUiPlaylistRecord{});
      current = &playlists.back();
      current->project = project;
      current->localIndex =
        static_cast<int>(playlists.size()) - 1;
      current->name = fields.size() > 1
        ? nativeUnescapeExtField(fields[1])
        : std::string("Repertório ") + std::to_string(playlists.size());
    } else if (fields[0] == "ITEM" && current) {
      current->itemLines.push_back(rawLine);
    } else if (fields[0] == "END") {
      current = nullptr;
    }
  }
  return playlists;
}

static std::string nativeUiWritePlaylistRecords(
  const std::vector<NativeUiPlaylistRecord>& playlists)
{
  std::ostringstream out;
  bool firstLine = true;
  const auto appendLine = [&](const std::string& line) {
    if (!firstLine) out << "\n";
    out << line;
    firstLine = false;
  };
  for (const auto& playlist : playlists) {
    appendLine(std::string("PLAYLIST\t") +
      nativeEscapeExtField(playlist.name));
    for (const std::string& itemLine : playlist.itemLines) {
      appendLine(itemLine);
    }
    appendLine("END");
  }
  return out.str();
}

static bool nativePublishPlaylistSnapshot(ReaProject* project)
{
  if (!project) return false;
  const std::string encoded = nativeGetProjExtStateString(
    project, kPlaylistExtSection, kPlaylistExtKey);
  if (encoded.size() > 480 * 1024) return false;
  const std::string activeName = nativeTrim(
    nativeGetProjExtStateString(project, kPlaylistExtSection,
      "LAST_PLAYLIST_NAME_V1"));
  std::ostringstream command;
  command << "{\"type\":\"playlist_snapshot_sync\",\"data\":"
          << nativeJsonString(encoded)
          << ",\"activePlaylistName\":"
          << nativeJsonString(activeName) << '}';
  const std::string commandBody = command.str();
  if (commandBody.size() > 512 * 1024) return false;
  nativeTimecodeLanRecordCommand(commandBody);
  return true;
}

static void nativeProjectSyncPublishInitialPlaylistOnMainThread()
{
  bool requested = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    requested = g_nativeProjectSyncPublishInitialPlaylistSnapshot &&
      g_nativeTimecodeLanMode == "project_sync" &&
      g_nativeTimecodeLanProjectSyncRole == "primary" &&
      g_nativeTimecodeLanPeerConnected;
  }
  if (!requested) return;
  ReaProject* project = getCurrentProject(nullptr, 0);
  if (!project || !nativePublishPlaylistSnapshot(project)) return;
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  if (g_nativeTimecodeLanMode == "project_sync" &&
      g_nativeTimecodeLanProjectSyncRole == "primary" &&
      g_nativeTimecodeLanPeerConnected) {
    g_nativeProjectSyncPublishInitialPlaylistSnapshot = false;
  }
}

static bool nativeUiSavePlaylistRecords(
  ReaProject* project,
  const std::vector<NativeUiPlaylistRecord>& playlists)
{
  if (!project || !SetProjExtState_ptr) return false;
  const std::string encoded = nativeUiWritePlaylistRecords(playlists);
  SetProjExtState_ptr(project, kPlaylistExtSection, kPlaylistExtKey,
    encoded.c_str());
  nativePublishPlaylistSnapshot(project);
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static int nativeUiCurrentPlaylistIndex(
  ReaProject* project,
  const std::vector<NativeUiPlaylistRecord>& playlists)
{
  if (!project || playlists.empty()) return -1;
  const std::string active = nativeTrim(nativeGetProjExtStateString(
    project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1"));
  int firstForProject = -1;
  for (size_t i = 0; i < playlists.size(); ++i) {
    if (playlists[i].project &&
        playlists[i].project != project) {
      continue;
    }
    if (firstForProject < 0) {
      firstForProject = static_cast<int>(i);
    }
    if (nativeTrim(playlists[i].name) == active) return static_cast<int>(i);
  }
  return firstForProject;
}

static double nativeUiStoredPlaylistTotalSec(
  const NativeUiPlaylistRecord& playlist)
{
  double total = 0.0;
  for (const std::string& rawLine : playlist.itemLines) {
    const auto fields = nativeSplit(rawLine, '\t');
    if (fields.size() < 5 || fields[0] != "ITEM") continue;
    const int sourceNumber = std::atoi(fields[2].c_str());
    const bool isBlock =
      fields[1] == "block" || sourceNumber < 0;
    const bool isChild =
      fields.size() > 9 && fields[9] == "1";
    if (isBlock || isChild) continue;
    total += std::max(0.0,
      std::atof(fields[4].c_str()) -
      std::atof(fields[3].c_str()));
  }
  return total;
}

static std::vector<NativeUiPlaylistRecord>
nativeUiReadOpenProjectPlaylistRecords()
{
  std::vector<NativeUiPlaylistRecord> result;
  if (!EnumProjects_ptr) return result;
  ReaProject* activeProject =
    EnumProjects_ptr(-1, nullptr, 0);
  for (int projectIndex = 0;
       projectIndex < 64; ++projectIndex) {
    char pathBuf[2048] = "";
    ReaProject* project = EnumProjects_ptr(
      projectIndex, pathBuf,
      static_cast<int>(sizeof(pathBuf)));
    if (!project) break;
    const std::string projectPath =
      normalizeSlashes(pathBuf);
    std::string projectName =
      nativeBasenameNoRpp(projectPath);
    if (projectName.empty()) {
      projectName = std::string("Projeto ") +
        std::to_string(projectIndex + 1);
    }
    auto projectPlaylists =
      nativeUiReadPlaylistRecords(project);
    const int activePlaylist =
      nativeUiCurrentPlaylistIndex(
        project, projectPlaylists);
    for (size_t localIndex = 0;
         localIndex < projectPlaylists.size();
         ++localIndex) {
      auto& playlist = projectPlaylists[localIndex];
      playlist.project = project;
      playlist.projectIndex = projectIndex;
      playlist.localIndex =
        static_cast<int>(localIndex);
      playlist.projectId = std::to_string(
        reinterpret_cast<std::uintptr_t>(project));
      playlist.projectName = projectName;
      playlist.projectPath = projectPath;
      playlist.totalSec =
        nativeUiStoredPlaylistTotalSec(playlist);
      playlist.projectActive =
        project == activeProject;
      playlist.playlistActive =
        static_cast<int>(localIndex) ==
          activePlaylist;
      result.push_back(std::move(playlist));
    }
  }
  return result;
}

static bool nativeUpdateMultiProjectPlaylistsAvailability(
  const std::vector<NativeUiPlaylistRecord>& records,
  ReaProject* currentProject)
{
  const bool available = currentProject &&
    std::any_of(records.begin(), records.end(),
      [currentProject](const NativeUiPlaylistRecord& record) {
        return record.project &&
          record.project != currentProject;
      });
  g_nativeMultiProjectPlaylistsAvailable.store(
    available);
  if (!available &&
      g_nativeMultiProjectPlaylistsEnabled.exchange(false)) {
    g_nativeUiPlaylistFilterDirty.store(true);
    g_nativeForceSnapshotBuild.store(true);
    g_nativeForceStateBuild.store(true);
  }
  return available;
}

static bool nativeRefreshMultiProjectPlaylistsAvailability()
{
  if (!EnumProjects_ptr) {
    g_nativeMultiProjectPlaylistsAvailable.store(false);
    return false;
  }
  ReaProject* currentProject =
    EnumProjects_ptr(-1, nullptr, 0);
  const auto records =
    nativeUiReadOpenProjectPlaylistRecords();
  return nativeUpdateMultiProjectPlaylistsAvailability(
    records, currentProject);
}

static std::vector<NativeUiPlaylistRecord>
nativeUiReadPlaylistDropdownRecords(ReaProject* currentProject)
{
  auto records = nativeUiReadOpenProjectPlaylistRecords();
  nativeUpdateMultiProjectPlaylistsAvailability(
    records, currentProject);
  if (g_nativeMultiProjectPlaylistsEnabled.load() ||
      !currentProject) {
    return records;
  }
  records.erase(
    std::remove_if(records.begin(), records.end(),
      [currentProject](const NativeUiPlaylistRecord& record) {
        return record.project != currentProject;
      }),
    records.end());
  return records;
}

static std::string nativeBuildOpenProjectPlaylistsJson()
{
  const auto playlists =
    nativeUiReadOpenProjectPlaylistRecords();
  ReaProject* currentProject = EnumProjects_ptr
    ? EnumProjects_ptr(-1, nullptr, 0) : nullptr;
  nativeUpdateMultiProjectPlaylistsAvailability(
    playlists, currentProject);
  std::ostringstream json;
  json << "[";
  for (size_t index = 0;
       index < playlists.size(); ++index) {
    if (index > 0) json << ",";
    const auto& playlist = playlists[index];
    const std::string localPlaylistId =
      std::to_string(playlist.localIndex + 1);
    const std::string selectorId =
      playlist.projectId + "|" + localPlaylistId;
    const bool transportActive =
      playlist.project && GetPlayStateEx_ptr &&
      GetPlayStateEx_ptr(playlist.project) != 0;
    json << "{"
         << "\"id\":" << nativeJsonString(selectorId) << ","
         << "\"selectorId\":" << nativeJsonString(selectorId) << ","
         << "\"playlistId\":" << nativeJsonString(localPlaylistId) << ","
         << "\"localPlaylistId\":" << nativeJsonString(localPlaylistId) << ","
         << "\"playlistIndex\":" << playlist.localIndex << ","
         << "\"name\":" << nativeJsonString(playlist.name) << ","
         << "\"projectId\":" << nativeJsonString(playlist.projectId) << ","
         << "\"projectIndex\":" << playlist.projectIndex << ","
         << "\"projectTabIndex\":" << playlist.projectIndex << ","
         << "\"projectName\":" << nativeJsonString(playlist.projectName) << ","
         << "\"projectPath\":" << nativeJsonString(playlist.projectPath) << ","
         << "\"projectActive\":" << (playlist.projectActive ? "true" : "false") << ","
         << "\"projectTransportActive\":" << (transportActive ? "true" : "false") << ","
         << "\"active\":"
         << (playlist.projectActive && playlist.playlistActive
              ? "true" : "false") << ","
         << "\"current\":"
         << (playlist.projectActive && playlist.playlistActive
              ? "true" : "false") << ","
         << "\"playlistTotalSec\":" << nativeNumber(playlist.totalSec) << ","
         << "\"activePlaylistTotalSec\":" << nativeNumber(playlist.totalSec) << ","
         << "\"totalSec\":" << nativeNumber(playlist.totalSec) << ","
         << "\"playlistTotalText\":"
         << nativeJsonString(
              nativeFormatTotalTextFromSeconds(
                playlist.totalSec)) << ","
         << "\"activePlaylistTotalText\":"
         << nativeJsonString(
              nativeFormatTotalTextFromSeconds(
                playlist.totalSec)) << ","
         << "\"totalText\":"
         << nativeJsonString(
              nativeFormatTotalTextFromSeconds(
                playlist.totalSec))
         << "}";
  }
  json << "]";
  return json.str();
}

static bool nativeUiPlaylistRecordBelongsToProject(
  const NativeUiPlaylistRecord& playlist,
  ReaProject* project)
{
  return project && playlist.project == project;
}

static bool nativeUiSelectedPlaylistsBelongToProject(
  ReaProject* project)
{
  if (!project) return false;
  bool foundSelection = false;
  for (const auto& entry : g_nativeUiPlaylistSelection) {
    if (!entry.second || entry.first < 0 ||
        entry.first >=
          static_cast<int>(g_nativeUiPlaylists.size())) {
      continue;
    }
    foundSelection = true;
    if (!nativeUiPlaylistRecordBelongsToProject(
          g_nativeUiPlaylists[
            static_cast<size_t>(entry.first)],
          project)) {
      return false;
    }
  }
  return foundSelection;
}

static int nativeUiPlaylistSelectedCount()
{
  int count = 0;
  for (const auto& entry : g_nativeUiPlaylistSelection) {
    if (entry.second && entry.first >= 0 &&
        entry.first < static_cast<int>(g_nativeUiPlaylists.size())) {
      ++count;
    }
  }
  return count;
}

static int nativeUiFirstSelectedPlaylist()
{
  for (const auto& entry : g_nativeUiPlaylistSelection) {
    if (entry.second && entry.first >= 0 &&
        entry.first < static_cast<int>(g_nativeUiPlaylists.size())) {
      return entry.first;
    }
  }
  return -1;
}

static bool nativeUiSelectedPlaylistEditableInCurrentProject()
{
  if (nativeUiPlaylistSelectedCount() != 1) return false;
  const int selected = nativeUiFirstSelectedPlaylist();
  if (selected < 0 ||
      selected >= static_cast<int>(
        g_nativeUiPlaylists.size())) {
    return false;
  }
  ReaProject* currentProject =
    getCurrentProject(nullptr, 0);
  return nativeUiPlaylistRecordBelongsToProject(
    g_nativeUiPlaylists[
      static_cast<size_t>(selected)],
    currentProject);
}

static void nativeUiSelectPlaylistIndex(int index, bool extend, bool range)
{
  if (index < 0 || index >= static_cast<int>(g_nativeUiPlaylists.size())) return;
  if (range) {
    const int anchor = g_nativeUiPlaylistLastClickedIndex >= 0
      ? g_nativeUiPlaylistLastClickedIndex
      : (g_nativeUiPlaylistSelectedIndex >= 0
          ? g_nativeUiPlaylistSelectedIndex : index);
    if (!extend) g_nativeUiPlaylistSelection.clear();
    const int first = std::min(anchor, index);
    const int last = std::max(anchor, index);
    for (int i = first; i <= last; ++i) {
      g_nativeUiPlaylistSelection[i] = true;
    }
  } else if (extend) {
    const auto found = g_nativeUiPlaylistSelection.find(index);
    if (found != g_nativeUiPlaylistSelection.end() && found->second) {
      g_nativeUiPlaylistSelection.erase(found);
    } else {
      g_nativeUiPlaylistSelection[index] = true;
    }
  } else {
    g_nativeUiPlaylistSelection.clear();
    g_nativeUiPlaylistSelection[index] = true;
  }
  g_nativeUiPlaylistSelectedIndex = index;
  g_nativeUiPlaylistLastClickedIndex = index;
  if (nativeUiPlaylistSelectedCount() == 1) {
    const int selected = nativeUiFirstSelectedPlaylist();
    g_nativeUiPlaylistInput =
      selected >= 0 ? g_nativeUiPlaylists[static_cast<size_t>(selected)].name
                    : std::string();
  } else {
    g_nativeUiPlaylistInput.clear();
  }
  g_nativeUiPlaylistInputCursor = g_nativeUiPlaylistInput.size();
  ReaProject* currentProject =
    getCurrentProject(nullptr, 0);
  if (!nativeUiPlaylistRecordBelongsToProject(
        g_nativeUiPlaylists[
          static_cast<size_t>(index)],
        currentProject)) {
    g_nativeUiPlaylistInputFocused = false;
  }
  if (index < g_nativeUiPlaylistScroll) g_nativeUiPlaylistScroll = index;
  if (index >= g_nativeUiPlaylistScroll + g_nativeUiPlaylistVisibleRows) {
    g_nativeUiPlaylistScroll =
      std::max(0, index - g_nativeUiPlaylistVisibleRows + 1);
  }
}

static bool nativeUiOpenPlaylistDropdown()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  // Por padrão o seletor mantém o comportamento local. O botão Multi libera
  // temporariamente os repertórios das demais abas abertas.
  g_nativeUiPlaylists =
    nativeUiReadPlaylistDropdownRecords(project);
  g_nativeUiPlaylistFilterDirty.store(false);
  g_nativeUiPlaylistSelection.clear();
  g_nativeUiPlaylistRowHits.clear();
  g_nativeUiPlaylistScroll = 0;
  g_nativeUiPlaylistVisibleRows = 1;
  g_nativeUiPlaylistLastClickedIndex = -1;
  const int active = nativeUiCurrentPlaylistIndex(project, g_nativeUiPlaylists);
  g_nativeUiPlaylistSelectedIndex = active;
  if (active >= 0) {
    g_nativeUiPlaylistSelection[active] = true;
    g_nativeUiPlaylistInput =
      g_nativeUiPlaylists[static_cast<size_t>(active)].name;
    g_nativeUiPlaylistLastClickedIndex = active;
  } else {
    g_nativeUiPlaylistInput.clear();
  }
  g_nativeUiPlaylistInputCursor = g_nativeUiPlaylistInput.size();
  g_nativeUiPlaylistInputFocused = false;
  g_nativeMainModalKind = NativeMainModalKind::PlaylistDropdown;
  return true;
}

static bool nativeUiRenameSelectedPlaylist()
{
  const int selected = nativeUiFirstSelectedPlaylist();
  std::string nextName = nativeUpperNamePtBr(nativeTrim(g_nativeUiPlaylistInput));
  if (selected < 0 || nativeUiPlaylistSelectedCount() != 1 ||
      nextName.empty()) return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  const NativeUiPlaylistRecord selectedRecord =
    g_nativeUiPlaylists[static_cast<size_t>(selected)];
  if (!nativeUiPlaylistRecordBelongsToProject(
        selectedRecord, project)) {
    return false;
  }
  auto localPlaylists =
    nativeUiReadPlaylistRecords(project);
  const int localIndex = selectedRecord.localIndex;
  if (localIndex < 0 ||
      localIndex >= static_cast<int>(
        localPlaylists.size())) {
    return false;
  }
  for (size_t i = 0; i < localPlaylists.size(); ++i) {
    if (static_cast<int>(i) == localIndex) continue;
    if (nativeUpperNamePtBr(nativeTrim(
          localPlaylists[i].name)) == nextName) {
      return false;
    }
  }
  const std::string oldName =
    localPlaylists[static_cast<size_t>(localIndex)].name;
  localPlaylists[static_cast<size_t>(localIndex)].name =
    nextName;
  const std::string activeName = nativeTrim(nativeGetProjExtStateString(
    project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1"));
  if (nativeTrim(oldName) == activeName && SetProjExtState_ptr) {
    SetProjExtState_ptr(project, kPlaylistExtSection,
      "LAST_PLAYLIST_NAME_V1", nextName.c_str());
  }
  g_nativeUiPlaylistInput = nextName;
  g_nativeUiPlaylistInputCursor = g_nativeUiPlaylistInput.size();
  if (!nativeUiSavePlaylistRecords(
        project, localPlaylists)) {
    return false;
  }
  g_nativeUiPlaylists =
    nativeUiReadPlaylistDropdownRecords(project);
  int refreshedIndex = -1;
  for (size_t index = 0;
       index < g_nativeUiPlaylists.size(); ++index) {
    const auto& candidate =
      g_nativeUiPlaylists[index];
    if (candidate.project == project &&
        candidate.localIndex == localIndex) {
      refreshedIndex = static_cast<int>(index);
      break;
    }
  }
  g_nativeUiPlaylistSelection.clear();
  if (refreshedIndex >= 0) {
    g_nativeUiPlaylistSelection[refreshedIndex] = true;
    g_nativeUiPlaylistSelectedIndex = refreshedIndex;
    g_nativeUiPlaylistLastClickedIndex =
      refreshedIndex;
  }
  return true;
}

static bool nativeUiCommitPlaylistInlineRename(bool revertInvalid)
{
  const int selected = nativeUiFirstSelectedPlaylist();
  if (selected < 0 || nativeUiPlaylistSelectedCount() != 1) {
    g_nativeUiPlaylistInputFocused = false;
    return false;
  }
  if (!nativeUiSelectedPlaylistEditableInCurrentProject()) {
    g_nativeUiPlaylistInputFocused = false;
    return false;
  }

  const std::string currentName =
    g_nativeUiPlaylists[static_cast<size_t>(selected)].name;
  const std::string nextName =
    nativeUpperNamePtBr(nativeTrim(g_nativeUiPlaylistInput));
  bool valid = !nextName.empty();
  const NativeUiPlaylistRecord& selectedRecord =
    g_nativeUiPlaylists[static_cast<size_t>(selected)];
  for (size_t index = 0;
       valid && index < g_nativeUiPlaylists.size(); ++index) {
    if (static_cast<int>(index) == selected) continue;
    if (g_nativeUiPlaylists[index].project !=
        selectedRecord.project) {
      continue;
    }
    if (nativeUpperNamePtBr(nativeTrim(
          g_nativeUiPlaylists[index].name)) == nextName) {
      valid = false;
    }
  }
  if (!valid) {
    if (revertInvalid) {
      g_nativeUiPlaylistInput = currentName;
      g_nativeUiPlaylistInputCursor = g_nativeUiPlaylistInput.size();
      g_nativeUiPlaylistInputFocused = false;
    }
    return false;
  }

  if (nextName == nativeUpperNamePtBr(nativeTrim(currentName))) {
    g_nativeUiPlaylistInput = currentName;
    g_nativeUiPlaylistInputCursor = g_nativeUiPlaylistInput.size();
    g_nativeUiPlaylistInputFocused = false;
    return true;
  }

  const bool saved = nativeUiRenameSelectedPlaylist();
  if (saved) g_nativeUiPlaylistInputFocused = false;
  return saved;
}

static bool nativeUiOpenSelectedPlaylist()
{
  const int selected = nativeUiFirstSelectedPlaylist();
  if (selected < 0 || nativeUiPlaylistSelectedCount() != 1) return false;
  const NativeUiPlaylistRecord& playlist =
    g_nativeUiPlaylists[static_cast<size_t>(selected)];
  char currentPath[2048] = "";
  ReaProject* currentProject = getCurrentProject(
    currentPath, static_cast<int>(sizeof(currentPath)));
  if (playlist.project && currentProject &&
      playlist.project != currentProject &&
      nativeAnyOpenProjectTransportActive()) {
    nativeNotifyProjectPlaylistSwitchBlocked();
    nativeUiShowTemporaryPopup(
      "Pare a reprodução antes de abrir um repertório de outra aba",
      2.4);
    return false;
  }
  std::ostringstream command;
  command << "{\"type\":\"select_playlist\",\"playlistId\":"
          << nativeJsonString(std::to_string(
               playlist.localIndex + 1))
          << ",\"playlistName\":"
          << nativeJsonString(playlist.name)
          << ",\"projectId\":"
          << nativeJsonString(playlist.projectId)
          << ",\"projectIndex\":"
          << playlist.projectIndex
          << ",\"projectPath\":"
          << nativeJsonString(playlist.projectPath)
          << ",\"projectName\":"
          << nativeJsonString(playlist.projectName)
          << "}";
  const bool handled = nativeApplyPlaylistCommand(command.str());
  if (handled) nativeUiCloseMainModal();
  return handled;
}

static bool nativeUiDeleteSelectedPlaylists()
{
  if (nativeUiPlaylistSelectedCount() <= 0) return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  if (!nativeUiSelectedPlaylistsBelongToProject(project)) {
    nativeUiShowTemporaryPopup(
      "Abra a aba do projeto para excluir esse repertório",
      2.0);
    return false;
  }
  auto localPlaylists =
    nativeUiReadPlaylistRecords(project);
  const std::string activeName = nativeTrim(nativeGetProjExtStateString(
    project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1"));
  std::set<int> localSelection;
  for (const auto& entry :
       g_nativeUiPlaylistSelection) {
    if (!entry.second || entry.first < 0 ||
        entry.first >= static_cast<int>(
          g_nativeUiPlaylists.size())) {
      continue;
    }
    const int localIndex =
      g_nativeUiPlaylists[
        static_cast<size_t>(entry.first)].localIndex;
    if (localIndex >= 0 &&
        localIndex < static_cast<int>(
          localPlaylists.size())) {
      localSelection.insert(localIndex);
    }
  }
  if (localSelection.empty()) return false;
  int fallback = *localSelection.begin();
  for (auto it = localSelection.rbegin();
       it != localSelection.rend(); ++it) {
    localPlaylists.erase(
      localPlaylists.begin() + *it);
  }
  if (!nativeUiSavePlaylistRecords(
        project, localPlaylists)) {
    return false;
  }
  if (localPlaylists.empty()) {
    if (SetProjExtState_ptr) {
      SetProjExtState_ptr(project, kPlaylistExtSection,
        "LAST_PLAYLIST_NAME_V1", "");
    }
    {
      std::lock_guard<std::mutex> lock(g_nativeMutex);
      g_nativeActivePlaylistItems.clear();
    }
    g_nativeUiRowsSourceSignatureValid = false;
    nativeUiCloseMainModal();
    nativeUiSetMainPageFromShortcut("regions");
    // Mantém o modal fechado mesmo se outras abas possuírem repertórios. Ao
    // abri-lo novamente, a lista agregada é reconstruída.
    g_nativeUiPlaylists.clear();
    return true;
  }
  bool activeStillExists = false;
  for (const auto& playlist : localPlaylists) {
    if (nativeTrim(playlist.name) == activeName) {
      activeStillExists = true;
      break;
    }
  }
  fallback = std::max(0, std::min(fallback,
    static_cast<int>(localPlaylists.size()) - 1));
  if (!activeStillExists && SetProjExtState_ptr) {
    SetProjExtState_ptr(project, kPlaylistExtSection,
      "LAST_PLAYLIST_NAME_V1",
      localPlaylists[
        static_cast<size_t>(fallback)].name.c_str());
  }
  g_nativeUiPlaylists =
    nativeUiReadPlaylistDropdownRecords(project);
  int refreshedIndex = -1;
  for (size_t index = 0;
       index < g_nativeUiPlaylists.size(); ++index) {
    const auto& candidate =
      g_nativeUiPlaylists[index];
    if (candidate.project == project &&
        candidate.localIndex == fallback) {
      refreshedIndex = static_cast<int>(index);
      break;
    }
  }
  g_nativeUiPlaylistSelection.clear();
  if (refreshedIndex >= 0) {
    g_nativeUiPlaylistSelection[refreshedIndex] = true;
  }
  g_nativeUiPlaylistSelectedIndex =
    refreshedIndex;
  g_nativeUiPlaylistLastClickedIndex =
    refreshedIndex;
  g_nativeUiPlaylistInput = refreshedIndex >= 0
    ? g_nativeUiPlaylists[
        static_cast<size_t>(refreshedIndex)].name
    : std::string();
  g_nativeUiPlaylistInputCursor =
    g_nativeUiPlaylistInput.size();
  g_nativeUiPlaylistScroll = std::max(0,
    std::min(g_nativeUiPlaylistScroll,
      std::max(0, refreshedIndex)));
  return true;
}

static std::map<int, std::vector<NativeSongWindow>>
nativeUiHashChildrenByParentNumber()
{
  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  std::map<std::string, int> parentNumberById;
  for (const auto& song : songs) {
    if (!song.isBlock && song.isHashParent &&
        song.sourceNumber > 0 && !song.id.empty()) {
      parentNumberById[song.id] = song.sourceNumber;
    }
  }
  std::map<int, std::vector<NativeSongWindow>> result;
  for (const auto& song : songs) {
    if (song.isBlock || !song.isHashChild ||
        song.parentId.empty()) {
      continue;
    }
    const auto parent = parentNumberById.find(song.parentId);
    if (parent == parentNumberById.end() || parent->second <= 0) {
      continue;
    }
    result[parent->second].push_back(song);
  }
  for (auto& entry : result) {
    std::sort(entry.second.begin(), entry.second.end(),
      [](const NativeSongWindow& left,
         const NativeSongWindow& right) {
        if (std::fabs(left.start - right.start) > 0.000001) {
          return left.start < right.start;
        }
        return left.end < right.end;
      });
  }
  return result;
}

static bool nativeUiCurrentPlaylistHasFamilyChildren()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  if (g_nativeUiPlaylists.empty()) {
    g_nativeUiPlaylists = nativeUiReadPlaylistRecords(project);
  }
  const int active = nativeUiCurrentPlaylistIndex(
    project, g_nativeUiPlaylists);
  if (active < 0 ||
      active >= static_cast<int>(g_nativeUiPlaylists.size())) {
    return false;
  }
  const auto children = nativeUiHashChildrenByParentNumber();
  if (children.empty()) return false;
  for (const std::string& itemLine :
       g_nativeUiPlaylists[static_cast<size_t>(active)].itemLines) {
    const auto fields = nativeSplit(itemLine, '\t');
    if (fields.size() < 3 || fields[0] != "ITEM" ||
        fields[1] == "block") {
      continue;
    }
    const int sourceNumber = std::atoi(fields[2].c_str());
    const auto found = children.find(sourceNumber);
    if (found != children.end() && !found->second.empty()) {
      return true;
    }
  }
  return false;
}

static bool nativeUiCopyCurrentPlaylistNames(
  bool includeChildren = false)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  const int active = nativeUiCurrentPlaylistIndex(project, g_nativeUiPlaylists);
  if (active < 0 || active >= static_cast<int>(g_nativeUiPlaylists.size())) {
    return false;
  }
  const auto& playlist = g_nativeUiPlaylists[static_cast<size_t>(active)];
  const auto childrenByParent =
    nativeUiHashChildrenByParentNumber();
  std::map<int, bool> listedParents;
  for (const std::string& itemLine : playlist.itemLines) {
    const auto fields = nativeSplit(itemLine, '\t');
    if (fields.size() < 3 || fields[0] != "ITEM" ||
        fields[1] == "block") {
      continue;
    }
    const int sourceNumber = std::atoi(fields[2].c_str());
    const bool storedParent = fields.size() > 8 &&
      fields[8] == "1";
    if (storedParent ||
        childrenByParent.find(sourceNumber) !=
          childrenByParent.end()) {
      listedParents[sourceNumber] = true;
    }
  }
  double totalSec = 0.0;
  std::vector<std::string> names;
  std::map<size_t, double> blockDurationByNameIndex;
  int currentBlockNameIndex = -1;
  const std::string familySeparator(40, '-');
  for (const std::string& itemLine : playlist.itemLines) {
    auto fields = nativeSplit(itemLine, '\t');
    if (fields.size() < 6) continue;
    const bool block = fields[1] == "block" ||
      std::atoi(fields[2].c_str()) < 0;
    const int sourceNumber = std::atoi(fields[2].c_str());
    int parentNumber = fields.size() > 12
      ? std::atoi(fields[12].c_str()) : 0;
    const bool childOfListedParent =
      !block && parentNumber > 0 &&
      listedParents[parentNumber];
    if (childOfListedParent) continue;
    const std::string itemName = nativeUnescapeExtField(fields[5]);
    if (block) {
      if (!names.empty() && !names.back().empty()) names.push_back("");
      std::string clean = nativeCleanSongName(itemName);
      if (clean.empty()) clean = "BLOCO";
      names.push_back(std::string("[") + clean + "]");
      currentBlockNameIndex =
        static_cast<int>(names.size()) - 1;
      blockDurationByNameIndex[
        static_cast<size_t>(currentBlockNameIndex)] = 0.0;
    } else {
      const double start = std::atof(fields[3].c_str());
      const double end = std::atof(fields[4].c_str());
      const double itemDurationSec =
        std::max(0.0, end - start);
      totalSec += std::max(0.0,
        std::floor(itemDurationSec + 0.5));
      if (currentBlockNameIndex >= 0) {
        blockDurationByNameIndex[
          static_cast<size_t>(
            currentBlockNameIndex)] +=
          itemDurationSec;
      }
      if (includeChildren && listedParents[sourceNumber]) {
        const auto children = childrenByParent.find(sourceNumber);
        if (children != childrenByParent.end() &&
            !children->second.empty()) {
          names.push_back(familySeparator);
          names.push_back(itemName);
          names.push_back(familySeparator);
          for (const auto& child : children->second) {
            names.push_back(child.name);
          }
          names.push_back(familySeparator);
        } else {
          names.push_back(itemName);
        }
      } else {
        names.push_back(itemName);
      }
    }
  }
  for (const auto& blockDuration :
       blockDurationByNameIndex) {
    if (blockDuration.first >= names.size()) continue;
    names[blockDuration.first] += " - " +
      nativeAppActiveFormatDuration(
        blockDuration.second);
  }
  if (names.empty()) return false;
  std::ostringstream text;
  text << playlist.name << "\n\nTempo total: "
       << nativeFormatTotalTextFromSeconds(totalSec) << "\n\n";
  for (size_t i = 0; i < names.size(); ++i) {
    if (i) text << "\n";
    text << names[i];
  }
  VS_Hook_SetClipboard(text.str().c_str());
  return true;
}

static bool nativeUiRequestCopyCurrentPlaylistNames()
{
  if (nativeUiCurrentPlaylistHasFamilyChildren()) {
    g_nativeMainModalKind =
      NativeMainModalKind::ConfirmCopyPlaylistChildren;
    return true;
  }
  const bool copied = nativeUiCopyCurrentPlaylistNames(false);
  nativeUiShowTemporaryPopup(copied
    ? "Nomes copiados" : "Repertorio vazio",
    copied ? 1.4 : 1.6);
  return copied;
}

static std::string nativeFindPlayingId(const std::vector<NativeSongWindow>& songs, double pos, std::string& nameOut, double& startOut, double& endOut)
{
  std::string id;
  double bestLen = 1e99;
  bool bestIsChild = false;
  for (const auto& s : songs) {
    if (s.isBlock) continue;
    // Intervalo fechado no inicio e aberto no fim. Quando duas regioes estao
    // coladas, o ponto compartilhado pertence exclusivamente a proxima musica.
    if (pos >= s.start && pos < s.end) {
      const double len = std::max(0.0, s.end - s.start);
      // Gaveta aberta/fechada nao participa desta escolha. Prioriza sempre a
      // regiao-filha real; o menor trecho continua sendo o desempate geral.
      const bool betterLength = len < bestLen - 0.0005;
      const bool childTieBreak = std::fabs(len - bestLen) <= 0.0005 && s.isHashChild && !bestIsChild;
      if (betterLength || childTieBreak) {
        bestLen = len;
        bestIsChild = s.isHashChild;
        id = s.id;
        nameOut = s.name;
        startOut = s.start;
        endOut = s.end;
      }
    }
  }
  return id;
}

static void nativeClearPendingPlayTarget()
{
  std::lock_guard<std::mutex> lock(g_nativeMutex);
  g_nativePendingPlayTarget = NativePendingPlayTarget{};
  ++g_nativePendingPlayTargetRevision;
}

static void nativeArmPendingPlayTarget(
  ReaProject* project,
  const NativeSongWindow& song)
{
  std::lock_guard<std::mutex> lock(g_nativeMutex);
  NativePendingPlayTarget pending;
  pending.project = project;
  pending.id = song.id;
  pending.start = song.start;
  pending.end = song.end;
  pending.requestedAt = std::chrono::steady_clock::now();
  pending.revision = ++g_nativePendingPlayTargetRevision;
  pending.active =
    project && !song.isBlock &&
    !song.id.empty() &&
    song.end > song.start + 0.0005;
  g_nativePendingPlayTarget = std::move(pending);
}

static std::string nativeFindPlayingIdWithPendingTarget(
  ReaProject* project,
  const std::vector<NativeSongWindow>& songs,
  bool playing,
  double& pos,
  std::string& nameOut,
  double& startOut,
  double& endOut)
{
  std::string playingId =
    playing
      ? nativeFindPlayingId(
          songs, pos, nameOut, startOut, endOut)
      : std::string();

  NativePendingPlayTarget pending;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    pending = g_nativePendingPlayTarget;
  }
  if (!pending.active) return playingId;

  const auto clearPendingCopy = [&]() {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (g_nativePendingPlayTarget.active &&
        g_nativePendingPlayTarget.revision ==
          pending.revision) {
      g_nativePendingPlayTarget =
        NativePendingPlayTarget{};
      ++g_nativePendingPlayTargetRevision;
    }
  };

  const auto ageMs =
    std::chrono::duration_cast<std::chrono::milliseconds>(
      std::chrono::steady_clock::now() -
        pending.requestedAt).count();
  if (pending.project != project || ageMs > 500) {
    clearPendingCopy();
    return playingId;
  }

  // Main_OnCommand(Play) pode confirmar o bit de transporte um ciclo antes
  // de GetPlayPositionEx alcançar o início pedido. Conserva o alvo enquanto
  // esse primeiro ciclo ainda não estiver tocando; Stop limpa-o explicitamente.
  if (!playing) return playingId;

  const NativeSongWindow* target = nullptr;
  const NativeSongWindow* targetById = nullptr;
  for (const auto& song : songs) {
    if (song.isBlock || song.id != pending.id) continue;
    if (!targetById) targetById = &song;
    if (std::fabs(song.start - pending.start) <= 0.003 &&
        std::fabs(song.end - pending.end) <= 0.003) {
      target = &song;
      break;
    }
  }
  if (!target) target = targetById;
  if (!target) {
    clearPendingCopy();
    return playingId;
  }

  // Assim que o REAPER entra no alvo, a posição real volta a ser a única
  // fonte. A regra de intervalos continua [início,fim), sem sobreposição.
  if (pos >= target->start && pos < target->end) {
    clearPendingCopy();
    return playingId;
  }

  const NativeSongWindow* predecessor = nullptr;
  for (const auto& song : songs) {
    if (song.isBlock) continue;
    const bool rawSong =
      !playingId.empty() && song.id == playingId &&
      pos >= song.start && pos < song.end;
    const bool containsRawPosition =
      playingId.empty() &&
      pos >= song.start && pos < song.end;
    if ((rawSong || containsRawPosition) &&
        std::fabs(song.end - target->start) <= 0.003) {
      predecessor = &song;
      break;
    }
  }

  // Corrige somente a primeira leitura obsoleta no limite de duas regiões
  // realmente coladas. Não antecipa regiões separadas nem muda overlaps.
  const bool staleAdjacentBoundary =
    predecessor &&
    pos < target->start &&
    target->start - pos <= 0.075;
  if (staleAdjacentBoundary) {
    pos = target->start;
    nameOut = target->name;
    startOut = target->start;
    endOut = target->end;
    return target->id;
  }

  clearPendingCopy();
  return playingId;
}

static std::string nativeStripJsonObjectBraces(std::string json)
{
  json = nativeTrim(json);
  if (json.size() >= 2 && json.front() == '{' && json.back() == '}') {
    json = json.substr(1, json.size() - 2);
  }
  json = nativeTrim(json);
  return json;
}


static const NativeSongWindow* nativeFindSongById(const std::vector<NativeSongWindow>& songs, const std::string& id)
{
  const std::string wanted = nativeTrim(id);
  if (wanted.empty()) return nullptr;
  for (const auto& s : songs) {
    if (s.id == wanted || std::to_string(s.sourceNumber) == wanted) return &s;
  }
  return nullptr;
}

static bool nativeLooksNumeric(const std::string& value);

static bool nativeBoolFromText(std::string value, bool fallback)
{
  value = nativeTrim(value);
  std::transform(value.begin(), value.end(), value.begin(), [](unsigned char c){ return static_cast<char>(std::tolower(c)); });
  if (value == "true" || value == "1" || value == "on" || value == "yes" || value == "playing" || value == "play") return true;
  if (value == "false" || value == "0" || value == "off" || value == "no" || value == "stopped" || value == "stop") return false;
  return fallback;
}

static bool nativeReadStopPauseModeEnabled()
{
  // Stop/Pause foi removido da interface. Ignora qualquer valor antigo
  // persistido para não continuar capturando Espaço sem um controle visível.
  return false;
}

static void nativeRefreshStopPauseModeFromExtState()
{
  g_stopPauseModeEnabled.store(nativeReadStopPauseModeEnabled());
}

static void nativeWriteStopPauseModeEnabled(bool enabled)
{
  (void)enabled;
  g_stopPauseModeEnabled.store(false);
  if (SetExtState_ptr) {
    const auto stamp = std::chrono::duration_cast<std::chrono::milliseconds>(
      std::chrono::system_clock::now().time_since_epoch()).count();
    SetExtState_ptr(kNativeExtStateSection, kStopPauseModeEnabledKey, "0", true);
    SetExtState_ptr(kNativeExtStateSection, kStopPauseModeRevisionKey, std::to_string(stamp).c_str(), true);
  }
  {
    // Stop/Pause participa da mesma revisao de retomada usada por Auto,
    // AT/BL e Auto Stop. Assim o Lua recebe o valor do Diretor antes de abrir.
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    nativeBumpSharedRevisionLocked("director");
  }
  g_nativeForceStateBuild.store(true);
}

static int nativeManualStopFadeoutClampDuration(const std::string& value)
{
  int duration = nativeLooksNumeric(nativeTrim(value)) ? std::atoi(value.c_str()) : 3;
  if (duration < 1) duration = 1;
  if (duration > 5) duration = 5;
  return duration;
}

static std::string nativeReadLuaWindowExtState(const char* key)
{
  if (!GetExtState_ptr || !key) return std::string();
  const char* raw = GetExtState_ptr(kLuaWindowExtStateSection, key);
  return raw ? std::string(raw) : std::string();
}

static std::vector<std::string> nativeManualStopFadeoutTrackIds()
{
  std::vector<std::string> out;
  std::string raw;
  bool projectValueExists = false;
  char projectPath[2048] = "";
  ReaProject* project = getCurrentProject(projectPath, static_cast<int>(sizeof(projectPath)));
  if (project && GetProjExtState_ptr) {
    std::vector<char> buffer(262144, '\0');
    const int rv = GetProjExtState_ptr(project, kManualStopFadeoutProjectSection, kManualStopFadeoutTracksKey, buffer.data(), static_cast<int>(buffer.size()));
    if (rv != 0) { projectValueExists = true; raw = buffer.data(); }
  }
  if (!projectValueExists) raw = nativeReadLuaWindowExtState(kManualStopFadeoutTracksKey);
  size_t begin = 0;
  while (begin <= raw.size()) {
    const size_t end = raw.find(';', begin);
    const std::string id = nativeTrim(raw.substr(begin, end == std::string::npos ? std::string::npos : end - begin));
    if (!id.empty() && std::find(out.begin(), out.end(), id) == out.end()) out.push_back(id);
    if (end == std::string::npos) break;
    begin = end + 1;
  }
  return out;
}

static void nativeWriteManualStopFadeoutTrackIds(const std::vector<std::string>& ids)
{
  if (!SetProjExtState_ptr) return;
  std::ostringstream joined;
  for (size_t i = 0; i < ids.size(); ++i) {
    if (i) joined << ";";
    joined << ids[i];
  }
  char projectPath[2048] = "";
  ReaProject* project = getCurrentProject(projectPath, static_cast<int>(sizeof(projectPath)));
  if (!project) return;
  SetProjExtState_ptr(project, kManualStopFadeoutProjectSection, kManualStopFadeoutTracksKey, joined.str().c_str());
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
}

static void nativeBumpManualStopFadeoutRevision()
{
  if (!SetExtState_ptr) return;
  const auto stamp = std::chrono::duration_cast<std::chrono::milliseconds>(
    std::chrono::system_clock::now().time_since_epoch()).count();
  SetExtState_ptr(kLuaWindowExtStateSection, kManualStopFadeoutRevisionKey, std::to_string(stamp).c_str(), true);
}

static bool nativePlayProtectionEnabled();

static std::string nativeBuildManualStopFadeoutJson()
{
  const bool enabled = nativeBoolFromText(nativeReadLuaWindowExtState(kManualStopFadeoutEnabledKey), false);
  const int duration = nativeManualStopFadeoutClampDuration(nativeReadLuaWindowExtState(kManualStopFadeoutDurationKey));
  const std::vector<std::string> selected = nativeManualStopFadeoutTrackIds();
  bool active = false;
  bool restorePending = false;
  double progress = 0.0;
  {
    std::lock_guard<std::mutex> lock(g_nativeManualStopFadeoutMutex);
    active = g_nativeManualStopFadeoutRuntime.active;
    restorePending = g_nativeManualStopFadeoutRuntime.restorePending;
    progress = g_nativeManualStopFadeoutRuntime.progress;
  }
  std::ostringstream json;
  json << "{";
  json << "\"enabled\":" << (enabled ? "true" : "false") << ",";
  json << "\"active\":" << (active ? "true" : "false") << ",";
  json << "\"fading\":" << (active ? "true" : "false") << ",";
  json << "\"restorePending\":" << (restorePending ? "true" : "false") << ",";
  json << "\"progress\":" << nativeNumber(std::max(0.0, std::min(1.0, progress)), 4) << ",";
  json << "\"remainingRatio\":" << nativeNumber(1.0 - std::max(0.0, std::min(1.0, progress)), 4) << ",";
  json << "\"duration\":" << duration << ",";
  json << "\"durationSec\":" << duration << ",";
  json << "\"playProtectionEnabled\":"
       << (nativePlayProtectionEnabled() ? "true" : "false")
       << ",";
  json << "\"selectedCount\":" << selected.size() << ",";
  json << "\"selectedTrackIds\":[";
  for (size_t i = 0; i < selected.size(); ++i) {
    if (i) json << ",";
    json << nativeJsonString(selected[i]);
  }
  json << "]}";
  return json.str();
}

static bool nativeApplyManualStopFadeoutCommand(const std::string& commandBody)
{
  const std::string type = nativeLower(nativeJsonExtractString(commandBody, "type"));
  const bool isGenericSet = type == "manual_stop_fadeout_set" || type == "faderout_set";
  if (!isGenericSet && type != "manual_stop_fadeout_set_enabled" && type != "manual_stop_fadeout_set_duration" &&
      type != "manual_stop_fadeout_toggle_track" && type != "manual_stop_fadeout_set_all_tracks") return false;
  nativeTimecodeLanRecordCommand(commandBody);
  if (!SetExtState_ptr) return false;

  bool changed = false;
  if (isGenericSet || type == "manual_stop_fadeout_set_enabled") {
    std::string value = nativeJsonExtractString(commandBody, "enabled");
    if (value.empty()) value = nativeJsonExtractString(commandBody, "desiredState");
    if (value.empty()) value = nativeJsonExtractString(commandBody, "fadeoutEnabled");
    if (!value.empty()) {
      const bool current = nativeBoolFromText(nativeReadLuaWindowExtState(kManualStopFadeoutEnabledKey), false);
      const bool enabled = nativeBoolFromText(value, current);
      SetExtState_ptr(kLuaWindowExtStateSection, kManualStopFadeoutEnabledKey, enabled ? "1" : "0", true);
      changed = true;
    }
  }
  if (isGenericSet || type == "manual_stop_fadeout_set_duration") {
    std::string value = nativeJsonExtractString(commandBody, "duration");
    if (value.empty()) value = nativeJsonExtractString(commandBody, "durationSec");
    if (value.empty()) value = nativeJsonExtractString(commandBody, "seconds");
    if (value.empty()) value = nativeJsonExtractString(commandBody, "fadeoutSeconds");
    if (!value.empty()) {
      const int duration = nativeManualStopFadeoutClampDuration(value);
      SetExtState_ptr(kLuaWindowExtStateSection, kManualStopFadeoutDurationKey, std::to_string(duration).c_str(), true);
      changed = true;
    }
  }
  if (type == "manual_stop_fadeout_toggle_track") {
    std::string id = nativeJsonExtractString(commandBody, "trackId");
    if (id.empty()) id = nativeJsonExtractString(commandBody, "guid");
    if (id.empty()) id = nativeJsonExtractString(commandBody, "targetId");
    id = nativeTrim(id);
    if (!id.empty()) {
      std::vector<std::string> ids = nativeManualStopFadeoutTrackIds();
      const auto it = std::find(ids.begin(), ids.end(), id);
      if (it == ids.end()) ids.push_back(id); else ids.erase(it);
      nativeWriteManualStopFadeoutTrackIds(ids);
      changed = true;
    }
  }
  if (type == "manual_stop_fadeout_set_all_tracks") {
    const bool select = nativeBoolFromText(nativeJsonExtractString(commandBody, "selected"),
      nativeBoolFromText(nativeJsonExtractString(commandBody, "enabled"), true));
    std::vector<std::string> ids;
    if (select && CountTracks_ptr && GetTrack_ptr) {
      char pathBuf[2048] = "";
      ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
      const int count = CountTracks_ptr(project);
      for (int i = 0; i < count; ++i) {
        MediaTrack* track = GetTrack_ptr(project, i);
        const std::string id = nativeTrackGuid(track, i);
        if (!id.empty()) ids.push_back(id);
      }
    }
    nativeWriteManualStopFadeoutTrackIds(ids);
    changed = true;
  }

  if (changed) {
    nativeBumpManualStopFadeoutRevision();
    g_nativeForceStateBuild.store(true);
  }
  return true;
}

static bool nativeSongIsPlayable(const NativeSongWindow& item)
{
  return !item.isBlock && !item.id.empty() && item.end > item.start + 0.0005;
}

static const NativeSongWindow* nativeFindFamilyParent(
  const NativeSongWindow& child,
  const std::vector<NativeSongWindow>& songs)
{
  if (!(child.isHashChild || child.isRegionChild) ||
      child.parentId.empty()) {
    return nullptr;
  }
  for (const auto& candidate : songs) {
    if (!candidate.isHashParent || !nativeSongIsPlayable(candidate)) continue;
    const bool sameId = candidate.id == child.parentId || std::to_string(candidate.sourceNumber) == child.parentId;
    const bool sameEnum = child.parentEnumIndex >= 0 && candidate.enumIndex == child.parentEnumIndex;
    if (sameId || sameEnum) return &candidate;
  }
  return nullptr;
}

static const NativeSongWindow* nativeFindPlayingFamilyChildLocked(
  const std::vector<NativeSongWindow>& songs,
  const std::string& playingId,
  double playPos,
  double songStart,
  double songEnd)
{
  const NativeSongWindow* best = nullptr;
  double bestLength = 1e99;
  for (const auto& candidate : songs) {
    if (!candidate.isHashChild || !nativeSongIsPlayable(candidate)) continue;
    const bool idMatch = !playingId.empty() &&
      (candidate.id == playingId || std::to_string(candidate.sourceNumber) == playingId || candidate.playlistEntryId == playingId);
    const bool boundsMatch = std::fabs(candidate.start - songStart) <= 0.002 && std::fabs(candidate.end - songEnd) <= 0.002;
    const bool containsPlay = playPos >= candidate.start && playPos < candidate.end;
    if (!idMatch && !boundsMatch && !containsPlay) continue;
    const double length = candidate.end - candidate.start;
    if (idMatch || boundsMatch || length < bestLength) {
      best = &candidate;
      bestLength = length;
      if (idMatch || boundsMatch) break;
    }
  }
  return best;
}

static bool nativeQueuedChildConflictsWithPlayingFamilyLocked(const NativeSongWindow& target)
{
  if (!target.isHashChild || target.parentId.empty() || !g_nativeCurrentTransportPlaying) return false;
  const NativeSongWindow* playingChild = nativeFindPlayingFamilyChildLocked(
    g_nativeSongWindows,
    g_nativeCurrentPlayingId,
    g_nativeCurrentPlayPosition,
    g_nativeCurrentSongStart,
    g_nativeCurrentSongEnd);
  return playingChild && !playingChild->parentId.empty() && playingChild->parentId == target.parentId;
}

static void nativeResolveQueueSourceBoundary(
  const std::vector<NativeSongWindow>& songs,
  const std::string& playingId,
  double playPos,
  double songStart,
  double songEnd,
  double& boundaryStart,
  double& boundaryEnd,
  std::string& boundaryId)
{
  boundaryStart = songStart;
  boundaryEnd = songEnd;
  boundaryId = playingId;
  const NativeSongWindow* child = nativeFindPlayingFamilyChildLocked(songs, playingId, playPos, songStart, songEnd);
  if (!child) return;
  const NativeSongWindow* parent = nativeFindFamilyParent(*child, songs);
  if (!parent) return;
  boundaryStart = parent->start;
  boundaryEnd = parent->end;
  boundaryId = parent->id;
}

static bool nativeSongBoundsMatch(const NativeSongWindow& item, double startPos, double endPos)
{
  if (startPos <= 0.0 && endPos <= 0.0) return false;
  const bool startOk = startPos <= 0.0 || std::fabs(item.start - startPos) <= 0.002;
  const bool endOk = endPos <= 0.0 || std::fabs(item.end - endPos) <= 0.002;
  return startOk && endOk;
}


static bool nativeApplyPlaylistNumberSortCommand(const std::string& commandBody)
{
  const std::string type = nativeJsonExtractString(commandBody, "type");
  if (type != "sort_playlist_by_number" && type != "playlist_sort_number" && type != "sort_repertoire_by_number") return false;
  nativeTimecodeLanRecordCommand(commandBody);
  if (!SetProjExtState_ptr) return false;

  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;

  const std::string data = nativeGetProjExtStateString(project, kPlaylistExtSection, kPlaylistExtKey);
  if (data.empty()) return true;

  std::string targetName = nativeJsonExtractString(commandBody, "playlistName");
  if (targetName.empty()) targetName = nativeJsonExtractString(commandBody, "activePlaylistName");
  if (targetName.empty()) targetName = nativeJsonExtractString(commandBody, "currentPlaylistName");
  if (targetName.empty()) targetName = nativeGetProjExtStateString(project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1");
  targetName = nativeTrim(targetName);

  std::string direction = nativeLower(nativeTrim(nativeJsonExtractString(commandBody, "direction")));
  const std::string descendingText = nativeLower(nativeTrim(nativeJsonExtractString(commandBody, "descending")));
  const bool descending =
    direction == "desc" || direction == "descending" || direction == "9-0" ||
    descendingText == "1" || descendingText == "true" || descendingText == "yes" || descendingText == "on";

  std::vector<std::string> lines = nativeSplit(data, '\n');
  bool inTarget = false;
  bool targetFound = false;
  int playlistIndex = 0;

  struct SortableLine {
    size_t lineIndex = 0;
    std::string raw;
    int key = 0;
    size_t oldOrder = 0;
  };
  std::vector<SortableLine> sortable;

  for (size_t i = 0; i < lines.size(); ++i) {
    const auto fields = nativeSplit(lines[i], '\t');
    if (fields.empty()) continue;

    if (fields[0] == "PLAYLIST") {
      ++playlistIndex;
      const std::string currentName = fields.size() > 1 ? nativeTrim(nativeUnescapeExtField(fields[1])) : std::string();
      inTarget = targetName.empty() ? (playlistIndex == 1) : (currentName == targetName);
      if (inTarget) targetFound = true;
      continue;
    }

    if (fields[0] == "END") {
      inTarget = false;
      continue;
    }

    if (!inTarget || fields[0] != "ITEM") continue;

    const std::string itemType = fields.size() > 1 ? nativeLower(nativeTrim(fields[1])) : std::string();
    const int sourceNumber = fields.size() > 2 ? std::atoi(fields[2].c_str()) : 0;
    const bool isBlock = itemType == "block" || itemType == "bloco" || sourceNumber < 0;
    if (isBlock) continue;

    SortableLine entry;
    entry.lineIndex = i;
    entry.raw = lines[i];
    entry.key = sourceNumber;
    entry.oldOrder = sortable.size();
    sortable.push_back(entry);
  }

  if (!targetFound || sortable.size() <= 1) return true;

  std::vector<SortableLine> sorted = sortable;
  std::stable_sort(sorted.begin(), sorted.end(), [descending](const SortableLine& a, const SortableLine& b) {
    if (a.key == b.key) return a.oldOrder < b.oldOrder;
    return descending ? (a.key > b.key) : (a.key < b.key);
  });

  bool changed = false;
  for (size_t i = 0; i < sortable.size(); ++i) {
    if (lines[sortable[i].lineIndex] != sorted[i].raw) changed = true;
    lines[sortable[i].lineIndex] = sorted[i].raw;
  }

  if (!changed) {
    g_nativeForceStateBuild.store(true);
    return true;
  }

  std::ostringstream rebuilt;
  for (size_t i = 0; i < lines.size(); ++i) {
    rebuilt << lines[i];
    if (i + 1 < lines.size()) rebuilt << '\n';
  }

  SetProjExtState_ptr(project, kPlaylistExtSection, kPlaylistExtKey, rebuilt.str().c_str());

  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeSelectedId.clear();
    g_nativeSelectedTab.clear();
    g_nativeSelectedStart = 0.0;
    g_nativeSelectedEnd = 0.0;
  }
  nativeUiClearMainRowSelection();

  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}


static bool nativeSongIdMatches(const NativeSongWindow& item, const std::string& idValue)
{
  if (idValue.empty()) return false;
  return item.id == idValue || std::to_string(item.sourceNumber) == idValue || item.playlistEntryId == idValue;
}

static const NativeSongWindow* nativeFindSongForCommand(const std::string& idValue, double startPos, double endPos);

static bool nativeSongIsCurrentPlayingLocked(const NativeSongWindow& item)
{
  if (!g_nativeCurrentTransportPlaying || !nativeSongIsPlayable(item)) return false;
  if (!g_nativeCurrentPlayingId.empty() && nativeSongIdMatches(item, g_nativeCurrentPlayingId)) return true;
  if (g_nativeCurrentSongEnd > g_nativeCurrentSongStart + 0.0005) {
    const bool sameStart = std::fabs(item.start - g_nativeCurrentSongStart) <= 0.002;
    const bool sameEnd = std::fabs(item.end - g_nativeCurrentSongEnd) <= 0.002;
    if (sameStart && sameEnd) return true;

    // Tanto marker-filho antigo quanto regiao-filho da segunda faixa impedem
    // enfileirar o proprio pai enquanto uma musica-filha estiver tocando.
    const bool itemContainsCurrentChild =
      item.isHashParent &&
      item.start <= g_nativeCurrentSongStart + 0.002 &&
      item.end >= g_nativeCurrentSongEnd - 0.002 &&
      (item.end - item.start) > (g_nativeCurrentSongEnd - g_nativeCurrentSongStart) + 0.002;
    if (itemContainsCurrentChild) return true;
  }
  return false;
}

