static void nativeUiReleaseBackBuffer()
{
  g_nativeUiBackBuffer.reset();
  g_nativeUiBackBufferWidth = 0;
  g_nativeUiBackBufferHeight = 0;
  g_nativeUiBackBufferHasFrame = false;
}

static HDC nativeUiBackBuffer(
  HDC paintDc,
  int width,
  int height)
{
  if (!paintDc || width <= 0 || height <= 0) return nullptr;
  if (g_nativeUiBackBuffer &&
      g_nativeUiBackBufferWidth == width &&
      g_nativeUiBackBufferHeight == height) {
    return g_nativeUiBackBuffer->GetDC();
  }

  nativeUiReleaseBackBuffer();
  g_nativeUiBackBuffer =
    std::make_unique<WDL_WinMemBitmap>();
  g_nativeUiBackBuffer->DoSize(paintDc, width, height);
  if (!g_nativeUiBackBuffer->GetDC()) {
    nativeUiReleaseBackBuffer();
    return nullptr;
  }
  g_nativeUiBackBufferWidth = width;
  g_nativeUiBackBufferHeight = height;
  return g_nativeUiBackBuffer->GetDC();
}

static void nativeUiReleasePaintResources()
{
  nativeUiReleaseBackBuffer();
  for (const auto& item : g_nativeUiBrushCache) {
    if (item.second) DeleteObject(item.second);
  }
  g_nativeUiBrushCache.clear();
  for (const auto& item : g_nativeUiPenCache) {
    if (item.second) DeleteObject(item.second);
  }
  g_nativeUiPenCache.clear();
  g_nativeUiTextWidthCache.clear();
  for (const auto& item : g_nativeUiConfiguredFonts) {
    if (item.second) DeleteObject(item.second);
  }
  g_nativeUiConfiguredFonts.clear();
  for (const auto& item : g_nativeUiCompactBlockFonts) {
    if (item.second) DeleteObject(item.second);
  }
  g_nativeUiCompactBlockFonts.clear();
  g_nativeUiButtonPaintFont = nullptr;
  if (g_nativeUiTimerFont) {
    DeleteObject(g_nativeUiTimerFont);
    g_nativeUiTimerFont = nullptr;
  }
  if (g_nativeUiInfoStripFont) {
    DeleteObject(g_nativeUiInfoStripFont);
    g_nativeUiInfoStripFont = nullptr;
  }
  if (g_nativeUiMultiLoopFont) {
    DeleteObject(g_nativeUiMultiLoopFont);
    g_nativeUiMultiLoopFont = nullptr;
  }
  if (g_nativeUiPopupFont) {
    DeleteObject(g_nativeUiPopupFont);
    g_nativeUiPopupFont = nullptr;
  }
  if (g_nativeUiSharedFont) {
    DeleteObject(g_nativeUiSharedFont);
    g_nativeUiSharedFont = nullptr;
  }
  if (g_nativeUiBlockTimeFont) {
    DeleteObject(g_nativeUiBlockTimeFont);
    g_nativeUiBlockTimeFont = nullptr;
  }
}

static void nativeAppActiveDrawBlackShadow(HDC dc, const RECT& rect)
{
  if (!dc || rect.right <= rect.left || rect.bottom <= rect.top) return;
#ifdef _WIN32
  using AlphaBlendProc = BOOL (WINAPI*)(HDC, int, int, int, int, HDC, int, int, int, int, BLENDFUNCTION);
  static HMODULE module = LoadLibraryW(L"msimg32.dll");
  static AlphaBlendProc alphaBlend = module
    ? reinterpret_cast<AlphaBlendProc>(GetProcAddress(module, "AlphaBlend"))
    : nullptr;
  if (alphaBlend) {
    HDC layer = CreateCompatibleDC(dc);
    HBITMAP bitmap = CreateCompatibleBitmap(dc, 1, 1);
    HGDIOBJ oldBitmap = SelectObject(layer, bitmap);
    SetPixelV(layer, 0, 0, RGB(0, 0, 0));
    BLENDFUNCTION blend{};
    blend.BlendOp = AC_SRC_OVER;
    blend.SourceConstantAlpha = 176;
    alphaBlend(dc, rect.left, rect.top, rect.right - rect.left, rect.bottom - rect.top,
      layer, 0, 0, 1, 1, blend);
    SelectObject(layer, oldBitmap);
    DeleteObject(bitmap);
    DeleteDC(layer);
    return;
  }
#else
  // O SWELL/LICE oferece pincel com alpha no macOS. Ele mistura a sombra
  // diretamente no backbuffer, preservando a interface visível por trás sem
  // o pontilhado que gerava listras em telas Retina.
  HBRUSH shadowBrush =
    CreateSolidBrushAlpha(RGB(0, 0, 0), 0.62f);
  if (shadowBrush) {
    FillRect(dc, &rect, shadowBrush);
    DeleteObject(shadowBrush);
  } else {
    nativeAppActiveFillRect(dc, rect, RGB(19, 23, 29));
  }
  return;
#endif
  // Fallback raro do Windows quando AlphaBlend nao estiver disponivel.
  nativeAppActiveFillRect(dc, rect, RGB(3, 5, 8));
}

static void nativeAppActiveDrawText(HDC dc, const std::string& text, RECT rect, UINT flags, COLORREF color, HFONT font)
{
  rect = nativeUiCustomizePaintRect(rect);
  HGDIOBJ oldFont = font ? SelectObject(dc, font) : nullptr;
  SetBkMode(dc, TRANSPARENT);
  SetTextColor(dc, color);
#ifdef _WIN32
  const int required = MultiByteToWideChar(CP_UTF8, 0, text.c_str(), -1, nullptr, 0);
  if (required > 0) {
    std::vector<wchar_t> wide(static_cast<size_t>(required), L'\0');
    MultiByteToWideChar(CP_UTF8, 0, text.c_str(), -1, wide.data(), required);
    DrawTextW(dc, wide.data(), -1, &rect, flags);
  }
#else
  DrawText(dc, text.c_str(), -1, &rect, flags);
#endif
  if (oldFont) SelectObject(dc, oldFont);
}

static int nativeAppActiveMeasureTextHeight(
  HDC dc,
  const std::string& text,
  int width,
  UINT flags,
  HFONT font)
{
  RECT measured{0, 0, std::max(1, width), 1};
  HGDIOBJ oldFont = font ? SelectObject(dc, font) : nullptr;
#ifdef _WIN32
  const int required = MultiByteToWideChar(
    CP_UTF8, 0, text.c_str(), -1, nullptr, 0);
  if (required > 0) {
    std::vector<wchar_t> wide(
      static_cast<size_t>(required), L'\0');
    MultiByteToWideChar(
      CP_UTF8, 0, text.c_str(), -1, wide.data(), required);
    DrawTextW(dc, wide.data(), -1, &measured,
      flags | DT_CALCRECT);
  }
#else
  DrawText(dc, text.c_str(), -1, &measured,
    flags | DT_CALCRECT);
#endif
  if (oldFont) SelectObject(dc, oldFont);
  return std::max(1, static_cast<int>(
    measured.bottom - measured.top));
}

static std::vector<std::string> nativeAppActiveWrapPopupText(
  HDC dc,
  const std::string& text,
  int maximumWidth,
  HFONT font)
{
  std::vector<std::string> lines;
  maximumWidth = std::max(1, maximumWidth);
  for (const std::string& paragraph : nativeSplit(text, '\n')) {
    if (paragraph.empty()) {
      lines.emplace_back();
      continue;
    }
    std::string line;
    size_t cursor = 0;
    while (cursor < paragraph.size()) {
      while (cursor < paragraph.size() &&
             (paragraph[cursor] == ' ' ||
              paragraph[cursor] == '\t' ||
              paragraph[cursor] == '\r')) {
        ++cursor;
      }
      if (cursor >= paragraph.size()) break;
      const size_t wordStart = cursor;
      while (cursor < paragraph.size() &&
             paragraph[cursor] != ' ' &&
             paragraph[cursor] != '\t' &&
             paragraph[cursor] != '\r') {
        ++cursor;
      }
      const std::string word = paragraph.substr(
        wordStart, cursor - wordStart);
      const std::string candidate = line.empty()
        ? word : line + " " + word;
      if (!line.empty() &&
          nativeUiTextWidth(dc, candidate, font) > maximumWidth) {
        lines.push_back(line);
        line = word;
      } else {
        line = candidate;
      }
    }
    if (!line.empty()) lines.push_back(line);
  }
  if (lines.empty()) lines.emplace_back();
  return lines;
}

static std::string nativeAppActiveSongNameForState(
  const std::vector<NativeSongWindow>& playlistItems,
  const std::vector<NativeSongWindow>& songs,
  const std::string& id,
  double start,
  double end)
{
  const NativeSongWindow* rangeMatch = nullptr;
  double rangeMatchDuration = 1.0e100;
  auto scan = [&](const std::vector<NativeSongWindow>& items) -> const NativeSongWindow* {
    for (const auto& item : items) {
      if (!nativeSongIsPlayable(item)) continue;
      if (!id.empty() && nativeSongIdMatches(item, id)) return &item;
      if (end > start + 0.0005 &&
          std::fabs(item.start - start) <= 0.003 && std::fabs(item.end - end) <= 0.003) {
        const double duration = item.end - item.start;
        if (!rangeMatch || duration < rangeMatchDuration) {
          rangeMatch = &item;
          rangeMatchDuration = duration;
        }
      }
    }
    return nullptr;
  };

  const NativeSongWindow* exact = scan(playlistItems);
  if (!exact) exact = scan(songs);
  const NativeSongWindow* result = exact ? exact : rangeMatch;
  return result ? nativeCleanSongName(result->name) : std::string();
}

static std::string nativeAppActiveArmedPartName(ReaProject* project, const std::string& markerId)
{
  if (!project || markerId.empty() || !CountProjectMarkers_ptr || !EnumProjectMarkers3_ptr) return std::string();
  int wantedNumber = 0;
  std::string numericId = markerId;
  if (!numericId.empty() && (numericId[0] == 'm' || numericId[0] == 'M')) numericId.erase(numericId.begin());
  if (!nativeLooksNumeric(numericId)) return std::string();
  wantedNumber = std::atoi(numericId.c_str());

  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  for (int i = 0; i < total; ++i) {
    bool isRegion = false;
    double pos = 0.0;
    double end = 0.0;
    const char* rawName = nullptr;
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, i, &isRegion, &pos, &end, &rawName, &number, &color)) continue;
    if (isRegion || number != wantedNumber) continue;
    std::string name = nativeTrim(rawName ? rawName : "");
    if (nativeStartsWith(name, "*1") || nativeStartsWith(name, "*2") ||
        nativeStartsWith(name, "*3") || nativeStartsWith(name, "*4")) {
      name = nativeTrim(name.substr(2));
    }
    else if (!name.empty() && (name[0] == '$' || name[0] == '!')) name = nativeTrim(name.substr(1));
    while (!name.empty() && (name[0] == '-' || name[0] == ':' || name[0] == ' ')) name.erase(name.begin());
    return nativeTrim(name);
  }
  return std::string();
}

static bool nativeParsePartsMarkerLabel(
  const std::string& rawName,
  std::string& prefixOut,
  std::string& labelOut)
{
  std::string name = nativeTrim(rawName);
  prefixOut.clear();
  labelOut.clear();
  if (name.empty() || name[0] == '!') return false;

  if (name[0] == '$') {
    prefixOut = "$";
    name.erase(name.begin());
  } else if (name[0] == '*') {
    size_t digitIndex = 1;
    while (digitIndex < name.size() &&
        std::isspace(static_cast<unsigned char>(name[digitIndex]))) {
      ++digitIndex;
    }
    if (digitIndex >= name.size() ||
        (name[digitIndex] < '1' || name[digitIndex] > '4')) {
      return false;
    }
    prefixOut = std::string("*") + name[digitIndex];
    name = name.substr(digitIndex + 1);
  } else {
    return false;
  }

  name = nativeTrim(name);
  while (!name.empty() &&
      (name[0] == '-' || name[0] == ':' || name[0] == ' ')) {
    name.erase(name.begin());
  }
  labelOut = nativeTrim(name);
  if (labelOut.empty()) labelOut = "sem nome";
  return true;
}

static const NativeSongWindow* nativeFindPanelSongForState(
  const std::vector<NativeSongWindow>& primary,
  const std::vector<NativeSongWindow>& secondary,
  const std::string& id,
  double start,
  double end)
{
  const NativeSongWindow* rangeMatch = nullptr;
  const auto scan = [&](const std::vector<NativeSongWindow>& items) -> const NativeSongWindow* {
    for (size_t i = 0; i < items.size(); ++i) {
      const NativeSongWindow& item = items[i];
      if (item.isBlock) continue;
      if (!id.empty() && item.id == id) return &item;
      if (!rangeMatch && end > start + 0.0005 &&
          std::fabs(item.start - start) <= 0.003 &&
          std::fabs(item.end - end) <= 0.003) {
        rangeMatch = &item;
      }
    }
    return nullptr;
  };

  const NativeSongWindow* exact = scan(primary);
  if (!exact) exact = scan(secondary);
  return exact ? exact : rangeMatch;
}

static const NativeSongWindow* nativeResolvePartsSource(
  bool parts2,
  bool regionsPage,
  bool playing,
  const std::vector<NativeSongWindow>& songs,
  const std::vector<NativeSongWindow>& playlistItems,
  const std::string& playingId,
  double playingStart,
  double playingEnd,
  const std::string& queuedId,
  double queuedStart,
  double queuedEnd,
  const std::string& selectedId,
  double selectedStart,
  double selectedEnd)
{
  if (parts2) {
    // Parts 2 segue primeiro a fila manual/ativa, inclusive o alvo do AT/BL.
    if (!queuedId.empty() && queuedEnd > queuedStart + 0.0005) {
      const NativeSongWindow* queued = nativeFindPanelSongForState(
        playlistItems, songs, queuedId, queuedStart, queuedEnd);
      if (queued) return queued;
    }
    if (regionsPage) {
      return nativeFindPanelSongForState(
        songs, playlistItems, selectedId, selectedStart, selectedEnd);
    }
    return nativeFindPanelSongForState(
      playlistItems, songs, selectedId, selectedStart, selectedEnd);
  }

  // Parts 1 acompanha primeiro a música realmente em execução.
  if (playing && playingEnd > playingStart + 0.0005) {
    const NativeSongWindow* current = nativeFindPanelSongForState(
      songs, playlistItems, playingId, playingStart, playingEnd);
    if (current) return current;
  }
  if (!playingId.empty()) {
    const NativeSongWindow* rememberedPlaying = nativeFindPanelSongForState(
      playlistItems, songs, playingId, playingStart, playingEnd);
    if (rememberedPlaying) return rememberedPlaying;
  }
  if (regionsPage) {
    return nativeFindPanelSongForState(
      songs, playlistItems, selectedId, selectedStart, selectedEnd);
  }
  return nativeFindPanelSongForState(
    playlistItems, songs, selectedId, selectedStart, selectedEnd);
}

static double nativeResolvePartsRegressTrigger(
  ReaProject* project,
  double startPos,
  double contextStart,
  double contextEnd)
{
  if (!project || !CountProjectMarkers_ptr ||
      !EnumProjectMarkers3_ptr ||
      contextEnd <= contextStart + 0.001) {
    return 0.0;
  }

  const double threshold = startPos + 0.0005;
  double nearest = 0.0;
  bool found = false;
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(
    project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  for (int index = 0; index < total; ++index) {
    bool isRegion = false;
    double pos = 0.0;
    double end = 0.0;
    const char* rawName = nullptr;
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, index,
          &isRegion, &pos, &end, &rawName,
          &number, &color) || isRegion) {
      continue;
    }
    if (pos <= threshold ||
        pos < contextStart - 0.001 ||
        pos > contextEnd + 0.001) {
      continue;
    }

    // vshook_marker_belongs_to_cancel_region usa a mesma regra de Parts:
    // somente $ / *1 / *2 / *3 / *4 e nunca markers iniciados por !.
    std::string prefix;
    std::string label;
    if (!nativeParsePartsMarkerLabel(
          rawName ? rawName : "", prefix, label)) {
      continue;
    }
    if (!found || pos < nearest) {
      nearest = pos;
      found = true;
    }
  }

  if (found) return nearest;
  return contextEnd > startPos + 0.001
    ? contextEnd : 0.0;
}

static NativeAppActivePanelModel::PartColumn nativeBuildPartsColumn(
  ReaProject* project,
  const NativeSongWindow* source,
  const std::map<std::string, bool>& openFamilyDrawers,
  const std::string& armedMarkerId,
  double armedTargetPos,
  double armedOriginPos,
  double regressTriggerPos,
  double playPosition)
{
  NativeAppActivePanelModel::PartColumn column;
  if (!source || source->isBlock) return column;

  column.hasSource = true;
  column.sourceId = source->id;
  column.sourceName = nativeCleanSongName(source->name);
  if (column.sourceName.empty()) column.sourceName = "SEM NOME";
  column.sourceStart = source->start;
  column.sourceEnd = source->end;

  // Regiões-pai mostram os seus Parts somente quando a gaveta de filhos está
  // recolhida, exatamente como vshook_hash_container_should_show_parts no Lua.
  if (source->isHashParent) {
    const auto drawer = openFamilyDrawers.find(source->id);
    if (drawer != openFamilyDrawers.end() && drawer->second) return column;
  }

  if (project && CountProjectMarkers_ptr && EnumProjectMarkers3_ptr &&
      source->end >= source->start) {
    int markerCount = 0;
    int regionCount = 0;
    int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
    if (total <= 0) total = markerCount + regionCount;
    const double lo = std::min(source->start, source->end) - 0.000001;
    const double hi = std::max(source->start, source->end) + 0.000001;
    for (int i = 0; i < total; ++i) {
      bool isRegion = false;
      double pos = 0.0;
      double end = 0.0;
      const char* rawName = nullptr;
      int number = 0;
      int color = 0;
      if (!EnumProjectMarkers3_ptr(project, i, &isRegion, &pos, &end,
          &rawName, &number, &color) || isRegion) continue;
      if (pos < lo || pos > hi) continue;

      std::string prefix;
      std::string label;
      const std::string fullName = rawName ? rawName : "";
      if (!nativeParsePartsMarkerLabel(fullName, prefix, label)) continue;

      NativeAppActivePanelModel::PartRow row;
      row.id = std::string("m") + std::to_string(number);
      row.name = label;
      row.rawName = fullName;
      row.prefix = prefix;
      row.pos = pos;
      row.number = number;
      row.enumIndex = i;
      row.color = color;
      column.rows.push_back(std::move(row));
    }
    std::sort(column.rows.begin(), column.rows.end(),
      [](const NativeAppActivePanelModel::PartRow& a,
         const NativeAppActivePanelModel::PartRow& b) {
        if (std::fabs(a.pos - b.pos) > 0.000001) return a.pos < b.pos;
        return a.number < b.number;
      });
  }

  if (!armedMarkerId.empty() &&
      armedTargetPos >= std::min(source->start, source->end) - 0.001 &&
      armedTargetPos <= std::max(source->start, source->end) + 0.001) {
    const double total = regressTriggerPos - armedOriginPos;
    if (total > 0.001) {
      column.regressActive = true;
      column.regressStart = armedOriginPos;
      column.regressEnd = regressTriggerPos;
      const double remaining = std::max(
        0.0, regressTriggerPos - playPosition);
      column.regressRatio = std::max(0.0, std::min(1.0,
        remaining / total));
    }
  }
  return column;
}

static bool nativeAppActivePartRowsEqual(
  const std::vector<NativeAppActivePanelModel::PartRow>& left,
  const std::vector<NativeAppActivePanelModel::PartRow>& right)
{
  if (left.size() != right.size()) return false;
  for (size_t i = 0; i < left.size(); ++i) {
    const auto& a = left[i];
    const auto& b = right[i];
    if (a.id != b.id || a.name != b.name || a.rawName != b.rawName ||
        a.prefix != b.prefix || std::fabs(a.pos - b.pos) > 0.000001 ||
        a.number != b.number || a.enumIndex != b.enumIndex || a.color != b.color) {
      return false;
    }
  }
  return true;
}

static bool nativeAppActivePartColumnsEqual(
  const NativeAppActivePanelModel::PartColumn& left,
  const NativeAppActivePanelModel::PartColumn& right)
{
  return left.hasSource == right.hasSource &&
    left.sourceId == right.sourceId &&
    left.sourceName == right.sourceName &&
    std::fabs(left.sourceStart - right.sourceStart) <= 0.0005 &&
    std::fabs(left.sourceEnd - right.sourceEnd) <= 0.0005 &&
    left.regressActive == right.regressActive &&
    std::fabs(left.regressStart - right.regressStart) <= 0.000001 &&
    std::fabs(left.regressEnd - right.regressEnd) <= 0.000001 &&
    // O Lua redesenha o regresso em cada ciclo. Uma tolerancia de 0.001 fazia
    // a barra andar em saltos perceptiveis quando o intervalo era longo.
    std::fabs(left.regressRatio - right.regressRatio) <= 0.000001 &&
    nativeAppActivePartRowsEqual(left.rows, right.rows);
}

static std::string nativeAppActiveFormatDuration(double seconds)
{
  if (!std::isfinite(seconds) || seconds < 0.0) seconds = 0.0;
  const int total = static_cast<int>(std::floor(seconds + 0.5));
  const int hours = total / 3600;
  const int minutes = (total % 3600) / 60;
  const int secs = total % 60;
  char text[32] = "";
  if (hours > 0) std::snprintf(text, sizeof(text), "%d:%02d:%02d", hours, minutes, secs);
  else std::snprintf(text, sizeof(text), "%02d:%02d", minutes, secs);
  return std::string(text);
}

static bool nativeAppActiveColorFromHex(const std::string& raw, COLORREF& colorOut)
{
  std::string value = nativeTrim(raw);
  if (!value.empty() && value[0] == '#') value.erase(value.begin());
  if (value.size() != 6) return false;
  char* end = nullptr;
  const unsigned long rgb = std::strtoul(value.c_str(), &end, 16);
  if (!end || end != value.c_str() + value.size()) return false;
  colorOut = RGB((rgb >> 16) & 0xff, (rgb >> 8) & 0xff, rgb & 0xff);
  return true;
}

static COLORREF nativeDrawerColor(const std::string& raw)
{
  const std::string value = nativeLower(nativeTrim(raw));
  if (value == "green") return RGB(26, 255, 87);
  if (value == "blue") return RGB(51, 148, 255);
  if (value == "purple") return RGB(184, 82, 255);
  if (value == "red") return RGB(255, 56, 46);
  if (value == "orange") return RGB(255, 133, 20);
  if (value == "cyan") return RGB(31, 235, 255);
  if (value == "white") return RGB(235, 242, 255);
  if (value == "gray" || value == "grey") {
    return kNativeUiUnifiedDarkGray;
  }
  return RGB(255, 240, 46);
}

static bool nativeAppActiveRowMatches(
  const NativeAppActivePanelModel::Row& row,
  const std::string& id,
  double start,
  double end)
{
  const bool hasBounds = end > start + 0.0005;
  if (!id.empty() && row.id != id) return false;
  if (hasBounds) {
    return std::fabs(row.start - start) <= 0.003 &&
      std::fabs(row.end - end) <= 0.003;
  }
  return !id.empty();
}

static void nativeUiHashBytes(
  uint64_t& hash,
  const void* data,
  size_t size)
{
  const auto* bytes = static_cast<const unsigned char*>(data);
  for (size_t index = 0; index < size; ++index) {
    hash ^= static_cast<uint64_t>(bytes[index]);
    hash *= 1099511628211ull;
  }
}

template <typename T>
static void nativeUiHashValue(uint64_t& hash, const T& value)
{
  nativeUiHashBytes(hash, &value, sizeof(value));
}

static void nativeUiHashString(
  uint64_t& hash,
  const std::string& value)
{
  nativeUiHashBytes(hash, value.data(), value.size());
  const unsigned char separator = 0xff;
  nativeUiHashBytes(hash, &separator, 1);
}

static uint64_t nativeUiRowsSourceSignature(
  const std::vector<NativeSongWindow>& songs,
  const std::vector<NativeSongWindow>& playlistItems,
  const std::map<std::string, bool>& openFamilyDrawers,
  const std::map<std::string, bool>& liveExecutedItems,
  bool regionsPage,
  bool liveEnabled)
{
  uint64_t hash = 1469598103934665603ull;
  nativeUiHashValue(hash, regionsPage);
  nativeUiHashValue(hash, liveEnabled);
  const auto hashSong = [&](const NativeSongWindow& item) {
    nativeUiHashString(hash, item.id);
    nativeUiHashString(hash, item.name);
    nativeUiHashString(hash, item.parentId);
    nativeUiHashString(hash, item.blockColorHex);
    nativeUiHashString(hash, item.inheritedBlockColorHex);
    nativeUiHashValue(hash, item.start);
    nativeUiHashValue(hash, item.end);
    nativeUiHashValue(hash, item.blockDurationSec);
    nativeUiHashValue(hash, item.playlistOrder);
    nativeUiHashValue(hash, item.sourceNumber);
    nativeUiHashValue(hash, item.enumIndex);
    nativeUiHashValue(hash, item.tunerValue);
    nativeUiHashValue(hash, item.bpmAvailable);
    nativeUiHashValue(hash, item.bpmValue);
    nativeUiHashValue(hash, item.bpmOriginal);
    nativeUiHashValue(hash, item.bpmGeneric);
    nativeUiHashValue(hash, item.isBlock);
    nativeUiHashValue(hash, item.isHashChild);
    nativeUiHashValue(hash, item.isRegionChild);
    nativeUiHashValue(hash, item.isHashParent);
    nativeUiHashValue(hash, item.liveExecuted);
  };
  nativeUiHashValue(hash, songs.size());
  for (const auto& item : songs) hashSong(item);
  nativeUiHashValue(hash, playlistItems.size());
  for (const auto& item : playlistItems) hashSong(item);
  nativeUiHashValue(hash, openFamilyDrawers.size());
  for (const auto& item : openFamilyDrawers) {
    nativeUiHashString(hash, item.first);
    nativeUiHashValue(hash, item.second);
  }
  nativeUiHashValue(hash, liveExecutedItems.size());
  for (const auto& item : liveExecutedItems) {
    nativeUiHashString(hash, item.first);
    nativeUiHashValue(hash, item.second);
  }
  return hash;
}

static bool nativePartsBlinkBright()
{
  const auto now = std::chrono::steady_clock::now().time_since_epoch();
  const auto millis = std::chrono::duration_cast<std::chrono::milliseconds>(now).count();
  return ((millis / 125) % 2) == 0;
}

