static int nativeUiVisualPresetIndex(
  const std::map<std::string, std::string>& values)
{
  const auto found = values.find(
    "visual_preset_index");
  return std::max(0, std::min(3,
    found == values.end()
      ? 0 : std::atoi(found->second.c_str())));
}

static std::string nativeUiVisualRawValue(
  const std::map<std::string, std::string>& values,
  const std::string& key)
{
  const auto found = values.find(key);
  if (found != values.end()) return found->second;
  const auto fallback =
    nativeUiVisualDefaults().find(key);
  return fallback == nativeUiVisualDefaults().end()
    ? std::string() : fallback->second;
}

static std::string nativeUiLiveMarkColorMode(
  const std::map<std::string, std::string>& values)
{
  std::string mode = nativeLower(nativeUiVisualPref(
    values, "live_mark_color_mode", "red"));
  const int presetIndex = nativeUiVisualPresetIndex(values);
  // Antes desta versão, o Padrão era gravado como cinza e não podia ser
  // editado. Migra somente esse valor legado; depois que o usuário escolher
  // uma cor, inclusive Cinza ou Nenhum, a escolha passa a prevalecer.
  if (presetIndex == 0 && mode == "gray" && GetExtState_ptr) {
    const char* chosen = GetExtState_ptr(
      kLuaWindowExtStateSection,
      "LIVE_MARK_DEFAULT_COLOR_CHOSEN_V1");
    if (!chosen || std::string(chosen) != "1") mode = "red";
  }
  return mode;
}

static COLORREF nativeUiLiveMarkBackgroundColor(
  const std::map<std::string, std::string>& values)
{
  const std::string mode = nativeUiLiveMarkColorMode(values);
  const COLORREF panel = nativeUiListPanelBackgroundColor(values);
  if (mode == "none") return panel;
  if (mode == "red") return RGB(153, 27, 27);
  return nativeUiBlendColor(
    panel, nativeUiNamedVisualColor(mode, "gray"), 0.82);
}

static void nativeUiWriteVisualPrefs(
  std::map<std::string, std::string> values)
{
  if (!SetExtState_ptr) return;
  const int active = nativeUiVisualPresetIndex(values);
  values["visual_preset_index"] =
    std::to_string(active);
  values["default_preset_initialized"] = "1";
  for (const auto& key :
       nativeUiVisualPreferenceKeys()) {
    if (values.find(key) == values.end()) {
      values[key] = nativeUiVisualRawValue(values, key);
    }
  }
  if (active > 0) {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      values["preset" + std::to_string(active) +
        "_" + key] = values[key];
    }
  }

  std::ostringstream encoded;
  encoded << "visual_preset_index=" << active
          << ";default_preset_initialized=1";
  for (const auto& key :
       nativeUiVisualPreferenceKeys()) {
    encoded << ';' << key << '=' << values[key];
  }
  for (int preset = 1; preset <= 3; ++preset) {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      const std::string presetKey =
        "preset" + std::to_string(preset) +
        "_" + key;
      const auto found = values.find(presetKey);
      encoded << ';' << presetKey << '='
              << (found == values.end()
                    ? nativeUiVisualRawValue(values, key)
                    : found->second);
    }
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    "VISUAL_PREFS_V2", encoded.str().c_str(), true);

  static const char* barKeys[] = {
    "status_current_top", "status_current_bottom",
    "status_queue_top", "status_queue_bottom",
    "list_current_top", "list_current_bottom",
    "list_queue_top", "list_queue_bottom"
  };
  std::ostringstream bars;
  for (size_t index = 0;
       index < std::size(barKeys); ++index) {
    if (index) bars << ';';
    bars << barKeys[index] << '='
         << values[barKeys[index]];
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    "BAR_VISIBILITY_V1", bars.str().c_str(), true);
  std::ostringstream statusLayout;
  statusLayout << "current\t"
    << values["status_current_position"]
    << "\nqueue\t"
    << values["status_queue_position"]
    << "\nmultiloop\t"
    << values["status_multiloop_position"];
  SetExtState_ptr(kLuaWindowExtStateSection,
    "STATUS_PANEL_LAYOUT_V1",
    statusLayout.str().c_str(), true);
  SetExtState_ptr(kLuaWindowExtStateSection,
    "RGB_MODE_V1", values["rgb_border_mode"].c_str(), true);
  nativeUiInvalidateVisualPrefsCache();
  // Preferências que também são desenhadas nos apps precisam chegar no
  // bridge no mesmo instante em que mudam na extensão.
  g_nativeForceStateBuild.store(true);

  std::ostringstream listBackgroundPresets;
  std::ostringstream barPresets;
  bool firstList = true;
  bool firstBar = true;
  for (int preset = 1; preset <= 3; ++preset) {
    for (const char* key : {
           "list_current_bg", "list_queue_bg"}) {
      if (!firstList) listBackgroundPresets << ';';
      firstList = false;
      const std::string presetKey =
        "preset" + std::to_string(preset) + "_" + key;
      listBackgroundPresets << presetKey << '='
        << (values.count(presetKey)
              ? values[presetKey]
              : nativeUiVisualRawValue(values, key));
    }
    for (const char* key : barKeys) {
      if (!firstBar) barPresets << ';';
      firstBar = false;
      const std::string presetKey =
        "preset" + std::to_string(preset) + "_" + key;
      barPresets << presetKey << '='
        << (values.count(presetKey)
              ? values[presetKey]
              : nativeUiVisualRawValue(values, key));
    }
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    "LIST_BG_PRESETS_V1",
    listBackgroundPresets.str().c_str(), true);
  SetExtState_ptr(kLuaWindowExtStateSection,
    "BAR_VISIBILITY_PRESETS_V1",
    barPresets.str().c_str(), true);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  if (g_nativeAppActivePanelHwnd) {
    InvalidateRect(g_nativeAppActivePanelHwnd,
      nullptr, FALSE);
  }
}

static bool nativeUiSetVisualPreset(int preset)
{
  auto values = nativeUiReadVisualPrefs();
  const int current = nativeUiVisualPresetIndex(values);
  if (current > 0) {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      values["preset" + std::to_string(current) +
        "_" + key] = nativeUiVisualRawValue(values, key);
    }
  }
  preset = std::max(0, std::min(3, preset));
  values["visual_preset_index"] =
    std::to_string(preset);
  if (preset == 0) {
    for (const auto& entry :
         nativeUiVisualFixedDefaultPreset()) {
      values[entry.first] = entry.second;
    }
  } else {
    for (const auto& key :
         nativeUiVisualPreferenceKeys()) {
      const std::string presetKey =
        "preset" + std::to_string(preset) +
        "_" + key;
      const auto saved = values.find(presetKey);
      values[key] = saved == values.end()
        ? nativeUiVisualDefaults().at(key)
        : saved->second;
    }
  }
  nativeUiWriteVisualPrefs(std::move(values));
  return true;
}

static bool nativeUiSetVisualValue(
  const std::string& key,
  const std::string& value)
{
  auto values = nativeUiReadVisualPrefs();
  const int active = nativeUiVisualPresetIndex(values);
  // O preset Padrão permanece protegido, exceto pela opção explícita de
  // remover o fundo da marcação Live pedida em Personalizar.
  if (active == 0 && key != "live_mark_color_mode") return false;
  if (active == 0 && key == "live_mark_color_mode" && SetExtState_ptr) {
    SetExtState_ptr(kLuaWindowExtStateSection,
      "LIVE_MARK_DEFAULT_COLOR_CHOSEN_V1", "1", true);
  }
  values[key] = value;
  if (active > 0) {
    values["preset" + std::to_string(active) +
      "_" + key] = value;
  }
  nativeUiWriteVisualPrefs(std::move(values));
  return true;
}

static bool nativeUiToggleVisualValue(
  const std::string& key)
{
  const auto values = nativeUiReadVisualPrefs();
  const std::string current = nativeLower(
    nativeUiVisualRawValue(values, key));
  const bool enabled = current == "1" ||
    current == "true" || current == "on" ||
    current == "yes" || current == "sim";
  return nativeUiSetVisualValue(
    key, enabled ? "0" : "1");
}

static std::set<std::string> nativeUiHiddenButtonSet(
  const std::map<std::string, std::string>& values,
  const std::string& rawPage)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const std::string encoded = nativeUiVisualRawValue(
    values, page + "_hidden_buttons");
  std::set<std::string> result;
  for (const auto& rawId : nativeSplit(encoded, ',')) {
    const std::string id = nativeLower(nativeTrim(rawId));
    if (!id.empty()) result.insert(id);
  }
  return result;
}

static bool nativeUiPageButtonVisible(
  const std::map<std::string, std::string>& values,
  const std::string& page,
  const std::string& rawId)
{
  if (rawId.empty()) return true;
  const std::string id = nativeLower(nativeTrim(rawId));
  if (id == "info_timer") {
    return nativeUiVisualPrefBool(values,
      "info_timer_visible", true);
  }
  if (id == "info_local_time") {
    return nativeUiVisualPrefBool(values,
      "info_local_time_visible", true);
  }
  if (id == "info_battery") {
    return nativeUiVisualPrefBool(values,
      "info_battery_visible", true);
  }
  if (id == "nav_playlist" ||
      id == "nav_regions" ||
      id == "nav_config" ||
      id == "header_update" ||
      (page == "regions" &&
       (id == "action_create" || id == "action_add"))) {
    return true;
  }
  return nativeUiHiddenButtonSet(values, page).count(id) == 0;
}

static bool nativeUiTogglePageButtonVisibility(
  const std::string& rawPage,
  const std::string& rawId)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const std::string id = nativeLower(nativeTrim(rawId));
  if (id.empty()) return false;
  if (id == "info_timer") {
    return nativeUiToggleVisualValue(
      "info_timer_visible");
  }
  if (id == "info_local_time") {
    return nativeUiToggleVisualValue(
      "info_local_time_visible");
  }
  if (id == "info_battery") {
    return nativeUiToggleVisualValue(
      "info_battery_visible");
  }
  if (id == "nav_playlist" ||
      id == "nav_regions" ||
      id == "nav_config" ||
      id == "header_update" ||
      (page == "regions" &&
       (id == "action_create" || id == "action_add"))) {
    return false;
  }
  auto values = nativeUiReadVisualPrefs();
  if (nativeUiVisualPresetIndex(values) == 0) return false;
  std::set<std::string> hidden =
    nativeUiHiddenButtonSet(values, page);
  if (hidden.count(id)) hidden.erase(id);
  else hidden.insert(id);
  std::ostringstream encoded;
  bool first = true;
  for (const auto& item : hidden) {
    if (!first) encoded << ',';
    first = false;
    encoded << item;
  }
  return nativeUiSetVisualValue(
    page + "_hidden_buttons", encoded.str());
}

static const std::array<std::string, 5>&
nativeUiButtonLayoutZones()
{
  static const std::array<std::string, 5> zones = {
    "top1", "top2", "top3", "header", "footer"
  };
  return zones;
}

static bool nativeUiButtonLayoutZoneValid(
  const std::string& zone)
{
  const auto& zones = nativeUiButtonLayoutZones();
  return std::find(zones.begin(), zones.end(), zone) !=
    zones.end();
}

static int nativeUiButtonLayoutActivePreset()
{
  return nativeUiVisualPresetIndex(
    nativeUiReadVisualPrefs());
}

static std::string nativeUiButtonLayoutStorageKey(
  const std::string& rawPage,
  int preset)
{
  return std::string(rawPage == "regions"
      ? "BUTTON_LAYOUT_REGIONS_PRESET"
      : "BUTTON_LAYOUT_PLAYLIST_PRESET") +
    std::to_string(std::max(1, std::min(3, preset))) +
    "_V1";
}

static std::map<std::string, std::vector<std::string>>
nativeUiDefaultButtonLayout(const std::string& rawPage)
{
  const bool regions = rawPage == "regions";
  std::map<std::string, std::vector<std::string>> layout;
  if (regions) {
    layout["top1"] = {
      "nav_playlist", "nav_regions", "nav_mixer",
      "nav_midi", "nav_help", "nav_config"
    };
    layout["top2"] = {
      "action_play", "action_all", "action_create",
      "action_add", "nav_tuner", "nav_bpm", "action_parts2",
      "action_parts1", "action_timer"
    };
    layout["top3"] = {};
  } else {
    layout["top1"] = {
      "nav_playlist", "nav_regions", "nav_mixer",
      "nav_midi", "nav_config"
    };
    layout["top2"] = {
      "action_loop", "action_atbl", "nav_tuner", "nav_bpm",
      "action_bypass", "nav_help"
    };
    layout["top3"] = {
      "action_play", "action_auto", "action_auto2",
      "action_blocks", "action_parts2", "action_parts1",
      "action_timer"
    };
  }
  layout["header"] = {
    "header_live", "header_retry", "header_number",
    "header_sort09", "header_update", "header_view"
  };
  if (regions) {
    layout["header"].push_back("header_alpha");
    layout["header"].push_back("header_reset");
  }
  layout["footer"] = {
    "footer_preview_page",
    "footer_preview1", "footer_preview2", "footer_preview3",
    "footer_preview4", "footer_preview5", "footer_preview6",
    "footer_export", "footer_tp1", "footer_tp2", "footer_stop"
  };
  return layout;
}

static std::set<std::string> nativeUiKnownButtonLayoutIds(
  const std::string& rawPage)
{
  std::set<std::string> result;
  const auto defaults = nativeUiDefaultButtonLayout(rawPage);
  for (const auto& zone : defaults) {
    result.insert(zone.second.begin(), zone.second.end());
  }
  return result;
}

static std::map<std::string, std::vector<std::string>>
nativeUiReadButtonLayout(const std::string& rawPage)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  auto result = nativeUiDefaultButtonLayout(page);
  const int preset = nativeUiButtonLayoutActivePreset();
  // O preset Padrao reproduz sempre a composicao oficial e nao aceita
  // sobrescrita de posicao.
  if (preset == 0 || !GetExtState_ptr) return result;
  const std::string storageKey =
    nativeUiButtonLayoutStorageKey(page, preset);
  const char* rawPtr = GetExtState_ptr(
    kLuaWindowExtStateSection,
    storageKey.c_str());
  const std::string raw = rawPtr ? rawPtr : "";
  if (raw.empty()) return result;

  std::map<std::string, std::vector<std::string>> parsed;
  std::set<std::string> seen;
  const std::set<std::string> known =
    nativeUiKnownButtonLayoutIds(page);
  for (const auto& rawZone : nativeSplit(raw, ';')) {
    const size_t separator = rawZone.find('=');
    if (separator == std::string::npos) continue;
    const std::string zone = nativeLower(
      nativeTrim(rawZone.substr(0, separator)));
    if (!nativeUiButtonLayoutZoneValid(zone)) continue;
    for (const auto& rawId :
         nativeSplit(rawZone.substr(separator + 1), ',')) {
      const std::string id = nativeLower(nativeTrim(rawId));
      if (id.empty() || !known.count(id) || seen.count(id)) continue;
      parsed[zone].push_back(id);
      seen.insert(id);
    }
  }
  for (const auto& zone : nativeUiButtonLayoutZones()) {
    if (!parsed.count(zone)) parsed[zone] = {};
  }
  const auto defaults = nativeUiDefaultButtonLayout(page);
  for (const auto& zone : nativeUiButtonLayoutZones()) {
    const auto found = defaults.find(zone);
    if (found == defaults.end()) continue;
    for (const auto& id : found->second) {
      if (seen.insert(id).second) parsed[zone].push_back(id);
    }
  }
  return parsed;
}

static bool nativeUiWriteButtonLayout(
  const std::string& rawPage,
  const std::map<std::string, std::vector<std::string>>& layout)
{
  if (!SetExtState_ptr) return false;
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const int preset = nativeUiButtonLayoutActivePreset();
  if (preset == 0) return false;
  const std::set<std::string> known =
    nativeUiKnownButtonLayoutIds(page);
  std::set<std::string> seen;
  std::ostringstream encoded;
  bool firstZone = true;
  for (const auto& zone : nativeUiButtonLayoutZones()) {
    if (!firstZone) encoded << ';';
    firstZone = false;
    encoded << zone << '=';
    bool firstId = true;
    const auto found = layout.find(zone);
    if (found == layout.end()) continue;
    for (const auto& rawId : found->second) {
      const std::string id = nativeLower(nativeTrim(rawId));
      if (!known.count(id) || !seen.insert(id).second) continue;
      if (!firstId) encoded << ',';
      firstId = false;
      encoded << id;
    }
  }
  const std::string storageKey =
    nativeUiButtonLayoutStorageKey(page, preset);
  SetExtState_ptr(kLuaWindowExtStateSection,
    storageKey.c_str(),
    encoded.str().c_str(), true);
  return true;
}

static std::vector<std::string> nativeUiButtonIdsForZone(
  const std::string& page,
  const std::string& zone)
{
  const auto layout = nativeUiReadButtonLayout(page);
  const auto found = layout.find(zone);
  return found == layout.end()
    ? std::vector<std::string>{} : found->second;
}

static bool nativeUiMoveButtonLayoutItem(
  const std::string& rawPage,
  const std::string& rawId,
  const std::string& rawZone,
  int rawIndex)
{
  const std::string page = rawPage == "regions"
    ? "regions" : "playlist";
  const std::string id = nativeLower(nativeTrim(rawId));
  const std::string zone = nativeLower(nativeTrim(rawZone));
  if (!nativeUiButtonLayoutZoneValid(zone) ||
      !nativeUiKnownButtonLayoutIds(page).count(id)) {
    return false;
  }
  auto layout = nativeUiReadButtonLayout(page);
  for (auto& item : layout) {
    item.second.erase(std::remove(
      item.second.begin(), item.second.end(), id),
      item.second.end());
  }
  auto& destination = layout[zone];
  const int index = std::max(0, std::min(
    rawIndex, static_cast<int>(destination.size())));
  destination.insert(destination.begin() + index, id);
  return nativeUiWriteButtonLayout(page, layout);
}

static void nativeUiResetButtonLayoutDrag()
{
  g_nativeUiButtonLayoutDrag = NativeUiButtonLayoutDrag{};
}

static bool nativeUiBeginButtonLayoutDrag(const POINT& point)
{
  if (g_nativeMainModalKind !=
      NativeMainModalKind::CustomizeButtonVisibility) {
    return false;
  }
  for (const auto& hit : g_nativeUiButtonLayoutHits) {
    if (!PtInRect(&hit.rect, point)) continue;
    g_nativeUiButtonLayoutDrag.pressed = true;
    g_nativeUiButtonLayoutDrag.pressPoint = point;
    g_nativeUiButtonLayoutDrag.page = hit.page;
    g_nativeUiButtonLayoutDrag.buttonId = hit.buttonId;
    g_nativeUiButtonLayoutDrag.sourceZone = hit.zone;
    g_nativeUiButtonLayoutDrag.sourceIndex = hit.index;
    g_nativeUiButtonLayoutDrag.targetZone = hit.zone;
    g_nativeUiButtonLayoutDrag.targetIndex = hit.index;
    return true;
  }
  return false;
}

static void nativeUiUpdateButtonLayoutDrag(const POINT& point)
{
  if (!g_nativeUiButtonLayoutDrag.pressed) return;
  const int dx = std::abs(
    point.x - g_nativeUiButtonLayoutDrag.pressPoint.x);
  const int dy = std::abs(
    point.y - g_nativeUiButtonLayoutDrag.pressPoint.y);
  if (!g_nativeUiButtonLayoutDrag.active &&
      (dx > 4 || dy > 4)) {
    g_nativeUiButtonLayoutDrag.active = true;
  }
  if (!g_nativeUiButtonLayoutDrag.active) return;

  std::string targetZone;
  for (const auto& zone : g_nativeUiButtonLayoutZoneHits) {
    RECT expanded = zone.rect;
    expanded.top -= 5;
    expanded.bottom += 5;
    if (PtInRect(&expanded, point)) {
      targetZone = zone.zone;
      break;
    }
  }
  if (targetZone.empty()) return;

  std::vector<const NativeUiButtonLayoutHit*> row;
  for (const auto& hit : g_nativeUiButtonLayoutHits) {
    if (hit.zone == targetZone &&
        hit.buttonId != g_nativeUiButtonLayoutDrag.buttonId) {
      row.push_back(&hit);
    }
  }
  std::sort(row.begin(), row.end(),
    [](const NativeUiButtonLayoutHit* left,
       const NativeUiButtonLayoutHit* right) {
      return left->rect.left < right->rect.left;
    });
  int targetIndex = static_cast<int>(row.size());
  for (size_t index = 0; index < row.size(); ++index) {
    const int center = (row[index]->rect.left +
      row[index]->rect.right) / 2;
    if (point.x < center) {
      targetIndex = static_cast<int>(index);
      break;
    }
  }
  g_nativeUiButtonLayoutDrag.targetZone = targetZone;
  g_nativeUiButtonLayoutDrag.targetIndex = targetIndex;
}

static bool nativeUiFinishButtonLayoutDrag()
{
  if (!g_nativeUiButtonLayoutDrag.pressed) return false;
  const NativeUiButtonLayoutDrag drag =
    g_nativeUiButtonLayoutDrag;
  nativeUiResetButtonLayoutDrag();
  if (!drag.active || drag.targetZone.empty() ||
      drag.targetIndex < 0) {
    return false;
  }
  const bool moved = nativeUiMoveButtonLayoutItem(
    drag.page, drag.buttonId,
    drag.targetZone, drag.targetIndex);
  if (!moved && nativeUiButtonLayoutActivePreset() == 0) {
    nativeUiShowTemporaryPopup(
      "O Preset Padrão tem posição fixa. Escolha o Preset 1, 2 ou 3.",
      2.0);
  }
  return moved;
}

