static std::string nativeUiVisualPref(
  const std::map<std::string, std::string>& values,
  const std::string& key,
  const std::string& fallback)
{
  const auto direct = values.find(key);
  if (direct != values.end() && !direct->second.empty()) {
    return direct->second;
  }
  int preset = 0;
  const auto active = values.find("visual_preset_index");
  if (active != values.end()) {
    preset = std::max(0, std::min(3,
      std::atoi(active->second.c_str())));
  }
  if (preset > 0) {
    const auto stored = values.find(
      "preset" + std::to_string(preset) + "_" + key);
    if (stored != values.end() && !stored->second.empty()) {
      return stored->second;
    }
  }
  return fallback;
}

static bool nativeUiVisualPrefBool(
  const std::map<std::string, std::string>& values,
  const std::string& key,
  bool fallback)
{
  const std::string raw = nativeLower(
    nativeUiVisualPref(values, key, fallback ? "1" : "0"));
  if (raw == "1" || raw == "true" || raw == "on" ||
      raw == "yes" || raw == "sim") {
    return true;
  }
  if (raw == "0" || raw == "false" || raw == "off" ||
      raw == "no" || raw == "nao" || raw == "não") {
    return false;
  }
  return fallback;
}

static COLORREF nativeUiNamedVisualColor(
  std::string mode,
  const std::string& fallback = "yellow")
{
  mode = nativeLower(nativeTrim(mode));
  if (mode.empty()) mode = fallback;
  if (mode == "green") return RGB(26, 255, 87);
  if (mode == "blue") return RGB(51, 148, 255);
  if (mode == "purple") return RGB(184, 82, 255);
  if (mode == "red") return RGB(255, 56, 46);
  if (mode == "orange") return RGB(255, 133, 20);
  if (mode == "cyan") return RGB(31, 235, 255);
  if (mode == "white") return RGB(235, 242, 255);
  if (mode == "gray" || mode == "grey") {
    return kNativeUiUnifiedDarkGray;
  }
  return RGB(255, 240, 46);
}

static bool nativeUiBorderColor(
  const std::map<std::string, std::string>& values,
  COLORREF& colorOut)
{
  const int mode = std::atoi(nativeUiVisualPref(
    values, "rgb_border_mode", "0").c_str());
  if (mode == 0) return false;

  if (mode == 1 || mode == 12 || mode == 13 || mode == 14) {
    double secondsPerCycle = 5.5;
    if (mode == 12) secondsPerCycle = 9.0;
    else if (mode == 13) secondsPerCycle = 2.2;
    else if (mode == 14) secondsPerCycle = 0.75;
    const double now =
      std::chrono::duration<double>(
        std::chrono::steady_clock::now().time_since_epoch()).count();
    const double hue = std::fmod(
      now / std::max(0.1, secondsPerCycle), 1.0);
    const double saturation = 0.92;
    const double value = 1.0;
    const double scaled = hue * 6.0;
    const int sector = static_cast<int>(std::floor(scaled)) % 6;
    const double fraction = scaled - std::floor(scaled);
    const double p = value * (1.0 - saturation);
    const double q = value * (1.0 - fraction * saturation);
    const double t = value * (1.0 - (1.0 - fraction) * saturation);
    double red = value;
    double green = t;
    double blue = p;
    if (sector == 1) { red = q; green = value; blue = p; }
    else if (sector == 2) { red = p; green = value; blue = t; }
    else if (sector == 3) { red = p; green = q; blue = value; }
    else if (sector == 4) { red = t; green = p; blue = value; }
    else if (sector == 5) { red = value; green = p; blue = q; }
    colorOut = RGB(
      static_cast<int>(std::floor(red * 255.0 + 0.5)),
      static_cast<int>(std::floor(green * 255.0 + 0.5)),
      static_cast<int>(std::floor(blue * 255.0 + 0.5)));
    return true;
  }

  if (mode == 3) colorOut = RGB(242, 56, 56);
  else if (mode == 4) colorOut = RGB(46, 209, 87);
  else if (mode == 5) colorOut = RGB(61, 133, 235);
  else if (mode == 6) colorOut = RGB(158, 82, 214);
  else if (mode == 7) colorOut = RGB(245, 209, 61);
  else if (mode == 8) colorOut = RGB(245, 51, 148);
  else if (mode == 9) colorOut = RGB(31, 204, 235);
  else if (mode == 10) colorOut = RGB(255, 122, 31);
  else if (mode == 11) colorOut = RGB(235, 242, 255);
  else return false;
  return true;
}

