static size_t nativeUiNextUtf8Byte(
  const std::string& value,
  size_t index)
{
  if (index >= value.size()) return value.size();
  const unsigned char first =
    static_cast<unsigned char>(value[index]);
  size_t width = 1;
  if ((first & 0xf8) == 0xf0) width = 4;
  else if ((first & 0xf0) == 0xe0) width = 3;
  else if ((first & 0xe0) == 0xc0) width = 2;
  return std::min(value.size(), index + width);
}

static std::vector<std::string> nativeUiWrapText(
  HDC dc,
  const std::string& text,
  int maxWidth,
  HFONT font)
{
  if (text.empty()) return {std::string()};
  if (maxWidth <= 8) return {text};

  std::string normalized;
  normalized.reserve(text.size());
  for (size_t i = 0; i < text.size(); ++i) {
    if (text[i] == '\r') {
      if (i + 1 < text.size() && text[i + 1] == '\n') continue;
      normalized.push_back('\n');
    } else {
      normalized.push_back(text[i]);
    }
  }

  std::vector<std::string> lines;
  size_t paragraphStart = 0;
  while (paragraphStart <= normalized.size()) {
    size_t paragraphEnd =
      normalized.find('\n', paragraphStart);
    if (paragraphEnd == std::string::npos) {
      paragraphEnd = normalized.size();
    }
    const std::string paragraph =
      normalized.substr(paragraphStart,
        paragraphEnd - paragraphStart);
    std::istringstream words(paragraph);
    std::string current;
    std::string word;
    bool hadWord = false;
    while (words >> word) {
      hadWord = true;
      const std::string candidate =
        current.empty() ? word : current + " " + word;
      if (nativeUiTextWidth(dc, candidate, font) <= maxWidth) {
        current = candidate;
        continue;
      }
      if (!current.empty()) {
        lines.push_back(current);
        current.clear();
      }
      if (nativeUiTextWidth(dc, word, font) <= maxWidth) {
        current = word;
        continue;
      }
      std::string piece;
      size_t byte = 0;
      while (byte < word.size()) {
        const size_t next = nativeUiNextUtf8Byte(word, byte);
        const std::string glyph = word.substr(byte, next - byte);
        const std::string test = piece + glyph;
        if (!piece.empty() &&
            nativeUiTextWidth(dc, test, font) > maxWidth) {
          lines.push_back(piece);
          piece = glyph;
        } else {
          piece = test;
        }
        byte = next;
      }
      current = piece;
    }
    if (!current.empty()) {
      lines.push_back(current);
    } else if (!hadWord) {
      lines.push_back(std::string());
    }
    if (paragraphEnd >= normalized.size()) break;
    paragraphStart = paragraphEnd + 1;
  }
  if (lines.empty()) lines.push_back(text);
  return lines;
}

static std::string nativeUiFitBlockLabelBeforeWrap(
  HDC dc,
  const std::string& value,
  int maxWidth,
  HFONT font)
{
  if (value.empty() || maxWidth <= 8 ||
      value.find("BLOCO") == std::string::npos ||
      nativeUiTextWidth(dc, value, font) <= maxWidth) {
    return value;
  }

  size_t firstName = value.find("BLOCO");
  if (firstName == std::string::npos) return value;
  size_t leftEnd = firstName;
  while (leftEnd > 0 &&
         std::isspace(static_cast<unsigned char>(
           value[leftEnd - 1]))) {
    --leftEnd;
  }
  std::string leftMarks = value.substr(0, leftEnd);
  if (leftMarks.empty() ||
      leftMarks.find_first_not_of(":=>") != std::string::npos) {
    return value;
  }

  size_t rightStart = value.size();
  while (rightStart > firstName &&
         std::isspace(static_cast<unsigned char>(
           value[rightStart - 1]))) {
    --rightStart;
  }
  size_t marksStart = rightStart;
  while (marksStart > firstName) {
    const char c = value[marksStart - 1];
    if (c != ':' && c != '=' && c != '<') break;
    --marksStart;
  }
  if (marksStart == rightStart) return value;
  const std::string fixedName =
    nativeTrim(value.substr(firstName,
      marksStart - firstName));
  const std::string rightMarks =
    value.substr(marksStart, rightStart - marksStart);
  const char leftChar = leftMarks.empty() ? ':' : leftMarks.front();
  const char rightChar =
    rightMarks.empty() ? ':' : rightMarks.front();

  for (int rightCount =
         static_cast<int>(rightMarks.size());
       rightCount >= 0; --rightCount) {
    std::string candidate(
      leftMarks.size(), leftChar);
    candidate += " " + fixedName;
    if (rightCount > 0) {
      candidate += " " +
        std::string(static_cast<size_t>(rightCount),
          rightChar);
    }
    if (nativeUiTextWidth(dc, candidate, font) <=
        maxWidth) {
      return candidate;
    }
  }
  for (int leftCount =
         static_cast<int>(leftMarks.size()) - 1;
       leftCount >= 0; --leftCount) {
    std::string candidate;
    if (leftCount > 0) {
      candidate =
        std::string(static_cast<size_t>(leftCount),
          leftChar) + " ";
    }
    candidate += fixedName;
    if (nativeUiTextWidth(dc, candidate, font) <=
        maxWidth) {
      return candidate;
    }
  }
  return fixedName;
}

