static MediaTrack* nativeUiFindTrackByExactName(
  ReaProject* project,
  const std::string& name,
  int* indexOut = nullptr)
{
  if (indexOut) *indexOut = -1;
  if (!project || !CountTracks_ptr || !GetTrack_ptr ||
      !GetTrackName_ptr) {
    return nullptr;
  }
  const std::string target =
    nativeUiNormalizedTrackName(name);
  const int count = CountTracks_ptr(project);
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (!track) continue;
    char nameBuf[2048] = "";
    if (GetTrackName_ptr(track, nameBuf,
          static_cast<int>(sizeof(nameBuf))) &&
        nativeUiNormalizedTrackName(nameBuf) ==
          target) {
      if (indexOut) *indexOut = index;
      return track;
    }
  }
  return nullptr;
}

static MediaTrack* nativeUiPrepareTelepromptTrack(
  const std::string& trackName,
  int targetIndex,
  int red,
  int green,
  int blue)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return nullptr;

  targetIndex = std::max(0, targetIndex);
  int index = -1;
  bool createdNow = false;
  MediaTrack* track = nativeUiFindTrackByExactName(
    project, trackName, &index);
  if (!track && InsertTrackAtIndex_ptr &&
      GetTrack_ptr) {
    InsertTrackAtIndex_ptr(targetIndex, true);
    track = GetTrack_ptr(project, targetIndex);
    index = targetIndex;
    createdNow = track != nullptr;
  }
  if (!track) return nullptr;

  if (index != targetIndex &&
      SetOnlyTrackSelected_ptr &&
      ReorderSelectedTracks_ptr) {
    SetOnlyTrackSelected_ptr(track);
    ReorderSelectedTracks_ptr(targetIndex, 0);
    track = GetTrack_ptr
      ? GetTrack_ptr(project, targetIndex)
      : track;
  }

  if (GetSetMediaTrackInfo_String_ptr) {
    std::vector<char> writable(
      trackName.begin(), trackName.end());
    writable.push_back('\0');
    GetSetMediaTrackInfo_String_ptr(
      track, "P_NAME", writable.data(), true);
  }
  if (SetMediaTrackInfo_Value_ptr) {
    const int nativeColor = ColorToNative_ptr
      ? ColorToNative_ptr(red, green, blue)
      : RGB(red, green, blue);
    SetMediaTrackInfo_Value_ptr(
      track, "I_CUSTOMCOLOR",
      static_cast<double>(
        nativeColor | 0x01000000));
  }
  if (SetOnlyTrackSelected_ptr) {
    SetOnlyTrackSelected_ptr(track);
  }
  if (TrackList_AdjustWindows_ptr) {
    TrackList_AdjustWindows_ptr(false);
  }
  (void)createdNow;
  return track;
}

