static std::string nativeUiBackupEscape(
  const std::string& value)
{
  std::string result;
  result.reserve(value.size());
  for (const char ch : value) {
    if (ch == '\\') result += "\\\\";
    else if (ch == '\r') result += "\\r";
    else if (ch == '\n') result += "\\n";
    else if (ch == '\t') result += "\\t";
    else result.push_back(ch);
  }
  return result;
}

static std::string nativeUiBackupUnescape(
  const std::string& value)
{
  std::string result;
  result.reserve(value.size());
  for (size_t index = 0;
       index < value.size(); ++index) {
    const char ch = value[index];
    if (ch != '\\' || index + 1 >= value.size()) {
      result.push_back(ch);
      continue;
    }
    const char next = value[++index];
    if (next == 'n') result.push_back('\n');
    else if (next == 'r') result.push_back('\r');
    else if (next == 't') result.push_back('\t');
    else result.push_back(next);
  }
  return result;
}

static void nativeUiBackupAddRecord(
  std::vector<std::string>& records,
  const std::string& section,
  const std::string& key,
  const std::string& value)
{
  records.push_back(
    "DATA\tGLOBAL\t" +
    nativeUiBackupEscape(section) + "\t" +
    nativeUiBackupEscape(key) + "\t" +
    nativeUiBackupEscape(value));
}

