static bool nativeUiBackupContainsKey(
  const std::vector<std::string>& keys,
  const std::string& key)
{
  return std::find(keys.begin(), keys.end(), key) != keys.end();
}

static bool nativeUiBackupKeyAllowed(
  const std::string& section,
  const std::string& key)
{
  if (section == kMidiBindingExtSection) {
    return !key.empty();
  }
  if (section == kMixerBindingExtSection) {
    return key.find("_MIDI_") !=
      std::string::npos;
  }
  if (section == kLuaWindowExtStateSection) {
    return nativeUiBackupContainsKey(
      nativeUiBackupWindowGlobalKeys(), key);
  }
  if (section == kNativeExtStateSection) {
    return nativeUiBackupContainsKey(
      nativeUiBackupNativeGlobalKeys(), key);
  }
  if (section == kExtStateSection) {
    return nativeUiBackupContainsKey(
      nativeUiBackupLoaderGlobalKeys(), key);
  }
  if (section == kNativeTelepromptSettingsSection) {
    return key == "TP1_SETTINGS_V1" ||
      key == "TP2_SETTINGS_V1";
  }
  if (section == "JBKEYS_VSLIVE_WINDOW") {
    return key == "PREMIX_V1" ||
      key == "PREMIX_ENABLED_V1" ||
      key == "PREMIX_GLOBAL_ENABLED_V1";
  }
  return section == kAccessExtSection &&
    (key == kAccessDirectorPassKey ||
     key == kAccessRecadosPassKey ||
     key == kAccessBlockInterfaceWhenDirectorConnectedKey);
}

static void nativeUiBackupEnumerateSection(
  std::vector<std::string>& records,
  const std::string& section)
{
  if (!EnumExtState_ptr) return;
  // O export e acionado por clique. Estes buffers eram locais (cerca de
  // 72 KiB por chamada) e consumiam pilha sem necessidade.
  std::vector<char> key(8192, '\0');
  std::vector<char> value(65536, '\0');
  for (int index = 0;; ++index) {
    std::fill(key.begin(), key.end(), '\0');
    std::fill(value.begin(), value.end(), '\0');
    if (!EnumExtState_ptr(section.c_str(),
          index, key.data(),
          static_cast<int>(key.size()), value.data(),
          static_cast<int>(value.size()))) {
      break;
    }
    if (nativeUiBackupKeyAllowed(
          section, key.data())) {
      nativeUiBackupAddRecord(
        records, section, key.data(), value.data());
    }
  }
}

static std::string nativeUiBuildBackupText()
{
  // Consolida o preset ativo nos tres presets antes de serializar. Assim o
  // backup representa exatamente o que o usuario esta vendo neste momento.
  nativeUiWriteVisualPrefs(nativeUiReadVisualPrefs());
  std::vector<std::string> records;
  records.push_back("VSHOOKBACKUP\t3");
  records.push_back("META\tscope\tGLOBAL");
  char created[64] = "";
  const std::time_t now = std::time(nullptr);
  std::tm local{};
#ifdef _WIN32
  localtime_s(&local, &now);
#else
  localtime_r(&now, &local);
#endif
  std::strftime(created, sizeof(created),
    "%Y-%m-%d %H:%M:%S", &local);
  records.push_back(std::string(
    "META\tcreatedAt\t") + created);

  const auto addKnown = [&](const char* section,
                            const char* key,
                            const std::string& overrideValue =
                              std::string()) {
    std::string value = overrideValue;
    if (value.empty() && GetExtState_ptr) {
      const char* raw = GetExtState_ptr(section, key);
      value = raw ? raw : "";
    }
    nativeUiBackupAddRecord(
      records, section, key, value);
  };
  for (const auto& key : nativeUiBackupWindowGlobalKeys()) {
    addKnown(kLuaWindowExtStateSection, key.c_str());
  }
  for (const auto& key : nativeUiBackupNativeGlobalKeys()) {
    addKnown(kNativeExtStateSection, key.c_str());
  }
  for (const auto& key : nativeUiBackupLoaderGlobalKeys()) {
    addKnown(kExtStateSection, key.c_str());
  }
  addKnown(kAccessExtSection,
    kAccessDirectorPassKey,
    nativeUiReadDirectorPassword());
  addKnown(kAccessExtSection,
    kAccessRecadosPassKey);
  addKnown(kAccessExtSection,
    kAccessBlockInterfaceWhenDirectorConnectedKey,
    nativeUiBlockInterfaceWhenDirectorConnectedEnabled()
      ? "1" : "0");
  nativeUiBackupEnumerateSection(
    records, kMidiBindingExtSection);
  nativeUiBackupEnumerateSection(
    records, kMixerBindingExtSection);
  nativeUiBackupEnumerateSection(
    records, kNativeTelepromptSettingsSection);

  std::ostringstream output;
  for (size_t index = 0;
       index < records.size(); ++index) {
    if (index) output << '\n';
    output << records[index];
  }
  return output.str();
}

static std::string nativeUiBackupDefaultDirectory()
{
  char projectPath[4096] = "";
  getCurrentProject(projectPath,
    static_cast<int>(sizeof(projectPath)));
  std::string normalized =
    normalizeSlashes(projectPath);
  const size_t separator =
    normalized.find_last_of('/');
  if (separator != std::string::npos) {
    return normalized.substr(0, separator);
  }
  return normalizeSlashes(
    GetResourcePath_ptr
      ? GetResourcePath_ptr() : "");
}

static bool nativeUiExportBackup()
{
  const std::string directory =
    nativeUiBackupDefaultDirectory();
  char selected[8192] = "";
  static const char filters[] =
    "Backup VS Hook (*.vshookbackup)\0"
    "*.vshookbackup\0"
    "Todos os arquivos (*.*)\0*.*\0\0";
  if (!vshook_jsapi::browseForSaveFile(
        "Exportar Backup VS Hook",
        directory.c_str(),
        "VS Hook Configuracoes Globais.vshookbackup",
        filters, selected,
        static_cast<int>(sizeof(selected)))) {
    return false;
  }
  std::string path = normalizeSlashes(selected);
  if (nativeLower(path).rfind(
        ".vshookbackup") !=
      path.size() - std::string(
        ".vshookbackup").size()) {
    path += ".vshookbackup";
  }
  std::ofstream file(path,
    std::ios::binary | std::ios::trunc);
  if (!file) {
    nativeUiOpenMessage(
      "Nao foi possivel salvar o backup.");
    return false;
  }
  file << nativeUiBuildBackupText();
  file.close();
  nativeUiOpenMessage("Backup exportado");
  return true;
}

static std::vector<std::string>
nativeUiBackupEnumeratedKeys(
  const std::string& section)
{
  std::vector<std::string> result;
  if (!EnumExtState_ptr) return result;
  for (int index = 0;; ++index) {
    char key[8192] = "";
    char value[2] = "";
    if (!EnumExtState_ptr(section.c_str(),
          index, key,
          static_cast<int>(sizeof(key)), value,
          static_cast<int>(sizeof(value)))) {
      break;
    }
    if (nativeUiBackupKeyAllowed(
          section, key)) {
      result.emplace_back(key);
    }
  }
  return result;
}

static void nativeUiClearBackupTargets()
{
  if (!SetExtState_ptr) return;
  for (const std::string& section : {
         std::string(kMidiBindingExtSection),
         std::string(kMixerBindingExtSection)}) {
    for (const auto& key :
         nativeUiBackupEnumeratedKeys(section)) {
      SetExtState_ptr(section.c_str(),
        key.c_str(), "", true);
    }
  }
  // Chaves fixas sao sobrescritas pelos registros presentes. Isso permite
  // importar um backup v2 sem apagar preferencias que ele ainda nao possuia.
}

static bool nativeUiApplyBackupText(
  const std::string& data,
  std::string& errorOut)
{
  if (data.rfind("VSHOOKBACKUP\t", 0) != 0) {
    errorOut = "Arquivo de backup invalido.";
    return false;
  }
  struct Record {
    std::string section;
    std::string key;
    std::string value;
  };
  std::vector<Record> pending;
  std::istringstream stream(data);
  std::string line;
  while (std::getline(stream, line)) {
    if (!line.empty() && line.back() == '\r') {
      line.pop_back();
    }
    if (line.rfind("DATA\t", 0) != 0) continue;
    std::vector<std::string> fields;
    size_t start = 0;
    for (int split = 0; split < 4; ++split) {
      const size_t tab = line.find('\t', start);
      if (tab == std::string::npos) break;
      fields.push_back(line.substr(
        start, tab - start));
      start = tab + 1;
    }
    fields.push_back(line.substr(start));
    if (fields.size() != 5 ||
        nativeUiBackupUnescape(fields[1]) !=
          "GLOBAL") {
      continue;
    }
    Record record{
      nativeUiBackupUnescape(fields[2]),
      nativeUiBackupUnescape(fields[3]),
      nativeUiBackupUnescape(fields[4])};
    if (nativeUiBackupKeyAllowed(
          record.section, record.key)) {
      pending.push_back(std::move(record));
    }
  }
  if (pending.empty()) {
    errorOut = "Backup sem dados para importar.";
    return false;
  }
  nativeUiClearBackupTargets();
  std::string restoredPassword;
  bool restoredPasswordFound = false;
  for (const auto& record : pending) {
    SetExtState_ptr(record.section.c_str(),
      record.key.c_str(), record.value.c_str(), true);
    if (record.section == kAccessExtSection &&
        record.key == kAccessDirectorPassKey) {
      restoredPassword = record.value;
      restoredPasswordFound = true;
    }
  }
  if (restoredPasswordFound) {
    SetExtState_ptr(kAccessExtSection,
      kAccessLegacyPassKey,
      restoredPassword.c_str(), true);
    nativeUiInvalidateDirectorSessions(
      "password_restore");
  }
  nativeUiInvalidateVisualPrefsCache();
  nativeTelepromptReloadSettingsAfterBackup();
  nativeRefreshStopPauseModeFromExtState();
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeAutomationSettingsLoaded = false;
    nativeLoadAutomationSettingsOnceLocked();
    nativeBumpSharedRevisionLocked("pc");
  }
  SetExtState_ptr(kLuaWindowExtStateSection,
    kManualStopFadeoutRevisionKey,
    std::to_string(
      nativeUiEpochMilliseconds()).c_str(), true);
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static bool nativeUiImportBackup()
{
  const std::string directory =
    nativeUiBackupDefaultDirectory();
  char selected[8192] = "";
  static const char filters[] =
    "Backup VS Hook (*.vshookbackup)\0"
    "*.vshookbackup\0"
    "Todos os arquivos (*.*)\0*.*\0\0";
  if (!vshook_jsapi::browseForOpenFile(
        "Importar Backup VS Hook",
        directory.c_str(), "", filters,
        selected,
        static_cast<int>(sizeof(selected)))) {
    return false;
  }
  if (ShowMessageBox_ptr) {
    const int confirmation = ShowMessageBox_ptr(
      "Importar Backup\n\nEssa acao restaurara todas as configuracoes globais do VS Hook: presets, aparencia, controles, MIDI, Tuner, FaderOut, Teleprompt e acessos. Dados proprios do projeto e a posicao da janela nao serao alterados.\n\nContinuar?",
      "Backup VS Hook", 4);
    if (confirmation != 6) return false;
  }
  const std::string data =
    readTextFile(selected);
  if (data.empty()) {
    nativeUiOpenMessage(
      "Nao foi possivel ler o backup.");
    return false;
  }
  std::string error;
  if (!nativeUiApplyBackupText(data, error)) {
    nativeUiOpenMessage(error.empty()
      ? "Falha ao importar backup." : error);
    return false;
  }
  nativeUiOpenMessage("Backup importado");
  return true;
}

// ==========================================================
// Project Sync: manifesto de preflight e configuracoes A -> B
// ----------------------------------------------------------
// O manifesto nunca leva caminhos absolutos, credenciais, codigo de
// pareamento ou papel do computador. A parte CONFIG reutiliza o mesmo formato
// escapado do backup, mas passa por uma allowlist menor e exclusiva.
// ==========================================================

struct NativeProjectSyncConfigRecord {
  std::string section;
  std::string key;
  std::string value;
};

struct NativeProjectSyncParsedManifest {
  bool valid = false;
  std::string error;
  std::map<std::string, std::string> structural;
  std::map<std::string, std::string> configs;
  std::map<std::string, std::string> summaries;
  std::string configSnapshot = "VSHOOK_PROJECT_SYNC_CONFIG\t1";
};

struct NativeProjectSyncDifference {
  std::string category;
  std::string kind;
  std::string id;
  std::string primary;
  std::string secondary;
};

struct NativeProjectSyncCompareResult {
  bool ready = false;
  bool valid = false;
  bool configApplied = false;
  int structuralDifferenceCount = 0;
  int configDifferenceCount = 0;
  int differenceCount = 0;
  bool truncated = false;
  std::map<std::string, int> categoryCounts;
  std::vector<NativeProjectSyncDifference> differences;
  std::string remoteConfigSnapshot;
  std::string diffJson;
  std::string modalMessage;
};

// O diagnostico do preflight precisa permanecer integro nos dois computadores.
// Ele nao usa o modal generico de mensagem: a lista estruturada abaixo conserva
// todas as diferencas recebidas (o produtor ja aplica o limite defensivo de 200)
// e possui viewport/scroll independentes dos demais modais da interface.
static std::vector<NativeProjectSyncDifference>
  g_nativeProjectSyncDiffModalDifferences;
static std::map<std::string, int>
  g_nativeProjectSyncDiffModalCategoryCounts;
static std::string g_nativeProjectSyncDiffModalHeadline;
static int g_nativeProjectSyncDiffModalDifferenceCount = 0;
static int g_nativeProjectSyncDiffModalStructuralCount = 0;
static int g_nativeProjectSyncDiffModalConfigCount = 0;
static bool g_nativeProjectSyncDiffModalReady = false;
static bool g_nativeProjectSyncDiffModalConfigApplied = false;
static bool g_nativeProjectSyncDiffModalTruncated = false;
static int g_nativeProjectSyncDiffModalScrollPixels = 0;
static int g_nativeProjectSyncDiffModalMaxScrollPixels = 0;
static RECT g_nativeProjectSyncDiffModalScrollTrackRect{0, 0, 0, 0};
static RECT g_nativeProjectSyncDiffModalScrollThumbRect{0, 0, 0, 0};
static bool g_nativeProjectSyncDiffModalScrollbarDragging = false;
static int g_nativeProjectSyncDiffModalScrollbarDragOffsetY = 0;
// A Hook Center pode reenviar o resultado do mesmo preflight enquanto o
// diagnóstico continua aberto. No Windows isso acontecia entre dois eventos
// de WM_MOUSEWHEEL e reconstruía o modal com o scroll em zero. O identificador
// abaixo distingue um reenvio idêntico de um diagnóstico realmente novo.
static std::string g_nativeProjectSyncDiffModalDiagnosticKey;

static std::vector<std::string> nativeProjectSyncTsvFields(
  const std::string& line)
{
  std::vector<std::string> fields;
  size_t start = 0;
  while (start <= line.size()) {
    const size_t tab = line.find('\t', start);
    fields.push_back(line.substr(
      start, tab == std::string::npos
        ? std::string::npos : tab - start));
    if (tab == std::string::npos) break;
    start = tab + 1;
  }
  return fields;
}

static bool nativeProjectSyncRequestIdIsValid(
  const std::string& value)
{
  if (value.size() < 16 || value.size() > 128) return false;
  return std::all_of(value.begin(), value.end(), [](unsigned char ch) {
    return (ch >= '0' && ch <= '9') ||
      (ch >= 'a' && ch <= 'f') ||
      (ch >= 'A' && ch <= 'F');
  });
}

static std::string nativeProjectSyncHashText(
  const std::string& value)
{
  uint64_t hash = UINT64_C(14695981039346656037);
  for (const unsigned char ch : value) {
    hash ^= static_cast<uint64_t>(ch);
    hash *= UINT64_C(1099511628211);
  }
  std::ostringstream text;
  text << std::uppercase << std::hex << std::setfill('0')
       << std::setw(16) << static_cast<unsigned long long>(hash);
  return text.str();
}

static std::string nativeProjectSyncNumber(double value)
{
  if (!std::isfinite(value)) value = 0.0;
  if (std::fabs(value) < 0.0000005) value = 0.0;
  std::ostringstream text;
  text << std::fixed << std::setprecision(6) << value;
  return text.str();
}

// O macOS normalmente entrega nomes de arquivo em Unicode decomposto (NFD),
// enquanto o Windows usa a forma composta (NFC). Visualmente os nomes sao
// iguais, mas uma comparacao byte a byte os tratava como arquivos diferentes.
static std::string nativeProjectSyncNormalizeUnicodeNfc(
  const std::string& value)
{
  if (value.empty()) return value;
#ifdef _WIN32
  const std::wstring wide = utf8ToWide(value);
  if (wide.empty()) return value;
  const int required = NormalizeString(NormalizationC, wide.data(),
    static_cast<int>(wide.size()), nullptr, 0);
  if (required <= 0) return value;
  std::wstring normalized(static_cast<size_t>(required), L'\0');
  const int written = NormalizeString(NormalizationC, wide.data(),
    static_cast<int>(wide.size()), normalized.data(), required);
  if (written <= 0) return value;
  normalized.resize(static_cast<size_t>(written));
  const int utf8Required = WideCharToMultiByte(CP_UTF8, 0,
    normalized.data(), static_cast<int>(normalized.size()),
    nullptr, 0, nullptr, nullptr);
  if (utf8Required <= 0) return value;
  std::string result(static_cast<size_t>(utf8Required), '\0');
  const int utf8Written = WideCharToMultiByte(CP_UTF8, 0,
    normalized.data(), static_cast<int>(normalized.size()),
    result.data(), utf8Required, nullptr, nullptr);
  if (utf8Written <= 0) return value;
  result.resize(static_cast<size_t>(utf8Written));
  return result;
#elif defined(__APPLE__)
  CFStringRef source = CFStringCreateWithBytes(kCFAllocatorDefault,
    reinterpret_cast<const UInt8*>(value.data()),
    static_cast<CFIndex>(value.size()), kCFStringEncodingUTF8, false);
  if (!source) return value;
  CFMutableStringRef normalized = CFStringCreateMutableCopy(
    kCFAllocatorDefault, 0, source);
  CFRelease(source);
  if (!normalized) return value;
  CFStringNormalize(normalized, kCFStringNormalizationFormC);
  const CFIndex maximum = CFStringGetMaximumSizeForEncoding(
    CFStringGetLength(normalized), kCFStringEncodingUTF8) + 1;
  std::vector<char> buffer(static_cast<size_t>(std::max<CFIndex>(1, maximum)));
  const bool converted = CFStringGetCString(normalized, buffer.data(),
    static_cast<CFIndex>(buffer.size()), kCFStringEncodingUTF8);
  CFRelease(normalized);
  return converted ? std::string(buffer.data()) : value;
#else
  return value;
#endif
}

static bool nativeProjectSyncUnicodeEqual(
  const std::string& left,
  const std::string& right)
{
  return left == right ||
    nativeProjectSyncNormalizeUnicodeNfc(left) ==
      nativeProjectSyncNormalizeUnicodeNfc(right);
}

static std::string nativeProjectSyncBasename(
  const std::string& rawPath)
{
  const std::string path = normalizeSlashes(rawPath);
  const size_t separator = path.find_last_of('/');
  return separator == std::string::npos
    ? path : path.substr(separator + 1);
}

static bool nativeProjectSyncHexPrefix20(const std::string& value)
{
  if (value.size() <= 21 || value[20] != '_') return false;
  for (size_t index = 0; index < 20; ++index) {
    const unsigned char character =
      static_cast<unsigned char>(value[index]);
    if (!std::isxdigit(character)) return false;
  }
  return true;
}

static std::string nativeProjectSyncCanonicalSourceName(
  const std::string& rawPath)
{
  std::string name = nativeProjectSyncBasename(rawPath);
  const std::string normalized = normalizeSlashes(rawPath);
  const std::string marker = "/VS Hook Project Sync/Media/";
#ifdef _WIN32
  const bool managed = nativeLower(normalized).find(
    nativeLower(marker)) != std::string::npos;
#else
  const bool managed = normalized.find(marker) != std::string::npos;
#endif
  if (!managed) return nativeProjectSyncNormalizeUnicodeNfc(name);

  // A mídia gerenciada recebe <sha20>_ no PC B. Esse prefixo pertence ao
  // armazenamento/deduplicação, não à identidade lógica do item. Remove
  // também prefixos duplicados gerados por builds anteriores.
  while (nativeProjectSyncHexPrefix20(name)) name.erase(0, 21);
  return nativeProjectSyncNormalizeUnicodeNfc(
    name.empty() ? nativeProjectSyncBasename(rawPath) : name);
}

static long long nativeProjectSyncFileSize(
  const std::string& path)
{
  if (path.empty()) return -1;
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty()) return -1;
  WIN32_FILE_ATTRIBUTE_DATA data{};
  if (!GetFileAttributesExW(
        widePath.c_str(), GetFileExInfoStandard, &data) ||
      (data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0) {
    return -1;
  }
  ULARGE_INTEGER size{};
  size.HighPart = data.nFileSizeHigh;
  size.LowPart = data.nFileSizeLow;
  const unsigned long long maximum = static_cast<unsigned long long>(
    std::numeric_limits<long long>::max());
  return size.QuadPart > maximum
    ? std::numeric_limits<long long>::max()
    : static_cast<long long>(size.QuadPart);
#else
  struct stat data{};
  if (stat(path.c_str(), &data) != 0 || !S_ISREG(data.st_mode)) {
    return -1;
  }
  return static_cast<long long>(data.st_size);
#endif
}

struct NativeProjectSyncRegularFileStamp {
  uint64_t size = 0;
  uint64_t modificationToken = 0;
  double modificationTimeMs = 0.0;
};

struct NativeProjectSyncCachedFileHash {
  uint64_t size = 0;
  uint64_t modificationToken = 0;
  std::string sha256;
};

static std::mutex g_nativeProjectSyncFileHashCacheMutex;
static std::map<std::string, NativeProjectSyncCachedFileHash>
  g_nativeProjectSyncFileHashCache;

static std::string nativeProjectSyncFileHashCacheKey(
  const std::string& rawPath)
{
  std::string key = normalizeSlashes(nativeTrim(rawPath));
#ifdef _WIN32
  key = nativeLower(key);
#endif
  return key;
}

static bool nativeProjectSyncCachedFileHash(
  const std::string& path,
  const NativeProjectSyncRegularFileStamp& stamp,
  std::string& sha256Out)
{
  sha256Out.clear();
  const std::string key = nativeProjectSyncFileHashCacheKey(path);
  if (key.empty()) return false;
  std::lock_guard<std::mutex> lock(
    g_nativeProjectSyncFileHashCacheMutex);
  const auto found = g_nativeProjectSyncFileHashCache.find(key);
  if (found == g_nativeProjectSyncFileHashCache.end() ||
      found->second.size != stamp.size ||
      found->second.modificationToken != stamp.modificationToken ||
      found->second.sha256.size() != 64) {
    return false;
  }
  sha256Out = found->second.sha256;
  return true;
}

static void nativeProjectSyncRememberFileHash(
  const std::string& path,
  const NativeProjectSyncRegularFileStamp& stamp,
  const std::string& sha256)
{
  if (sha256.size() != 64) return;
  const std::string key = nativeProjectSyncFileHashCacheKey(path);
  if (key.empty()) return;
  std::lock_guard<std::mutex> lock(
    g_nativeProjectSyncFileHashCacheMutex);
  if (g_nativeProjectSyncFileHashCache.size() >= 32768 &&
      g_nativeProjectSyncFileHashCache.count(key) == 0) {
    g_nativeProjectSyncFileHashCache.clear();
  }
  g_nativeProjectSyncFileHashCache[key] = {
    stamp.size, stamp.modificationToken, nativeLower(sha256)};
}

static bool nativeProjectSyncRegularFileStamp(
  const std::string& rawPath,
  NativeProjectSyncRegularFileStamp& stampOut)
{
  stampOut = NativeProjectSyncRegularFileStamp{};
  const std::string path = normalizeSlashes(nativeTrim(rawPath));
  if (path.empty()) return false;
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty()) return false;
  WIN32_FILE_ATTRIBUTE_DATA data{};
  if (!GetFileAttributesExW(
        widePath.c_str(), GetFileExInfoStandard, &data) ||
      (data.dwFileAttributes & FILE_ATTRIBUTE_DIRECTORY) != 0 ||
      (data.dwFileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0) {
    return false;
  }
  ULARGE_INTEGER size{};
  size.HighPart = data.nFileSizeHigh;
  size.LowPart = data.nFileSizeLow;
  ULARGE_INTEGER modified{};
  modified.HighPart = data.ftLastWriteTime.dwHighDateTime;
  modified.LowPart = data.ftLastWriteTime.dwLowDateTime;
  stampOut.size = size.QuadPart;
  stampOut.modificationToken = modified.QuadPart;
  constexpr double kWindowsToUnixEpochMs = 11644473600000.0;
  stampOut.modificationTimeMs =
    static_cast<double>(modified.QuadPart) / 10000.0 -
      kWindowsToUnixEpochMs;
#else
  struct stat info{};
  if (lstat(path.c_str(), &info) != 0 || !S_ISREG(info.st_mode) ||
      S_ISLNK(info.st_mode) || info.st_size < 0) {
    return false;
  }
#ifdef __APPLE__
  const std::time_t seconds = info.st_mtimespec.tv_sec;
  const long nanoseconds = info.st_mtimespec.tv_nsec;
#else
  const std::time_t seconds = info.st_mtim.tv_sec;
  const long nanoseconds = info.st_mtim.tv_nsec;
#endif
  stampOut.size = static_cast<uint64_t>(info.st_size);
  stampOut.modificationToken =
    static_cast<uint64_t>(seconds) * 1000000000ULL +
      static_cast<uint64_t>(std::max<long>(0, nanoseconds));
  stampOut.modificationTimeMs =
    static_cast<double>(seconds) * 1000.0 +
      static_cast<double>(nanoseconds) / 1000000.0;
#endif
  return true;
}

static bool nativeProjectSyncConfigKeyAllowed(
  const std::string& section,
  const std::string& key)
{
  if (section == kLuaWindowExtStateSection) {
    return nativeUiBackupContainsKey(
      nativeUiBackupWindowGlobalKeys(), key) ||
      key == "PREMIX_V1" ||
      key == "PREMIX_ENABLED_V1" ||
      key == "PREMIX_GLOBAL_ENABLED_V1";
  }
  if (section == kNativeExtStateSection) {
    return nativeUiBackupContainsKey(
      nativeUiBackupNativeGlobalKeys(), key);
  }
  if (section == kNativeTelepromptSettingsSection) {
    return key == "TP1_SETTINGS_V1" ||
      key == "TP2_SETTINGS_V1";
  }
  return section == kManualStopFadeoutProjectSection &&
    key == kManualStopFadeoutTracksKey;
}

static std::string nativeProjectSyncBuildConfigSnapshot()
{
  std::vector<NativeProjectSyncConfigRecord> records;
  const auto addGlobal = [&](const std::string& section,
                             const std::string& key) {
    const char* raw = GetExtState_ptr
      ? GetExtState_ptr(section.c_str(), key.c_str()) : nullptr;
    records.push_back({section, key, raw ? raw : ""});
  };
  for (const std::string& key : nativeUiBackupWindowGlobalKeys()) {
    addGlobal(kLuaWindowExtStateSection, key);
  }
  for (const std::string& key : nativeUiBackupNativeGlobalKeys()) {
    addGlobal(kNativeExtStateSection, key);
  }
  addGlobal(kNativeTelepromptSettingsSection, "TP1_SETTINGS_V1");
  addGlobal(kNativeTelepromptSettingsSection, "TP2_SETTINGS_V1");
  addGlobal("JBKEYS_VSLIVE_WINDOW", "PREMIX_V1");
  addGlobal("JBKEYS_VSLIVE_WINDOW", "PREMIX_ENABLED_V1");
  addGlobal("JBKEYS_VSLIVE_WINDOW", "PREMIX_GLOBAL_ENABLED_V1");

  std::ostringstream fadeoutTracks;
  const std::vector<std::string> trackIds =
    nativeManualStopFadeoutTrackIds();
  for (size_t index = 0; index < trackIds.size(); ++index) {
    if (index) fadeoutTracks << ';';
    fadeoutTracks << trackIds[index];
  }
  records.push_back({
    kManualStopFadeoutProjectSection,
    kManualStopFadeoutTracksKey,
    fadeoutTracks.str()});

  std::sort(records.begin(), records.end(),
    [](const NativeProjectSyncConfigRecord& left,
       const NativeProjectSyncConfigRecord& right) {
      if (left.section != right.section) {
        return left.section < right.section;
      }
      return left.key < right.key;
    });

  std::vector<std::string> lines;
  lines.push_back("VSHOOK_PROJECT_SYNC_CONFIG\t1");
  for (const auto& record : records) {
    nativeUiBackupAddRecord(
      lines, record.section, record.key, record.value);
  }
  std::ostringstream output;
  for (size_t index = 0; index < lines.size(); ++index) {
    if (index) output << '\n';
    output << lines[index];
  }
  const std::string snapshot = output.str();
  if (snapshot.size() > 384 * 1024) {
    return "VSHOOK_PROJECT_SYNC_CONFIG\t1\nERROR\tsnapshot_too_large";
  }
  return snapshot;
}

static bool nativeProjectSyncApplyConfigSnapshot(
  const std::string& snapshot,
  const std::string& revision,
  std::string& errorOut)
{
  if (!SetExtState_ptr || snapshot.size() > 384 * 1024 ||
      snapshot.rfind("VSHOOK_PROJECT_SYNC_CONFIG\t1", 0) != 0) {
    errorOut = "Snapshot de configuracoes invalido.";
    return false;
  }
  std::map<std::string, NativeProjectSyncConfigRecord> pending;
  std::istringstream stream(snapshot);
  std::string line;
  bool firstLine = true;
  while (std::getline(stream, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    if (firstLine) {
      firstLine = false;
      continue;
    }
    if (line.rfind("ERROR\t", 0) == 0) {
      errorOut = "Snapshot de configuracoes excedeu o limite seguro.";
      return false;
    }
    if (line.rfind("DATA\t", 0) != 0) continue;
    const std::vector<std::string> fields =
      nativeProjectSyncTsvFields(line);
    if (fields.size() != 5 ||
        nativeUiBackupUnescape(fields[1]) != "GLOBAL") {
      errorOut = "Registro de configuracao invalido.";
      return false;
    }
    NativeProjectSyncConfigRecord record{
      nativeUiBackupUnescape(fields[2]),
      nativeUiBackupUnescape(fields[3]),
      nativeUiBackupUnescape(fields[4])};
    if (!nativeProjectSyncConfigKeyAllowed(
          record.section, record.key)) {
      errorOut = "Snapshot contem configuracao nao permitida.";
      return false;
    }
    pending[record.section + "\t" + record.key] = std::move(record);
  }
  if (pending.empty()) {
    errorOut = "Snapshot sem configuracoes permitidas.";
    return false;
  }

  ReaProject* project = getCurrentProject(nullptr, 0);
  bool projectSettingsChanged = false;
  for (const auto& entry : pending) {
    const NativeProjectSyncConfigRecord& record = entry.second;
    if (record.section == kManualStopFadeoutProjectSection) {
      if (!project || !SetProjExtState_ptr) {
        errorOut = "Projeto local indisponivel para aplicar o FaderOut.";
        return false;
      }
      std::ostringstream currentTracks;
      const std::vector<std::string> currentTrackIds =
        nativeManualStopFadeoutTrackIds();
      for (size_t index = 0; index < currentTrackIds.size(); ++index) {
        if (index) currentTracks << ';';
        currentTracks << currentTrackIds[index];
      }
      if (currentTracks.str() != record.value) {
        SetProjExtState_ptr(project,
          kManualStopFadeoutProjectSection,
          kManualStopFadeoutTracksKey,
          record.value.c_str());
        // A leitura ainda suporta o armazenamento global legado quando a chave
        // do projeto nao existe. Mantem esse fallback igual ao mestre, inclusive
        // para que uma selecao vazia nao ressuscite pistas antigas no PC B.
        SetExtState_ptr(kLuaWindowExtStateSection,
          kManualStopFadeoutTracksKey,
          record.value.c_str(), true);
        projectSettingsChanged = true;
      }
      continue;
    }
    const char* current = GetExtState_ptr
      ? GetExtState_ptr(record.section.c_str(), record.key.c_str())
      : nullptr;
    if (std::string(current ? current : "") != record.value) {
      SetExtState_ptr(record.section.c_str(), record.key.c_str(),
        record.value.c_str(), true);
    }
  }
  if (projectSettingsChanged && project && MarkProjectDirty_ptr) {
    MarkProjectDirty_ptr(project);
  }

  nativeUiInvalidateVisualPrefsCache();
  nativeTelepromptReloadSettingsAfterBackup();
  nativeRefreshStopPauseModeFromExtState();
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeAutomationSettingsLoaded = false;
    nativeLoadAutomationSettingsOnceLocked();
    nativeBumpSharedRevisionLocked("pc");
  }
  nativeBumpManualStopFadeoutRevision();
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  g_nativeProjectSyncLastAppliedConfigRevision = revision;
  return true;
}

static std::string nativeProjectSyncBuildStructuralManifest(
  ReaProject* project)
{
  constexpr size_t kManifestLimit = 640 * 1024;
  if (!project || !CountTracks_ptr || !GetTrack_ptr ||
      !GetTrackNumMediaItems_ptr || !GetTrackMediaItem_ptr ||
      !GetMediaItemInfo_Value_ptr) {
    return "VSHOOK_PROJECT_SYNC_MANIFEST\t1\nERROR\tproject_api_unavailable";
  }
  std::vector<std::string> records;
  size_t bytes = 0;
  bool overflow = false;
  const std::string projectFileDirectory =
    nativeTelepromptProjectFileDirectory(project);
  const std::string projectMediaDirectory =
    nativeTelepromptProjectMediaDirectory(project);
  const auto addRecord = [&](const std::string& value) {
    if (overflow) return;
    if (bytes + value.size() + 1 > kManifestLimit) {
      overflow = true;
      return;
    }
    bytes += value.size() + 1;
    records.push_back(value);
  };

  const int trackCount = CountTracks_ptr(project);
  for (int trackIndex = 0; trackIndex < trackCount && !overflow;
       ++trackIndex) {
    MediaTrack* track = GetTrack_ptr(project, trackIndex);
    if (!track) continue;
    const std::string trackGuid =
      nativeTrackGuid(track, trackIndex);
    const std::string trackName =
      nativeTrackName(track, trackIndex);
    const int itemCount = GetTrackNumMediaItems_ptr(track);
    const int folderDepth = GetMediaTrackInfo_Value_ptr
      ? static_cast<int>(std::lround(GetMediaTrackInfo_Value_ptr(
          track, "I_FOLDERDEPTH"))) : 0;
    addRecord(
      "TRACK\t" + nativeUiBackupEscape(trackGuid) + "\t" +
      std::to_string(trackIndex + 1) + "\t" +
      nativeUiBackupEscape(
        nativeProjectSyncNormalizeUnicodeNfc(trackName)) + "\t" +
      std::to_string(folderDepth) + "\t" +
      std::to_string(itemCount) + "\t" +
      // Volume, mute e solo sao estado vivo do mixer. O snapshot absoluto de
      // pistas os aplica logo apos o pareamento; eles nao devem bloquear o
      // preflight nem iniciar copia de projeto/midia.
      "1.000000\t0\t0");

    const int fxCount = TrackFX_GetCount_ptr
      ? std::max(0, TrackFX_GetCount_ptr(track)) : 0;
    for (int fxIndex = 0; fxIndex < fxCount && !overflow; ++fxIndex) {
      std::string fxGuid;
      if (TrackFX_GetFXGUID_ptr && guidToString_ptr) {
        GUID* guid = TrackFX_GetFXGUID_ptr(track, fxIndex);
        if (guid) {
          char buffer[80] = "";
          guidToString_ptr(guid, buffer);
          fxGuid = buffer;
        }
      }
      if (fxGuid.empty()) fxGuid = std::to_string(fxIndex + 1);
      char fxNameBuffer[1024] = "";
      if (TrackFX_GetFXName_ptr) {
        TrackFX_GetFXName_ptr(
          track, fxIndex, fxNameBuffer,
          static_cast<int>(sizeof(fxNameBuffer)));
      }
      const std::string normalizedFxName =
        nativeProjectSyncNormalizeUnicodeNfc(fxNameBuffer);
      std::ostringstream parameterState;
      const int parameterCount = TrackFX_GetNumParams_ptr
        ? std::max(0, TrackFX_GetNumParams_ptr(track, fxIndex)) : 0;
      parameterState << parameterCount;
      if (TrackFX_GetParamNormalized_ptr) {
        for (int parameterIndex = 0;
             parameterIndex < parameterCount; ++parameterIndex) {
          double value = TrackFX_GetParamNormalized_ptr(
            track, fxIndex, parameterIndex);
          if (!std::isfinite(value)) value = 0.0;
          // Seis casas evitam falso positivo por pequenas diferenças de
          // ponto flutuante entre Windows e macOS sem esconder uma alteração
          // audível de parâmetro.
          parameterState << ':' << nativeProjectSyncNumber(value);
        }
      }
      const std::string parameterHash =
        nativeProjectSyncHashText(parameterState.str());
      const std::string fxIdentity = trackGuid + ":fx:" + fxGuid;
      addRecord(
        "FX\t" + nativeUiBackupEscape(fxIdentity) + "\t" +
        nativeUiBackupEscape(trackGuid) + "\t" +
        std::to_string(fxIndex + 1) + "\t" +
        nativeUiBackupEscape(fxGuid) + "\t" +
        nativeUiBackupEscape(normalizedFxName) + "\t" +
        ((!TrackFX_GetEnabled_ptr ||
          TrackFX_GetEnabled_ptr(track, fxIndex)) ? "1" : "0") + "\t" +
        ((TrackFX_GetOffline_ptr &&
          TrackFX_GetOffline_ptr(track, fxIndex)) ? "1" : "0") + "\t" +
        parameterHash);
    }

    for (int itemIndex = 0; itemIndex < itemCount && !overflow;
         ++itemIndex) {
      MediaItem* item = GetTrackMediaItem_ptr(track, itemIndex);
      if (!item) continue;
      const std::string itemGuid = nativeMediaItemGuid(
        item, trackGuid + ":item:" + std::to_string(itemIndex + 1));
      MediaItem_Take* take = GetActiveTake_ptr
        ? GetActiveTake_ptr(item) : nullptr;
      const bool midi = take && TakeIsMIDI_ptr && TakeIsMIDI_ptr(take);
      const std::string sourcePath =
        midi ? std::string() : nativeReadTakeSourcePath(take);
      const std::string resolvedSourcePath =
        midi || sourcePath.empty()
          ? sourcePath
          : nativeResolveTelepromptMediaPath(
              sourcePath, projectFileDirectory,
              projectMediaDirectory);
      const std::string mediaKind = midi
        ? "midi" : (sourcePath.empty() ? "empty" : "file");
      std::string sourceName = sourcePath.empty()
        ? nativeTakeName(item, midi ? "MIDI" : "Sem arquivo")
        : nativeProjectSyncCanonicalSourceName(sourcePath);
      if (sourceName.empty()) sourceName = mediaKind;
      sourceName = nativeProjectSyncNormalizeUnicodeNfc(sourceName);
      const bool sourceExists = midi ||
        (!resolvedSourcePath.empty() && fileExists(resolvedSourcePath));
      const long long sourceSize = sourcePath.empty()
        ? (midi ? 0 : -1)
        : nativeProjectSyncFileSize(resolvedSourcePath);
      const double startOffset = take && GetMediaItemTakeInfo_Value_ptr
        ? GetMediaItemTakeInfo_Value_ptr(take, "D_STARTOFFS") : 0.0;
      const double playRate = take && GetMediaItemTakeInfo_Value_ptr
        ? GetMediaItemTakeInfo_Value_ptr(take, "D_PLAYRATE") : 1.0;
      const double itemVolume = GetMediaItemInfo_Value_ptr(
        item, "D_VOL");
      const double takeVolume = take && GetMediaItemTakeInfo_Value_ptr
        ? GetMediaItemTakeInfo_Value_ptr(take, "D_VOL") : 1.0;
      addRecord(
        "ITEM\t" + nativeUiBackupEscape(itemGuid) + "\t" +
        nativeUiBackupEscape(trackGuid) + "\t" +
        std::to_string(itemIndex + 1) + "\t" +
        mediaKind + "\t" + nativeUiBackupEscape(sourceName) + "\t" +
        (sourceExists ? "1" : "0") + "\t" +
        std::to_string(sourceSize) + "\t" +
        nativeProjectSyncNumber(GetMediaItemInfo_Value_ptr(
          item, "D_POSITION")) + "\t" +
        nativeProjectSyncNumber(GetMediaItemInfo_Value_ptr(
          item, "D_LENGTH")) + "\t" +
        nativeProjectSyncNumber(startOffset) + "\t" +
        nativeProjectSyncNumber(playRate) + "\t" +
        (GetMediaItemInfo_Value_ptr(item, "B_LOOPSRC") > 0.5
          ? "1" : "0") + "\t" +
        nativeProjectSyncNumber(itemVolume) + "\t" +
        nativeProjectSyncNumber(takeVolume));
    }
  }

  if (!overflow && CountProjectMarkers_ptr && EnumProjectMarkers3_ptr) {
    std::map<std::string, int> identityOccurrences;
    int markerCount = 0;
    int regionCount = 0;
    int total = CountProjectMarkers_ptr(
      project, &markerCount, &regionCount);
    if (total <= 0) total = markerCount + regionCount;
    for (int enumIndex = 0; enumIndex < total && !overflow;
         ++enumIndex) {
      bool region = false;
      double start = 0.0;
      double end = 0.0;
      const char* rawName = nullptr;
      int number = 0;
      int color = 0;
      if (!EnumProjectMarkers3_ptr(project, enumIndex, &region,
            &start, &end, &rawName, &number, &color)) {
        continue;
      }
      const std::string type = region ? "REGION" : "MARKER";
      const std::string identityBase =
        std::string(region ? "region_" : "marker_") +
        std::to_string(number);
      const int occurrence = ++identityOccurrences[identityBase];
      const std::string identity = identityBase + "_" +
        std::to_string(occurrence);
      std::string record = type + "\t" +
        nativeUiBackupEscape(identity) + "\t" +
        std::to_string(number) + "\t" +
        nativeUiBackupEscape(nativeProjectSyncNormalizeUnicodeNfc(
          rawName ? rawName : "")) + "\t" +
        nativeProjectSyncNumber(start) + "\t";
      if (region) record += nativeProjectSyncNumber(end) + "\t";
      // A cor de regiao/marcador e apenas visual e o COLORREF nativo ainda
      // possui representacao diferente no Windows e no macOS. Ela nao pode
      // bloquear o Project Sync nem aparecer como uma diferenca de execucao.
      // Mantem o campo no manifesto v1 para compatibilidade do parser, mas o
      // valor canonico e neutro nos dois sistemas.
      // A faixa da regua tambem e apenas organizacao visual; -1 instrui a
      // aplicacao a preservar a faixa local no PC B.
      record += "0\t-1";
      addRecord(record);
    }
  }

  if (!overflow && CountTempoTimeSigMarkers_ptr &&
      GetTempoTimeSigMarker_ptr) {
    const int count = CountTempoTimeSigMarkers_ptr(project);
    for (int index = 0; index < count && !overflow; ++index) {
      double timePosition = 0.0;
      int measurePosition = 0;
      double beatPosition = 0.0;
      double bpm = 0.0;
      int numerator = 0;
      int denominator = 0;
      bool linear = false;
      if (!GetTempoTimeSigMarker_ptr(project, index,
            &timePosition, &measurePosition, &beatPosition,
            &bpm, &numerator, &denominator, &linear)) {
        continue;
      }
      addRecord(
        "TEMPO\t" + std::to_string(index + 1) + "\t" +
        nativeProjectSyncNumber(timePosition) + "\t" +
        std::to_string(measurePosition) + "\t" +
        nativeProjectSyncNumber(beatPosition) + "\t" +
        nativeProjectSyncNumber(bpm) + "\t" +
        std::to_string(numerator) + "\t" +
        std::to_string(denominator) + "\t" +
        (linear ? "1" : "0"));
    }
  }

  if (overflow) {
    return "VSHOOK_PROJECT_SYNC_MANIFEST\t1\nERROR\tmanifest_too_large";
  }
  std::ostringstream output;
  output << "VSHOOK_PROJECT_SYNC_MANIFEST\t1";
  for (const std::string& record : records) {
    output << '\n' << record;
  }
  return output.str();
}

static std::string nativeProjectSyncMergeManifestAndConfig(
  const std::string& structural,
  const std::string& configSnapshot)
{
  std::ostringstream output;
  output << structural;
  std::istringstream stream(configSnapshot);
  std::string line;
  bool firstLine = true;
  while (std::getline(stream, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    if (firstLine) {
      firstLine = false;
      continue;
    }
    if (line.rfind("ERROR\t", 0) == 0) {
      output << '\n' << line;
      continue;
    }
    const std::vector<std::string> fields =
      nativeProjectSyncTsvFields(line);
    if (fields.size() == 5 && fields[0] == "DATA" &&
        nativeUiBackupUnescape(fields[1]) == "GLOBAL") {
      output << "\nCONFIG\t" << fields[2] << '\t'
             << fields[3] << '\t' << fields[4];
    }
  }
  const std::string merged = output.str();
  // /command aceita no maximo 1 MiB. O manifesto ainda sera escapado como uma
  // string JSON, portanto conserva margem inclusive para valores com muitas
  // barras/aspas.
  if (merged.size() > 480 * 1024) {
    return "VSHOOK_PROJECT_SYNC_MANIFEST\t1\nERROR\tmanifest_too_large";
  }
  return merged;
}

static std::string nativeProjectSyncRecordSummary(
  const std::vector<std::string>& escapedFields)
{
  if (escapedFields.empty()) return {};
  std::vector<std::string> fields = escapedFields;
  for (size_t index = 1; index < fields.size(); ++index) {
    fields[index] = nativeUiBackupUnescape(fields[index]);
  }
  const std::string& type = fields[0];
  if (type == "TRACK" && fields.size() == 9) {
    return "Pista " + fields[2] + " - " + fields[3];
  }
  if (type == "ITEM" &&
      (fields.size() == 13 || fields.size() == 15)) {
    return "Arquivo " + fields[5] + " na pista " + fields[2] +
      " em " + fields[8] + " s";
  }
  if (type == "FX" && fields.size() == 9) {
    return "Plugin " + fields[5] + " (ordem " + fields[3] +
      ") na pista " + fields[2];
  }
  if (type == "REGION" && fields.size() == 8) {
    return "Regiao " + fields[3] + " em " + fields[4] + " s";
  }
  if (type == "MARKER" && fields.size() == 7) {
    return "Marcador " + fields[3] + " em " + fields[4] + " s";
  }
  if (type == "TEMPO" && fields.size() == 9) {
    return "Tempo " + fields[5] + " BPM em " + fields[2] + " s";
  }
  if (type == "CONFIG" && fields.size() == 4) {
    return "Configuracao " + fields[2];
  }
  return fields.size() > 1 ? fields[1] : type;
}

struct NativeProjectSyncRecordComparison {
  bool recognized = false;
  bool equivalent = false;
  std::string primarySummary;
  std::string secondarySummary;
};

static bool nativeProjectSyncItemNumberEqual(
  const std::string& left,
  const std::string& right,
  double tolerance)
{
  char* leftEnd = nullptr;
  char* rightEnd = nullptr;
  const double leftValue = std::strtod(left.c_str(), &leftEnd);
  const double rightValue = std::strtod(right.c_str(), &rightEnd);
  if (!leftEnd || leftEnd == left.c_str() || *leftEnd != '\0' ||
      !rightEnd || rightEnd == right.c_str() || *rightEnd != '\0' ||
      !std::isfinite(leftValue) || !std::isfinite(rightValue)) {
    return left == right;
  }
  return std::fabs(leftValue - rightValue) <= tolerance;
}

static NativeProjectSyncRecordComparison
nativeProjectSyncCompareItemRecords(
  const std::string& primaryLine,
  const std::string& secondaryLine)
{
  NativeProjectSyncRecordComparison comparison;
  std::vector<std::string> primary =
    nativeProjectSyncTsvFields(primaryLine);
  std::vector<std::string> secondary =
    nativeProjectSyncTsvFields(secondaryLine);
  if ((primary.size() != 13 && primary.size() != 15) ||
      (secondary.size() != 13 && secondary.size() != 15) ||
      primary.empty() || secondary.empty() ||
      primary[0] != "ITEM" || secondary[0] != "ITEM") {
    return comparison;
  }
  for (size_t index = 1; index < primary.size(); ++index) {
    primary[index] = nativeUiBackupUnescape(primary[index]);
  }
  for (size_t index = 1; index < secondary.size(); ++index) {
    secondary[index] = nativeUiBackupUnescape(secondary[index]);
  }
  comparison.recognized = true;

  // Manifestos v1 antigos nao tinham os volumes do item/take. O valor que o
  // REAPER usa quando esses campos nao existem e 1.0, portanto esse e o unico
  // default semanticamente seguro ao comparar uma versao antiga com a atual.
  const auto field = [](const std::vector<std::string>& values,
                        size_t index,
                        const char* fallback = "") -> std::string {
    return index < values.size() ? values[index] : fallback;
  };
  const bool stableGuid = primary[1] == secondary[1] &&
    primary[1].size() >= 2 && primary[1].front() == '{' &&
    primary[1].back() == '}';

  struct ChangedField {
    std::string label;
    std::string primary;
    std::string secondary;
  };
  std::vector<ChangedField> changed;
  const auto compareText = [&](const char* label, size_t index,
                               const char* fallback = "") {
    const std::string left = field(primary, index, fallback);
    const std::string right = field(secondary, index, fallback);
    if (!nativeProjectSyncUnicodeEqual(left, right)) {
      changed.push_back({label, left, right});
    }
  };
  const auto compareNumber = [&](const char* label, size_t index,
                                 double tolerance,
                                 const char* suffix = "",
                                 const char* fallback = "") {
    const std::string left = field(primary, index, fallback);
    const std::string right = field(secondary, index, fallback);
    if (!nativeProjectSyncItemNumberEqual(left, right, tolerance)) {
      changed.push_back({label, left + suffix, right + suffix});
    }
  };
  const auto compareFlag = [&](const char* label, size_t index) {
    const std::string left = field(primary, index);
    const std::string right = field(secondary, index);
    if (left != right) {
      changed.push_back({label,
        left == "1" ? "sim" : "nao",
        right == "1" ? "sim" : "nao"});
    }
  };

  compareText("pista", 2);
  // A ordem interna pode divergir depois de uma edicao sem alterar o item.
  // Ela so participa da comparacao quando nao ha GUID real e a identidade
  // depende do fallback posicional.
  if (!stableGuid) compareText("ordem interna", 3);
  compareText("natureza", 4);
  compareText("arquivo", 5);
  compareFlag("arquivo disponivel", 6);
  compareText("tamanho do arquivo", 7);
  compareNumber("posicao", 8, 0.000001, " s");
  compareNumber("duracao", 9, 0.000001, " s");
  compareNumber("offset", 10, 0.000001, " s");
  compareNumber("velocidade", 11, 0.000001, "x");
  compareFlag("loop", 12);
  compareNumber("volume do item", 13, 0.000001, "", "1.000000");
  compareNumber("volume do take", 14, 0.000001, "", "1.000000");

  comparison.equivalent = changed.empty();
  if (comparison.equivalent) return comparison;

  const std::string primaryName = field(primary, 5, "item");
  const std::string secondaryName = field(secondary, 5, "item");
  comparison.primarySummary = "Arquivo " + primaryName;
  comparison.secondarySummary = "Arquivo " + secondaryName;
  for (const ChangedField& entry : changed) {
    comparison.primarySummary += " | " + entry.label + ": " + entry.primary;
    comparison.secondarySummary += " | " + entry.label + ": " + entry.secondary;
  }
  return comparison;
}

static NativeProjectSyncRecordComparison
nativeProjectSyncCompareTrackRecords(
  const std::string& primaryLine,
  const std::string& secondaryLine)
{
  NativeProjectSyncRecordComparison comparison;
  std::vector<std::string> primary =
    nativeProjectSyncTsvFields(primaryLine);
  std::vector<std::string> secondary =
    nativeProjectSyncTsvFields(secondaryLine);
  if (primary.size() != 9 || secondary.size() != 9 ||
      primary[0] != "TRACK" || secondary[0] != "TRACK") {
    return comparison;
  }
  for (size_t index = 1; index < primary.size(); ++index) {
    primary[index] = nativeUiBackupUnescape(primary[index]);
    secondary[index] = nativeUiBackupUnescape(secondary[index]);
  }
  comparison.recognized = true;

  // Campos 6/7/8 sao D_VOL, B_MUTE e I_SOLO. Eles sao sincronizados por
  // comandos absolutos do mixer e nao fazem parte da estrutura do projeto.
  comparison.equivalent = primary[1] == secondary[1] &&
    primary[2] == secondary[2] &&
    nativeProjectSyncUnicodeEqual(primary[3], secondary[3]) &&
    primary[4] == secondary[4] &&
    primary[5] == secondary[5];
  if (!comparison.equivalent) {
    comparison.primarySummary = nativeProjectSyncRecordSummary(primary);
    comparison.secondarySummary = nativeProjectSyncRecordSummary(secondary);
  }
  return comparison;
}

static NativeProjectSyncRecordComparison
nativeProjectSyncCompareTempoRecords(
  const std::string& primaryLine,
  const std::string& secondaryLine)
{
  NativeProjectSyncRecordComparison comparison;
  const std::vector<std::string> primary =
    nativeProjectSyncTsvFields(primaryLine);
  const std::vector<std::string> secondary =
    nativeProjectSyncTsvFields(secondaryLine);
  if (primary.size() != 9 || secondary.size() != 9 ||
      primary[0] != "TEMPO" || secondary[0] != "TEMPO") {
    return comparison;
  }
  comparison.recognized = true;

  // measurePosition e beatPosition (campos 3/4) sao coordenadas derivadas.
  // Ao recriar o mesmo mapa em Time e voltar o projeto para Beats, o REAPER
  // pode normaliza-las de forma diferente entre Windows/macOS, embora tempo,
  // BPM, assinatura e curva sejam identicos. Elas nao alteram a execucao e
  // nao podem produzir um falso bloqueio.
  const bool samePosition = nativeProjectSyncItemNumberEqual(
    primary[2], secondary[2], 0.000001);
  const bool sameBpm = nativeProjectSyncItemNumberEqual(
    primary[5], secondary[5], 0.000001);
  comparison.equivalent = samePosition && sameBpm &&
    primary[6] == secondary[6] &&
    primary[7] == secondary[7] &&
    primary[8] == secondary[8];
  if (comparison.equivalent) return comparison;

  comparison.primarySummary = nativeProjectSyncRecordSummary(primary);
  comparison.secondarySummary = nativeProjectSyncRecordSummary(secondary);
  return comparison;
}

static NativeProjectSyncParsedManifest
nativeProjectSyncParseManifest(const std::string& manifest)
{
  NativeProjectSyncParsedManifest parsed;
  if (manifest.empty() || manifest.size() > 768 * 1024) {
    parsed.error = "manifest_size_invalid";
    return parsed;
  }
  std::istringstream stream(manifest);
  std::string line;
  bool firstLine = true;
  while (std::getline(stream, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    if (firstLine) {
      firstLine = false;
      if (line != "VSHOOK_PROJECT_SYNC_MANIFEST\t1") {
        parsed.error = "manifest_version_invalid";
        return parsed;
      }
      continue;
    }
    if (line.empty()) continue;
    if (line.rfind("ERROR\t", 0) == 0) {
      parsed.error = nativeUiBackupUnescape(line.substr(6));
      return parsed;
    }
    const std::vector<std::string> fields =
      nativeProjectSyncTsvFields(line);
    if (fields.empty()) continue;
    const std::string& type = fields[0];
    const bool validSize =
      (type == "TRACK" && fields.size() == 9) ||
      (type == "ITEM" &&
       (fields.size() == 13 || fields.size() == 15)) ||
      (type == "FX" && fields.size() == 9) ||
      (type == "REGION" && fields.size() == 8) ||
      (type == "MARKER" && fields.size() == 7) ||
      (type == "TEMPO" && fields.size() == 9) ||
      (type == "CONFIG" && fields.size() == 4);
    if (!validSize) {
      parsed.error = "manifest_record_invalid";
      return parsed;
    }
    if (type == "CONFIG") {
      const std::string section = nativeUiBackupUnescape(fields[1]);
      const std::string key = nativeUiBackupUnescape(fields[2]);
      if (!nativeProjectSyncConfigKeyAllowed(section, key)) {
        parsed.error = "manifest_config_not_allowed";
        return parsed;
      }
      const std::string identity = "CONFIG\t" + section + "\t" + key;
      if (parsed.configs.count(identity) != 0) {
        parsed.error = "manifest_duplicate_identity";
        return parsed;
      }
      parsed.configs[identity] = line;
      parsed.summaries[identity] =
        nativeProjectSyncRecordSummary(fields);
      continue;
    }
    const std::string identity = type + "\t" +
      nativeUiBackupUnescape(fields[1]);
    if (parsed.structural.count(identity) != 0) {
      parsed.error = "manifest_duplicate_identity";
      return parsed;
    }
    parsed.structural[identity] = line;
    parsed.summaries[identity] =
      nativeProjectSyncRecordSummary(fields);
  }
  if (firstLine) {
    parsed.error = "manifest_empty";
    return parsed;
  }

  std::ostringstream config;
  config << "VSHOOK_PROJECT_SYNC_CONFIG\t1";
  for (const auto& entry : parsed.configs) {
    const std::vector<std::string> fields =
      nativeProjectSyncTsvFields(entry.second);
    config << "\nDATA\tGLOBAL\t" << fields[1]
           << '\t' << fields[2] << '\t' << fields[3];
  }
  parsed.configSnapshot = config.str();
  parsed.valid = true;
  return parsed;
}

static std::string nativeProjectSyncCategoryForIdentity(
  const std::string& identity)
{
  if (identity.rfind("TRACK\t", 0) == 0) return "tracks";
  if (identity.rfind("ITEM\t", 0) == 0) return "files";
  if (identity.rfind("FX\t", 0) == 0) return "plugins";
  if (identity.rfind("REGION\t", 0) == 0) return "regions";
  if (identity.rfind("MARKER\t", 0) == 0) return "markers";
  if (identity.rfind("TEMPO\t", 0) == 0) return "tempoMarkers";
  if (identity.rfind("CONFIG\t", 0) == 0) return "configs";
  return "project";
}

static std::string nativeProjectSyncIdentityLabel(
  const std::string& identity)
{
  const size_t firstTab = identity.find('\t');
  return firstTab == std::string::npos
    ? identity : identity.substr(firstTab + 1);
}

static std::string nativeProjectSyncCategoryLabel(
  const std::string& category)
{
  if (category == "tracks") return "Pistas";
  if (category == "files") return "Arquivos/itens";
  if (category == "plugins") return "Plugins";
  if (category == "regions") return "Regioes";
  if (category == "markers") return "Marcadores";
  if (category == "tempoMarkers") return "Marcadores de tempo";
  if (category == "configs") return "Configuracoes";
  return "Projeto";
}

static void nativeProjectSyncBuildComparePresentation(
  NativeProjectSyncCompareResult& result)
{
  std::ostringstream message;
  if (!result.valid) {
    message << "Project Sync nao conseguiu validar os projetos.";
  } else if (result.structuralDifferenceCount > 0) {
    message << "Existem diferencas que alteram a execucao entre o PC A e o PC B.";
  } else if (result.configDifferenceCount > 0) {
    message << (result.configApplied
      ? "As configuracoes diferentes foram copiadas do PC A para o PC B."
      : "Foram encontradas configuracoes diferentes entre os computadores.");
  } else {
    message << "Projetos conferidos. O PC B esta pronto para receber o PC A.";
  }
  message << "\n\nPC A (mestre) x PC B (escravo)";
  for (const std::string& category : {
         std::string("tracks"), std::string("files"),
         std::string("plugins"),
         std::string("regions"), std::string("markers"),
         std::string("tempoMarkers"), std::string("configs"),
         std::string("project")}) {
    const auto found = result.categoryCounts.find(category);
    if (found != result.categoryCounts.end() && found->second > 0) {
      message << "\n" << nativeProjectSyncCategoryLabel(category)
              << ": " << found->second;
    }
  }
  const size_t visible = std::min<size_t>(
    result.differences.size(), 18);
  if (visible > 0) message << "\n";
  for (size_t index = 0; index < visible; ++index) {
    const NativeProjectSyncDifference& difference =
      result.differences[index];
    message << "\n- ";
    if (difference.kind == "missing_on_secondary") {
      message << "Falta no PC B: " << difference.primary;
    } else if (difference.kind == "extra_on_secondary") {
      message << "So existe no PC B: " << difference.secondary;
    } else {
      message << "Diferente: "
              << (!difference.primary.empty()
                    ? difference.primary : difference.secondary);
    }
  }
  if (result.truncated || result.differences.size() > visible) {
    message << "\n\nA lista completa permanece no diagnostico do Project Sync.";
  }
  result.modalMessage = message.str();

  std::ostringstream json;
  json << "{\"schemaVersion\":1,\"ready\":"
       << (result.ready ? "true" : "false")
       << ",\"configApplied\":"
       << (result.configApplied ? "true" : "false")
       << ",\"differenceCount\":" << result.differenceCount
       << ",\"structuralDifferenceCount\":"
       << result.structuralDifferenceCount
       << ",\"configDifferenceCount\":"
       << result.configDifferenceCount
       << ",\"truncated\":"
       << (result.truncated ? "true" : "false")
       << ",\"summary\":{";
  bool first = true;
  for (const auto& entry : result.categoryCounts) {
    if (!first) json << ',';
    first = false;
    json << nativeJsonString(entry.first) << ':' << entry.second;
  }
  json << "},\"message\":" << nativeJsonString(result.modalMessage)
       << ",\"differences\":[";
  first = true;
  for (const NativeProjectSyncDifference& difference :
       result.differences) {
    if (!first) json << ',';
    first = false;
    json << "{\"category\":"
         << nativeJsonString(difference.category)
         << ",\"kind\":" << nativeJsonString(difference.kind)
         << ",\"id\":" << nativeJsonString(difference.id)
         << ",\"primary\":"
         << nativeJsonString(difference.primary)
         << ",\"secondary\":"
         << nativeJsonString(difference.secondary) << '}';
  }
  json << "]}";
  result.diffJson = json.str();
}

static NativeProjectSyncCompareResult nativeProjectSyncErrorResult(
  const std::string& detail)
{
  NativeProjectSyncCompareResult result;
  result.valid = false;
  result.ready = false;
  result.structuralDifferenceCount = 1;
  result.differenceCount = 1;
  result.categoryCounts["project"] = 1;
  result.differences.push_back({
    "project", "invalid", "manifest", detail, ""});
  nativeProjectSyncBuildComparePresentation(result);
  return result;
}

static NativeProjectSyncCompareResult nativeProjectSyncCompareManifests(
  const std::string& primaryManifest,
  const std::string& secondaryManifest)
{
  const NativeProjectSyncParsedManifest primary =
    nativeProjectSyncParseManifest(primaryManifest);
  const NativeProjectSyncParsedManifest secondary =
    nativeProjectSyncParseManifest(secondaryManifest);
  if (!primary.valid) {
    return nativeProjectSyncErrorResult(
      "Manifesto do PC A invalido: " + primary.error);
  }
  if (!secondary.valid) {
    return nativeProjectSyncErrorResult(
      "Manifesto do PC B invalido: " + secondary.error);
  }

  NativeProjectSyncCompareResult result;
  result.valid = true;
  result.remoteConfigSnapshot = primary.configSnapshot;
  constexpr size_t kDifferenceLimit = 200;
  const auto collect = [&](const std::map<std::string, std::string>& left,
                           const std::map<std::string, std::string>& right,
                           bool config) {
    std::set<std::string> identities;
    for (const auto& entry : left) identities.insert(entry.first);
    for (const auto& entry : right) identities.insert(entry.first);
    for (const std::string& identity : identities) {
      const auto leftValue = left.find(identity);
      const auto rightValue = right.find(identity);
      const bool leftExists = leftValue != left.end();
      const bool rightExists = rightValue != right.end();
      if (leftExists && rightExists &&
          leftValue->second == rightValue->second) {
        continue;
      }
      NativeProjectSyncRecordComparison recordComparison;
      if (!config && leftExists && rightExists &&
          identity.rfind("TRACK\t", 0) == 0) {
        recordComparison = nativeProjectSyncCompareTrackRecords(
          leftValue->second, rightValue->second);
        if (recordComparison.recognized && recordComparison.equivalent) {
          continue;
        }
      } else if (!config && leftExists && rightExists &&
                 identity.rfind("ITEM\t", 0) == 0) {
        recordComparison = nativeProjectSyncCompareItemRecords(
          leftValue->second, rightValue->second);
        if (recordComparison.recognized && recordComparison.equivalent) {
          continue;
        }
      } else if (!config && leftExists && rightExists &&
                 identity.rfind("TEMPO\t", 0) == 0) {
        recordComparison = nativeProjectSyncCompareTempoRecords(
          leftValue->second, rightValue->second);
        if (recordComparison.recognized && recordComparison.equivalent) {
          continue;
        }
      }
      const std::string category =
        nativeProjectSyncCategoryForIdentity(identity);
      ++result.differenceCount;
      ++result.categoryCounts[category];
      if (config) ++result.configDifferenceCount;
      else ++result.structuralDifferenceCount;
      if (result.differences.size() >= kDifferenceLimit) {
        result.truncated = true;
        continue;
      }
      NativeProjectSyncDifference difference;
      difference.category = category;
      difference.id = nativeProjectSyncIdentityLabel(identity);
      difference.kind = !rightExists
        ? "missing_on_secondary"
        : (!leftExists ? "extra_on_secondary" : "changed");
      if (leftExists) {
        if (recordComparison.recognized &&
            !recordComparison.primarySummary.empty()) {
          difference.primary = recordComparison.primarySummary;
        } else {
          const auto summary = primary.summaries.find(identity);
          difference.primary = summary != primary.summaries.end()
            ? summary->second : difference.id;
        }
      }
      if (rightExists) {
        if (recordComparison.recognized &&
            !recordComparison.secondarySummary.empty()) {
          difference.secondary = recordComparison.secondarySummary;
        } else {
          const auto summary = secondary.summaries.find(identity);
          difference.secondary = summary != secondary.summaries.end()
            ? summary->second : difference.id;
        }
      }
      result.differences.push_back(std::move(difference));
    }
  };
  collect(primary.structural, secondary.structural, false);
  collect(primary.configs, secondary.configs, true);
  result.ready = result.structuralDifferenceCount == 0;
  nativeProjectSyncBuildComparePresentation(result);
  return result;
}

static std::vector<std::string> nativeProjectSyncJsonObjectArray(
  const std::string& arrayJson,
  size_t maximumObjects = 200)
{
  std::vector<std::string> objects;
  if (arrayJson.size() < 2 || arrayJson.front() != '[') return objects;
  bool inString = false;
  bool escaped = false;
  int depth = 0;
  size_t objectStart = std::string::npos;
  for (size_t index = 1; index + 1 < arrayJson.size(); ++index) {
    const char value = arrayJson[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (value == '\\') escaped = true;
      else if (value == '"') inString = false;
      continue;
    }
    if (value == '"') {
      inString = true;
    } else if (value == '{') {
      if (depth++ == 0) objectStart = index;
    } else if (value == '}' && depth > 0) {
      if (--depth == 0 && objectStart != std::string::npos) {
        objects.push_back(arrayJson.substr(
          objectStart, index - objectStart + 1));
        objectStart = std::string::npos;
        if (objects.size() >= maximumObjects) break;
      }
    }
  }
  return objects;
}

static void nativeProjectSyncResetDiffModalState()
{
  g_nativeProjectSyncDiffModalDifferences.clear();
  g_nativeProjectSyncDiffModalCategoryCounts.clear();
  g_nativeProjectSyncDiffModalHeadline.clear();
  g_nativeProjectSyncDiffModalDifferenceCount = 0;
  g_nativeProjectSyncDiffModalStructuralCount = 0;
  g_nativeProjectSyncDiffModalConfigCount = 0;
  g_nativeProjectSyncDiffModalReady = false;
  g_nativeProjectSyncDiffModalConfigApplied = false;
  g_nativeProjectSyncDiffModalTruncated = false;
  g_nativeProjectSyncDiffModalScrollPixels = 0;
  g_nativeProjectSyncDiffModalMaxScrollPixels = 0;
  g_nativeProjectSyncDiffModalScrollTrackRect = RECT{0, 0, 0, 0};
  g_nativeProjectSyncDiffModalScrollThumbRect = RECT{0, 0, 0, 0};
  g_nativeProjectSyncDiffModalScrollbarDragging = false;
  g_nativeProjectSyncDiffModalScrollbarDragOffsetY = 0;
  g_nativeProjectSyncDiffModalDiagnosticKey.clear();
}

static void nativeProjectSyncSetDiffModalScrollFromPoint(int pointY)
{
  if (g_nativeProjectSyncDiffModalMaxScrollPixels <= 0) return;
  const int trackHeight = std::max(1, static_cast<int>(
    g_nativeProjectSyncDiffModalScrollTrackRect.bottom -
    g_nativeProjectSyncDiffModalScrollTrackRect.top));
  const int thumbHeight = std::max(1, static_cast<int>(
    g_nativeProjectSyncDiffModalScrollThumbRect.bottom -
    g_nativeProjectSyncDiffModalScrollThumbRect.top));
  const int travel = std::max(1, trackHeight - thumbHeight);
  const int thumbTop = std::max(
    static_cast<int>(g_nativeProjectSyncDiffModalScrollTrackRect.top),
    std::min(
      static_cast<int>(
        g_nativeProjectSyncDiffModalScrollTrackRect.bottom) - thumbHeight,
      pointY - g_nativeProjectSyncDiffModalScrollbarDragOffsetY));
  const double ratio = static_cast<double>(thumbTop -
    g_nativeProjectSyncDiffModalScrollTrackRect.top) / travel;
  g_nativeProjectSyncDiffModalScrollPixels = std::max(0,
    std::min(g_nativeProjectSyncDiffModalMaxScrollPixels,
      static_cast<int>(std::lround(ratio *
        g_nativeProjectSyncDiffModalMaxScrollPixels))));
}

static bool nativeProjectSyncBeginDiffModalScrollbarDrag(
  HWND hwnd,
  const POINT& point)
{
  if (!hwnd ||
      g_nativeMainModalKind != NativeMainModalKind::ProjectSyncDiff ||
      g_nativeProjectSyncDiffModalMaxScrollPixels <= 0 ||
      !PtInRect(&g_nativeProjectSyncDiffModalScrollTrackRect, point)) {
    return false;
  }
  const int thumbHeight = std::max(1, static_cast<int>(
    g_nativeProjectSyncDiffModalScrollThumbRect.bottom -
    g_nativeProjectSyncDiffModalScrollThumbRect.top));
  g_nativeProjectSyncDiffModalScrollbarDragOffsetY =
    PtInRect(&g_nativeProjectSyncDiffModalScrollThumbRect, point)
      ? point.y - g_nativeProjectSyncDiffModalScrollThumbRect.top
      : thumbHeight / 2;
  g_nativeProjectSyncDiffModalScrollbarDragging = true;
  SetCapture(hwnd);
  nativeProjectSyncSetDiffModalScrollFromPoint(point.y);
  return true;
}

static void nativeProjectSyncShowDiffModal(
  const std::string& diffJson)
{
  std::string requestId;
  bool applyBusy = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    requestId = g_nativeProjectSyncPreflight.requestId;
    const std::string applyState = nativeLower(nativeTrim(
      g_nativeProjectSyncApply.state));
    applyBusy = applyState == "requested" ||
      applyState == "requesting" || applyState == "downloading" ||
      applyState == "verifying" || applyState == "validating" ||
      applyState == "ready_to_open" ||
      applyState == "ready_to_apply" || applyState == "applying" ||
      applyState == "apply_started";
  }
  if (g_nativeMainModalKind == NativeMainModalKind::ProjectSyncDiff &&
      applyBusy) {
    // Durante a transferencia/validacao, diagnosticos repetidos do relay nao
    // podem substituir a tela AGUARDE pela lista de diferencas. A conferencia
    // original permanece congelada ate sucesso ou erro terminal.
    if (nativeAppActivePanelIsOpen()) {
      InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
    }
    return;
  }
  const std::string diagnosticKey = requestId + ":" +
    std::to_string(diffJson.size()) + ":" +
    nativeProjectSyncHashText(diffJson);
  if (g_nativeMainModalKind == NativeMainModalKind::ProjectSyncDiff &&
      !g_nativeProjectSyncDiffModalDiagnosticKey.empty() &&
      g_nativeProjectSyncDiffModalDiagnosticKey == diagnosticKey) {
    // Não reabre nem reparsa o mesmo diagnóstico: preserva scroll, captura da
    // barra e posição visual durante a rolagem contínua no Windows.
    if (nativeAppActivePanelIsOpen()) {
      InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
    }
    return;
  }
  nativeProjectSyncResetDiffModalState();
  g_nativeProjectSyncDiffModalDiagnosticKey = diagnosticKey;
  g_nativeProjectSyncDiffModalReady = nativeJsonBoolValue(
    diffJson, "ready", false);
  g_nativeProjectSyncDiffModalConfigApplied = nativeJsonBoolValue(
    diffJson, "configApplied", false);
  g_nativeProjectSyncDiffModalDifferenceCount = std::max<int>(0,
    static_cast<int>(nativeJsonInt64(
      diffJson, "differenceCount", 0)));
  g_nativeProjectSyncDiffModalStructuralCount = std::max<int>(0,
    static_cast<int>(nativeJsonInt64(
      diffJson, "structuralDifferenceCount", 0)));
  g_nativeProjectSyncDiffModalConfigCount = std::max<int>(0,
    static_cast<int>(nativeJsonInt64(
      diffJson, "configDifferenceCount", 0)));
  g_nativeProjectSyncDiffModalTruncated = nativeJsonBoolValue(
    diffJson, "truncated", false);

  const std::string summaryJson = nativeTrim(
    nativeJsonExtractRawValue(diffJson, "summary"));
  for (const std::string& category : {
         std::string("tracks"), std::string("files"),
         std::string("plugins"), std::string("regions"),
         std::string("markers"), std::string("tempoMarkers"),
         std::string("configs"), std::string("project")}) {
    const int count = std::max<int>(0, static_cast<int>(
      nativeJsonInt64(summaryJson, category.c_str(), 0)));
    if (count > 0) {
      g_nativeProjectSyncDiffModalCategoryCounts[category] = count;
    }
  }

  const std::string differencesJson = nativeTrim(
    nativeJsonExtractRawValue(diffJson, "differences"));
  for (const std::string& object :
       nativeProjectSyncJsonObjectArray(differencesJson)) {
    NativeProjectSyncDifference difference;
    difference.category = nativeTrim(
      nativeJsonExtractString(object, "category"));
    difference.kind = nativeTrim(
      nativeJsonExtractString(object, "kind"));
    difference.id = nativeTrim(
      nativeJsonExtractString(object, "id"));
    difference.primary = nativeTrim(
      nativeJsonExtractString(object, "primary"));
    difference.secondary = nativeTrim(
      nativeJsonExtractString(object, "secondary"));
    if (difference.category.empty()) difference.category = "project";
    if (difference.id.empty() && difference.primary.empty() &&
        difference.secondary.empty()) {
      continue;
    }
    g_nativeProjectSyncDiffModalDifferences.push_back(
      std::move(difference));
  }

  // Hook Centers mais antigas podem omitir o objeto summary. Reconstroi os
  // totais por categoria sem perder a lista detalhada recebida.
  if (g_nativeProjectSyncDiffModalCategoryCounts.empty()) {
    for (const auto& difference :
         g_nativeProjectSyncDiffModalDifferences) {
      ++g_nativeProjectSyncDiffModalCategoryCounts[
        difference.category];
    }
  }
  if (g_nativeProjectSyncDiffModalDifferenceCount == 0) {
    g_nativeProjectSyncDiffModalDifferenceCount = static_cast<int>(
      g_nativeProjectSyncDiffModalDifferences.size());
  }

  std::string message = nativeJsonExtractString(diffJson, "message");
  const size_t detailsStart = message.find("\n\nPC A");
  if (detailsStart != std::string::npos) {
    message.erase(detailsStart);
  }
  g_nativeProjectSyncDiffModalHeadline = nativeTrim(message);
  if (g_nativeProjectSyncDiffModalHeadline.empty()) {
    if (g_nativeProjectSyncDiffModalStructuralCount > 0) {
      g_nativeProjectSyncDiffModalHeadline =
        "Existem diferencas que alteram a execucao entre o PC A e o PC B.";
    } else if (g_nativeProjectSyncDiffModalConfigCount > 0) {
      g_nativeProjectSyncDiffModalHeadline =
        g_nativeProjectSyncDiffModalConfigApplied
          ? "As configuracoes do PC A foram copiadas para o PC B."
          : "Existem configuracoes diferentes entre os computadores.";
    } else {
      g_nativeProjectSyncDiffModalHeadline =
        "Project Sync conferiu o PC A e o PC B.";
    }
  }

  if (!nativeAppActivePanelIsOpen()) nativeOpenAppActivePanel();
  g_nativeMainModalKind = NativeMainModalKind::ProjectSyncDiff;
  if (nativeAppActivePanelIsOpen()) {
    InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
  }
}

static void nativeProjectSyncRefreshManifestOnMainThread(bool force);

static void nativeProjectSyncOpenConferenceFromConfig()
{
  std::string role;
  std::string remoteManifest;
  std::string remoteRevision;
  std::string requestId;
  bool applyBusy = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    role = g_nativeTimecodeLanProjectSyncRole;
    remoteManifest = g_nativeProjectSyncPreflight.remoteManifest;
    remoteRevision =
      g_nativeProjectSyncPreflight.remoteManifestRevision;
    requestId = g_nativeProjectSyncPreflight.requestId;
    const std::string state = nativeLower(nativeTrim(
      g_nativeProjectSyncApply.state));
    applyBusy = state == "requested" || state == "requesting" ||
      state == "downloading" || state == "verifying" ||
      state == "validating" || state == "ready_to_open" ||
      state == "ready_to_apply" || state == "applying" ||
      state == "apply_started";
  }

  // No PC B, abrir manualmente Conferencia/Progresso fora de uma transferencia
  // significa conferir novamente o projeto atual contra o manifesto do PC A.
  // Isso captura inclusive alteracoes feitas diretamente no escravo depois do
  // pareamento, sem fazer a janela reaparecer sozinha.
  if (!applyBusy && role == "secondary" && !remoteManifest.empty() &&
      nativeProjectSyncRequestIdIsValid(requestId)) {
    nativeProjectSyncRefreshManifestOnMainThread(true);
    std::string localManifest;
    {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      localManifest = g_nativeProjectSyncPreflight.manifest;
    }
    if (!localManifest.empty()) {
      NativeProjectSyncCompareResult result =
        nativeProjectSyncCompareManifests(remoteManifest, localManifest);
      nativeProjectSyncBuildComparePresentation(result);
      {
        std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
        g_nativeProjectSyncPreflight.ready = result.ready;
        g_nativeProjectSyncPreflight.hasResult = true;
        g_nativeProjectSyncPreflight.diff = result.diffJson;
        g_nativeProjectSyncPreflight.remoteManifestRevision =
          remoteRevision;
      }
    }
  }

  std::string diffJson;
  bool conferenceAvailable = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    conferenceAvailable =
      g_nativeTimecodeLanMode == "project_sync" &&
      g_nativeProjectSyncPreflight.hasResult &&
      !g_nativeProjectSyncPreflight.requestId.empty();
    if (conferenceAvailable) {
      diffJson = g_nativeProjectSyncPreflight.diff;
    }
  }
  if (conferenceAvailable && !diffJson.empty()) {
    nativeProjectSyncShowDiffModal(diffJson);
    return;
  }
  nativeUiShowTemporaryPopup(
    "NENHUMA CONFERENCIA OU TRANSFERENCIA DO PROJECT SYNC",
    2.0);
}

static void nativeProjectSyncRefreshManifestOnMainThread(bool force)
{
  std::string mode;
  std::string role;
  bool peerConnected = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    mode = g_nativeTimecodeLanMode;
    role = g_nativeTimecodeLanProjectSyncRole;
    peerConnected = g_nativeTimecodeLanPeerConnected;
  }
  if (mode != "project_sync" ||
      (role != "primary" && role != "secondary")) {
    g_nativeProjectSyncLastManifestRefresh =
      std::chrono::steady_clock::time_point{};
    return;
  }

  const auto now = std::chrono::steady_clock::now();
  const int refreshIntervalMs = peerConnected ? 200 : 500;
  if (!force &&
      g_nativeProjectSyncLastManifestRefresh.time_since_epoch().count() != 0 &&
      std::chrono::duration_cast<std::chrono::milliseconds>(
        now - g_nativeProjectSyncLastManifestRefresh).count() <
          refreshIntervalMs) {
    return;
  }
  g_nativeProjectSyncLastManifestRefresh = now;

  ReaProject* project = getCurrentProject(nullptr, 0);
  const std::string projectSignature = getCurrentProjectSignature();
  const int changeCount = project && GetProjectStateChangeCount_ptr
    ? GetProjectStateChangeCount_ptr(project) : -1;
  const bool lightweightRuntimeMutation = !force && project &&
    g_nativeLightweightMutationProject == project &&
    g_nativeLightweightMutationChangeCount == changeCount;
  const bool rebuildStructural = force ||
    project != g_nativeProjectSyncManifestProject ||
    projectSignature != g_nativeProjectSyncManifestProjectSignature ||
    (!lightweightRuntimeMutation &&
      changeCount != g_nativeProjectSyncManifestChangeCount) ||
    g_nativeProjectSyncStructuralManifest.empty();
  if (rebuildStructural) {
    g_nativeProjectSyncStructuralManifest =
      nativeProjectSyncBuildStructuralManifest(project);
    g_nativeProjectSyncManifestProject = project;
    g_nativeProjectSyncManifestChangeCount = changeCount;
    g_nativeProjectSyncManifestProjectSignature = projectSignature;
  } else if (lightweightRuntimeMutation) {
    // Repeat, time selection e volumes transitórios do Multiloops não alteram
    // a estrutura comparada no preflight. Apenas absorve a nova revisão.
    g_nativeProjectSyncManifestProject = project;
    g_nativeProjectSyncManifestChangeCount = changeCount;
    g_nativeProjectSyncManifestProjectSignature = projectSignature;
  }
  const std::string configSnapshot =
    nativeProjectSyncBuildConfigSnapshot();
  const std::string configRevision =
    nativeProjectSyncHashText(configSnapshot);
  const std::string manifest = nativeProjectSyncMergeManifestAndConfig(
    g_nativeProjectSyncStructuralManifest, configSnapshot);
  const std::string manifestRevision =
    nativeProjectSyncHashText(manifest);
  const std::string structuralManifestRevision =
    nativeProjectSyncHashText(g_nativeProjectSyncStructuralManifest);
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncPreflight.manifest = manifest;
    g_nativeProjectSyncPreflight.manifestRevision = manifestRevision;
    g_nativeProjectSyncPreflight.structuralManifestRevision =
      structuralManifestRevision;
    g_nativeProjectSyncPreflight.configSnapshot = configSnapshot;
    g_nativeProjectSyncPreflight.configRevision = configRevision;
  }

  const bool publish = role == "primary" && peerConnected &&
    (g_nativeProjectSyncPublishInitialConfig ||
     configRevision != g_nativeProjectSyncLastPublishedConfigRevision);
  if (!publish) return;
  std::ostringstream command;
  command << "{\"type\":\"project_sync_config_snapshot\",";
  command << "\"schemaVersion\":1,\"revision\":"
          << nativeJsonString(configRevision)
          << ",\"snapshot\":"
          << nativeJsonString(configSnapshot) << '}';
  const std::string commandBody = command.str();
  if (commandBody.size() <= 500 * 1024) {
    nativeTimecodeLanRecordCommand(commandBody);
    g_nativeProjectSyncLastPublishedConfigRevision = configRevision;
    g_nativeProjectSyncPublishInitialConfig = false;
  }
}

static void nativeProjectSyncStorePreflightResult(
  const std::string& requestId,
  bool ready,
  const std::string& diff,
  const std::string& remoteManifestRevision,
  const std::string& remoteManifest = std::string(),
  const std::string& remoteConfigSnapshot = std::string())
{
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  const std::string applyState = nativeLower(nativeTrim(
    g_nativeProjectSyncApply.state));
  const bool applyBusy = applyState == "requested" ||
    applyState == "requesting" || applyState == "downloading" ||
    applyState == "verifying" || applyState == "validating" ||
    applyState == "ready_to_open" ||
    applyState == "ready_to_apply" || applyState == "applying" ||
    applyState == "apply_started";
  // Um novo pareamento substitui qualquer estado visual órfão da sessão
  // anterior. Nunca interrompe um worker/pending commit ainda legítimo.
  if (!requestId.empty() &&
      g_nativeProjectSyncApply.requestId != requestId &&
      !applyBusy &&
      !g_nativeProjectSyncBundleWorkerRunning.load() &&
      !g_nativeProjectSyncPendingOpen.ready) {
    g_nativeProjectSyncApply = NativeProjectSyncApplyState{};
  }
  g_nativeProjectSyncPreflight.requestId = requestId;
  g_nativeProjectSyncPreflight.ready = ready;
  g_nativeProjectSyncPreflight.hasResult = true;
  g_nativeProjectSyncPreflight.diff = diff;
  g_nativeProjectSyncPreflight.remoteManifestRevision =
    remoteManifestRevision;
  g_nativeProjectSyncPreflight.remoteManifest = remoteManifest;
  g_nativeProjectSyncPreflight.remoteConfigSnapshot =
    remoteConfigSnapshot;
  g_nativeProjectSyncPreflight.remoteConfigRevision =
    remoteConfigSnapshot.empty()
      ? std::string()
      : nativeProjectSyncHashText(remoteConfigSnapshot);
}

struct NativeProjectSyncSha256 {
  std::array<uint32_t, 8> state{{
    0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
    0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u}};
  std::array<unsigned char, 64> buffer{};
  uint64_t bitCount = 0;
  size_t buffered = 0;

  static uint32_t rotateRight(uint32_t value, int count)
  {
    return (value >> count) | (value << (32 - count));
  }

  void transform(const unsigned char* block)
  {
    static const uint32_t constants[64] = {
      0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u,
      0x3956c25bu, 0x59f111f1u, 0x923f82a4u, 0xab1c5ed5u,
      0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
      0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u,
      0xe49b69c1u, 0xefbe4786u, 0x0fc19dc6u, 0x240ca1ccu,
      0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
      0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u,
      0xc6e00bf3u, 0xd5a79147u, 0x06ca6351u, 0x14292967u,
      0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
      0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u,
      0xa2bfe8a1u, 0xa81a664bu, 0xc24b8b70u, 0xc76c51a3u,
      0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
      0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u,
      0x391c0cb3u, 0x4ed8aa4au, 0x5b9cca4fu, 0x682e6ff3u,
      0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
      0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u};
    uint32_t words[64]{};
    for (int index = 0; index < 16; ++index) {
      words[index] =
        (static_cast<uint32_t>(block[index * 4]) << 24) |
        (static_cast<uint32_t>(block[index * 4 + 1]) << 16) |
        (static_cast<uint32_t>(block[index * 4 + 2]) << 8) |
        static_cast<uint32_t>(block[index * 4 + 3]);
    }
    for (int index = 16; index < 64; ++index) {
      const uint32_t s0 = rotateRight(words[index - 15], 7) ^
        rotateRight(words[index - 15], 18) ^
        (words[index - 15] >> 3);
      const uint32_t s1 = rotateRight(words[index - 2], 17) ^
        rotateRight(words[index - 2], 19) ^
        (words[index - 2] >> 10);
      words[index] = words[index - 16] + s0 +
        words[index - 7] + s1;
    }
    uint32_t a = state[0];
    uint32_t b = state[1];
    uint32_t c = state[2];
    uint32_t d = state[3];
    uint32_t e = state[4];
    uint32_t f = state[5];
    uint32_t g = state[6];
    uint32_t h = state[7];
    for (int index = 0; index < 64; ++index) {
      const uint32_t sum1 = rotateRight(e, 6) ^
        rotateRight(e, 11) ^ rotateRight(e, 25);
      const uint32_t choose = (e & f) ^ ((~e) & g);
      const uint32_t temporary1 = h + sum1 + choose +
        constants[index] + words[index];
      const uint32_t sum0 = rotateRight(a, 2) ^
        rotateRight(a, 13) ^ rotateRight(a, 22);
      const uint32_t majority = (a & b) ^ (a & c) ^ (b & c);
      const uint32_t temporary2 = sum0 + majority;
      h = g;
      g = f;
      f = e;
      e = d + temporary1;
      d = c;
      c = b;
      b = a;
      a = temporary1 + temporary2;
    }
    state[0] += a;
    state[1] += b;
    state[2] += c;
    state[3] += d;
    state[4] += e;
    state[5] += f;
    state[6] += g;
    state[7] += h;
  }

  void update(const unsigned char* data, size_t size)
  {
    if (!data || size == 0) return;
    bitCount += static_cast<uint64_t>(size) * 8u;
    while (size > 0) {
      const size_t count = std::min(size, buffer.size() - buffered);
      std::memcpy(buffer.data() + buffered, data, count);
      buffered += count;
      data += count;
      size -= count;
      if (buffered == buffer.size()) {
        transform(buffer.data());
        buffered = 0;
      }
    }
  }

  std::string finish()
  {
    const uint64_t originalBitCount = bitCount;
    const unsigned char marker = 0x80;
    update(&marker, 1);
    const unsigned char zero = 0;
    while (buffered != 56) update(&zero, 1);
    unsigned char length[8]{};
    for (int index = 0; index < 8; ++index) {
      length[7 - index] = static_cast<unsigned char>(
        (originalBitCount >> (index * 8)) & 0xffu);
    }
    update(length, sizeof(length));
    std::ostringstream output;
    output << std::hex << std::setfill('0');
    for (uint32_t value : state) output << std::setw(8) << value;
    return output.str();
  }
};

static std::FILE* nativeProjectSyncOpenFile(
  const std::string& path,
  const char* mode)
{
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty()) return nullptr;
  std::wstring wideMode;
  for (const char* cursor = mode; cursor && *cursor; ++cursor) {
    wideMode.push_back(static_cast<wchar_t>(*cursor));
  }
  return _wfopen(widePath.c_str(), wideMode.c_str());
#else
  return std::fopen(path.c_str(), mode);
#endif
}

static bool nativeProjectSyncDirectoryExists(const std::string& rawPath)
{
  const std::string path = normalizeSlashes(nativeTrim(rawPath));
  if (path.empty()) return false;
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty()) return false;
  const DWORD attributes = GetFileAttributesW(widePath.c_str());
  return attributes != INVALID_FILE_ATTRIBUTES &&
    (attributes & FILE_ATTRIBUTE_DIRECTORY) != 0;
#else
  struct stat info{};
  return stat(path.c_str(), &info) == 0 && S_ISDIR(info.st_mode);
#endif
}

static std::string nativeProjectSyncParentPath(
  const std::string& rawPath);
static bool nativeProjectSyncPathEquals(
  const std::string& leftRaw,
  const std::string& rightRaw);
static bool nativeProjectSyncPathWithin(
  const std::string& rootRaw,
  const std::string& pathRaw);

static bool nativeProjectSyncPathIsLinkOrReparse(
  const std::string& rawPath)
{
  const std::string path = normalizeSlashes(nativeTrim(rawPath));
  if (path.empty()) return false;
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty()) return true;
  const DWORD attributes = GetFileAttributesW(widePath.c_str());
  return attributes != INVALID_FILE_ATTRIBUTES &&
    (attributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0;
#else
  struct stat info{};
  return lstat(path.c_str(), &info) == 0 && S_ISLNK(info.st_mode);
#endif
}

static bool nativeProjectSyncPathChainIsSafe(
  const std::string& rootRaw,
  const std::string& pathRaw)
{
  const std::string root = normalizeSlashes(nativeTrim(rootRaw));
  std::string path = normalizeSlashes(nativeTrim(pathRaw));
  if (!nativeProjectSyncPathWithin(root, path)) return false;
  while (!path.empty()) {
    if ((fileExists(path) || nativeProjectSyncDirectoryExists(path)) &&
        nativeProjectSyncPathIsLinkOrReparse(path)) {
      return false;
    }
    if (nativeProjectSyncPathEquals(path, root)) return true;
    const std::string parent = nativeProjectSyncParentPath(path);
    if (parent.empty() || parent == path) break;
    path = parent;
  }
  return false;
}

static std::string nativeProjectSyncParentPath(
  const std::string& rawPath)
{
  std::string path = normalizeSlashes(nativeTrim(rawPath));
  while (path.size() > 1 && path.back() == '/') path.pop_back();
  const size_t separator = path.find_last_of('/');
  if (separator == std::string::npos) return {};
  if (separator == 0) return "/";
#ifdef _WIN32
  if (separator == 2 && path.size() >= 3 && path[1] == ':') {
    return path.substr(0, 3);
  }
#endif
  return path.substr(0, separator);
}

static bool nativeProjectSyncEnsureDirectory(
  const std::string& rawPath,
  std::string& errorOut)
{
  const std::string path = normalizeSlashes(nativeTrim(rawPath));
  if (path.empty()) {
    errorOut = "Diretorio do bundle vazio.";
    return false;
  }
  if (nativeProjectSyncDirectoryExists(path)) return true;
  const std::string parent = nativeProjectSyncParentPath(path);
  if (!parent.empty() && parent != path &&
      !nativeProjectSyncDirectoryExists(parent) &&
      !nativeProjectSyncEnsureDirectory(parent, errorOut)) {
    return false;
  }
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty() ||
      (!CreateDirectoryW(widePath.c_str(), nullptr) &&
       GetLastError() != ERROR_ALREADY_EXISTS)) {
    errorOut = "Nao foi possivel criar " + path;
    return false;
  }
#else
  if (mkdir(path.c_str(), 0755) != 0 && errno != EEXIST) {
    errorOut = "Nao foi possivel criar " + path;
    return false;
  }
#endif
  if (!nativeProjectSyncDirectoryExists(path)) {
    errorOut = "O caminho do bundle nao e um diretorio: " + path;
    return false;
  }
  return true;
}

static bool nativeProjectSyncRemoveOwnFile(const std::string& path)
{
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  return !widePath.empty() && DeleteFileW(widePath.c_str());
#else
  return std::remove(path.c_str()) == 0;
#endif
}

static bool nativeProjectSyncMoveFile(
  const std::string& source,
  const std::string& destination,
  bool replace)
{
#ifdef _WIN32
  const std::wstring wideSource = utf8ToWide(source);
  const std::wstring wideDestination = utf8ToWide(destination);
  if (wideSource.empty() || wideDestination.empty()) return false;
  DWORD flags = MOVEFILE_WRITE_THROUGH;
  if (replace) flags |= MOVEFILE_REPLACE_EXISTING;
  return MoveFileExW(
    wideSource.c_str(), wideDestination.c_str(), flags) != FALSE;
#else
  if (!replace && fileExists(destination)) return false;
  return std::rename(source.c_str(), destination.c_str()) == 0;
#endif
}

static bool nativeProjectSyncRemoveOwnedTree(
  const std::string& rawRoot,
  const std::string& rawPath)
{
  const std::string root = normalizeSlashes(nativeTrim(rawRoot));
  const std::string path = normalizeSlashes(nativeTrim(rawPath));
  if (root.empty() || path.empty() ||
      !nativeProjectSyncPathWithin(root, path) ||
      nativeProjectSyncPathIsLinkOrReparse(path) ||
      g_nativeProjectSyncBundleWorkerCancel.load()) {
    return false;
  }
#ifdef _WIN32
  const std::wstring widePath = utf8ToWide(path);
  if (widePath.empty()) return false;
  const DWORD attributes = GetFileAttributesW(widePath.c_str());
  if (attributes == INVALID_FILE_ATTRIBUTES) return true;
  if ((attributes & FILE_ATTRIBUTE_DIRECTORY) == 0) {
    return DeleteFileW(widePath.c_str()) != FALSE;
  }
  WIN32_FIND_DATAW data{};
  const std::wstring pattern = widePath + L"\\*";
  HANDLE find = FindFirstFileW(pattern.c_str(), &data);
  if (find != INVALID_HANDLE_VALUE) {
    do {
      const std::wstring name = data.cFileName;
      if (name == L"." || name == L"..") continue;
      if ((data.dwFileAttributes & FILE_ATTRIBUTE_REPARSE_POINT) != 0) {
        FindClose(find);
        return false;
      }
      const int utf8Size = WideCharToMultiByte(CP_UTF8, 0,
        name.c_str(), static_cast<int>(name.size()),
        nullptr, 0, nullptr, nullptr);
      if (utf8Size <= 0) {
        FindClose(find);
        return false;
      }
      std::string childName(static_cast<size_t>(utf8Size), '\0');
      WideCharToMultiByte(CP_UTF8, 0, name.c_str(),
        static_cast<int>(name.size()), childName.data(),
        utf8Size, nullptr, nullptr);
      if (!nativeProjectSyncRemoveOwnedTree(
            root, joinPath(path, childName))) {
        FindClose(find);
        return false;
      }
    } while (FindNextFileW(find, &data));
    FindClose(find);
  }
  return RemoveDirectoryW(widePath.c_str()) != FALSE;
#else
  struct stat info{};
  if (lstat(path.c_str(), &info) != 0) return errno == ENOENT;
  if (S_ISLNK(info.st_mode)) return false;
  if (!S_ISDIR(info.st_mode)) return std::remove(path.c_str()) == 0;
  DIR* directory = opendir(path.c_str());
  if (!directory) return false;
  bool ok = true;
  while (ok) {
    errno = 0;
    dirent* entry = readdir(directory);
    if (!entry) {
      if (errno != 0) ok = false;
      break;
    }
    const std::string name = entry->d_name;
    if (name == "." || name == "..") continue;
    ok = nativeProjectSyncRemoveOwnedTree(
      root, joinPath(path, name));
  }
  closedir(directory);
  return ok && rmdir(path.c_str()) == 0;
#endif
}

static bool nativeProjectSyncSafeRelativePath(
  const std::string& rawPath,
  std::string& normalizedOut)
{
  std::string path = normalizeSlashes(nativeTrim(rawPath));
  while (nativeStartsWith(path, "./")) path.erase(0, 2);
  if (path.empty() || path.front() == '/' ||
      path.find(':') != std::string::npos ||
      path.find('\0') != std::string::npos) {
    return false;
  }
  std::vector<std::string> components;
  size_t start = 0;
  while (start <= path.size()) {
    const size_t slash = path.find('/', start);
    const std::string component = path.substr(start,
      slash == std::string::npos ? std::string::npos : slash - start);
    if (component.empty() || component == "." || component == "..") {
      return false;
    }
    components.push_back(component);
    if (slash == std::string::npos) break;
    start = slash + 1;
  }
  std::ostringstream result;
  for (size_t index = 0; index < components.size(); ++index) {
    if (index) result << '/';
    result << components[index];
  }
  normalizedOut = result.str();
  return !normalizedOut.empty();
}

static std::string nativeProjectSyncSafeFileName(
  const std::string& rawName)
{
  std::string name = nativeProjectSyncBasename(rawName);
  if (name.empty()) name = "media.bin";
  for (char& character : name) {
    const unsigned char value = static_cast<unsigned char>(character);
    if (value < 0x20 || character == '<' || character == '>' ||
        character == ':' || character == '"' || character == '/' ||
        character == '\\' || character == '|' || character == '?' ||
        character == '*') {
      character = '_';
    }
  }
  while (!name.empty() && (name.back() == '.' || name.back() == ' ')) {
    name.pop_back();
  }
  if (name.empty()) name = "media.bin";
  if (name.size() > 120) name.erase(0, name.size() - 120);
  return name;
}

static std::string nativeProjectSyncTimestampForPath()
{
  char value[64] = "";
  const std::time_t now = std::time(nullptr);
  std::tm local{};
#ifdef _WIN32
  localtime_s(&local, &now);
#else
  localtime_r(&now, &local);
#endif
  std::strftime(value, sizeof(value), "%Y%m%d-%H%M%S", &local);
  return value;
}

static void nativeProjectSyncUpdateWorkerProgress(
  bool preparing,
  const std::string& requestId,
  uint64_t bytesDone,
  uint64_t totalBytes,
  int fileIndex,
  int fileCount)
{
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  if (preparing) {
    if (g_nativeProjectSyncBundle.requestId != requestId) return;
    g_nativeProjectSyncBundle.bytesDone = bytesDone;
    g_nativeProjectSyncBundle.totalBytes = totalBytes;
    g_nativeProjectSyncBundle.fileIndex = fileIndex;
    g_nativeProjectSyncBundle.fileCount = fileCount;
  } else {
    if (g_nativeProjectSyncApply.requestId != requestId) return;
    g_nativeProjectSyncApply.bytesDone = bytesDone;
    g_nativeProjectSyncApply.totalBytes = totalBytes;
    g_nativeProjectSyncApply.fileIndex = fileIndex;
    g_nativeProjectSyncApply.fileCount = fileCount;
    // Este timestamp mede inatividade, não duração total. Projetos grandes
    // podem levar bastante tempo, mas cada bloco lido mantém a operação viva.
    g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
  }
  g_nativeForceStateBuild.store(true);
}

static bool nativeProjectSyncCopyAndHashFile(
  const std::string& sourcePath,
  const std::string& destinationPath,
  bool preparing,
  const std::string& requestId,
  uint64_t totalBytes,
  uint64_t& bytesDone,
  int fileIndex,
  int fileCount,
  std::string& sha256Out,
  std::string& errorOut)
{
  std::FILE* source = nativeProjectSyncOpenFile(sourcePath, "rb");
  if (!source) {
    errorOut = "Nao foi possivel ler: " + sourcePath;
    return false;
  }
  std::FILE* destination = nullptr;
  if (!destinationPath.empty()) {
    const std::string parent = nativeProjectSyncParentPath(destinationPath);
    if (!nativeProjectSyncEnsureDirectory(parent, errorOut)) {
      std::fclose(source);
      return false;
    }
    destination = nativeProjectSyncOpenFile(destinationPath, "wb");
    if (!destination) {
      std::fclose(source);
      errorOut = "Nao foi possivel gravar: " + destinationPath;
      return false;
    }
  }
  NativeProjectSyncSha256 sha;
  std::vector<unsigned char> buffer(1024 * 1024);
  bool ok = true;
  while (!g_nativeProjectSyncBundleWorkerCancel.load()) {
    const size_t count = std::fread(
      buffer.data(), 1, buffer.size(), source);
    if (count > 0) {
      sha.update(buffer.data(), count);
      if (destination &&
          std::fwrite(buffer.data(), 1, count, destination) != count) {
        errorOut = "Falha ao gravar um arquivo do bundle.";
        ok = false;
        break;
      }
      bytesDone += static_cast<uint64_t>(count);
      nativeProjectSyncUpdateWorkerProgress(preparing, requestId,
        bytesDone, totalBytes, fileIndex, fileCount);
    }
    if (count < buffer.size()) {
      if (std::ferror(source)) {
        errorOut = "Falha durante a leitura de um arquivo do bundle.";
        ok = false;
      }
      break;
    }
  }
  if (g_nativeProjectSyncBundleWorkerCancel.load()) {
    errorOut = "Operacao cancelada.";
    ok = false;
  }
  if (destination) {
    if (std::fflush(destination) != 0) ok = false;
    std::fclose(destination);
  }
  std::fclose(source);
  if (!ok) {
    if (!destinationPath.empty()) {
      nativeProjectSyncRemoveOwnFile(destinationPath);
    }
    return false;
  }
  sha256Out = sha.finish();
  return true;
}

static bool nativeProjectSyncWriteAndHashText(
  const std::string& path,
  const std::string& value,
  std::string& sha256Out,
  std::string& errorOut)
{
  if (!nativeProjectSyncEnsureDirectory(
        nativeProjectSyncParentPath(path), errorOut)) {
    return false;
  }
  std::FILE* file = nativeProjectSyncOpenFile(path, "wb");
  if (!file) {
    errorOut = "Nao foi possivel gravar: " + path;
    return false;
  }
  const bool written = value.empty() ||
    std::fwrite(value.data(), 1, value.size(), file) == value.size();
  const bool flushed = std::fflush(file) == 0;
  std::fclose(file);
  if (!written || !flushed) {
    nativeProjectSyncRemoveOwnFile(path);
    errorOut = "Falha ao gravar: " + path;
    return false;
  }
  NativeProjectSyncSha256 sha;
  sha.update(reinterpret_cast<const unsigned char*>(value.data()),
    value.size());
  sha256Out = sha.finish();
  return true;
}

static bool nativeProjectSyncReadFileLimited(
  const std::string& path,
  size_t maximumSize,
  std::string& valueOut,
  std::string& errorOut)
{
  const long long size = nativeProjectSyncFileSize(path);
  if (size < 0 || static_cast<unsigned long long>(size) > maximumSize) {
    errorOut = "Arquivo ausente ou maior que o limite seguro: " + path;
    return false;
  }
  std::FILE* file = nativeProjectSyncOpenFile(path, "rb");
  if (!file) {
    errorOut = "Nao foi possivel ler: " + path;
    return false;
  }
  valueOut.resize(static_cast<size_t>(size));
  const bool read = valueOut.empty() ||
    std::fread(valueOut.data(), 1, valueOut.size(), file) == valueOut.size();
  const bool clean = std::ferror(file) == 0;
  std::fclose(file);
  if (!read || !clean) {
    valueOut.clear();
    errorOut = "Falha ao ler: " + path;
    return false;
  }
  return true;
}

static bool nativeProjectSyncCopyFileSimple(
  const std::string& source,
  const std::string& destination,
  std::string& errorOut)
{
  uint64_t done = 0;
  std::string ignoredHash;
  const bool previousCancel =
    g_nativeProjectSyncBundleWorkerCancel.exchange(false);
  const bool copied = nativeProjectSyncCopyAndHashFile(
    source, destination, false, "", 0, done, 0, 0,
    ignoredHash, errorOut);
  g_nativeProjectSyncBundleWorkerCancel.store(previousCancel);
  return copied;
}

struct NativeProjectSyncRppReference {
  size_t valueStart = 0;
  size_t valueEnd = 0;
  std::string sourcePath;
  std::string resolvedPath;
  bool quoted = true;
  std::string itemId;
};

struct NativeProjectSyncDifferencePlan {
  bool scoped = false;
  std::set<std::string> trackIds;
  std::set<std::string> itemIds;
  std::set<std::string> fxTrackIds;
};

static NativeProjectSyncDifferencePlan nativeProjectSyncParseDifferencePlan(
  const std::string& raw)
{
  NativeProjectSyncDifferencePlan plan;
  if (raw.empty() || raw.size() > 128 * 1024) return plan;
  std::istringstream input(raw);
  std::string line;
  while (std::getline(input, line)) {
    if (!line.empty() && line.back() == '\r') line.pop_back();
    const size_t tab = line.find('\t');
    if (tab == std::string::npos) continue;
    const std::string kind = nativeLower(nativeTrim(line.substr(0, tab)));
    const std::string id = nativeLower(nativeTrim(line.substr(tab + 1)));
    if (id.empty() || id.size() > 512 || id.find('\0') != std::string::npos) {
      continue;
    }
    if (kind == "track") plan.trackIds.insert(id);
    else if (kind == "item") plan.itemIds.insert(id);
    else if (kind == "fxtrack") plan.fxTrackIds.insert(id);
  }
  plan.scoped = !plan.trackIds.empty() || !plan.itemIds.empty() ||
    !plan.fxTrackIds.empty();
  return plan;
}

static std::string nativeProjectSyncMergeDifferencePlans(
  const std::string& first,
  const std::string& second)
{
  NativeProjectSyncDifferencePlan merged =
    nativeProjectSyncParseDifferencePlan(first);
  const NativeProjectSyncDifferencePlan incoming =
    nativeProjectSyncParseDifferencePlan(second);
  merged.trackIds.insert(
    incoming.trackIds.begin(), incoming.trackIds.end());
  merged.itemIds.insert(
    incoming.itemIds.begin(), incoming.itemIds.end());
  merged.fxTrackIds.insert(
    incoming.fxTrackIds.begin(), incoming.fxTrackIds.end());
  std::ostringstream output;
  const auto append = [&](const char* kind,
                          const std::set<std::string>& ids) {
    for (const auto& id : ids) {
      if (output.tellp() > 0) output << '\n';
      output << kind << '\t' << id;
    }
  };
  append("TRACK", merged.trackIds);
  append("ITEM", merged.itemIds);
  append("FXTRACK", merged.fxTrackIds);
  std::string result = output.str();
  if (result.size() > 128 * 1024) result.resize(128 * 1024);
  return result;
}

static std::vector<NativeProjectSyncRppReference>
nativeProjectSyncRppReferences(
  const std::string& rpp,
  const std::string& projectDirectory,
  const std::string& mediaDirectory)
{
  std::vector<NativeProjectSyncRppReference> references;
  size_t position = 0;
  while (position < rpp.size()) {
    const size_t lineEnd = rpp.find('\n', position);
    const size_t end = lineEnd == std::string::npos
      ? rpp.size() : lineEnd;
    size_t cursor = position;
    while (cursor < end &&
           (rpp[cursor] == ' ' || rpp[cursor] == '\t')) ++cursor;
    if (cursor + 5 <= end && rpp.compare(cursor, 5, "FILE ") == 0) {
      cursor += 5;
      while (cursor < end &&
             (rpp[cursor] == ' ' || rpp[cursor] == '\t')) ++cursor;
      if (cursor < end && rpp[cursor] == '"') {
        const size_t valueStart = ++cursor;
        bool escaped = false;
        while (cursor < end) {
          const char character = rpp[cursor];
          if (character == '"' && !escaped) break;
          if (character == '\\') escaped = !escaped;
          else escaped = false;
          ++cursor;
        }
        if (cursor < end && cursor > valueStart) {
          std::string sourcePath = rpp.substr(
            valueStart, cursor - valueStart);
          // O RPP armazena barra invertida literalmente; apenas aspas usam
          // escape. Mantemos o texto original para substituir exatamente o
          // intervalo certo e normalizamos somente para resolver no disco.
          const std::string resolvedPath =
            nativeResolveTelepromptMediaPath(sourcePath,
              projectDirectory, mediaDirectory);
          references.push_back({valueStart, cursor,
            sourcePath, normalizeSlashes(resolvedPath), true});
        }
      } else if (cursor < end) {
        const size_t valueStart = cursor;
        while (cursor < end && rpp[cursor] != ' ' &&
               rpp[cursor] != '\t' && rpp[cursor] != '\r') {
          ++cursor;
        }
        if (cursor > valueStart) {
          const std::string sourcePath = rpp.substr(
            valueStart, cursor - valueStart);
          const std::string resolvedPath =
            nativeResolveTelepromptMediaPath(sourcePath,
              projectDirectory, mediaDirectory);
          references.push_back({valueStart, cursor,
            sourcePath, normalizeSlashes(resolvedPath), false});
        }
      }
    }
    if (lineEnd == std::string::npos) break;
    position = lineEnd + 1;
  }

  // Associa cada FILE ao GUID do ITEM que o contem. Isso permite que um
  // bundle incremental calcule/transfira apenas a midia dos itens realmente
  // diferentes, sem sequer abrir os demais arquivos do projeto.
  struct ItemRange {
    size_t start = 0;
    size_t end = 0;
    std::string id;
  };
  std::vector<ItemRange> itemRanges;
  position = 0;
  int depth = 0;
  int itemParentDepth = -1;
  size_t itemStart = std::string::npos;
  while (position < rpp.size()) {
    const size_t lineEnd = rpp.find('\n', position);
    const size_t afterLine = lineEnd == std::string::npos
      ? rpp.size() : lineEnd + 1;
    const std::string trimmed = nativeTrim(
      rpp.substr(position, afterLine - position));
    const bool opens = !trimmed.empty() && trimmed.front() == '<';
    const bool closes = trimmed == ">";
    if (itemStart == std::string::npos && opens &&
        nativeLower(trimmed).rfind("<item", 0) == 0) {
      itemStart = position;
      itemParentDepth = depth;
    }
    if (opens) ++depth;
    if (closes) {
      depth = std::max(0, depth - 1);
      if (itemStart != std::string::npos && depth == itemParentDepth) {
        std::string itemId;
        size_t itemLine = itemStart;
        while (itemLine < afterLine) {
          const size_t itemLineEnd = rpp.find('\n', itemLine);
          const size_t itemEnd = itemLineEnd == std::string::npos
            ? afterLine : std::min(afterLine, itemLineEnd);
          const std::string itemText = nativeTrim(
            rpp.substr(itemLine, itemEnd - itemLine));
          if (nativeLower(itemText).rfind("guid ", 0) == 0) {
            itemId = nativeLower(nativeTrim(itemText.substr(5)));
            break;
          }
          if (itemLineEnd == std::string::npos ||
              itemLineEnd >= afterLine) break;
          itemLine = itemLineEnd + 1;
        }
        itemRanges.push_back({itemStart, afterLine, itemId});
        itemStart = std::string::npos;
        itemParentDepth = -1;
      }
    }
    if (lineEnd == std::string::npos) break;
    position = afterLine;
  }
  size_t rangeIndex = 0;
  for (auto& reference : references) {
    while (rangeIndex < itemRanges.size() &&
           reference.valueStart >= itemRanges[rangeIndex].end) {
      ++rangeIndex;
    }
    if (rangeIndex < itemRanges.size() &&
        reference.valueStart >= itemRanges[rangeIndex].start &&
        reference.valueEnd <= itemRanges[rangeIndex].end) {
      reference.itemId = itemRanges[rangeIndex].id;
    }
  }
  return references;
}

struct NativeProjectSyncBundleFile {
  std::string id;
  std::string relativePath;
  std::string kind;
  uint64_t size = 0;
  std::string sha256;
};

struct NativeProjectSyncLocalReuseFile {
  std::string absolutePath;
  uint64_t size = 0;
  std::string sha256;
};

struct NativeProjectSyncBundleSource {
  std::string id;
  std::string absolutePath;
  uint64_t size = 0;
  std::string sha256;
  double modificationTimeMs = 0.0;
};

struct NativeProjectSyncPrepareInput {
  std::string requestId;
  std::string bundleId;
  std::string projectPath;
  std::string activeProjectPath;
  std::string projectDirectory;
  std::string mediaDirectory;
  std::string projectFileName;
  std::string manifestRevision;
  std::string structuralRevision;
  std::string configSnapshot;
  std::string sourceSessionId;
  std::string resourcePath;
  int projectChangeCount = -1;
  bool automatic = false;
  bool supportsSourceMap = false;
  std::string differencePlan;
};

static void nativeProjectSyncFinishBundleError(
  const std::string& requestId,
  const std::string& error)
{
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  if (g_nativeProjectSyncBundle.requestId == requestId) {
    g_nativeProjectSyncBundle.state = "error";
    g_nativeProjectSyncBundle.error = error.empty()
      ? "Falha ao preparar o bundle." : error;
    g_nativeProjectSyncBundle.descriptorPath.clear();
  }
  if (g_nativeProjectSyncPendingPrepareConfirmation.requestId == requestId) {
    g_nativeProjectSyncPendingPrepareConfirmation =
      NativeProjectSyncPendingPrepareConfirmation{};
  }
  if (g_nativeProjectSyncPendingBundleReady.requestId == requestId) {
    g_nativeProjectSyncPendingBundleReady =
      NativeProjectSyncPendingBundleReady{};
  }
  g_nativeForceStateBuild.store(true);
}

static void nativeProjectSyncPrepareBundleWorker(
  NativeProjectSyncPrepareInput input)
{
  std::string error;
  std::string rpp;
  if (!nativeProjectSyncReadFileLimited(
        input.projectPath, 128u * 1024u * 1024u, rpp, error)) {
    nativeProjectSyncFinishBundleError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  // O arquivo foi lido inteiro, mas o operador ainda pode ter alterado o
  // projeto enquanto o worker fazia a copia. A conferencia final acontece na
  // main thread antes de publicar ready; aqui o change count e preservado no
  // input para aquele commit.
  const std::vector<NativeProjectSyncRppReference> allReferences =
    nativeProjectSyncRppReferences(rpp, input.projectDirectory,
      input.mediaDirectory);
  const NativeProjectSyncDifferencePlan differencePlan =
    nativeProjectSyncParseDifferencePlan(input.differencePlan);
  std::vector<NativeProjectSyncRppReference> references;
  references.reserve(allReferences.size());
  for (const auto& reference : allReferences) {
    if (!differencePlan.scoped ||
        (!reference.itemId.empty() &&
         differencePlan.itemIds.count(
           nativeLower(reference.itemId)) != 0)) {
      references.push_back(reference);
    }
  }
  std::map<std::string, std::string> uniqueSources;
  std::map<std::string, NativeProjectSyncRegularFileStamp> sourceStamps;
  std::map<std::string, std::string> cachedSourceHashes;
  bool useSourceMap = input.supportsSourceMap;
  uint64_t totalBytes = static_cast<uint64_t>(rpp.size()) +
    static_cast<uint64_t>(input.configSnapshot.size());
  for (const auto& reference : references) {
    const std::string key = normalizeSlashes(reference.resolvedPath);
    if (nativeFileExtensionLower(key) == "rpp") {
      nativeProjectSyncFinishBundleError(input.requestId,
        "Este projeto usa um subprojeto RPP. Aplique depois de consolidar "
        "o subprojeto, pois suas dependencias internas ainda nao entram no bundle.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    NativeProjectSyncRegularFileStamp sourceStamp;
    long long legacySize = useSourceMap
      ? -1 : nativeProjectSyncFileSize(key);
    bool sourceReady = false;
    if (useSourceMap &&
        nativeProjectSyncRegularFileStamp(key, sourceStamp)) {
      sourceReady = true;
    } else {
      if (legacySize < 0) legacySize = nativeProjectSyncFileSize(key);
      if (!key.empty() && fileExists(key) && legacySize >= 0) {
        // Um symlink/reparse point (por exemplo OneDrive) nao pode ser servido
        // diretamente com seguranca. Conserva a compatibilidade materializando
        // o bundle legado inteiro, que a Hook Center nova tambem entende.
        useSourceMap = false;
        sourceStamp.size = static_cast<uint64_t>(legacySize);
        sourceReady = true;
      }
    }
    if (!sourceReady) {
      nativeProjectSyncFinishBundleError(input.requestId,
        "Arquivo usado pelo projeto nao foi encontrado" +
          std::string(useSourceMap ? " ou nao e seguro: " : ": ") +
          reference.sourcePath);
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    if (!useSourceMap) {
      sourceStamp.size = static_cast<uint64_t>(legacySize);
    }
    if (uniqueSources.emplace(key, reference.sourcePath).second) {
      sourceStamps.emplace(key, sourceStamp);
    }
  }
  for (const auto& source : uniqueSources) {
    const auto stamp = sourceStamps.find(source.first);
    std::string cachedSha256;
    if (useSourceMap && stamp != sourceStamps.end() &&
        nativeProjectSyncCachedFileHash(
          source.first, stamp->second, cachedSha256)) {
      cachedSourceHashes[source.first] = cachedSha256;
    } else if (stamp != sourceStamps.end()) {
      totalBytes += stamp->second.size;
    }
  }
  if (uniqueSources.size() + 2 > 16384) {
    nativeProjectSyncFinishBundleError(input.requestId,
      "O projeto possui arquivos demais para um unico bundle.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  const std::string resourcePath = input.resourcePath;
  if (resourcePath.empty()) {
    nativeProjectSyncFinishBundleError(input.requestId,
      "A pasta de recursos do REAPER nao esta disponivel.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  const std::string root = joinPath(resourcePath,
    "VS Hook/Project Sync/Exports/" + input.bundleId);
  const std::string exportsRoot = nativeProjectSyncParentPath(root);
  const std::string projectSyncRoot =
    nativeProjectSyncParentPath(exportsRoot);
  if ((nativeProjectSyncDirectoryExists(exportsRoot) &&
       nativeProjectSyncPathIsLinkOrReparse(exportsRoot)) ||
      (nativeProjectSyncDirectoryExists(projectSyncRoot) &&
       nativeProjectSyncPathIsLinkOrReparse(projectSyncRoot)) ||
      nativeProjectSyncDirectoryExists(root) || fileExists(root)) {
    nativeProjectSyncFinishBundleError(input.requestId,
      "A pasta de exportacao do Project Sync nao e segura ou ja existe.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  struct NativeProjectSyncPartialExportGuard {
    std::string root;
    bool keep = false;
    ~NativeProjectSyncPartialExportGuard()
    {
      if (!keep && nativeProjectSyncDirectoryExists(root)) {
        nativeProjectSyncRemoveOwnedTree(root, root);
      }
    }
  } partialExport{root, false};
  const std::string projectRoot = joinPath(root, "project");
  const std::string configRoot = joinPath(root, "config");
  if (!nativeProjectSyncEnsureDirectory(projectRoot, error) ||
      !nativeProjectSyncEnsureDirectory(configRoot, error) ||
      (!useSourceMap &&
       !nativeProjectSyncEnsureDirectory(joinPath(root, "media"), error))) {
    nativeProjectSyncFinishBundleError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  if (!nativeProjectSyncPathChainIsSafe(root, projectRoot) ||
      !nativeProjectSyncPathChainIsSafe(root, configRoot) ||
      (!useSourceMap &&
       !nativeProjectSyncPathChainIsSafe(root, joinPath(root, "media")))) {
    nativeProjectSyncFinishBundleError(input.requestId,
      "A pasta de exportacao do Project Sync nao e segura.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncBundle.requestId == input.requestId) {
      g_nativeProjectSyncBundle.totalBytes = totalBytes;
      g_nativeProjectSyncBundle.fileCount =
        static_cast<int>(uniqueSources.size()) + 2;
    }
  }

  std::vector<NativeProjectSyncBundleFile> files;
  std::vector<NativeProjectSyncBundleSource> localSources;
  std::map<std::string, std::string> sourceToRelative;
  uint64_t bytesDone = 0;
  int fileIndex = 0;
  for (const auto& source : uniqueSources) {
    ++fileIndex;
    const auto expectedStamp = sourceStamps.find(source.first);
    if (expectedStamp == sourceStamps.end()) {
      nativeProjectSyncFinishBundleError(input.requestId,
        "O snapshot perdeu os metadados de uma midia.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    const std::string temporaryPath = useSourceMap
      ? std::string()
      : joinPath(joinPath(root, "media"),
          ".vshook-" + std::to_string(fileIndex) + ".part");
    std::string sha256;
    const auto cachedHash = cachedSourceHashes.find(source.first);
    if (cachedHash != cachedSourceHashes.end()) {
      sha256 = cachedHash->second;
    } else {
      if (!nativeProjectSyncCopyAndHashFile(source.first,
            temporaryPath, true, input.requestId, totalBytes,
            bytesDone, fileIndex,
            static_cast<int>(uniqueSources.size()) + 2,
            sha256, error)) {
        nativeProjectSyncFinishBundleError(input.requestId, error);
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
    }
    NativeProjectSyncRegularFileStamp finalStamp;
    const bool sourceUnchanged = useSourceMap
      ? (nativeProjectSyncRegularFileStamp(source.first, finalStamp) &&
          finalStamp.size == expectedStamp->second.size &&
          finalStamp.modificationToken ==
            expectedStamp->second.modificationToken)
      : (nativeProjectSyncFileSize(source.first) ==
          static_cast<long long>(expectedStamp->second.size));
    if (!sourceUnchanged) {
      nativeProjectSyncFinishBundleError(input.requestId,
        "Uma midia mudou durante a preparacao do Project Sync: " +
          source.second);
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    if (useSourceMap && cachedHash == cachedSourceHashes.end()) {
      nativeProjectSyncRememberFileHash(
        source.first, finalStamp, sha256);
    }
    if (!useSourceMap) finalStamp = expectedStamp->second;
    const std::string relativePath = "media/" +
      sha256.substr(0, 20) + "_" +
      nativeProjectSyncSafeFileName(source.second);
    const std::string fileId =
      "media-" + std::to_string(fileIndex);
    if (!useSourceMap) {
      const std::string finalPath = joinPath(root, relativePath);
      if (!nativeProjectSyncMoveFile(temporaryPath, finalPath, false)) {
        nativeProjectSyncRemoveOwnFile(temporaryPath);
        nativeProjectSyncFinishBundleError(input.requestId,
          "Nao foi possivel finalizar um arquivo do bundle.");
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
    }
    sourceToRelative[source.first] = relativePath;
    files.push_back({fileId, relativePath, "media",
      finalStamp.size, sha256});
    if (useSourceMap) {
      localSources.push_back({fileId, source.first,
        finalStamp.size, sha256, finalStamp.modificationTimeMs});
    }
  }

  std::string portableRpp;
  portableRpp.reserve(rpp.size() + references.size() * 32);
  size_t copiedUntil = 0;
  for (const auto& reference : references) {
    if (reference.valueStart < copiedUntil ||
        reference.valueEnd > rpp.size()) continue;
    portableRpp.append(rpp, copiedUntil,
      reference.valueStart - copiedUntil);
    const auto mapped = sourceToRelative.find(
      normalizeSlashes(reference.resolvedPath));
    if (mapped == sourceToRelative.end()) {
      nativeProjectSyncFinishBundleError(input.requestId,
        "O snapshot nao conseguiu mapear toda a midia.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    const std::string portablePath = "../" + mapped->second;
    if (reference.quoted) {
      portableRpp += portablePath;
    } else {
      portableRpp += '"' + portablePath + '"';
    }
    copiedUntil = reference.valueEnd;
  }
  portableRpp.append(rpp, copiedUntil, std::string::npos);

  std::string projectRelative = "project/" +
    nativeProjectSyncSafeFileName(input.projectFileName);
  if (nativeFileExtensionLower(projectRelative) != "rpp") {
    projectRelative += ".rpp";
  }
  const std::string projectSnapshotPath = joinPath(root, projectRelative);
  std::string projectSha256;
  if (!nativeProjectSyncWriteAndHashText(projectSnapshotPath,
        portableRpp, projectSha256, error)) {
    nativeProjectSyncFinishBundleError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  bytesDone += static_cast<uint64_t>(portableRpp.size());
  files.push_back({"project", projectRelative, "project",
    static_cast<uint64_t>(portableRpp.size()), projectSha256});
  nativeProjectSyncUpdateWorkerProgress(true, input.requestId,
    bytesDone, totalBytes, ++fileIndex,
    static_cast<int>(uniqueSources.size()) + 2);

  const std::string configRelative =
    "config/project-sync-config.tsv";
  const std::string configPath = joinPath(root, configRelative);
  std::string configSha256;
  if (!nativeProjectSyncWriteAndHashText(configPath,
        input.configSnapshot, configSha256, error)) {
    nativeProjectSyncFinishBundleError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  bytesDone += static_cast<uint64_t>(input.configSnapshot.size());
  files.push_back({"config", configRelative, "config",
    static_cast<uint64_t>(input.configSnapshot.size()), configSha256});
  nativeProjectSyncUpdateWorkerProgress(true, input.requestId,
    bytesDone, totalBytes, ++fileIndex,
    static_cast<int>(uniqueSources.size()) + 2);

  std::ostringstream descriptor;
  descriptor << "{\"schemaVersion\":1,\"bundleId\":"
    << nativeJsonString(input.bundleId)
    << ",\"requestId\":" << nativeJsonString(input.requestId)
    << ",\"sourceSessionId\":"
    << nativeJsonString(input.sourceSessionId)
    << ",\"sourceManifestRevision\":"
    << nativeJsonString(input.manifestRevision)
    << ",\"sourceStructuralRevision\":"
    << nativeJsonString(input.structuralRevision)
    << ",\"projectFile\":{\"relativePath\":"
    << nativeJsonString(projectRelative)
    << ",\"size\":" << portableRpp.size()
    << ",\"sha256\":" << nativeJsonString(projectSha256)
    << "},\"configFile\":{\"relativePath\":"
    << nativeJsonString(configRelative)
    << ",\"size\":" << input.configSnapshot.size()
    << ",\"sha256\":" << nativeJsonString(configSha256)
    << "},\"files\":[";
  for (size_t index = 0; index < files.size(); ++index) {
    if (index) descriptor << ',';
    const auto& file = files[index];
    descriptor << "{\"id\":" << nativeJsonString(file.id)
      << ",\"relativePath\":"
      << nativeJsonString(file.relativePath)
      << ",\"size\":" << file.size
      << ",\"sha256\":" << nativeJsonString(file.sha256)
      << ",\"kind\":" << nativeJsonString(file.kind) << '}';
  }
  descriptor << "]}";
  if (descriptor.str().size() > 8u * 1024u * 1024u) {
    nativeProjectSyncFinishBundleError(input.requestId,
      "O descriptor do projeto excedeu o limite seguro de 8 MiB.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  const std::string descriptorPath = joinPath(root, "descriptor.json");
  std::string descriptorSha;
  if (!nativeProjectSyncWriteAndHashText(descriptorPath,
        descriptor.str(), descriptorSha, error)) {
    nativeProjectSyncFinishBundleError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  // Este mapa existe apenas no PC A. Ele permite que a Hook Center sirva a
  // midia original sob demanda, sem duplicar todos os arquivos na pasta de
  // exportacao. O descriptor enviado pela LAN continua contendo somente
  // caminhos relativos e hashes; caminhos absolutos nunca entram nele.
  if (useSourceMap) {
    std::ostringstream localSourceMap;
    localSourceMap << "{\"schemaVersion\":1,\"bundleId\":"
      << nativeJsonString(input.bundleId)
      << ",\"requestId\":" << nativeJsonString(input.requestId)
      << ",\"descriptorSha256\":" << nativeJsonString(descriptorSha)
      << ",\"sources\":[";
    for (size_t index = 0; index < localSources.size(); ++index) {
      if (index) localSourceMap << ',';
      const NativeProjectSyncBundleSource& source = localSources[index];
      localSourceMap << "{\"id\":" << nativeJsonString(source.id)
        << ",\"absolutePath\":"
        << nativeJsonString(source.absolutePath)
        << ",\"size\":" << source.size
        << ",\"sha256\":" << nativeJsonString(source.sha256)
        << ",\"mtimeMs\":" << std::fixed << std::setprecision(3)
        << source.modificationTimeMs << '}';
    }
    localSourceMap << "]}";
    if (localSourceMap.str().size() > 8u * 1024u * 1024u) {
      nativeProjectSyncFinishBundleError(input.requestId,
        "O mapa local de midias excedeu o limite seguro de 8 MiB.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    std::string localSourceMapSha;
    if (!nativeProjectSyncWriteAndHashText(
          joinPath(root, ".vshook-source-map.json"),
          localSourceMap.str(), localSourceMapSha, error)) {
      nativeProjectSyncFinishBundleError(input.requestId, error);
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
  }

  bool handedOff = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncBundle.requestId == input.requestId &&
        g_nativeTimecodeLanMode == "project_sync" &&
        g_nativeTimecodeLanProjectSyncRole == "primary") {
      g_nativeProjectSyncBundle.state = "validating";
      g_nativeProjectSyncBundle.bundleId = input.bundleId;
      g_nativeProjectSyncBundle.revision = input.manifestRevision;
      g_nativeProjectSyncBundle.descriptorPath.clear();
      g_nativeProjectSyncBundle.error.clear();
      g_nativeProjectSyncBundle.bytesDone = totalBytes;
      g_nativeProjectSyncBundle.totalBytes = totalBytes;
      g_nativeProjectSyncBundle.fileIndex =
        static_cast<int>(files.size());
      g_nativeProjectSyncBundle.fileCount =
        static_cast<int>(files.size());
      g_nativeProjectSyncPendingPrepareConfirmation =
        NativeProjectSyncPendingPrepareConfirmation{};
      g_nativeProjectSyncPendingBundleReady.ready = true;
      g_nativeProjectSyncPendingBundleReady.requestId = input.requestId;
      g_nativeProjectSyncPendingBundleReady.bundleId = input.bundleId;
      g_nativeProjectSyncPendingBundleReady.revision =
        input.manifestRevision;
      g_nativeProjectSyncPendingBundleReady.descriptorPath =
        descriptorPath;
      g_nativeProjectSyncPendingBundleReady.projectPath =
        input.activeProjectPath;
      g_nativeProjectSyncPendingBundleReady.projectChangeCount =
        input.projectChangeCount;
      g_nativeProjectSyncPendingBundleReady.totalBytes = totalBytes;
      g_nativeProjectSyncPendingBundleReady.fileCount =
        static_cast<int>(files.size());
      g_nativeProjectSyncPendingBundleReady.automatic = input.automatic;
      handedOff = true;
    }
  }
  g_nativeForceStateBuild.store(true);
  partialExport.keep = handedOff;
  if (!handedOff) {
    nativeProjectSyncFinishBundleError(input.requestId,
      "O pareamento mudou antes de concluir o bundle.");
  }
  g_nativeProjectSyncBundleWorkerRunning.store(false);
}

static bool nativeProjectSyncSha256IsValid(const std::string& value)
{
  return value.size() == 64 &&
    std::all_of(value.begin(), value.end(), [](unsigned char character) {
      return (character >= '0' && character <= '9') ||
        (character >= 'a' && character <= 'f') ||
        (character >= 'A' && character <= 'F');
    });
}

static bool nativeProjectSyncPortableIdIsValid(
  const std::string& value,
  size_t maximumLength = 160)
{
  return !value.empty() && value.size() <= maximumLength &&
    std::all_of(value.begin(), value.end(), [](unsigned char character) {
      return (character >= '0' && character <= '9') ||
        (character >= 'a' && character <= 'z') ||
        (character >= 'A' && character <= 'Z') ||
        character == '.' || character == '_' || character == '-';
    });
}

static bool nativeProjectSyncPathEquals(
  const std::string& leftRaw,
  const std::string& rightRaw)
{
  std::string left = normalizeSlashes(nativeTrim(leftRaw));
  std::string right = normalizeSlashes(nativeTrim(rightRaw));
  while (left.size() > 1 && left.back() == '/') left.pop_back();
  while (right.size() > 1 && right.back() == '/') right.pop_back();
#ifdef _WIN32
  return nativeLower(left) == nativeLower(right);
#else
  return left == right;
#endif
}

static bool nativeProjectSyncPathWithin(
  const std::string& rootRaw,
  const std::string& pathRaw)
{
  std::string root = normalizeSlashes(nativeTrim(rootRaw));
  std::string path = normalizeSlashes(nativeTrim(pathRaw));
  while (root.size() > 1 && root.back() == '/') root.pop_back();
#ifdef _WIN32
  root = nativeLower(root);
  path = nativeLower(path);
#endif
  return path == root ||
    (path.size() > root.size() &&
     path.compare(0, root.size(), root) == 0 &&
     path[root.size()] == '/');
}

struct NativeProjectSyncApplyInput {
  std::string requestId;
  std::string bundleId;
  std::string descriptorPath;
  std::string stagingRoot;
  std::string originalProjectPath;
  std::string originalProjectDirectory;
  std::string originalMediaDirectory;
  std::string backupRoot;
  int originalProjectChangeCount = -1;
  std::string previousConfigSnapshot;
  std::string previousConfigRevision;
  std::string sourceManifest;
  bool automatic = false;
  std::string differencePlan;
};

static void nativeProjectSyncFinishApplyError(
  const std::string& requestId,
  const std::string& error)
{
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  if (g_nativeProjectSyncApply.requestId == requestId) {
    g_nativeProjectSyncApply.state = "error";
    g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
    g_nativeProjectSyncApply.error = error.empty()
      ? "Falha ao aplicar as modificacoes." : error;
  }
  if (g_nativeProjectSyncPendingOpen.requestId == requestId) {
    g_nativeProjectSyncPendingOpen = NativeProjectSyncPendingOpen{};
  }
  g_nativeForceStateBuild.store(true);
}

static bool nativeProjectSyncDescriptorFile(
  const std::string& object,
  NativeProjectSyncBundleFile& fileOut,
  std::string& errorOut)
{
  fileOut = NativeProjectSyncBundleFile{};
  fileOut.id = nativeTrim(nativeJsonExtractString(object, "id"));
  if (!nativeProjectSyncPortableIdIsValid(fileOut.id)) {
    errorOut = "O descriptor contem um identificador de arquivo invalido.";
    return false;
  }
  fileOut.kind = nativeLower(nativeTrim(
    nativeJsonExtractString(object, "kind")));
  if (!nativeProjectSyncSafeRelativePath(
        nativeJsonExtractString(object, "relativePath"),
        fileOut.relativePath)) {
    errorOut = "O descriptor contem um caminho relativo invalido.";
    return false;
  }
  const long long size = nativeJsonInt64(object, "size", -1);
  if (size < 0) {
    errorOut = "O descriptor contem tamanho de arquivo invalido.";
    return false;
  }
  fileOut.size = static_cast<uint64_t>(size);
  fileOut.sha256 = nativeLower(nativeTrim(
    nativeJsonExtractString(object, "sha256")));
  if (!nativeProjectSyncSha256IsValid(fileOut.sha256)) {
    errorOut = "O descriptor contem SHA256 invalido.";
    return false;
  }
  if (fileOut.kind != "media" && fileOut.kind != "project" &&
      fileOut.kind != "config") {
    errorOut = "O descriptor contem um tipo de arquivo nao permitido.";
    return false;
  }
  return true;
}

static void nativeProjectSyncApplyBundleWorker(
  NativeProjectSyncApplyInput input)
{
  std::string error;
  if (!nativeProjectSyncPathWithin(
        input.stagingRoot, input.descriptorPath) ||
      !nativeProjectSyncPathChainIsSafe(
        input.stagingRoot, input.descriptorPath) ||
      !fileExists(input.descriptorPath)) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O descriptor nao pertence ao staging validado da Hook Center.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  std::string descriptor;
  if (!nativeProjectSyncReadFileLimited(input.descriptorPath,
        8u * 1024u * 1024u, descriptor, error)) {
    nativeProjectSyncFinishApplyError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  if (nativeJsonInt64(descriptor, "schemaVersion", 0) != 1 ||
      nativeTrim(nativeJsonExtractString(descriptor, "requestId")) !=
        input.requestId ||
      nativeTrim(nativeJsonExtractString(descriptor, "bundleId")) !=
        input.bundleId) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O descriptor recebido nao corresponde a esta solicitacao.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  const std::string sourceManifestRevision = nativeTrim(
    nativeJsonExtractString(descriptor, "sourceManifestRevision"));
  const std::string sourceStructuralRevision = nativeTrim(
    nativeJsonExtractString(descriptor, "sourceStructuralRevision"));
  if (sourceManifestRevision.empty() || sourceStructuralRevision.empty()) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O descriptor nao informa a revisao do projeto mestre.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  const std::string projectObject = nativeTrim(
    nativeJsonExtractRawValue(descriptor, "projectFile"));
  std::string projectRelative;
  if (projectObject.empty() || projectObject.front() != '{' ||
      !nativeProjectSyncSafeRelativePath(
        nativeJsonExtractString(projectObject, "relativePath"),
        projectRelative)) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O RPP do bundle nao foi identificado.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  const std::string filesJson = nativeTrim(
    nativeJsonExtractRawValue(descriptor, "files"));
  const std::vector<std::string> fileObjects =
    nativeProjectSyncJsonObjectArray(filesJson, 16384);
  if (fileObjects.empty() || fileObjects.size() > 16384) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "A lista de arquivos do bundle e invalida.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  std::vector<NativeProjectSyncBundleFile> files;
  std::set<std::string> relativePaths;
  uint64_t totalBytes = 0;
  bool projectListed = false;
  std::string configRelative;
  for (const std::string& object : fileObjects) {
    NativeProjectSyncBundleFile file;
    if (!nativeProjectSyncDescriptorFile(object, file, error)) {
      nativeProjectSyncFinishApplyError(input.requestId, error);
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    std::string identity = file.relativePath;
#ifdef _WIN32
    identity = nativeLower(identity);
#endif
    if (!relativePaths.insert(identity).second) {
      nativeProjectSyncFinishApplyError(input.requestId,
        "O descriptor repete um caminho de arquivo.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    if (std::numeric_limits<uint64_t>::max() - totalBytes < file.size) {
      nativeProjectSyncFinishApplyError(input.requestId,
        "O tamanho total do bundle excede o limite suportado.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    totalBytes += file.size;
    if (file.kind == "project" && file.relativePath == projectRelative) {
      projectListed = true;
    }
    if (file.kind == "config") configRelative = file.relativePath;
    files.push_back(std::move(file));
  }
  if (!projectListed) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O RPP nao consta na lista assinada do bundle.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  // Este bloco e acrescentado somente pela Hook Center do proprio PC B,
  // depois de validar que o conteudo ja existe no projeto local. Ele nunca
  // vem do PC A e cada entrada ainda precisa coincidir com tamanho e SHA do
  // manifesto autenticado recebido pela rede.
  std::map<std::string, NativeProjectSyncLocalReuseFile> localReuseFiles;
  const std::string localReuseJson = nativeTrim(
    nativeJsonExtractRawValue(descriptor, "localReuseFiles"));
  if (!localReuseJson.empty() && localReuseJson != "null") {
    const std::vector<std::string> reuseObjects =
      nativeProjectSyncJsonObjectArray(localReuseJson, 16384);
    std::map<std::string, const NativeProjectSyncBundleFile*> filesById;
    for (const NativeProjectSyncBundleFile& file : files) {
      filesById[file.id] = &file;
    }
    for (const std::string& object : reuseObjects) {
      const std::string id = nativeTrim(
        nativeJsonExtractString(object, "id"));
      const auto fileFound = filesById.find(id);
      if (!nativeProjectSyncPortableIdIsValid(id) ||
          fileFound == filesById.end() ||
          fileFound->second->kind != "media" ||
          localReuseFiles.count(id) != 0) {
        nativeProjectSyncFinishApplyError(input.requestId,
          "O mapa local de midia contem um identificador invalido.");
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
      NativeProjectSyncLocalReuseFile reuse;
      reuse.absolutePath = normalizeSlashes(nativeTrim(
        nativeJsonExtractString(object, "absolutePath")));
      const long long reuseSize = nativeJsonInt64(object, "size", -1);
      reuse.sha256 = nativeLower(nativeTrim(
        nativeJsonExtractString(object, "sha256")));
      if (reuse.absolutePath.empty() ||
          !nativeTelepromptPathIsAbsolute(reuse.absolutePath) ||
          reuseSize < 0 ||
          static_cast<uint64_t>(reuseSize) != fileFound->second->size ||
          reuse.sha256 != nativeLower(fileFound->second->sha256)) {
        nativeProjectSyncFinishApplyError(input.requestId,
          "O mapa local de midia nao corresponde ao manifesto recebido.");
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
      reuse.size = static_cast<uint64_t>(reuseSize);
      NativeProjectSyncRegularFileStamp reuseStamp;
      if (!nativeProjectSyncRegularFileStamp(
            reuse.absolutePath, reuseStamp) ||
          reuseStamp.size != reuse.size) {
        nativeProjectSyncFinishApplyError(input.requestId,
          "Uma midia que seria reutilizada no PC B nao esta mais disponivel.");
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
      localReuseFiles.emplace(id, std::move(reuse));
    }
  }

  uint64_t validationTotalBytes = 0;
  int validationFileCount = 0;
  for (const NativeProjectSyncBundleFile& file : files) {
    if (localReuseFiles.count(file.id) != 0) continue;
    if (std::numeric_limits<uint64_t>::max() - validationTotalBytes <
        file.size) {
      nativeProjectSyncFinishApplyError(input.requestId,
        "O tamanho dos arquivos novos excede o limite suportado.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    validationTotalBytes += file.size;
    ++validationFileCount;
  }

  // A midia recebida pertence ao proprio projeto B. Usa o caminho efetivo de
  // gravacao/midia que o REAPER devolve por GetProjectPathEx (por exemplo,
  // "Audio Files"), sem criar uma arvore paralela "VS Hook Project Sync".
  const std::string projectMediaRoot =
    input.originalMediaDirectory.empty()
      ? input.originalProjectDirectory
      : input.originalMediaDirectory;
  if (projectMediaRoot.empty() ||
      !nativeProjectSyncEnsureDirectory(projectMediaRoot, error)) {
    nativeProjectSyncFinishApplyError(input.requestId,
      error.empty()
        ? "A pasta de midia do projeto B nao esta disponivel."
        : error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }

  bool handedOff = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncApply.requestId == input.requestId) {
      g_nativeProjectSyncApply.state = "validating";
      g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
      g_nativeProjectSyncApply.revision = sourceManifestRevision;
      g_nativeProjectSyncApply.totalBytes = validationTotalBytes;
      g_nativeProjectSyncApply.fileCount = validationFileCount;
      g_nativeProjectSyncApply.error.clear();
    }
  }
  uint64_t bytesDone = 0;
  int validationFileIndex = 0;
  std::map<std::string, std::string> stagedMediaToLocal;
  std::map<std::string, std::string> portableMediaToLocal;
  const auto mediaPathKey = [](const std::string& value) {
    std::string key = normalizeSlashes(nativeTrim(value));
#ifdef _WIN32
    key = nativeLower(key);
#endif
    return key;
  };
  std::string sourceProjectPath;
  for (size_t index = 0; index < files.size(); ++index) {
    const NativeProjectSyncBundleFile& file = files[index];
    const std::string stagedSourcePath = joinPath(
      input.stagingRoot, file.relativePath);
    const auto reuseFound = localReuseFiles.find(file.id);
    const bool reusedLocally = reuseFound != localReuseFiles.end();
    if (!reusedLocally) ++validationFileIndex;
    const std::string sourcePath = reusedLocally
      ? reuseFound->second.absolutePath : stagedSourcePath;
    if ((!reusedLocally &&
         (!nativeProjectSyncPathWithin(input.stagingRoot, sourcePath) ||
          !nativeProjectSyncPathChainIsSafe(
            input.stagingRoot, sourcePath))) ||
        !fileExists(sourcePath) ||
        nativeProjectSyncFileSize(sourcePath) !=
          static_cast<long long>(file.size)) {
      nativeProjectSyncFinishApplyError(input.requestId,
        "Arquivo ausente ou com tamanho incorreto: " +
          file.relativePath);
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    if (!reusedLocally) {
      std::string actualSha256;
      if (!nativeProjectSyncCopyAndHashFile(sourcePath,
            "", false, input.requestId, validationTotalBytes,
            bytesDone, validationFileIndex,
            validationFileCount, actualSha256, error)) {
        nativeProjectSyncFinishApplyError(input.requestId, error);
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
      if (nativeLower(actualSha256) != nativeLower(file.sha256)) {
        nativeProjectSyncFinishApplyError(input.requestId,
          "SHA256 nao confere: " + file.relativePath);
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
    }
    if (file.kind == "project") {
      sourceProjectPath = sourcePath;
      continue;
    }
    if (file.kind != "media") continue;

    if (reusedLocally) {
      // O projeto B ja referencia este conteudo. Mantem o arquivo no lugar,
      // sem criar uma segunda copia no staging nem no cache gerenciado.
      stagedMediaToLocal[mediaPathKey(stagedSourcePath)] = sourcePath;
      portableMediaToLocal[mediaPathKey(file.relativePath)] = sourcePath;
      portableMediaToLocal[mediaPathKey("../" + file.relativePath)] =
        sourcePath;
      continue;
    }

    // Preserva o nome real na pasta Media/Audio Files do projeto. O prefixo
    // SHA existe apenas no descriptor de transporte e nunca deve aparecer no
    // projeto do usuario. O PC A e a autoridade: se ja existir outro conteudo
    // com o mesmo nome no PC B, ele sera substituido atomicamente.
    std::string mediaName = nativeProjectSyncSafeFileName(
      file.relativePath);
    while (nativeProjectSyncHexPrefix20(mediaName)) {
      mediaName.erase(0, 21);
    }
    if (mediaName.empty()) mediaName = "midia";
    const std::string destinationPath = joinPath(
      projectMediaRoot, mediaName);
    bool destinationReady = false;
    if (fileExists(destinationPath) &&
        nativeProjectSyncFileSize(destinationPath) ==
          static_cast<long long>(file.size)) {
      uint64_t ignoredBytes = 0;
      std::string destinationSha;
      std::string destinationError;
      destinationReady = nativeProjectSyncCopyAndHashFile(
        destinationPath, "", false, input.requestId, 0,
        ignoredBytes, 0, 0, destinationSha, destinationError) &&
        nativeLower(destinationSha) == nativeLower(file.sha256);
    }
    if (!destinationReady) {
      const std::string temporaryPath = destinationPath +
        "." + input.requestId.substr(0, 12) + ".part";
      nativeProjectSyncRemoveOwnFile(temporaryPath);
      uint64_t ignoredBytes = 0;
      std::string copiedSha;
      if (!nativeProjectSyncCopyAndHashFile(sourcePath,
            temporaryPath, false, input.requestId, 0,
            ignoredBytes, 0, 0, copiedSha, error) ||
          nativeLower(copiedSha) != nativeLower(file.sha256) ||
          !nativeProjectSyncMoveFile(
            temporaryPath, destinationPath, true)) {
        nativeProjectSyncRemoveOwnFile(temporaryPath);
        nativeProjectSyncFinishApplyError(input.requestId,
          error.empty()
            ? "Nao foi possivel instalar a midia recebida no projeto B."
            : error);
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        return;
      }
    }
    stagedMediaToLocal[mediaPathKey(stagedSourcePath)] = destinationPath;
    portableMediaToLocal[mediaPathKey(file.relativePath)] = destinationPath;
    portableMediaToLocal[mediaPathKey("../" + file.relativePath)] =
      destinationPath;
  }

  if (sourceProjectPath.empty() || !fileExists(sourceProjectPath)) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O pacote validado nao contem o snapshot do RPP.");
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  std::string sourceProjectText;
  if (!nativeProjectSyncReadFileLimited(sourceProjectPath,
        128u * 1024u * 1024u, sourceProjectText, error)) {
    nativeProjectSyncFinishApplyError(input.requestId, error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  const std::vector<NativeProjectSyncRppReference> references =
    nativeProjectSyncRppReferences(sourceProjectText,
      nativeProjectSyncParentPath(sourceProjectPath),
      nativeProjectSyncParentPath(sourceProjectPath));
  std::string inPlaceProjectText;
  inPlaceProjectText.reserve(
    sourceProjectText.size() + references.size() * 64);
  const NativeProjectSyncDifferencePlan differencePlan =
    nativeProjectSyncParseDifferencePlan(input.differencePlan);
  size_t copiedUntil = 0;
  for (const auto& reference : references) {
    if (reference.valueStart < copiedUntil ||
        reference.valueEnd > sourceProjectText.size()) continue;
    auto mapped = stagedMediaToLocal.find(
      mediaPathKey(reference.resolvedPath));
    std::string mappedPath;
    if (mapped != stagedMediaToLocal.end()) {
      mappedPath = mapped->second;
    } else {
      const auto portableMapped = portableMediaToLocal.find(
        mediaPathKey(reference.sourcePath));
      if (portableMapped != portableMediaToLocal.end()) {
        mappedPath = portableMapped->second;
      }
    }
    if (mappedPath.empty()) {
      if (differencePlan.scoped) {
        // O bloco deste item permanece exatamente como ja esta no PC B.
        // Logo esta referencia igual nao precisa de hash, copia ou relink.
        continue;
      }
      nativeProjectSyncFinishApplyError(input.requestId,
        "O snapshot nao conseguiu vincular toda a midia recebida.");
      g_nativeProjectSyncBundleWorkerRunning.store(false);
      return;
    }
    inPlaceProjectText.append(sourceProjectText, copiedUntil,
      reference.valueStart - copiedUntil);
    inPlaceProjectText += mappedPath;
    copiedUntil = reference.valueEnd;
  }
  inPlaceProjectText.append(
    sourceProjectText, copiedUntil, std::string::npos);
  const std::string backupPath = joinPath(
    input.backupRoot,
    nativeProjectSyncTimestampForPath() + "-" +
      std::to_string(nativeSystemNowMs()) + "/" +
      nativeProjectSyncSafeFileName(input.originalProjectPath));
  const std::string previousConfigSnapshot =
    input.previousConfigSnapshot;
  const std::string previousConfigRevision =
    input.previousConfigRevision;
  if (!nativeProjectSyncCopyFileSimple(
        input.originalProjectPath, backupPath, error)) {
    nativeProjectSyncFinishApplyError(input.requestId,
      error.empty() ? "Nao foi possivel preparar a aplicacao no PC B." : error);
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    return;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncApply.requestId == input.requestId &&
        g_nativeTimecodeLanMode == "project_sync" &&
        g_nativeTimecodeLanProjectSyncRole == "secondary") {
      g_nativeProjectSyncApply.state = "ready_to_apply";
      g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
      g_nativeProjectSyncApply.bytesDone = validationTotalBytes;
      g_nativeProjectSyncApply.totalBytes = validationTotalBytes;
      g_nativeProjectSyncApply.fileIndex = validationFileCount;
      g_nativeProjectSyncApply.fileCount = validationFileCount;
      g_nativeProjectSyncApply.error.clear();
      g_nativeProjectSyncPendingOpen.ready = true;
      g_nativeProjectSyncPendingOpen.requestId = input.requestId;
      g_nativeProjectSyncPendingOpen.bundleId = input.bundleId;
      g_nativeProjectSyncPendingOpen.sourceManifestRevision =
        sourceManifestRevision;
      g_nativeProjectSyncPendingOpen.originalProjectPath =
        input.originalProjectPath;
      g_nativeProjectSyncPendingOpen.backupPath = backupPath;
      // Configuracoes sao uma escolha separada na conferencia. A aplicacao
      // estrutural nunca as importa de forma implicita.
      g_nativeProjectSyncPendingOpen.inPlaceProjectText =
        std::move(inPlaceProjectText);
      g_nativeProjectSyncPendingOpen.sourceManifest =
        input.sourceManifest;
      g_nativeProjectSyncPendingOpen.originalProjectChangeCount =
        input.originalProjectChangeCount;
      g_nativeProjectSyncPendingOpen.backupReady = true;
      g_nativeProjectSyncPendingOpen.previousConfigSnapshot =
        previousConfigSnapshot;
      g_nativeProjectSyncPendingOpen.previousConfigRevision =
        previousConfigRevision;
      g_nativeProjectSyncPendingOpen.automatic = input.automatic;
      g_nativeProjectSyncPendingOpen.differencePlan =
        input.differencePlan;
      handedOff = true;
    }
  }
  if (!handedOff) {
    nativeProjectSyncFinishApplyError(input.requestId,
      "O pareamento mudou antes de aplicar o bundle.");
  }
  g_nativeForceStateBuild.store(true);
  g_nativeProjectSyncBundleWorkerRunning.store(false);
}

static void nativeProjectSyncJoinFinishedBundleWorker()
{
  if (!g_nativeProjectSyncBundleWorkerRunning.load() &&
      g_nativeProjectSyncBundleWorker.joinable()) {
    g_nativeProjectSyncBundleWorker.join();
  }
}

static void nativeProjectSyncFinalizePreparedBundleOnMainThread()
{
  nativeProjectSyncJoinFinishedBundleWorker();
  NativeProjectSyncPendingBundleReady pending;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (!g_nativeProjectSyncPendingBundleReady.ready) return;
    pending = g_nativeProjectSyncPendingBundleReady;
  }
  char currentPathBuffer[8192] = "";
  ReaProject* project = getCurrentProject(currentPathBuffer,
    static_cast<int>(sizeof(currentPathBuffer)));
  const std::string currentPath = normalizeSlashes(
    nativeTrim(currentPathBuffer));
  std::string validationError;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeTimecodeLanMode != "project_sync" ||
        g_nativeTimecodeLanProjectSyncRole != "primary" ||
        g_nativeProjectSyncPreflight.requestId != pending.requestId) {
      validationError = "O pareamento mudou durante a preparacao.";
    }
  }
  if (validationError.empty() &&
      (!project || !IsProjectDirty_ptr ||
       !GetProjectStateChangeCount_ptr ||
       !nativeProjectSyncPathEquals(currentPath, pending.projectPath) ||
       GetProjectStateChangeCount_ptr(project) !=
         pending.projectChangeCount)) {
    validationError =
      "O projeto do PC A mudou durante a preparacao. Salve e confira novamente.";
  }
  if (!validationError.empty()) {
    nativeProjectSyncFinishBundleError(
      pending.requestId, validationError);
    return;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (!g_nativeProjectSyncPendingBundleReady.ready ||
        g_nativeProjectSyncPendingBundleReady.requestId !=
          pending.requestId) {
      return;
    }
    g_nativeProjectSyncBundle.state = "ready";
    g_nativeProjectSyncBundle.bundleId = pending.bundleId;
    g_nativeProjectSyncBundle.revision = pending.revision;
    g_nativeProjectSyncBundle.descriptorPath = pending.descriptorPath;
    g_nativeProjectSyncBundle.error.clear();
    g_nativeProjectSyncBundle.bytesDone = pending.totalBytes;
    g_nativeProjectSyncBundle.totalBytes = pending.totalBytes;
    g_nativeProjectSyncBundle.fileIndex = pending.fileCount;
    g_nativeProjectSyncBundle.fileCount = pending.fileCount;
    g_nativeProjectSyncPendingBundleReady =
      NativeProjectSyncPendingBundleReady{};
  }
  g_nativeForceStateBuild.store(true);
}

static bool nativeProjectSyncConsumeBundleFromCommand(
  const std::string& commandBody)
{
  nativeProjectSyncJoinFinishedBundleWorker();
  const std::string requestId = nativeTrim(
    nativeJsonExtractString(commandBody, "requestId"));
  const std::string bundleId = nativeTrim(
    nativeJsonExtractString(commandBody, "bundleId"));
  if (!nativeProjectSyncRequestIdIsValid(requestId) ||
      !nativeProjectSyncPortableIdIsValid(bundleId)) {
    return true;
  }
  std::string descriptorPath;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeTimecodeLanProjectSyncRole != "primary" ||
        g_nativeProjectSyncBundle.state != "ready" ||
        g_nativeProjectSyncBundle.requestId != requestId ||
        g_nativeProjectSyncBundle.bundleId != bundleId) {
      return true;
    }
    descriptorPath = g_nativeProjectSyncBundle.descriptorPath;
  }
  const std::string resourcePath = normalizeSlashes(
    GetResourcePath_ptr ? GetResourcePath_ptr() : "");
  const std::string exportsRoot = joinPath(resourcePath,
    "VS Hook/Project Sync/Exports");
  const std::string expectedBundleRoot = joinPath(
    exportsRoot, bundleId);
  const std::string descriptorRoot =
    nativeProjectSyncParentPath(descriptorPath);
  if (resourcePath.empty() ||
      !nativeProjectSyncPathEquals(
        descriptorRoot, expectedBundleRoot) ||
      !nativeProjectSyncPathWithin(exportsRoot, expectedBundleRoot) ||
      !nativeProjectSyncPathChainIsSafe(
        exportsRoot, expectedBundleRoot) ||
      g_nativeProjectSyncBundleWorkerRunning.load()) {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncBundle.error =
      "O export nao passou na validacao para limpeza segura.";
    return true;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncBundle.state = "consuming";
  }
  g_nativeProjectSyncBundleWorkerCancel.store(false);
  g_nativeProjectSyncBundleWorkerRunning.store(true);
  try {
    g_nativeProjectSyncBundleWorker = std::thread(
      [exportsRoot, expectedBundleRoot, requestId, bundleId]() {
        bool removed = false;
        try {
          removed = nativeProjectSyncRemoveOwnedTree(
            expectedBundleRoot, expectedBundleRoot);
        } catch (...) {
          removed = false;
        }
        {
          std::lock_guard<std::mutex> lock(
            g_nativeTimecodeLanMutex);
          if (g_nativeProjectSyncBundle.requestId == requestId &&
              g_nativeProjectSyncBundle.bundleId == bundleId) {
            g_nativeProjectSyncBundle.state = removed
              ? "consumed" : "cleanup_error";
            if (removed) {
              g_nativeProjectSyncBundle.descriptorPath.clear();
              g_nativeProjectSyncBundle.error.clear();
            } else {
              g_nativeProjectSyncBundle.error =
                "O bundle foi entregue, mas a limpeza local falhou.";
            }
          }
        }
        g_nativeProjectSyncBundleWorkerRunning.store(false);
        g_nativeForceStateBuild.store(true);
      });
  } catch (...) {
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncBundle.state = "cleanup_error";
    g_nativeProjectSyncBundle.error =
      "Nao foi possivel iniciar a limpeza do export.";
  }
  return true;
}

static bool nativeProjectSyncPrepareBundleFromCommand(
  const std::string& commandBody)
{
  nativeProjectSyncJoinFinishedBundleWorker();
  const std::string requestId = nativeTrim(
    nativeJsonExtractString(commandBody, "requestId"));
  const std::string expectedRevision = nativeTrim(
    nativeJsonExtractString(commandBody, "expectedRevision"));
  const bool automatic = nativeJsonBoolValue(
    commandBody, "automatic", false);
  const bool supportsSourceMap = nativeJsonBoolValue(
    commandBody, "supportsSourceMap", false);
  const std::string differencePlan =
    nativeJsonExtractString(commandBody, "differencePlan").substr(
      0, 128 * 1024);
  if (!nativeProjectSyncRequestIdIsValid(requestId)) return true;

  std::string role;
  std::string manifestRevision;
  std::string structuralRevision;
  std::string configSnapshot;
  std::string currentPreflightRequestId;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    role = g_nativeTimecodeLanProjectSyncRole;
    manifestRevision = g_nativeProjectSyncPreflight.manifestRevision;
    structuralRevision =
      g_nativeProjectSyncPreflight.structuralManifestRevision;
    configSnapshot = g_nativeProjectSyncPreflight.configSnapshot;
    currentPreflightRequestId = g_nativeProjectSyncPreflight.requestId;
  }
  if (role != "primary") return true;
  if (currentPreflightRequestId != requestId) {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncBundle = NativeProjectSyncBundleState{};
    g_nativeProjectSyncBundle.state = "error";
    g_nativeProjectSyncBundle.requestId = requestId;
    g_nativeProjectSyncBundle.error =
      "Este pedido nao pertence ao pareamento atual.";
    return true;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncBundle.state == "ready" &&
        g_nativeProjectSyncBundle.requestId == requestId &&
        (expectedRevision.empty() ||
         nativeProjectSyncPathEquals(
           expectedRevision,
           g_nativeProjectSyncPreflight.structuralManifestRevision))) {
      return true;
    }
  }
  // A confirmacao feita no PC B autoriza a aplicacao. Como o PC A e a
  // autoridade do Project Sync, ele inicia a preparacao imediatamente, sem uma
  // segunda pergunta capaz de interromper a transferencia ou provocar retry.
  if (g_nativeProjectSyncBundleWorkerRunning.load()) {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncBundle.requestId != requestId) {
      g_nativeProjectSyncBundle = NativeProjectSyncBundleState{};
      g_nativeProjectSyncBundle.state = "error";
      g_nativeProjectSyncBundle.requestId = requestId;
      g_nativeProjectSyncBundle.error =
        "Outra transferencia do Project Sync ainda esta em andamento.";
    }
    return true;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncBundle = NativeProjectSyncBundleState{};
    g_nativeProjectSyncBundle.state = "preparing";
    g_nativeProjectSyncBundle.requestId = requestId;
  }
  nativeProjectSyncRefreshManifestOnMainThread(true);
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    manifestRevision = g_nativeProjectSyncPreflight.manifestRevision;
    structuralRevision =
      g_nativeProjectSyncPreflight.structuralManifestRevision;
    configSnapshot = g_nativeProjectSyncPreflight.configSnapshot;
  }
  if (!expectedRevision.empty() &&
      !nativeProjectSyncPathEquals(expectedRevision, manifestRevision) &&
      !nativeProjectSyncPathEquals(expectedRevision, structuralRevision)) {
    nativeProjectSyncFinishBundleError(requestId,
      "O projeto do PC A mudou antes de preparar o bundle. Confira novamente.");
    return true;
  }

  char projectPathBuffer[8192] = "";
  ReaProject* project = getCurrentProject(projectPathBuffer,
    static_cast<int>(sizeof(projectPathBuffer)));
  const std::string projectPath = normalizeSlashes(
    nativeTrim(projectPathBuffer));
  if (!project || projectPath.empty() || !fileExists(projectPath)) {
    nativeProjectSyncFinishBundleError(requestId,
      "Salve o projeto do PC A antes de aplicar modificacoes no PC B.");
    return true;
  }
  if (!IsProjectDirty_ptr || !GetProjectStateChangeCount_ptr) {
    nativeProjectSyncFinishBundleError(requestId,
      "O REAPER nao disponibilizou as APIs de seguranca do projeto.");
    return true;
  }
  const std::string projectDirectory =
    nativeProjectSyncParentPath(projectPath);
  const std::string projectFileName =
    nativeProjectSyncBasename(projectPath);
  const std::string mediaDirectory =
    nativeTelepromptProjectMediaDirectory(project);
  const std::string bundleId =
    (structuralRevision.empty()
      ? nativeProjectSyncHashText(projectPath)
      : structuralRevision).substr(0, 16) + "-" +
    requestId.substr(0, 16) + "-" +
    std::to_string(nativeSystemNowMs());
  if (!Main_SaveProjectEx_ptr) {
    nativeProjectSyncFinishBundleError(requestId,
      "O REAPER nao disponibilizou o snapshot vivo do projeto.");
    return true;
  }
  std::string snapshotError;
  const std::string snapshotDirectory = joinPath(
    normalizeSlashes(GetResourcePath_ptr ? GetResourcePath_ptr() : ""),
    "VS Hook/Project Sync/Live Snapshots/" + bundleId);
  if (!nativeProjectSyncEnsureDirectory(
        snapshotDirectory, snapshotError)) {
    nativeProjectSyncFinishBundleError(requestId,
      snapshotError.empty()
        ? "Nao foi possivel preparar o snapshot vivo do PC A."
        : snapshotError);
    return true;
  }
  const std::string snapshotProjectPath = joinPath(
    snapshotDirectory, projectFileName);
  Main_SaveProjectEx_ptr(project, snapshotProjectPath.c_str(), 0);
  if (!fileExists(snapshotProjectPath)) {
    nativeProjectSyncFinishBundleError(requestId,
      "O REAPER nao criou o snapshot vivo do PC A.");
    return true;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncBundle.bundleId = bundleId;
    g_nativeProjectSyncBundle.revision = manifestRevision;
  }
  g_nativeProjectSyncBundleWorkerCancel.store(false);
  g_nativeProjectSyncBundleWorkerRunning.store(true);
  try {
    NativeProjectSyncPrepareInput input{
      requestId, bundleId, snapshotProjectPath, projectPath,
      projectDirectory,
      mediaDirectory, projectFileName, manifestRevision,
      structuralRevision, configSnapshot,
      nativeTimecodeLanSessionId(),
      normalizeSlashes(
        GetResourcePath_ptr ? GetResourcePath_ptr() : ""),
      GetProjectStateChangeCount_ptr(project), automatic,
      supportsSourceMap, differencePlan};
    g_nativeProjectSyncBundleWorker = std::thread([input]() {
      try {
        nativeProjectSyncPrepareBundleWorker(input);
      } catch (...) {
        nativeProjectSyncFinishBundleError(input.requestId,
          "Erro inesperado ao preparar o bundle.");
        g_nativeProjectSyncBundleWorkerRunning.store(false);
      }
    });
  } catch (...) {
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    nativeProjectSyncFinishBundleError(requestId,
      "Nao foi possivel iniciar a preparacao do bundle.");
  }
  g_nativeForceStateBuild.store(true);
  return true;
}

static bool nativeProjectSyncUpdateApplyProgressFromCommand(
  const std::string& commandBody)
{
  const std::string requestId = nativeTrim(
    nativeJsonExtractString(commandBody, "requestId"));
  if (!nativeProjectSyncRequestIdIsValid(requestId)) return true;
  const std::string state = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "state")));
  const std::set<std::string> allowedStates = {
    "requested", "requesting", "downloading", "verifying",
    "validating", "applying", "apply_started", "error"};
  if (allowedStates.count(state) == 0) return true;
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  if (g_nativeTimecodeLanProjectSyncRole != "secondary" ||
      g_nativeProjectSyncApply.requestId != requestId) {
    return true;
  }
  g_nativeProjectSyncApply.state = state;
  g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
  const std::string bundleId = nativeTrim(
    nativeJsonExtractString(commandBody, "bundleId"));
  if (!bundleId.empty()) g_nativeProjectSyncApply.bundleId = bundleId;
  g_nativeProjectSyncApply.bytesDone = static_cast<uint64_t>(
    std::max<long long>(0,
      nativeJsonInt64(commandBody, "bytesDone", 0)));
  g_nativeProjectSyncApply.totalBytes = static_cast<uint64_t>(
    std::max<long long>(0,
      nativeJsonInt64(commandBody, "totalBytes", 0)));
  g_nativeProjectSyncApply.fileIndex = std::max<int>(0,
    static_cast<int>(nativeJsonInt64(commandBody, "fileIndex", 0)));
  g_nativeProjectSyncApply.fileCount = std::max<int>(0,
    static_cast<int>(nativeJsonInt64(commandBody, "fileCount", 0)));
  std::string progressError = state == "error"
    ? nativeTrim(nativeJsonExtractString(commandBody, "error"))
    : std::string();
  const std::string normalizedProgressError = nativeLower(progressError);
  if (progressError == "0" || normalizedProgressError == "false" ||
      normalizedProgressError == "null") {
    progressError.clear();
  }
  g_nativeProjectSyncApply.error = std::move(progressError);
  g_nativeForceStateBuild.store(true);
  // O snapshot geral pode continuar semanticamente igual enquanto somente
  // bytes/progresso mudam. Solicita o repaint diretamente para a conferencia
  // responder no mesmo instante, sem depender de outra interacao do usuario.
  if (g_nativeMainModalKind == NativeMainModalKind::ProjectSyncDiff &&
      nativeAppActivePanelIsOpen()) {
    InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
  }
  return true;
}

static bool nativeProjectSyncApplyStateIsBusy(
  const std::string& rawState)
{
  const std::string state = nativeLower(nativeTrim(rawState));
  return state == "requested" || state == "requesting" ||
    state == "downloading" || state == "verifying" ||
    state == "validating" || state == "ready_to_open" ||
    state == "ready_to_apply" || state == "applying" ||
    state == "apply_started";
}

static bool nativeProjectSyncApplyIsBusy()
{
  std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
  return nativeProjectSyncApplyStateIsBusy(
    g_nativeProjectSyncApply.state);
}

static void nativeProjectSyncExpireStalledApplyOnMainThread()
{
  const int64_t nowMs = nativeSteadyNowMs();
  bool expired = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    const std::string state = nativeLower(nativeTrim(
      g_nativeProjectSyncApply.state));
    const int64_t ageMs = g_nativeProjectSyncApply.stateUpdatedAtMs > 0
      ? nowMs - g_nativeProjectSyncApply.stateUpdatedAtMs : 0;
    const bool requestNeverStarted = state == "requested" && ageMs > 15000;
    const bool transferStopped =
      (state == "requesting" || state == "downloading" ||
       state == "verifying" || state == "validating" ||
       state == "ready_to_apply" || state == "applying" ||
       state == "apply_started") &&
      ageMs > 1800000;
    if (requestNeverStarted || transferStopped) {
      g_nativeProjectSyncApply.state = "error";
      g_nativeProjectSyncApply.stateUpdatedAtMs = nowMs;
      g_nativeProjectSyncApply.error = requestNeverStarted
        ? "A Hook Center nao iniciou a transferencia. Confira se ela esta aberta e tente novamente."
        : "O Project Sync parou de responder. Confira a Hook Center e tente novamente.";
      expired = true;
    }
  }
  if (!expired) return;
  g_nativeForceStateBuild.store(true);
  if (g_nativeMainModalKind == NativeMainModalKind::ProjectSyncDiff &&
      nativeAppActivePanelIsOpen()) {
    InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
  }
}

static bool nativeProjectSyncApplyBundleFromCommand(
  const std::string& commandBody)
{
  nativeProjectSyncJoinFinishedBundleWorker();
  const std::string requestId = nativeTrim(
    nativeJsonExtractString(commandBody, "requestId"));
  const std::string bundleId = nativeTrim(
    nativeJsonExtractString(commandBody, "bundleId"));
  const std::string descriptorPath = normalizeSlashes(nativeTrim(
    nativeJsonExtractString(commandBody, "descriptorPath")));
  const std::string stagingRoot = normalizeSlashes(nativeTrim(
    nativeJsonExtractString(commandBody, "stagingRoot")));
  const bool automatic = nativeJsonBoolValue(
    commandBody, "automatic", false);
  if (!nativeProjectSyncRequestIdIsValid(requestId)) return true;
  if (!nativeProjectSyncPortableIdIsValid(bundleId) ||
      descriptorPath.empty() || stagingRoot.empty()) {
    nativeProjectSyncFinishApplyError(requestId,
      "A Hook Center enviou um staging incompleto.");
    return true;
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeTimecodeLanProjectSyncRole != "secondary" ||
        g_nativeProjectSyncApply.requestId != requestId) {
      return true;
    }
  }
  if (g_nativeProjectSyncBundleWorkerRunning.load()) {
    nativeProjectSyncFinishApplyError(requestId,
      "Outra transferencia ainda esta sendo validada.");
    return true;
  }
  char projectPathBuffer[8192] = "";
  ReaProject* project = getCurrentProject(projectPathBuffer,
    static_cast<int>(sizeof(projectPathBuffer)));
  const std::string projectPath = normalizeSlashes(
    nativeTrim(projectPathBuffer));
  if (!project || projectPath.empty() || !fileExists(projectPath)) {
    nativeProjectSyncFinishApplyError(requestId,
      "Salve o projeto do PC B antes de aplicar as modificacoes.");
    return true;
  }
  if (!IsProjectDirty_ptr || !GetProjectStateChangeCount_ptr) {
    nativeProjectSyncFinishApplyError(requestId,
      "O REAPER nao disponibilizou as APIs de seguranca do projeto.");
    return true;
  }
  const int changeCount = GetProjectStateChangeCount_ptr(project);
  const std::string previousConfigSnapshot =
    nativeProjectSyncBuildConfigSnapshot();
  const std::string previousConfigRevision =
    nativeProjectSyncHashText(previousConfigSnapshot);
  std::string sourceManifest;
  std::string differencePlan;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncApply.state = "validating";
    g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
    g_nativeProjectSyncApply.bundleId = bundleId;
    g_nativeProjectSyncApply.descriptorPath = descriptorPath;
    g_nativeProjectSyncApply.stagingRoot = stagingRoot;
    g_nativeProjectSyncApply.error.clear();
    g_nativeProjectSyncApply.automatic = automatic;
    sourceManifest = g_nativeProjectSyncPreflight.remoteManifest;
    differencePlan = g_nativeProjectSyncApply.differencePlan;
  }
  if (sourceManifest.empty()) {
    nativeProjectSyncFinishApplyError(requestId,
      "O manifesto confirmado do PC A nao esta mais disponivel.");
    return true;
  }
  g_nativeProjectSyncBundleWorkerCancel.store(false);
  g_nativeProjectSyncBundleWorkerRunning.store(true);
  try {
    const std::string projectDirectory =
      nativeProjectSyncParentPath(projectPath);
    std::string projectMediaDirectory =
      nativeTelepromptProjectMediaDirectory(project);
    if (projectMediaDirectory.empty()) {
      projectMediaDirectory = projectDirectory;
    }
    const std::string backupRoot = joinPath(
      normalizeSlashes(GetResourcePath_ptr ? GetResourcePath_ptr() : ""),
      "VS Hook/Project Sync/Backups");
    NativeProjectSyncApplyInput input{
      requestId, bundleId, descriptorPath, stagingRoot,
      projectPath, projectDirectory, projectMediaDirectory, backupRoot,
      changeCount, previousConfigSnapshot, previousConfigRevision,
      sourceManifest, automatic, differencePlan};
    g_nativeProjectSyncBundleWorker = std::thread([input]() {
      try {
        nativeProjectSyncApplyBundleWorker(input);
      } catch (...) {
        nativeProjectSyncFinishApplyError(input.requestId,
          "Erro inesperado ao validar o bundle.");
        g_nativeProjectSyncBundleWorkerRunning.store(false);
      }
    });
  } catch (...) {
    g_nativeProjectSyncBundleWorkerRunning.store(false);
    nativeProjectSyncFinishApplyError(requestId,
      "Nao foi possivel iniciar a validacao do bundle.");
  }
  g_nativeForceStateBuild.store(true);
  return true;
}

static std::string nativeProjectSyncNewApplyRequestId()
{
  const uint64_t seed = static_cast<uint64_t>(
    std::chrono::high_resolution_clock::now()
      .time_since_epoch().count()) ^
    static_cast<uint64_t>(reinterpret_cast<std::uintptr_t>(
      &g_nativeProjectSyncApply));
  std::mt19937_64 random(seed);
  std::ostringstream value;
  value << std::hex << std::setfill('0')
        << std::setw(16) << static_cast<unsigned long long>(random())
        << std::setw(16) << static_cast<unsigned long long>(random());
  return value.str();
}

static void nativeProjectSyncApplyConfigFromDiffModal()
{
  std::string role;
  std::string requestId;
  std::string remoteManifestRevision;
  std::string remoteManifest;
  std::string remoteConfigSnapshot;
  std::string remoteConfigRevision;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    role = g_nativeTimecodeLanProjectSyncRole;
    requestId = g_nativeProjectSyncPreflight.requestId;
    remoteManifestRevision =
      g_nativeProjectSyncPreflight.remoteManifestRevision;
    remoteManifest = g_nativeProjectSyncPreflight.remoteManifest;
    remoteConfigSnapshot =
      g_nativeProjectSyncPreflight.remoteConfigSnapshot;
    remoteConfigRevision =
      g_nativeProjectSyncPreflight.remoteConfigRevision;
  }
  if (role != "secondary") {
    nativeUiShowTemporaryPopup(
      "As configuracoes podem ser aplicadas somente no PC B.", 2.0);
    return;
  }
  if (remoteConfigSnapshot.empty() ||
      remoteConfigSnapshot.rfind(
        "VSHOOK_PROJECT_SYNC_CONFIG\t1", 0) != 0) {
    nativeUiShowTemporaryPopup(
      "O snapshot de configuracoes do PC A nao esta disponivel.", 2.0);
    return;
  }
  if (!ShowMessageBox_ptr) {
    nativeUiShowTemporaryPopup(
      "Nao foi possivel abrir a confirmacao de seguranca.", 2.0);
    return;
  }
  const int confirmation = ShowMessageBox_ptr(
    "Aplicar as configuracoes do PC A neste PC B?\n\n"
    "Somente as funcoes e preferencias do VS Hook serao copiadas. "
    "O projeto continuara aberto e nenhuma alteracao estrutural sera "
    "aplicada por esta acao.\n\nContinuar?",
    "Project Sync - Aplicar configuracoes", 4);
  if (confirmation != 6) return;

  if (remoteConfigRevision.empty()) {
    remoteConfigRevision =
      nativeProjectSyncHashText(remoteConfigSnapshot);
  }
  std::string error;
  if (!nativeProjectSyncApplyConfigSnapshot(
        remoteConfigSnapshot, remoteConfigRevision, error)) {
    g_nativeProjectSyncDiffModalHeadline = error.empty()
      ? "Nao foi possivel aplicar as configuracoes do PC A."
      : error;
    nativeUiShowTemporaryPopup(
      "Falha ao aplicar as configuracoes do PC A.", 2.0);
    if (nativeAppActivePanelIsOpen()) {
      InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
    }
    return;
  }

  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    // A escolha positiva vale para o restante deste pareamento: os snapshots
    // vivos seguintes do PC A passam a ser aceitos automaticamente.
    g_nativeProjectSyncConfigurationAuthorized = true;
  }
  nativeProjectSyncRefreshManifestOnMainThread(true);

  std::string localManifest;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    localManifest = g_nativeProjectSyncPreflight.manifest;
  }
  if (!remoteManifest.empty() && !localManifest.empty()) {
    NativeProjectSyncCompareResult result =
      nativeProjectSyncCompareManifests(remoteManifest, localManifest);
    result.configApplied = true;
    nativeProjectSyncBuildComparePresentation(result);
    nativeProjectSyncStorePreflightResult(
      requestId, result.ready, result.diffJson,
      remoteManifestRevision, remoteManifest, remoteConfigSnapshot);
    if ((result.structuralDifferenceCount > 0 ||
         result.configDifferenceCount > 0) &&
        g_nativeMainModalKind ==
          NativeMainModalKind::ProjectSyncDiff &&
        nativeAppActivePanelIsOpen()) {
      // Apenas atualiza a conferencia que o handshake ja abriu. Aplicar
      // configuracoes nunca pode ressuscitar o modal depois de ele fechar.
      nativeProjectSyncShowDiffModal(result.diffJson);
    } else {
      nativeUiCloseMainModal();
    }
  } else {
    nativeUiCloseMainModal();
  }
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiShowTemporaryPopup(
    "Configuracoes do PC A aplicadas no PC B.", 2.0);
}

static bool nativeProjectSyncApplyTimelineInPlace(
  ReaProject* project,
  const std::string& sourceManifest,
  std::string& errorOut);

static void nativeProjectSyncRequestApplyFromDiffModal()
{
  std::string role;
  std::string revision;
  std::string preflightRequestId;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    role = g_nativeTimecodeLanProjectSyncRole;
    revision = g_nativeProjectSyncPreflight.remoteManifestRevision;
    preflightRequestId = g_nativeProjectSyncPreflight.requestId;
  }
  if (role != "secondary") {
    nativeUiShowTemporaryPopup(
      "A aplicacao das modificacoes acontece somente no PC B.", 2.0);
    return;
  }
  if (!ShowMessageBox_ptr) {
    nativeUiShowTemporaryPopup(
      "Nao foi possivel abrir a confirmacao de seguranca.", 2.0);
    return;
  }
  const int confirmation = ShowMessageBox_ptr(
    "Aplicar as modificacoes do PC A neste PC B?\n\n"
    "O VS Hook vai baixar somente os arquivos que faltam, validar o pacote, "
    "e aplicar pistas, itens, plugins e timeline "
    "diretamente neste projeto aberto. O roteamento e as cores locais nao "
    "serao alterados. As configuracoes visuais continuam separadas.\n\n"
    "Continuar?",
    "Project Sync - Aplicar modificacoes", 4);
  if (confirmation != 6) return;
  bool applyConfigurations = false;
  if (g_nativeProjectSyncDiffModalConfigCount > 0) {
    const int configConfirmation = ShowMessageBox_ptr(
      "Tambem aplicar no PC B as configuracoes do VS Hook mostradas "
      "na conferencia?\n\nIsso inclui Personalizar, FaderOut, Multiloops "
      "e demais funcoes permitidas pelo Project Sync.\n\n"
      "Escolha Nao para manter as configuracoes atuais do PC B.",
      "Project Sync - Aplicar configuracoes", 4);
    applyConfigurations = configConfirmation == 6;
  }

  // Alteracoes que nao carregam ITEM/FX nao precisam criar snapshot, calcular
  // hashes ou percorrer a pasta de midia. O caminho leve abaixo aplica pistas,
  // timeline e configuracoes diretamente no projeto B. Somente diferencas que
  // realmente dependem de arquivos/chunks seguem para o bundle.
  std::string remoteManifest;
  std::string localManifest;
  std::string remoteConfigSnapshot;
  std::string remoteConfigRevision;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    remoteManifest = g_nativeProjectSyncPreflight.remoteManifest;
    localManifest = g_nativeProjectSyncPreflight.manifest;
    remoteConfigSnapshot =
      g_nativeProjectSyncPreflight.remoteConfigSnapshot;
    remoteConfigRevision =
      g_nativeProjectSyncPreflight.remoteConfigRevision;
  }
  const NativeProjectSyncParsedManifest remoteParsed =
    nativeProjectSyncParseManifest(remoteManifest);
  const NativeProjectSyncParsedManifest localParsed =
    nativeProjectSyncParseManifest(localManifest);
  NativeProjectSyncCompareResult currentComparison =
    nativeProjectSyncCompareManifests(remoteManifest, localManifest);
  bool requiresFileBundle = !remoteParsed.valid || !localParsed.valid;
  bool timelineDiffers = false;
  bool tracksDiffer = false;
  const auto categoryCount = [&](const char* category) {
    const auto found = currentComparison.categoryCounts.find(category);
    return found == currentComparison.categoryCounts.end()
      ? 0 : found->second;
  };
  requiresFileBundle = requiresFileBundle ||
    categoryCount("files") > 0 || categoryCount("plugins") > 0 ||
    categoryCount("project") > 0;
  tracksDiffer = categoryCount("tracks") > 0;
  timelineDiffers = categoryCount("regions") > 0 ||
    categoryCount("markers") > 0 ||
    categoryCount("tempoMarkers") > 0;

  if (!requiresFileBundle) {
    struct TrackTarget {
      int index = 0;
      std::string guid;
      std::string name;
      int folderDepth = 0;
      double volume = 1.0;
      bool mute = false;
      int solo = 0;
      MediaTrack* track = nullptr;
    };
    ReaProject* project = getCurrentProject(nullptr, 0);
    std::vector<TrackTarget> targets;
    bool directReady = project && CountTracks_ptr && GetTrack_ptr &&
      SetOnlyTrackSelected_ptr && ReorderSelectedTracks_ptr &&
      GetSetMediaTrackInfo_String_ptr && SetMediaTrackInfo_Value_ptr;
    if (directReady && tracksDiffer) {
      std::map<std::string, MediaTrack*> localTracks;
      const int localTrackCount = CountTracks_ptr(project);
      for (int index = 0; index < localTrackCount; ++index) {
        MediaTrack* track = GetTrack_ptr(project, index);
        if (track) {
          localTracks[nativeLower(nativeTrackGuid(track, index))] = track;
        }
      }
      for (const auto& record : remoteParsed.structural) {
        if (record.first.rfind("TRACK\t", 0) != 0) continue;
        std::vector<std::string> fields =
          nativeProjectSyncTsvFields(record.second);
        if (fields.size() != 9) {
          directReady = false;
          break;
        }
        for (size_t field = 1; field < fields.size(); ++field) {
          fields[field] = nativeUiBackupUnescape(fields[field]);
        }
        TrackTarget target;
        target.guid = nativeLower(nativeTrim(fields[1]));
        target.index = std::max(0, std::atoi(fields[2].c_str()) - 1);
        target.name = fields[3];
        target.folderDepth = std::atoi(fields[4].c_str());
        target.volume = std::atof(fields[6].c_str());
        target.mute = fields[7] == "1";
        target.solo = std::atoi(fields[8].c_str());
        const auto found = localTracks.find(target.guid);
        if (found == localTracks.end()) {
          directReady = false;
          break;
        }
        target.track = found->second;
        targets.push_back(std::move(target));
      }
      if (static_cast<int>(targets.size()) != localTrackCount) {
        directReady = false;
      }
      std::sort(targets.begin(), targets.end(),
        [](const TrackTarget& left, const TrackTarget& right) {
          return left.index < right.index;
        });
    }

    if (directReady) {
      std::string directError;
      if (Undo_BeginBlock2_ptr) Undo_BeginBlock2_ptr(project);
      if (PreventUIRefresh_ptr) PreventUIRefresh_ptr(1);
      bool directApplied = true;
      if (tracksDiffer) {
        for (size_t targetIndex = 0;
             targetIndex < targets.size(); ++targetIndex) {
          MediaTrack* track = targets[targetIndex].track;
          SetOnlyTrackSelected_ptr(track);
          if (!ReorderSelectedTracks_ptr(
                static_cast<int>(targetIndex), 0)) {
            directApplied = false;
            directError = "Nao foi possivel alinhar a ordem das pistas.";
            break;
          }
          track = GetTrack_ptr(project, static_cast<int>(targetIndex));
          std::vector<char> writableName(
            targets[targetIndex].name.begin(),
            targets[targetIndex].name.end());
          writableName.push_back('\0');
          if (!track || !GetSetMediaTrackInfo_String_ptr(
                track, "P_NAME", writableName.data(), true)) {
            directApplied = false;
            directError = "Nao foi possivel atualizar uma pista.";
            break;
          }
          SetMediaTrackInfo_Value_ptr(track, "I_FOLDERDEPTH",
            targets[targetIndex].folderDepth);
          SetMediaTrackInfo_Value_ptr(track, "D_VOL",
            targets[targetIndex].volume);
          SetMediaTrackInfo_Value_ptr(track, "B_MUTE",
            targets[targetIndex].mute ? 1.0 : 0.0);
          SetMediaTrackInfo_Value_ptr(track, "I_SOLO",
            targets[targetIndex].solo);
        }
      }
      if (directApplied && timelineDiffers) {
        directApplied = nativeProjectSyncApplyTimelineInPlace(
          project, remoteManifest, directError);
      }
      if (PreventUIRefresh_ptr) PreventUIRefresh_ptr(-1);
      if (Undo_EndBlock2_ptr) {
        Undo_EndBlock2_ptr(project,
          "VS Hook: aplicar diferencas do Project Sync", -1);
      }
      if (!directApplied) {
        if (Undo_DoUndo2_ptr) Undo_DoUndo2_ptr(project);
        nativeUiShowTemporaryPopup(
          directError.empty() ? "Falha ao aplicar as diferencas."
                              : directError, 2.5);
        return;
      }
      if (applyConfigurations && !remoteConfigSnapshot.empty()) {
        std::string configError;
        if (!nativeProjectSyncApplyConfigSnapshot(
              remoteConfigSnapshot, remoteConfigRevision, configError)) {
          if (Undo_DoUndo2_ptr) Undo_DoUndo2_ptr(project);
          nativeUiShowTemporaryPopup(
            configError.empty()
              ? "Falha ao aplicar as configuracoes."
              : configError, 2.5);
          return;
        }
        std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
        g_nativeProjectSyncConfigurationAuthorized = true;
      }
      if (MarkProjectDirty_ptr && (tracksDiffer || timelineDiffers)) {
        MarkProjectDirty_ptr(project);
      }
      if (TrackList_AdjustWindows_ptr) TrackList_AdjustWindows_ptr(false);
      if (UpdateTimeline_ptr) UpdateTimeline_ptr();
      if (UpdateArrange_ptr) UpdateArrange_ptr();
      nativeProjectSyncRefreshManifestOnMainThread(true);
      {
        std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
        localManifest = g_nativeProjectSyncPreflight.manifest;
      }
      NativeProjectSyncCompareResult refreshed =
        nativeProjectSyncCompareManifests(remoteManifest, localManifest);
      nativeProjectSyncBuildComparePresentation(refreshed);
      nativeProjectSyncStorePreflightResult(
        preflightRequestId, refreshed.ready, refreshed.diffJson,
        revision, remoteManifest, remoteConfigSnapshot);
      if (refreshed.differenceCount == 0) {
        nativeUiCloseMainModal();
      } else {
        nativeProjectSyncShowDiffModal(refreshed.diffJson);
      }
      g_nativeForceSnapshotBuild.store(true);
      g_nativeForceStateBuild.store(true);
      nativeUiShowTemporaryPopup(
        "Diferencas aplicadas no PC B.", 2.0);
      return;
    }
  }

  const std::string requestId =
    nativeProjectSyncRequestIdIsValid(preflightRequestId)
      ? preflightRequestId : nativeProjectSyncNewApplyRequestId();
  std::string differencePlan;
  if (!currentComparison.truncated) {
    std::set<std::string> planLines;
    for (const auto& difference : currentComparison.differences) {
      const std::string id = nativeLower(nativeTrim(difference.id));
      if (id.empty()) continue;
      if (difference.category == "files") {
        planLines.insert("ITEM\t" + id);
      } else if (difference.category == "tracks") {
        planLines.insert("TRACK\t" + id);
      } else if (difference.category == "plugins") {
        const std::string identity = "FX\t" + difference.id;
        const auto primary = remoteParsed.structural.find(identity);
        const auto secondary = localParsed.structural.find(identity);
        std::string selectedLine;
        if (primary != remoteParsed.structural.end()) {
          selectedLine = primary->second;
        } else if (secondary != localParsed.structural.end()) {
          selectedLine = secondary->second;
        }
        if (!selectedLine.empty()) {
          const std::vector<std::string> fields =
            nativeProjectSyncTsvFields(selectedLine);
          if (fields.size() == 9) {
            planLines.insert("FXTRACK\t" + nativeLower(nativeTrim(
              nativeUiBackupUnescape(fields[2]))));
          }
        }
      }
    }
    std::ostringstream encodedPlan;
    for (const auto& line : planLines) {
      if (encodedPlan.tellp() > 0) encodedPlan << '\n';
      encodedPlan << line;
    }
    differencePlan = encodedPlan.str();
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncApply = NativeProjectSyncApplyState{};
    g_nativeProjectSyncApply.state = "requested";
    g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
    g_nativeProjectSyncApply.requestId = requestId;
    g_nativeProjectSyncApply.revision = revision;
    g_nativeProjectSyncApply.sequence =
      ++g_nativeProjectSyncApplySequence;
    g_nativeProjectSyncApply.automatic = false;
    g_nativeProjectSyncApply.applyConfigurations = applyConfigurations;
    g_nativeProjectSyncApply.differencePlan = differencePlan;
    g_nativeProjectSyncConfigurationAuthorized = false;
  }
  g_nativeForceStateBuild.store(true);
  if (nativeAppActivePanelIsOpen()) {
    InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
  }
}

static void nativeProjectSyncRequestRoleHandoverFromDiffModal()
{
  std::string role;
  bool peerConnected = false;
  bool conferenceConnected = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    role = g_nativeTimecodeLanProjectSyncRole;
    peerConnected = g_nativeTimecodeLanPeerConnected;
    conferenceConnected = g_nativeProjectSyncPreflight.hasResult &&
      nativeProjectSyncRequestIdIsValid(
        g_nativeProjectSyncPreflight.requestId);
  }
  if (role != "primary" || (!peerConnected && !conferenceConnected)) {
    nativeUiShowTemporaryPopup(
      "A troca de mestre exige uma conferencia ativa entre o PC A e o PC B.",
      2.4);
    return;
  }
  if (!ShowMessageBox_ptr) return;
  const int answer = ShowMessageBox_ptr(
    "Transferir o controle mestre para o PC B?\n\n"
    "Este computador passara a ser o PC B Escravo e o outro computador "
    "assumira como PC A Mestre. O Project Sync continuara ativo e "
    "reconectara automaticamente.\n\nContinuar?",
    "Project Sync - Transferir mestre", 4);
  if (answer != 6) return;

  const std::string requestId = nativeProjectSyncHashText(
    "handover|" + std::to_string(nativeSystemNowMs()) + "|" +
    std::to_string(reinterpret_cast<std::uintptr_t>(
      &g_nativeProjectSyncRoleHandover)));
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    g_nativeProjectSyncRoleHandover.state = "requested";
    g_nativeProjectSyncRoleHandover.requestId = requestId;
    g_nativeProjectSyncRoleHandover.error.clear();
    g_nativeProjectSyncRoleHandover.updatedAtMs = nativeSteadyNowMs();
  }
  g_nativeForceStateBuild.store(true);
  nativeUiShowTemporaryPopup(
    "Transferindo o controle mestre para o PC B...", 2.0);
}

struct NativeProjectSyncRppSegment {
  std::string key;
  std::string text;
  bool block = false;
};

static std::string nativeProjectSyncRppLineKey(const std::string& line)
{
  const std::string trimmed = nativeTrim(line);
  if (trimmed.empty() || trimmed == ">") return {};
  size_t start = trimmed.front() == '<' ? 1 : 0;
  size_t end = start;
  while (end < trimmed.size() && trimmed[end] != ' ' &&
         trimmed[end] != '\t' && trimmed[end] != '\r' &&
         trimmed[end] != '\n') ++end;
  return nativeLower(trimmed.substr(start, end - start));
}

static std::vector<std::string> nativeProjectSyncRppTrackChunks(
  const std::string& rpp)
{
  std::vector<std::string> chunks;
  size_t position = 0;
  size_t trackStart = std::string::npos;
  int depth = 0;
  int trackParentDepth = -1;
  while (position < rpp.size()) {
    const size_t lineEnd = rpp.find('\n', position);
    const size_t afterLine = lineEnd == std::string::npos
      ? rpp.size() : lineEnd + 1;
    const std::string line = rpp.substr(position, afterLine - position);
    const std::string trimmed = nativeTrim(line);
    const bool opens = !trimmed.empty() && trimmed.front() == '<';
    const bool closes = trimmed == ">";
    if (trackStart == std::string::npos && opens &&
        nativeProjectSyncRppLineKey(trimmed) == "track") {
      trackStart = position;
      trackParentDepth = depth;
    }
    if (opens) ++depth;
    if (closes) depth = std::max(0, depth - 1);
    if (trackStart != std::string::npos && closes &&
        depth == trackParentDepth) {
      chunks.push_back(rpp.substr(trackStart, afterLine - trackStart));
      trackStart = std::string::npos;
      trackParentDepth = -1;
    }
    if (lineEnd == std::string::npos) break;
    position = afterLine;
  }
  return chunks;
}

static std::vector<NativeProjectSyncRppSegment>
nativeProjectSyncRppTrackSegments(const std::string& chunk)
{
  std::vector<NativeProjectSyncRppSegment> segments;
  size_t position = 0;
  int depth = 0;
  size_t blockStart = std::string::npos;
  std::string blockKey;
  while (position < chunk.size()) {
    const size_t lineEnd = chunk.find('\n', position);
    const size_t afterLine = lineEnd == std::string::npos
      ? chunk.size() : lineEnd + 1;
    const std::string line = chunk.substr(position, afterLine - position);
    const std::string trimmed = nativeTrim(line);
    const bool opens = !trimmed.empty() && trimmed.front() == '<';
    const bool closes = trimmed == ">";
    if (depth == 0 && opens) {
      segments.push_back({nativeProjectSyncRppLineKey(line), line, false});
      ++depth;
    } else if (depth == 1 && opens) {
      blockStart = position;
      blockKey = nativeProjectSyncRppLineKey(line);
      ++depth;
    } else {
      if (opens) ++depth;
      if (closes) {
        depth = std::max(0, depth - 1);
        if (blockStart != std::string::npos && depth == 1) {
          segments.push_back({blockKey,
            chunk.substr(blockStart, afterLine - blockStart), true});
          blockStart = std::string::npos;
          blockKey.clear();
        } else if (depth == 0) {
          segments.push_back({"", line, false});
        }
      } else if (depth == 1 && blockStart == std::string::npos) {
        segments.push_back({nativeProjectSyncRppLineKey(line), line, false});
      }
    }
    if (lineEnd == std::string::npos) break;
    position = afterLine;
  }
  return segments;
}

static std::string nativeProjectSyncRppNamedValue(
  const std::string& chunk,
  const std::string& wantedKey)
{
  for (const auto& segment : nativeProjectSyncRppTrackSegments(chunk)) {
    if (segment.block || segment.key != nativeLower(wantedKey)) continue;
    std::string value = nativeTrim(segment.text);
    const size_t separator = value.find_first_of(" \t");
    value = separator == std::string::npos
      ? std::string() : nativeTrim(value.substr(separator + 1));
    if (value.size() >= 2 && value.front() == '"' &&
        value.back() == '"') {
      value = value.substr(1, value.size() - 2);
      std::string decoded;
      decoded.reserve(value.size());
      bool escaped = false;
      for (char character : value) {
        if (escaped) {
          decoded.push_back(character);
          escaped = false;
        } else if (character == '\\') {
          escaped = true;
        } else {
          decoded.push_back(character);
        }
      }
      return decoded;
    }
    return value;
  }
  return {};
}

static std::string nativeProjectSyncRppTrackGuid(
  const std::string& chunk)
{
  const auto segments = nativeProjectSyncRppTrackSegments(chunk);
  if (segments.empty() || segments.front().key != "track") return {};
  std::string opening = nativeTrim(segments.front().text);
  const size_t separator = opening.find_first_of(" \t");
  if (separator == std::string::npos) return {};
  std::string value = nativeTrim(opening.substr(separator + 1));
  const size_t end = value.find_first_of(" \t\r\n");
  if (end != std::string::npos) value.resize(end);
  if (value.size() >= 2 && value.front() == '"' &&
      value.back() == '"') {
    value = value.substr(1, value.size() - 2);
  }
  return nativeLower(nativeTrim(value));
}

static std::string nativeProjectSyncMergeNumericLine(
  const std::string& sourceLine,
  const std::string& targetLine,
  size_t sourceFieldCount)
{
  const std::string sourceTrimmed = nativeTrim(sourceLine);
  const std::string targetTrimmed = nativeTrim(targetLine);
  const size_t sourceKeyEnd = sourceTrimmed.find_first_of(" \t");
  const size_t targetKeyEnd = targetTrimmed.find_first_of(" \t");
  if (sourceKeyEnd == std::string::npos ||
      targetKeyEnd == std::string::npos) return sourceLine;
  std::istringstream sourceValues(sourceTrimmed.substr(sourceKeyEnd + 1));
  std::istringstream targetValues(targetTrimmed.substr(targetKeyEnd + 1));
  std::vector<std::string> sourceFields;
  std::vector<std::string> targetFields;
  std::string field;
  while (sourceValues >> field) sourceFields.push_back(field);
  while (targetValues >> field) targetFields.push_back(field);
  if (sourceFields.size() < sourceFieldCount) return targetLine;
  if (targetFields.size() < sourceFields.size()) {
    targetFields.resize(sourceFields.size(), "0");
  }
  for (size_t index = 0; index < sourceFieldCount; ++index) {
    targetFields[index] = sourceFields[index];
  }
  const size_t indentCount = targetLine.find_first_not_of(" \t");
  std::ostringstream merged;
  merged << targetLine.substr(0,
    indentCount == std::string::npos ? 0 : indentCount)
         << targetTrimmed.substr(0, targetKeyEnd);
  for (const auto& value : targetFields) merged << ' ' << value;
  merged << '\n';
  return merged.str();
}

static bool nativeProjectSyncTrackChunkIsImportedBlock(
  const NativeProjectSyncRppSegment& segment)
{
  return segment.block &&
    (segment.key == "fxchain" || segment.key == "fxchain_rec" ||
     segment.key == "item");
}

static bool nativeProjectSyncTrackChunkIsRoutingLine(
  const NativeProjectSyncRppSegment& segment)
{
  if (segment.block) return false;
  return segment.key == "auxrecv" || segment.key == "auxsend" ||
    segment.key == "mainsend" || segment.key == "hwout" ||
    segment.key == "midiout" || segment.key == "nchan";
}

static std::string nativeProjectSyncRppItemGuid(
  const std::string& chunk)
{
  std::istringstream input(chunk);
  std::string line;
  while (std::getline(input, line)) {
    const std::string trimmed = nativeTrim(line);
    if (nativeLower(trimmed).rfind("guid ", 0) == 0) {
      return nativeLower(nativeTrim(trimmed.substr(5)));
    }
  }
  return {};
}

static std::string nativeProjectSyncMergeTrackChunk(
  const std::string& source,
  const std::string& target,
  const NativeProjectSyncDifferencePlan* differencePlan = nullptr)
{
  const auto sourceSegments = nativeProjectSyncRppTrackSegments(source);
  const auto targetSegments = nativeProjectSyncRppTrackSegments(target);
  if (sourceSegments.size() < 2 || targetSegments.size() < 2) return {};
  const bool scoped = differencePlan && differencePlan->scoped;
  const std::string sourceTrackGuid =
    nativeProjectSyncRppTrackGuid(source);
  const bool importTrackMetadata = !scoped ||
    differencePlan->trackIds.count(sourceTrackGuid) != 0;
  const bool importFx = !scoped || importTrackMetadata ||
    differencePlan->fxTrackIds.count(sourceTrackGuid) != 0;
  std::map<std::string, std::string> sourceLines;
  std::vector<std::string> sourceFxBlocks;
  std::vector<std::string> sourceItemBlocks;
  std::map<std::string, std::string> targetItemsByGuid;
  std::vector<std::pair<std::string, std::string>> targetItemBlocks;
  std::vector<std::string> targetFxBlocks;
  for (const auto& segment : sourceSegments) {
    if (segment.block &&
        (segment.key == "fxchain" || segment.key == "fxchain_rec")) {
      sourceFxBlocks.push_back(segment.text);
    } else if (segment.block && segment.key == "item") {
      sourceItemBlocks.push_back(segment.text);
    } else if (!segment.block && !segment.key.empty()) {
      sourceLines[segment.key] = segment.text;
    }
  }
  for (const auto& segment : targetSegments) {
    if (segment.block &&
        (segment.key == "fxchain" || segment.key == "fxchain_rec")) {
      targetFxBlocks.push_back(segment.text);
    } else if (segment.block && segment.key == "item") {
      const std::string id = nativeProjectSyncRppItemGuid(segment.text);
      targetItemBlocks.push_back({id, segment.text});
      if (!id.empty()) targetItemsByGuid[id] = segment.text;
    }
  }
  bool wroteName = false;
  bool wroteFolder = false;
  bool wroteTrackId = false;
  bool wroteVolume = false;
  bool wroteMuteSolo = false;
  std::ostringstream result;
  result << sourceSegments.front().text;
  for (size_t index = 1; index + 1 < targetSegments.size(); ++index) {
    const auto& segment = targetSegments[index];
    if (nativeProjectSyncTrackChunkIsImportedBlock(segment)) continue;
    const auto replacement = sourceLines.find(segment.key);
    if (segment.key == "name" || segment.key == "isbus" ||
        segment.key == "trackid") {
      result << (importTrackMetadata && replacement != sourceLines.end()
        ? replacement->second : segment.text);
      if (segment.key == "name") wroteName = true;
      else if (segment.key == "isbus") wroteFolder = true;
      else wroteTrackId = true;
    } else if (segment.key == "volpan" &&
               importTrackMetadata && replacement != sourceLines.end()) {
      // D_VOL é o primeiro campo. PAN e os demais parâmetros continuam B.
      result << nativeProjectSyncMergeNumericLine(
        replacement->second, segment.text, 1);
      wroteVolume = true;
    } else if (segment.key == "mutesolo" &&
               importTrackMetadata && replacement != sourceLines.end()) {
      // B_MUTE e I_SOLO são os dois primeiros campos.
      result << nativeProjectSyncMergeNumericLine(
        replacement->second, segment.text, 2);
      wroteMuteSolo = true;
    } else {
      // Inclui PEAKCOL e todas as linhas de routing do próprio PC B.
      result << segment.text;
    }
  }
  // Alguns projetos antigos podem omitir uma linha opcional no chunk do PC B.
  // Nesse caso insere apenas os campos comportamentais autorizados; nunca
  // completa o chunk com linhas de routing vindas do PC A.
  for (const auto& key : {std::string("name"), std::string("isbus"),
                         std::string("trackid")}) {
    const bool written = key == "name" ? wroteName
      : (key == "isbus" ? wroteFolder : wroteTrackId);
    const auto sourceLine = sourceLines.find(key);
    if (importTrackMetadata && !written &&
        sourceLine != sourceLines.end()) {
      result << sourceLine->second;
    }
  }
  if (importTrackMetadata && !wroteVolume) {
    const auto sourceLine = sourceLines.find("volpan");
    if (sourceLine != sourceLines.end()) result << sourceLine->second;
  }
  if (importTrackMetadata && !wroteMuteSolo) {
    const auto sourceLine = sourceLines.find("mutesolo");
    if (sourceLine != sourceLines.end()) result << sourceLine->second;
  }
  for (const auto& block : (importFx ? sourceFxBlocks : targetFxBlocks)) {
    result << block;
  }
  std::set<std::string> sourceItemIds;
  for (const auto& block : sourceItemBlocks) {
    const std::string id = nativeProjectSyncRppItemGuid(block);
    if (!id.empty()) sourceItemIds.insert(id);
    if (!scoped || (!id.empty() &&
        differencePlan->itemIds.count(id) != 0)) {
      result << block;
      continue;
    }
    const auto local = targetItemsByGuid.find(id);
    if (local != targetItemsByGuid.end()) result << local->second;
  }
  if (scoped) {
    for (const auto& local : targetItemBlocks) {
      if (!local.first.empty() && sourceItemIds.count(local.first) != 0) {
        continue;
      }
      // Item extra so e removido se ele aparece explicitamente no plano.
      if (!local.first.empty() &&
          differencePlan->itemIds.count(local.first) != 0) {
        continue;
      }
      result << local.second;
    }
  }
  result << targetSegments.back().text;
  return result.str();
}

static std::string nativeProjectSyncSanitizeNewTrackChunk(
  const std::string& source)
{
  const auto segments = nativeProjectSyncRppTrackSegments(source);
  if (segments.size() < 2) return {};
  std::ostringstream result;
  for (const auto& segment : segments) {
    if (!nativeProjectSyncTrackChunkIsRoutingLine(segment)) {
      result << segment.text;
    }
  }
  return result.str();
}

static bool nativeProjectSyncReadTrackChunk(
  MediaTrack* track,
  std::string& chunkOut)
{
  if (!track || !GetTrackStateChunk_ptr) return false;
  for (const size_t size : {size_t(1024 * 1024),
                            size_t(8 * 1024 * 1024),
                            size_t(32 * 1024 * 1024),
                            size_t(128 * 1024 * 1024)}) {
    std::vector<char> buffer(size, '\0');
    if (GetTrackStateChunk_ptr(
          track, buffer.data(), static_cast<int>(buffer.size()), false)) {
      chunkOut.assign(buffer.data());
      return !chunkOut.empty();
    }
  }
  return false;
}

static bool nativeProjectSyncApplyTracksInPlace(
  ReaProject* project,
  const std::string& sourceRpp,
  std::string& errorOut,
  const NativeProjectSyncDifferencePlan* differencePlan = nullptr)
{
  if (!project || !CountTracks_ptr || !GetTrack_ptr ||
      !InsertTrackAtIndex_ptr || !DeleteTrack_ptr ||
      !SetOnlyTrackSelected_ptr || !ReorderSelectedTracks_ptr ||
      !SetTrackStateChunk_ptr || !GetTrackStateChunk_ptr) {
    errorOut = "O REAPER nao disponibilizou as APIs de pistas para aplicar no projeto aberto.";
    return false;
  }
  const std::vector<std::string> sourceChunks =
    nativeProjectSyncRppTrackChunks(sourceRpp);
  if (sourceChunks.empty() && CountTracks_ptr(project) > 0) {
    errorOut = "O snapshot do PC A nao contem pistas validas.";
    return false;
  }
  std::vector<MediaTrack*> originalTracks;
  std::map<std::string, MediaTrack*> byGuid;
  std::multimap<std::string, MediaTrack*> byName;
  const int originalCount = CountTracks_ptr(project);
  for (int index = 0; index < originalCount; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (!track) continue;
    originalTracks.push_back(track);
    byGuid[nativeLower(nativeTrackGuid(track, index))] = track;
    byName.emplace(nativeLower(nativeTrim(nativeTrackName(track, index))), track);
  }
  std::set<MediaTrack*> used;
  for (size_t sourceIndex = 0; sourceIndex < sourceChunks.size();
       ++sourceIndex) {
    const std::string& sourceChunk = sourceChunks[sourceIndex];
    const auto sourceSegments = nativeProjectSyncRppTrackSegments(sourceChunk);
    std::string sourceGuid = nativeProjectSyncRppTrackGuid(sourceChunk);
    if (sourceGuid.empty()) {
      sourceGuid = nativeLower(nativeTrim(
        nativeProjectSyncRppNamedValue(sourceChunk, "trackid")));
    }
    const std::string sourceName = nativeLower(nativeTrim(
      nativeProjectSyncRppNamedValue(sourceChunk, "name")));
    MediaTrack* target = nullptr;
    const auto byGuidMatch = byGuid.find(sourceGuid);
    if (!sourceGuid.empty() && byGuidMatch != byGuid.end() &&
        used.count(byGuidMatch->second) == 0) {
      target = byGuidMatch->second;
    }
    if (!target && !sourceName.empty()) {
      const auto range = byName.equal_range(sourceName);
      MediaTrack* only = nullptr;
      int available = 0;
      for (auto it = range.first; it != range.second; ++it) {
        if (used.count(it->second) == 0) {
          only = it->second;
          ++available;
        }
      }
      if (available == 1) target = only;
    }
    const bool created = target == nullptr;
    if (created) {
      InsertTrackAtIndex_ptr(static_cast<int>(sourceIndex), true);
      target = GetTrack_ptr(project, static_cast<int>(sourceIndex));
      if (!target) {
        errorOut = "Nao foi possivel criar uma pista que falta no PC B.";
        return false;
      }
    } else {
      SetOnlyTrackSelected_ptr(target);
      if (!ReorderSelectedTracks_ptr(
            static_cast<int>(sourceIndex), 0)) {
        errorOut = "Nao foi possivel alinhar a ordem das pistas no PC B.";
        return false;
      }
      target = GetTrack_ptr(project, static_cast<int>(sourceIndex));
    }
    if (!target) {
      errorOut = "A pista de destino deixou de existir durante a aplicacao.";
      return false;
    }
    std::string finalChunk;
    if (created) {
      finalChunk = nativeProjectSyncSanitizeNewTrackChunk(sourceChunk);
    } else {
      std::string targetChunk;
      if (!nativeProjectSyncReadTrackChunk(target, targetChunk)) {
        errorOut = "Nao foi possivel preservar o estado local de uma pista do PC B.";
        return false;
      }
      finalChunk = nativeProjectSyncMergeTrackChunk(
        sourceChunk, targetChunk, differencePlan);
    }
    if (finalChunk.empty() ||
        !SetTrackStateChunk_ptr(target, finalChunk.c_str(), false)) {
      errorOut = "O REAPER recusou a atualizacao de uma pista no projeto aberto.";
      return false;
    }
    used.insert(target);
  }
  for (int index = CountTracks_ptr(project) - 1;
       index >= static_cast<int>(sourceChunks.size()); --index) {
    MediaTrack* extra = GetTrack_ptr(project, index);
    if (!extra) continue;
    if (differencePlan && differencePlan->scoped) {
      const std::string extraId = nativeLower(
        nativeTrackGuid(extra, index));
      if (differencePlan->trackIds.count(extraId) == 0) continue;
    }
    DeleteTrack_ptr(extra);
  }
  return true;
}

struct NativeProjectSyncTimelineEntry {
  bool region = false;
  double start = 0.0;
  double end = 0.0;
  int number = -1;
  int color = 0;
  int lane = -1;
  std::string name;
  std::string guid;
};

static std::string nativeProjectSyncTimelineIdentity(
  bool region,
  int number,
  int occurrence)
{
  return std::string(region ? "region_" : "marker_") +
    std::to_string(number) + "_" + std::to_string(occurrence);
}

static bool nativeProjectSyncParseTimelineFromManifest(
  const std::string& manifest,
  std::vector<NativeProjectSyncTimelineEntry>& timelineOut,
  std::vector<std::vector<std::string>>& tempoOut,
  std::string& errorOut)
{
  timelineOut.clear();
  tempoOut.clear();
  const NativeProjectSyncParsedManifest parsed =
    nativeProjectSyncParseManifest(manifest);
  if (!parsed.valid) {
    errorOut = "O manifesto do PC A ficou invalido: " + parsed.error;
    return false;
  }
  for (const auto& record : parsed.structural) {
    const std::vector<std::string> fields =
      nativeProjectSyncTsvFields(record.second);
    if ((fields[0] == "REGION" && fields.size() == 8) ||
        (fields[0] == "MARKER" && fields.size() == 7)) {
      NativeProjectSyncTimelineEntry entry;
      entry.region = fields[0] == "REGION";
      entry.guid = nativeUiBackupUnescape(fields[1]);
      entry.number = std::atoi(fields[2].c_str());
      entry.name = nativeUiBackupUnescape(fields[3]);
      entry.start = std::atof(fields[4].c_str());
      const size_t colorIndex = entry.region ? 6 : 5;
      const size_t laneIndex = entry.region ? 7 : 6;
      entry.end = entry.region
        ? std::atof(fields[5].c_str()) : entry.start;
      entry.color = std::atoi(fields[colorIndex].c_str());
      entry.lane = std::atoi(fields[laneIndex].c_str());
      timelineOut.push_back(std::move(entry));
    } else if (fields[0] == "TEMPO" && fields.size() == 9) {
      tempoOut.push_back(fields);
    }
  }
  std::sort(timelineOut.begin(), timelineOut.end(),
    [](const auto& left, const auto& right) {
      if (left.start != right.start) return left.start < right.start;
      if (left.region != right.region) return left.region < right.region;
      return left.number < right.number;
    });
  std::sort(tempoOut.begin(), tempoOut.end(),
    [](const auto& left, const auto& right) {
      return std::atof(left[2].c_str()) < std::atof(right[2].c_str());
    });
  return true;
}

static bool nativeProjectSyncApplyTimelineInPlace(
  ReaProject* project,
  const std::string& sourceManifest,
  std::string& errorOut)
{
  if (!project || !CountProjectMarkers_ptr || !EnumProjectMarkers3_ptr ||
      !DeleteProjectMarkerByIndex_ptr || !AddProjectMarker2_ptr ||
      !CountTempoTimeSigMarkers_ptr || !DeleteTempoTimeSigMarker_ptr ||
      !SetTempoTimeSigMarker_ptr) {
    errorOut = "O REAPER nao disponibilizou as APIs da timeline.";
    return false;
  }
  std::vector<NativeProjectSyncTimelineEntry> sourceTimeline;
  std::vector<std::vector<std::string>> sourceTempo;
  if (!nativeProjectSyncParseTimelineFromManifest(
        sourceManifest, sourceTimeline, sourceTempo, errorOut)) {
    return false;
  }

  // Os itens precisam permanecer ancorados em tempo enquanto o mapa de tempo
  // e recriado. Regioes e marcadores comuns sao aplicados somente DEPOIS do
  // mapa definitivo; caso contrario o REAPER pode reposiciona-los ao converter
  // o mapa de tempo e eles chegam no PC B em outro ponto do grid.
  // Independentemente de sucesso ou falha, a saida obrigatoria e Beats
  // (position, length, rate).
  if (!nativeSetProjectItemsTimebase(project, 0)) {
    errorOut =
      "Nao foi possivel mudar o timebase para Time antes dos marcadores de tempo.";
    return false;
  }
  bool tempoApplied = true;
  for (int index = CountTempoTimeSigMarkers_ptr(project) - 1;
       index >= 0; --index) {
    if (!DeleteTempoTimeSigMarker_ptr(project, index)) {
      errorOut = "Nao foi possivel atualizar os marcadores de tempo no PC B.";
      tempoApplied = false;
      break;
    }
  }
  if (tempoApplied) {
    for (const auto& fields : sourceTempo) {
      if (!SetTempoTimeSigMarker_ptr(project, -1,
            std::atof(fields[2].c_str()), std::atoi(fields[3].c_str()),
            std::atof(fields[4].c_str()), std::atof(fields[5].c_str()),
            std::atoi(fields[6].c_str()), std::atoi(fields[7].c_str()),
            fields[8] == "1")) {
        errorOut = "Nao foi possivel recriar um marcador de tempo no PC B.";
        tempoApplied = false;
        break;
      }
    }
  }
  const bool restoredBeats = nativeSetProjectItemsTimebase(project, 1);
  if (!restoredBeats) {
    errorOut = tempoApplied
      ? "Os marcadores de tempo foram criados, mas o projeto nao voltou para Beats."
      : errorOut + " O projeto tambem nao voltou para Beats.";
    return false;
  }
  if (!tempoApplied) return false;

  // Cor e faixa visual nao participam do Project Sync. Marcadores/regioes ja
  // existentes sao atualizados no lugar para preservar esses atributos locais.
  struct LocalTimelineEntry {
    int enumIndex = -1;
    bool region = false;
    int number = -1;
    int color = 0;
    std::string identity;
  };
  std::vector<LocalTimelineEntry> localTimeline;
  std::map<std::string, LocalTimelineEntry> localByIdentity;
  std::map<std::string, int> identityOccurrences;
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  for (int enumIndex = 0; enumIndex < total; ++enumIndex) {
    bool region = false;
    double start = 0.0;
    double end = 0.0;
    const char* rawName = nullptr;
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, enumIndex, &region,
          &start, &end, &rawName, &number, &color)) continue;
    const std::string base = std::string(region ? "region_" : "marker_") +
      std::to_string(number);
    const std::string identity = nativeProjectSyncTimelineIdentity(
      region, number, ++identityOccurrences[base]);
    LocalTimelineEntry local;
    local.enumIndex = enumIndex;
    local.region = region;
    local.number = number;
    local.color = color;
    local.identity = identity;
    localTimeline.push_back(local);
    localByIdentity[identity] = local;
  }

  std::set<std::string> sourceIdentities;
  std::vector<NativeProjectSyncTimelineEntry> missingTimeline;
  for (const auto& entry : sourceTimeline) {
    sourceIdentities.insert(entry.guid);
    const auto local = localByIdentity.find(entry.guid);
    if (local != localByIdentity.end()) {
      if (!SetProjectMarkerByIndex2_ptr ||
          !SetProjectMarkerByIndex2_ptr(project, local->second.enumIndex,
            entry.region, entry.start, entry.end, entry.number,
            entry.name.c_str(), local->second.color, 2)) {
        errorOut = "Nao foi possivel atualizar uma regiao ou marcador no PC B.";
        return false;
      }
    } else {
      missingTimeline.push_back(entry);
    }
  }
  for (auto it = localTimeline.rbegin(); it != localTimeline.rend(); ++it) {
    if (sourceIdentities.count(it->identity) != 0) continue;
    if (!DeleteProjectMarkerByIndex_ptr(project, it->enumIndex)) {
      errorOut = "Nao foi possivel remover uma regiao ou marcador extra do PC B.";
      return false;
    }
  }
  if (SetProjectMarkerByIndex2_ptr) {
    SetProjectMarkerByIndex2_ptr(
      project, -1, false, 0.0, 0.0, -1, nullptr, 0, 2);
  }
  for (const auto& entry : missingTimeline) {
    const int markerNumber = AddProjectMarker2_ptr(project, entry.region,
      entry.start, entry.end, entry.name.c_str(), entry.number, 0);
    if (markerNumber < 0) {
      errorOut = "Nao foi possivel criar uma regiao ou marcador no PC B.";
      return false;
    }
  }
  return true;
}

static void nativeProjectSyncCommitPendingOpenOnMainThread()
{
  nativeProjectSyncJoinFinishedBundleWorker();
  NativeProjectSyncPendingOpen pending;
  bool applyConfigurations = false;
  std::string remoteConfigSnapshot;
  std::string remoteConfigRevision;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (!g_nativeProjectSyncPendingOpen.ready) return;
    pending = g_nativeProjectSyncPendingOpen;
    if (g_nativeProjectSyncApply.requestId == pending.requestId) {
      g_nativeProjectSyncApply.state = "applying";
      g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
      applyConfigurations =
        g_nativeProjectSyncApply.applyConfigurations;
      remoteConfigSnapshot =
        g_nativeProjectSyncPreflight.remoteConfigSnapshot;
      remoteConfigRevision =
        g_nativeProjectSyncPreflight.remoteConfigRevision;
    }
  }
  char currentPathBuffer[8192] = "";
  ReaProject* project = getCurrentProject(currentPathBuffer,
    static_cast<int>(sizeof(currentPathBuffer)));
  const std::string currentPath = normalizeSlashes(
    nativeTrim(currentPathBuffer));
  if (!project || !IsProjectDirty_ptr ||
      !GetProjectStateChangeCount_ptr ||
      !nativeProjectSyncPathEquals(
        currentPath, pending.originalProjectPath) ||
      (!pending.automatic &&
       GetProjectStateChangeCount_ptr(project) !=
         pending.originalProjectChangeCount) ||
      !pending.backupReady || !fileExists(pending.backupPath) ||
      pending.inPlaceProjectText.empty() ||
      pending.sourceManifest.empty()) {
    nativeProjectSyncFinishApplyError(pending.requestId,
      "O projeto do PC B mudou durante o download ou a preparacao nao foi concluida.");
    return;
  }
  std::string error;
  if (!Undo_BeginBlock2_ptr || !Undo_EndBlock2_ptr ||
      !Undo_DoUndo2_ptr) {
    nativeProjectSyncFinishApplyError(pending.requestId,
      "O REAPER nao disponibilizou a transacao Undo para aplicar com seguranca.");
    return;
  }
  Undo_BeginBlock2_ptr(project);
  if (PreventUIRefresh_ptr) PreventUIRefresh_ptr(1);
  const NativeProjectSyncDifferencePlan differencePlan =
    nativeProjectSyncParseDifferencePlan(pending.differencePlan);
  bool applied = nativeProjectSyncApplyTracksInPlace(
    project, pending.inPlaceProjectText, error,
    differencePlan.scoped ? &differencePlan : nullptr);
  if (applied && !pending.automatic) {
    applied = nativeProjectSyncApplyTimelineInPlace(
      project, pending.sourceManifest, error);
  }
  if (PreventUIRefresh_ptr) PreventUIRefresh_ptr(-1);
  Undo_EndBlock2_ptr(project,
    "VS Hook: aplicar modificacoes do Project Sync", -1);
  if (!applied) {
    Undo_DoUndo2_ptr(project);
    if (UpdateTimeline_ptr) UpdateTimeline_ptr();
    if (TrackList_AdjustWindows_ptr) TrackList_AdjustWindows_ptr(false);
    if (UpdateArrange_ptr) UpdateArrange_ptr();
    nativeProjectSyncFinishApplyError(pending.requestId,
      error.empty()
        ? "Falha ao aplicar modificacoes no projeto aberto. O Undo restaurou o PC B."
        : error + " O Undo restaurou o PC B.");
    return;
  }
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  if (UpdateTimeline_ptr) UpdateTimeline_ptr();
  if (TrackList_AdjustWindows_ptr) TrackList_AdjustWindows_ptr(false);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  nativeProjectSyncScheduleMissingPeaks();

  bool configurationsApplied = false;
  std::string configurationError;
  if (applyConfigurations && !remoteConfigSnapshot.empty()) {
    if (remoteConfigRevision.empty()) {
      remoteConfigRevision =
        nativeProjectSyncHashText(remoteConfigSnapshot);
    }
    configurationsApplied = nativeProjectSyncApplyConfigSnapshot(
      remoteConfigSnapshot, remoteConfigRevision, configurationError);
    if (configurationsApplied) {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      g_nativeProjectSyncConfigurationAuthorized = true;
    }
  }
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    if (g_nativeProjectSyncApply.requestId == pending.requestId) {
      g_nativeProjectSyncApply.state = "applied";
      g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
      g_nativeProjectSyncApply.revision =
        pending.sourceManifestRevision;
      g_nativeProjectSyncApply.error.clear();
    }
    g_nativeProjectSyncPendingOpen = NativeProjectSyncPendingOpen{};
    // O mesmo preflight permanece vivo depois da aplicacao. Zera-lo fazia a
    // Hook Center iniciar outro pareamento e reabrir a conferencia para as
    // mesmas diferencas que acabaram de ser tratadas.
  }
  g_nativeProjectSyncStructuralManifest.clear();
  g_nativeProjectSyncManifestProject = nullptr;
  g_nativeProjectSyncManifestChangeCount = -1;
  g_nativeProjectSyncManifestProjectSignature.clear();
  g_nativeProjectSyncLastManifestRefresh =
    std::chrono::steady_clock::time_point{};
  nativeProjectSyncRefreshManifestOnMainThread(true);
  std::string remoteManifest;
  std::string localManifest;
  std::string requestId;
  std::string remoteManifestRevision;
  std::string storedRemoteConfigSnapshot;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    remoteManifest = g_nativeProjectSyncPreflight.remoteManifest;
    localManifest = g_nativeProjectSyncPreflight.manifest;
    requestId = g_nativeProjectSyncPreflight.requestId;
    remoteManifestRevision =
      g_nativeProjectSyncPreflight.remoteManifestRevision;
    storedRemoteConfigSnapshot =
      g_nativeProjectSyncPreflight.remoteConfigSnapshot;
  }
  if (!remoteManifest.empty() && !localManifest.empty() &&
      nativeProjectSyncRequestIdIsValid(requestId)) {
    NativeProjectSyncCompareResult result =
      nativeProjectSyncCompareManifests(remoteManifest, localManifest);
    result.configApplied = configurationsApplied ||
      result.configDifferenceCount == 0;
    nativeProjectSyncBuildComparePresentation(result);
    nativeProjectSyncStorePreflightResult(
      requestId, result.ready, result.diffJson,
      remoteManifestRevision, remoteManifest,
      storedRemoteConfigSnapshot);
  }
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiCloseMainModal();
  bool queuedAutomatic = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    const std::string queuedPlan =
      g_nativeProjectSyncQueuedAutomaticPlan;
    const std::string queuedRevision =
      g_nativeProjectSyncQueuedAutomaticRevision;
    const std::string queuedRequestId =
      g_nativeProjectSyncPreflight.requestId;
    if (!queuedPlan.empty() &&
        nativeProjectSyncRequestIdIsValid(queuedRequestId) &&
        g_nativeTimecodeLanMode == "project_sync" &&
        g_nativeTimecodeLanProjectSyncRole == "secondary") {
      g_nativeProjectSyncApply = NativeProjectSyncApplyState{};
      g_nativeProjectSyncApply.state = "requested";
      g_nativeProjectSyncApply.stateUpdatedAtMs = nativeSteadyNowMs();
      g_nativeProjectSyncApply.requestId = queuedRequestId;
      g_nativeProjectSyncApply.revision = queuedRevision;
      g_nativeProjectSyncApply.sequence =
        ++g_nativeProjectSyncApplySequence;
      g_nativeProjectSyncApply.automatic = true;
      g_nativeProjectSyncApply.differencePlan = queuedPlan;
      g_nativeProjectSyncQueuedAutomaticPlan.clear();
      g_nativeProjectSyncQueuedAutomaticRevision.clear();
      queuedAutomatic = true;
    }
  }
  if (queuedAutomatic) g_nativeForceStateBuild.store(true);
  if (applyConfigurations && !configurationsApplied) {
    nativeUiShowTemporaryPopup(
      configurationError.empty()
        ? "Projeto aplicado; as configuracoes nao puderam ser copiadas."
        : "Projeto aplicado; falha ao copiar configuracoes do PC A.",
      3.2);
  } else {
    nativeUiShowTemporaryPopup(
      configurationsApplied
        ? "Projeto e configuracoes aplicados."
        : "Modificacoes aplicadas no projeto aberto.",
      2.8);
  }
}

static bool nativeApplyProjectSyncCommand(
  const std::string& commandBody)
{
  const std::string type = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "type")));
  if (type != "project_sync_preflight" &&
      type != "project_sync_config_snapshot" &&
      type != "project_sync_prepare_bundle" &&
      type != "project_sync_bundle_consumed" &&
      type != "project_sync_bundle_progress" &&
      type != "project_sync_apply_bundle" &&
      type != "project_sync_role_handover" &&
      type != "project_sync_role_handover_state") {
    return false;
  }
  const std::string preflightPhase = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "phase")));
  // Regra dura: um diagnostico recebido durante heartbeat/live sync nunca
  // toma o foco nem reabre a conferencia. Somente o handshake explicito pode
  // autorizar a UI; o resultado continua salvo no status para o relay.
  const bool showConference = type == "project_sync_preflight" &&
    (nativeJsonBoolValue(commandBody, "showConference", false) ||
     preflightPhase == "pairing");

  std::string localMode;
  std::string localRole;
  {
    std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
    localMode = g_nativeTimecodeLanMode;
    localRole = g_nativeTimecodeLanProjectSyncRole;
  }
  if (localMode != "project_sync") return true;

  if (type == "project_sync_role_handover_state") {
    const std::string state = nativeLower(nativeTrim(
      nativeJsonExtractString(commandBody, "state")));
    const std::string requestId = nativeTrim(
      nativeJsonExtractString(commandBody, "requestId"));
    const std::string error = nativeTrim(
      nativeJsonExtractString(commandBody, "error"));
    if (state == "completed" || state == "error") {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      g_nativeProjectSyncRoleHandover.state = state;
      g_nativeProjectSyncRoleHandover.requestId = requestId;
      g_nativeProjectSyncRoleHandover.error = error;
      g_nativeProjectSyncRoleHandover.updatedAtMs = nativeSteadyNowMs();
      g_nativeForceStateBuild.store(true);
    }
    return true;
  }

  if (type == "project_sync_role_handover") {
    const std::string targetRole = nativeLower(nativeTrim(
      nativeJsonExtractString(commandBody, "role")));
    const std::string requestId = nativeTrim(
      nativeJsonExtractString(commandBody, "requestId"));
    if ((targetRole != "primary" && targetRole != "secondary") ||
        !SetExtState_ptr) return true;
    SetExtState_ptr(kExtStateSection, kProjectSyncRoleKey,
      targetRole.c_str(), true);
    nativeTimecodeLanRefreshConfigOnMainThread();
    {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      g_nativeProjectSyncRoleHandover.state = "completed";
      g_nativeProjectSyncRoleHandover.requestId = requestId;
      g_nativeProjectSyncRoleHandover.error.clear();
      g_nativeProjectSyncRoleHandover.updatedAtMs = nativeSteadyNowMs();
    }
    g_nativeForceStateBuild.store(true);
    nativeUiShowTemporaryPopup(
      targetRole == "primary"
        ? "Este computador agora e o PC A Mestre. Reconectando..."
        : "Este computador agora e o PC B Escravo. Reconectando...",
      2.4);
    return true;
  }

  if (type == "project_sync_prepare_bundle") {
    return nativeProjectSyncPrepareBundleFromCommand(commandBody);
  }
  if (type == "project_sync_bundle_consumed") {
    return nativeProjectSyncConsumeBundleFromCommand(commandBody);
  }
  if (type == "project_sync_bundle_progress") {
    return nativeProjectSyncUpdateApplyProgressFromCommand(commandBody);
  }
  if (type == "project_sync_apply_bundle") {
    return nativeProjectSyncApplyBundleFromCommand(commandBody);
  }

  if (type == "project_sync_config_snapshot") {
    if (localRole != "secondary") return true;
    {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      if (!g_nativeProjectSyncConfigurationAuthorized) {
        // O snapshot inicial continua no manifesto/diff para o usuario decidir.
        // Somente depois de confirmar Aplicar configuracoes o fluxo ao vivo
        // volta a aceitar configuracoes do PC A automaticamente.
        return true;
      }
    }
    const std::string snapshot =
      nativeJsonExtractString(commandBody, "snapshot");
    const std::string announcedRevision = nativeTrim(
      nativeJsonExtractString(commandBody, "revision"));
    if (snapshot.empty() || snapshot.size() > 384 * 1024) return true;
    const std::string revision =
      nativeProjectSyncHashText(snapshot);
    if (!announcedRevision.empty() &&
        nativeLower(announcedRevision) != nativeLower(revision)) {
      return true;
    }
    if (revision == g_nativeProjectSyncLastAppliedConfigRevision) {
      return true;
    }
    const std::string localSnapshot =
      nativeProjectSyncBuildConfigSnapshot();
    if (nativeProjectSyncHashText(localSnapshot) == revision) {
      g_nativeProjectSyncLastAppliedConfigRevision = revision;
      return true;
    }
    std::string error;
    if (nativeProjectSyncApplyConfigSnapshot(
          snapshot, revision, error)) {
      nativeProjectSyncRefreshManifestOnMainThread(true);
    }
    return true;
  }

  const std::string commandRole = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "role")));
  std::string requestId = nativeTrim(
    nativeJsonExtractString(commandBody, "requestId"));
  if (!nativeProjectSyncRequestIdIsValid(requestId)) {
    // Invalidacoes ocorridas depois do pareamento nao pertencem a um poll de
    // preflight e algumas Hook Centers nao enviam requestId. Reaproveita o ID
    // anterior (ou cria um hexadecimal local) para conservar o diagnostico no
    // PC A. O pedido inicial recebido pelo PC B continua exigindo ID valido.
    if (commandRole != "primary" || localRole != "primary") return true;
    {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      requestId = g_nativeProjectSyncPreflight.requestId;
    }
    if (!nativeProjectSyncRequestIdIsValid(requestId)) {
      requestId = nativeProjectSyncHashText(
        commandBody + std::to_string(nativeSystemNowMs()));
    }
  }
  if (commandRole == "secondary") {
    if (localRole != "secondary") {
      NativeProjectSyncCompareResult result =
        nativeProjectSyncErrorResult(
          "Este computador nao esta configurado como PC B.");
      nativeProjectSyncStorePreflightResult(
        requestId, false, result.diffJson, "");
      if (showConference) nativeProjectSyncShowDiffModal(result.diffJson);
      return true;
    }
    const std::string remoteManifest =
      nativeJsonExtractString(commandBody, "manifest");
    const std::string remoteRevision = nativeTrim(
      nativeJsonExtractString(commandBody, "manifestRevision"));
    if (remoteManifest.empty() || remoteRevision.empty() ||
        nativeLower(nativeProjectSyncHashText(remoteManifest)) !=
          nativeLower(remoteRevision)) {
      NativeProjectSyncCompareResult result =
        nativeProjectSyncErrorResult(
          "O manifesto recebido do PC A esta incompleto ou corrompido.");
      nativeProjectSyncStorePreflightResult(
        requestId, false, result.diffJson, remoteRevision);
      if (showConference) nativeProjectSyncShowDiffModal(result.diffJson);
      return true;
    }

    nativeProjectSyncRefreshManifestOnMainThread(true);
    std::string localManifest;
    {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      localManifest = g_nativeProjectSyncPreflight.manifest;
    }
    NativeProjectSyncCompareResult result =
      nativeProjectSyncCompareManifests(remoteManifest, localManifest);
    {
      std::lock_guard<std::mutex> lock(g_nativeTimecodeLanMutex);
      // Configuracao e uma escolha independente da estrutura. Diferencas de
      // configuracao nunca bloqueiam o pareamento; elas apenas suspendem a
      // copia viva ate o usuario do PC B autorizar explicitamente.
      if (result.configDifferenceCount == 0) {
        g_nativeProjectSyncConfigurationAuthorized = true;
      }
    }
    nativeProjectSyncStorePreflightResult(
      requestId, result.ready, result.diffJson, remoteRevision,
      remoteManifest, result.remoteConfigSnapshot);
    if (showConference &&
        (!result.ready || result.differenceCount > 0)) {
      nativeProjectSyncShowDiffModal(result.diffJson);
    }
    return true;
  }

  if (commandRole == "primary") {
    if (localRole != "primary") return true;
    const bool ready = nativeJsonBoolValue(
      commandBody, "ready", false);
    std::string diff = nativeTrim(
      nativeJsonExtractRawValue(commandBody, "diff"));
    if (diff.empty() || diff == "null" || diff.front() != '{') {
      NativeProjectSyncCompareResult fallback =
        ready
          ? nativeProjectSyncCompareManifests(
              g_nativeProjectSyncPreflight.manifest,
              g_nativeProjectSyncPreflight.manifest)
          : nativeProjectSyncErrorResult(
              nativeJsonBoolValue(commandBody, "timedOut", false)
                ? "O preflight do PC B expirou."
                : "O PC B nao devolveu o diagnostico do preflight.");
      diff = fallback.diffJson;
    }
    const std::string remoteRevision = nativeTrim(
      nativeJsonExtractString(commandBody, "remoteManifestRevision"));
    nativeProjectSyncStorePreflightResult(
      requestId, ready, diff, remoteRevision);
    if (ready) g_nativeProjectSyncPublishInitialConfig = true;
    if (showConference &&
        (!ready || nativeJsonInt64(diff, "differenceCount", 0) > 0)) {
      nativeProjectSyncShowDiffModal(diff);
    } else if (g_nativeMainModalKind ==
                 NativeMainModalKind::ProjectSyncDiff) {
      // O PC A pode ter aberto primeiro um projeto vazio e depois trocado
      // para o projeto correto. O PC B recalcula o diff pelo snapshot vivo;
      // se a Conferencia ja esta aberta, troca seu conteudo imediatamente em
      // vez de manter o diagnostico preso ao projeto/aba anterior.
      nativeProjectSyncShowDiffModal(diff);
    }
    return true;
  }

  NativeProjectSyncCompareResult result =
    nativeProjectSyncErrorResult("Papel de preflight invalido.");
  nativeProjectSyncStorePreflightResult(
    requestId, false, result.diffJson, "");
  if (showConference) nativeProjectSyncShowDiffModal(result.diffJson);
  return true;
}

struct NativeUiConverterTimelineEntry {
  int enumIndex = -1;
  bool region = false;
  double start = 0.0;
  double end = 0.0;
  std::string name;
  int number = 0;
  int color = 0;
  int lane = -1;
};

struct NativeUiConverterAudioEntry {
  MediaItem* item = nullptr;
  double start = 0.0;
  double end = 0.0;
  int order = 0;
};

struct NativeUiConverterRegionPlan {
  int markerEnumIndex = -1;
  double start = 0.0;
  double end = 0.0;
  std::string name;
  int sourceColor = 0;
  bool nested = false;
  double parentStart = 0.0;
  double parentEnd = 0.0;
};

static int nativeUiConverterColor(int red, int green, int blue)
{
  const int color = ColorToNative_ptr
    ? ColorToNative_ptr(red, green, blue)
    : RGB(red, green, blue);
  return color | 0x01000000;
}

static bool nativeUiConverterLoopMarker(const std::string& name)
{
  const std::string value = nativeTrim(name);
  if (value.size() < 2 || value.front() != '*') return false;
  const int number = std::atoi(value.c_str() + 1);
  return number == 1 || number == 2;
}

static bool nativeUiConverterSpecialMarker(const std::string& name)
{
  const std::string value = nativeTrim(name);
  if (value.empty()) return false;
  // No Converter, somente os markers reservados para Parts/loops e os
  // desativados com ! ficam fora da criação de regiões. Outros nomes que
  // eventualmente começam com * continuam sendo markers comuns.
  return value.front() == '$' || value.front() == '!' ||
    nativeUiConverterLoopMarker(value);
}

static bool nativeUiConverterExplicitParent(const std::string& name)
{
  std::string value = nativeTrim(name);
  size_t cursor = 0;
  while (cursor < value.size() &&
         value[cursor] >= '0' && value[cursor] <= '9') {
    ++cursor;
  }
  if (cursor > 0) {
    while (cursor < value.size() &&
           std::isspace(static_cast<unsigned char>(value[cursor]))) {
      ++cursor;
    }
    value = value.substr(cursor);
  }
  return value.size() >= 2 && value[0] == '-' && value[1] == '-';
}

static void nativeUiConverterCollectTimeline(
  ReaProject* project,
  std::vector<NativeUiConverterTimelineEntry>& markers,
  std::vector<NativeUiConverterTimelineEntry>& regions)
{
  markers.clear();
  regions.clear();
  if (!project || !CountProjectMarkers_ptr ||
      !EnumProjectMarkers3_ptr) {
    return;
  }
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project,
    &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  for (int enumIndex = 0; enumIndex < total; ++enumIndex) {
    bool isRegion = false;
    double start = 0.0;
    double end = 0.0;
    const char* rawName = "";
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, enumIndex,
          &isRegion, &start, &end, &rawName,
          &number, &color)) {
      continue;
    }
    NativeUiConverterTimelineEntry entry;
    entry.enumIndex = enumIndex;
    entry.region = isRegion;
    entry.start = start;
    entry.end = isRegion ? end : start;
    entry.name = rawName ? rawName : "";
    entry.number = number;
    entry.color = color;
    entry.lane = nativeGetRegionRulerLaneNumber(project, enumIndex);
    if (isRegion) {
      regions.push_back(std::move(entry));
    } else if (!nativeTrim(entry.name).empty()) {
      markers.push_back(std::move(entry));
    }
  }
  const auto order = [](const NativeUiConverterTimelineEntry& left,
                        const NativeUiConverterTimelineEntry& right) {
    if (std::fabs(left.start - right.start) <= 0.0000001) {
      return left.number < right.number;
    }
    return left.start < right.start;
  };
  std::sort(markers.begin(), markers.end(), order);
  std::sort(regions.begin(), regions.end(), order);
}

static std::vector<NativeUiConverterAudioEntry>
nativeUiConverterCollectAudio(ReaProject* project)
{
  std::vector<NativeUiConverterAudioEntry> result;
  if (!project || !CountTracks_ptr || !GetTrack_ptr ||
      !GetTrackNumMediaItems_ptr || !GetTrackMediaItem_ptr ||
      !GetMediaItemInfo_Value_ptr || !GetActiveTake_ptr) {
    return result;
  }
  int order = 0;
  const int trackCount = CountTracks_ptr(project);
  for (int trackIndex = 0; trackIndex < trackCount; ++trackIndex) {
    MediaTrack* track = GetTrack_ptr(project, trackIndex);
    if (!track) continue;
    const int itemCount = GetTrackNumMediaItems_ptr(track);
    for (int itemIndex = 0; itemIndex < itemCount; ++itemIndex) {
      MediaItem* item = GetTrackMediaItem_ptr(track, itemIndex);
      MediaItem_Take* take = item ? GetActiveTake_ptr(item) : nullptr;
      if (!item || !take || (TakeIsMIDI_ptr && TakeIsMIDI_ptr(take))) {
        continue;
      }
      const double start =
        GetMediaItemInfo_Value_ptr(item, "D_POSITION");
      const double length = std::max(0.0,
        GetMediaItemInfo_Value_ptr(item, "D_LENGTH"));
      if (length <= 0.000001) continue;
      result.push_back({item, start, start + length, order++});
    }
  }
  std::sort(result.begin(), result.end(),
    [](const NativeUiConverterAudioEntry& left,
       const NativeUiConverterAudioEntry& right) {
      if (std::fabs(left.start - right.start) <= 0.000001) {
        return left.order < right.order;
      }
      return left.start < right.start;
    });
  return result;
}

static const NativeUiConverterAudioEntry*
nativeUiConverterAudioAt(
  double position,
  const std::vector<NativeUiConverterAudioEntry>& audio)
{
  const NativeUiConverterAudioEntry* best = nullptr;
  for (const auto& item : audio) {
    if (std::fabs(item.start - position) > 0.000001 ||
        item.end <= position + 0.000001) {
      continue;
    }
    if (!best || item.end > best->end + 0.000001) best = &item;
  }
  return best;
}

static bool nativeUiConverterEnsureRulerLanes(ReaProject* project)
{
  if (!project || !GetSetProjectInfo_ptr ||
      !GetSetProjectInfo_String_ptr) {
    return false;
  }
  char existing[256] = "";
  const bool hasThird = GetSetProjectInfo_String_ptr(
    project, "RULER_LANE_NAME:2", existing, false);
  if (!hasThird && Main_OnCommand_ptr) {
    Main_OnCommand_ptr(43541, 0);
    GetSetProjectInfo_ptr(project, "RULER_LANE_ORDER:2", 1.0, true);
  }
  char first[] = "Musicas/Blocos";
  char second[] = "Musicas/Filhos";
  char third[] = "Parts/Loops";
  GetSetProjectInfo_String_ptr(project,
    "RULER_LANE_NAME:0", first, true);
  GetSetProjectInfo_String_ptr(project,
    "RULER_LANE_NAME:1", second, true);
  GetSetProjectInfo_String_ptr(project,
    "RULER_LANE_NAME:2", third, true);
  GetSetProjectInfo_ptr(project, "RULER_LANE_DEFAULT:0", 1.0, true);
  GetSetProjectInfo_ptr(project, "RULER_LANE_DEFAULT:1", 0.0, true);
  GetSetProjectInfo_ptr(project, "RULER_LANE_DEFAULT:2", 2.0, true);
  return true;
}

static void nativeUiConverterPlaceRulerLanes(
  ReaProject* project,
  const std::vector<NativeUiConverterRegionPlan>& plans)
{
  if (!project || !GetRegionOrMarker_ptr ||
      !GetRegionOrMarkerInfo_Value_ptr ||
      !SetRegionOrMarkerInfo_Value_ptr ||
      !GetSetRegionOrMarkerInfo_String_ptr ||
      !nativeUiConverterEnsureRulerLanes(project) ||
      !CountProjectMarkers_ptr) {
    return;
  }
  struct LaneEntry {
    void* handle = nullptr;
    double start = 0.0;
    double end = 0.0;
    int lane = -1;
    bool region = false;
    bool specialMarker = false;
    int parent = -1;
    bool hasChild = false;
  };
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project,
    &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  std::vector<LaneEntry> entries;
  for (int enumIndex = 0; enumIndex < total; ++enumIndex) {
    void* handle = GetRegionOrMarker_ptr(project, enumIndex, "");
    if (!handle) continue;
    LaneEntry entry;
    entry.handle = handle;
    entry.region = GetRegionOrMarkerInfo_Value_ptr(
      project, handle, "B_ISREGION") > 0.5;
    entry.start = GetRegionOrMarkerInfo_Value_ptr(
      project, handle, "D_STARTPOS");
    entry.end = entry.region
      ? GetRegionOrMarkerInfo_Value_ptr(project, handle, "D_ENDPOS")
      : entry.start;
    entry.lane = static_cast<int>(std::floor(
      GetRegionOrMarkerInfo_Value_ptr(project, handle, "I_LANENUMBER")));
    if (!entry.region) {
      char name[2048] = "";
      GetSetRegionOrMarkerInfo_String_ptr(
        project, handle, "P_NAME", name, false);
      const std::string trimmed = nativeTrim(name);
      entry.specialMarker = !trimmed.empty() &&
        (trimmed.front() == '$' || nativeUiConverterLoopMarker(trimmed));
    }
    entries.push_back(entry);
  }

  for (size_t childIndex = 0; childIndex < entries.size(); ++childIndex) {
    auto& child = entries[childIndex];
    if (!child.region) continue;
    const double childLength = child.end - child.start;
    if (childLength <= 0.000001) continue;
    int best = -1;
    double bestLength = 0.0;
    for (size_t parentIndex = 0;
         parentIndex < entries.size(); ++parentIndex) {
      const auto& parent = entries[parentIndex];
      if (parentIndex == childIndex || !parent.region ||
          (parent.lane != 0 && parent.lane != -1)) {
        continue;
      }
      const double parentLength = parent.end - parent.start;
      if (parentLength <= childLength + 0.000001) continue;
      const double overlap = std::min(child.end, parent.end) -
        std::max(child.start, parent.start);
      if (overlap <= 0.000001 ||
          overlap / childLength < 0.50) {
        continue;
      }
      if (best < 0 || parentLength < bestLength) {
        best = static_cast<int>(parentIndex);
        bestLength = parentLength;
      }
    }
    if (best >= 0) {
      child.parent = best;
      entries[static_cast<size_t>(best)].hasChild = true;
    }
  }

  for (const auto& plan : plans) {
    if (!plan.nested) continue;
    int childIndex = -1;
    int parentIndex = -1;
    for (size_t index = 0; index < entries.size(); ++index) {
      const auto& entry = entries[index];
      if (!entry.region) continue;
      if (std::fabs(entry.start - plan.start) <= 0.000001 &&
          std::fabs(entry.end - plan.end) <= 0.000001) {
        childIndex = static_cast<int>(index);
      }
      if (std::fabs(entry.start - plan.parentStart) <= 0.000001 &&
          std::fabs(entry.end - plan.parentEnd) <= 0.000001) {
        parentIndex = static_cast<int>(index);
      }
    }
    if (childIndex >= 0 && parentIndex >= 0 &&
        childIndex != parentIndex) {
      entries[static_cast<size_t>(childIndex)].parent = parentIndex;
      entries[static_cast<size_t>(parentIndex)].hasChild = true;
    }
  }

  for (auto& entry : entries) {
    if (entry.region) {
      int targetLane = -1;
      if (entry.parent >= 0) targetLane = 1;
      else if (entry.hasChild || entry.lane == 1) targetLane = 0;
      if (targetLane >= 0 && entry.lane != targetLane) {
        SetRegionOrMarkerInfo_Value_ptr(project, entry.handle,
          "I_LANENUMBER", static_cast<double>(targetLane));
      }
    } else if (entry.specialMarker && entry.lane != 2) {
      SetRegionOrMarkerInfo_Value_ptr(project, entry.handle,
        "I_LANENUMBER", 2.0);
    }
  }
}

static int nativeUiApplyProjectColorRules(
  ReaProject* project,
  bool colorRegions)
{
  if (!project || !CountProjectMarkers_ptr ||
      !EnumProjectMarkers3_ptr || !SetProjectMarkerByIndex2_ptr) {
    return 0;
  }
  std::vector<NativeUiConverterTimelineEntry> markers;
  std::vector<NativeUiConverterTimelineEntry> regions;
  nativeUiConverterCollectTimeline(project, markers, regions);
  int changed = 0;
  if (colorRegions) {
    const int parentColor = nativeUiConverterColor(125, 10, 175);
    const int childColor = nativeUiConverterColor(255, 230, 0);
    for (const auto& region : regions) {
      bool child = region.lane == 1;
      if (region.lane < 0) {
        const double length = region.end - region.start;
        for (const auto& parent : regions) {
          if (parent.enumIndex == region.enumIndex) continue;
          const double parentLength = parent.end - parent.start;
          const double overlap = std::min(region.end, parent.end) -
            std::max(region.start, parent.start);
          if (length > 0.000001 && parentLength > length + 0.000001 &&
              overlap / length >= 0.50) {
            child = true;
            break;
          }
        }
      }
      const int desired = child ? childColor : parentColor;
      if (region.color == desired) continue;
      if (SetProjectMarkerByIndex2_ptr(project, region.enumIndex,
            true, region.start, region.end, region.number,
            region.name.c_str(), desired, 0)) {
        ++changed;
      }
    }
  }
  const int cyan = nativeUiConverterColor(0, 210, 220);
  const int red = nativeUiConverterColor(255, 0, 0);
  const int blue = nativeUiConverterColor(0, 120, 255);
  for (const auto& marker : markers) {
    const std::string name = nativeTrim(marker.name);
    int desired = marker.color;
    bool hasRule = false;
    if (!name.empty() && name.front() == '$') {
      desired = cyan;
      hasRule = true;
    } else if (nativeUiConverterLoopMarker(name)) {
      desired = red;
      hasRule = true;
    } else {
      for (const auto& region : regions) {
        if (marker.start >= region.start - 0.000001 &&
            marker.start < region.end - 0.000001) {
          desired = blue;
          hasRule = true;
          break;
        }
      }
    }
    if (!hasRule || desired == marker.color) continue;
    if (SetProjectMarkerByIndex2_ptr(project, marker.enumIndex,
          false, marker.start, 0.0, marker.number,
          marker.name.c_str(), desired, 0)) {
      ++changed;
    }
  }
  return changed;
}

static bool nativeUiExecuteConverter(bool applyNativeColors)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !AddProjectMarker2_ptr ||
      !DeleteProjectMarkerByIndex_ptr ||
      !CountProjectMarkers_ptr || !EnumProjectMarkers3_ptr) {
    nativeUiShowTemporaryPopup(
      "Conversor indisponível nesta versão do REAPER", 2.2);
    return false;
  }
  std::vector<NativeUiConverterTimelineEntry> markers;
  std::vector<NativeUiConverterTimelineEntry> regions;
  nativeUiConverterCollectTimeline(project, markers, regions);
  const auto audio = nativeUiConverterCollectAudio(project);
  const double epsilon = 0.000001;
  std::vector<bool> parentHasStrictMarker(regions.size(), false);
  for (size_t regionIndex = 0;
       regionIndex < regions.size(); ++regionIndex) {
    for (const auto& marker : markers) {
      if (nativeUiConverterSpecialMarker(marker.name)) continue;
      if (marker.start > regions[regionIndex].start + epsilon &&
          marker.start < regions[regionIndex].end - epsilon) {
        parentHasStrictMarker[regionIndex] = true;
        break;
      }
    }
  }
  std::vector<int> parentByMarker(markers.size(), -1);
  std::map<int, std::vector<int>> childrenByParent;
  for (size_t markerIndex = 0;
       markerIndex < markers.size(); ++markerIndex) {
    const auto& marker = markers[markerIndex];
    if (nativeUiConverterSpecialMarker(marker.name)) continue;
    int bestParent = -1;
    double bestLength = 0.0;
    for (size_t regionIndex = 0;
         regionIndex < regions.size(); ++regionIndex) {
      const auto& region = regions[regionIndex];
      const double length = region.end - region.start;
      const bool strictlyInside =
        marker.start > region.start + epsilon &&
        marker.start < region.end - epsilon;
      const bool atStart =
        std::fabs(marker.start - region.start) <= epsilon &&
        (parentHasStrictMarker[regionIndex] ||
         nativeUiConverterExplicitParent(region.name));
      if (length <= epsilon || (!strictlyInside && !atStart)) continue;
      if (bestParent < 0 || length < bestLength) {
        bestParent = static_cast<int>(regionIndex);
        bestLength = length;
      }
    }
    if (bestParent >= 0) {
      parentByMarker[markerIndex] = bestParent;
      childrenByParent[bestParent].push_back(
        static_cast<int>(markerIndex));
    }
  }
  for (auto& entry : childrenByParent) {
    std::sort(entry.second.begin(), entry.second.end(),
      [&](int left, int right) {
        return markers[static_cast<size_t>(left)].start <
          markers[static_cast<size_t>(right)].start;
      });
  }

  std::vector<NativeUiConverterRegionPlan> plans;
  for (size_t markerIndex = 0;
       markerIndex < markers.size(); ++markerIndex) {
    const auto& marker = markers[markerIndex];
    if (nativeUiConverterSpecialMarker(marker.name)) continue;
    const int parentIndex = parentByMarker[markerIndex];
    if (parentIndex >= 0) {
      const auto& parent = regions[static_cast<size_t>(parentIndex)];
      const auto& siblings = childrenByParent[parentIndex];
      double childEnd = parent.end;
      const auto found = std::find(siblings.begin(), siblings.end(),
        static_cast<int>(markerIndex));
      if (found != siblings.end() && found + 1 != siblings.end()) {
        childEnd = markers[static_cast<size_t>(*(found + 1))].start;
      } else if (const auto* item =
                   nativeUiConverterAudioAt(marker.start, audio)) {
        childEnd = item->end;
      }
      if (childEnd <= marker.start + epsilon) childEnd = parent.end;
      if (childEnd > marker.start + epsilon) {
        plans.push_back({marker.enumIndex, marker.start, childEnd,
          marker.name, marker.color, true, parent.start, parent.end});
      }
      continue;
    }
    bool existingAtStart = false;
    for (const auto& region : regions) {
      if (std::fabs(region.start - marker.start) <= epsilon) {
        existingAtStart = true;
        break;
      }
    }
    if (existingAtStart) continue;
    const auto* item = nativeUiConverterAudioAt(marker.start, audio);
    if (!item) continue;
    double end = item->end;
    for (const auto& region : regions) {
      if (region.start > marker.start + epsilon &&
          region.start < end - epsilon) {
        end = region.start;
      }
    }
    for (const auto& nextMarker : markers) {
      if (nativeUiConverterSpecialMarker(nextMarker.name) ||
          nextMarker.start <= marker.start + epsilon ||
          nextMarker.start >= end - epsilon) {
        continue;
      }
      if (nativeUiConverterAudioAt(nextMarker.start, audio)) {
        end = nextMarker.start;
      }
    }
    if (end > marker.start + epsilon) {
      plans.push_back({marker.enumIndex, marker.start, end,
        marker.name.empty() ? "SEM NOME" : marker.name,
        marker.color, false, 0.0, 0.0});
    }
  }

  if (Undo_BeginBlock2_ptr) Undo_BeginBlock2_ptr(project);
  std::vector<int> deleteIndexes;
  for (const auto& plan : plans) {
    deleteIndexes.push_back(plan.markerEnumIndex);
  }
  std::sort(deleteIndexes.begin(), deleteIndexes.end(),
    std::greater<int>());
  deleteIndexes.erase(std::unique(deleteIndexes.begin(),
    deleteIndexes.end()), deleteIndexes.end());
  for (int enumIndex : deleteIndexes) {
    DeleteProjectMarkerByIndex_ptr(project, enumIndex);
  }

  int created = 0;
  std::vector<std::pair<double, double>> usedBounds;
  for (const auto& region : regions) {
    usedBounds.push_back({region.start, region.end});
  }
  for (const auto& plan : plans) {
    bool exists = false;
    for (const auto& bounds : usedBounds) {
      if (std::fabs(bounds.first - plan.start) <= epsilon &&
          std::fabs(bounds.second - plan.end) <= epsilon) {
        exists = true;
        break;
      }
    }
    if (exists) continue;
    const int color = applyNativeColors
      ? nativeUiConverterColor(125, 10, 175)
      : plan.sourceColor;
    if (AddProjectMarker2_ptr(project, true, plan.start, plan.end,
          plan.name.c_str(), -1, color) >= 0) {
      ++created;
      usedBounds.push_back({plan.start, plan.end});
    }
  }
  nativeUiConverterPlaceRulerLanes(project, plans);
  if (applyNativeColors) {
    nativeUiApplyProjectColorRules(project, true);
  }
  // Converter também prepara imediatamente as pistas harmônicas. Essa ação
  // não pode depender de um pedido externo do Lua/bridge para inserir o FX.
  const int preparedReaPitchTracks =
    nativeEnsureReaPitchFirstOnHashTracks(project);
  if (Undo_EndBlock2_ptr) {
    Undo_EndBlock2_ptr(project,
      "Converter projeto e preparar espaço inicial", -1);
  }
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  if (UpdateTimeline_ptr) UpdateTimeline_ptr();
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiShowTemporaryPopup(
    "Projeto convertido | " + std::to_string(created) +
      " regiões criadas | " +
      std::to_string(deleteIndexes.size() -
        static_cast<size_t>(created)) +
      " marker(s) preservado(s) | scan " +
      std::to_string(markers.size()) + " marker(s)/" +
      std::to_string(audio.size()) + " áudio(s) | ReaPitch " +
      std::to_string(preparedReaPitchTracks) + " pista(s)", 3.5);
  return true;
}

static bool nativeUiConfirmNativeColors(const std::string& action)
{
  if (!ShowMessageBox_ptr) return true;
  const std::string message =
    "Deseja aplicar o padrão de cores nativo do VS Hook durante " +
    action + "?\n\nSIM: aplica as cores padrão do VS Hook.\n"
    "NÃO: preserva as cores atuais das regiões e markers.";
  return ShowMessageBox_ptr(message.c_str(),
    "VS Hook - Padrão de cores", 4) == 6;
}

static void nativeUiRequestConverter()
{
  g_nativeUiConverterApplyColors =
    nativeUiConfirmNativeColors("a conversão");
  g_nativeUiConverterPending = true;
  g_nativeUiConverterExecuteAt =
    std::chrono::steady_clock::now() +
      std::chrono::seconds(3);
  nativeUiShowTemporaryPopup("Analisando, aguarde...", 3.1);
}

static void nativeUiProcessPendingConverter()
{
  if (!g_nativeUiConverterPending ||
      std::chrono::steady_clock::now() <
        g_nativeUiConverterExecuteAt) {
    return;
  }
  g_nativeUiConverterPending = false;
  nativeUiExecuteConverter(g_nativeUiConverterApplyColors);
}

static void nativeUiUpdateProjectFromConfig()
{
  const bool applyColors =
    nativeUiConfirmNativeColors("a atualização");
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  int preparedReaPitchTracks = 0;
  if (project) {
    nativeUiConverterPlaceRulerLanes(project, {});
    if (applyColors) nativeUiApplyProjectColorRules(project, true);
    preparedReaPitchTracks =
      nativeEnsureReaPitchFirstOnHashTracks(project);
    if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
    if (UpdateTimeline_ptr) UpdateTimeline_ptr();
    if (UpdateArrange_ptr) UpdateArrange_ptr();
  }
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiShowTemporaryPopup(applyColors
    ? "Atualizado com padrão de cores do VS Hook | ReaPitch " +
        std::to_string(preparedReaPitchTracks) + " pista(s)"
    : "Atualizado preservando as cores atuais | ReaPitch " +
        std::to_string(preparedReaPitchTracks) + " pista(s)", 2.0);
}

static bool nativeUiConverterPartsMarkerIsActionable(
  const std::string& name)
{
  const std::string trimmed = nativeTrim(name);
  return trimmed.empty() ||
    (trimmed.front() != '!' && trimmed.front() != '*');
}

static bool nativeUiConverterPartsHasPrefix(
  const std::string& name)
{
  const std::string trimmed = nativeTrim(name);
  return !trimmed.empty() && trimmed.front() == '$';
}

static std::string nativeUiConverterPartsDisplayName(
  const NativeUiConverterPartsEntry& entry)
{
  std::string clean = nativeTrim(entry.name);
  const bool isPart = nativeUiConverterPartsHasPrefix(clean);
  if (isPart) {
    clean.erase(clean.begin());
    clean = nativeTrim(clean);
  }
  if (clean.empty()) clean = "SEM NOME";
  return std::string(isPart ? "$ " : "  ") + clean;
}

static std::string nativeUiConverterPartsToggleName(
  const std::string& name)
{
  std::string clean = nativeTrim(name);
  if (!clean.empty() && clean.front() == '$') {
    clean.erase(clean.begin());
    return nativeTrim(clean);
  }
  return "$" + clean;
}

static int nativeUiConverterPartsSelectedCount()
{
  int count = 0;
  for (const auto& entry :
       g_nativeUiConverterPartsSelection) {
    if (entry.second && entry.first >= 0 &&
        entry.first < static_cast<int>(
          g_nativeUiConverterPartsEntries.size())) {
      ++count;
    }
  }
  return count;
}

static void nativeUiConverterPartsSelectAll()
{
  g_nativeUiConverterPartsSelection.clear();
  for (size_t index = 0;
       index < g_nativeUiConverterPartsEntries.size(); ++index) {
    g_nativeUiConverterPartsSelection[
      static_cast<int>(index)] = true;
  }
  g_nativeUiConverterPartsAnchor =
    g_nativeUiConverterPartsEntries.empty() ? -1 : 0;
}

static bool nativeUiOpenConverterParts()
{
  g_nativeUiConverterPartsEntries.clear();
  g_nativeUiConverterPartsRowHits.clear();
  g_nativeUiConverterPartsSelection.clear();
  g_nativeUiConverterPartsAnchor = -1;
  g_nativeUiConverterPartsScroll = 0;

  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (project && CountProjectMarkers_ptr &&
      EnumProjectMarkers3_ptr) {
    int markerCount = 0;
    int regionCount = 0;
    CountProjectMarkers_ptr(project,
      &markerCount, &regionCount);
    const int total = markerCount + regionCount;
    for (int enumIndex = 0;
         enumIndex < total; ++enumIndex) {
      bool isRegion = false;
      double position = 0.0;
      double regionEnd = 0.0;
      const char* rawName = "";
      int number = 0;
      int color = 0;
      if (!EnumProjectMarkers3_ptr(project, enumIndex,
            &isRegion, &position, &regionEnd, &rawName,
            &number, &color) || isRegion) {
        continue;
      }
      const std::string name = rawName ? rawName : "";
      if (!nativeUiConverterPartsMarkerIsActionable(name)) {
        continue;
      }
      NativeUiConverterPartsEntry entry;
      entry.enumIndex = enumIndex;
      entry.position = position;
      entry.name = name;
      entry.number = number;
      entry.color = color;
      entry.hasPartsPrefix =
        nativeUiConverterPartsHasPrefix(name);
      g_nativeUiConverterPartsEntries.push_back(
        std::move(entry));
    }
    std::sort(g_nativeUiConverterPartsEntries.begin(),
      g_nativeUiConverterPartsEntries.end(),
      [](const NativeUiConverterPartsEntry& left,
         const NativeUiConverterPartsEntry& right) {
        if (std::fabs(left.position - right.position) <=
            0.0000001) {
          return left.number < right.number;
        }
        return left.position < right.position;
      });
  }
  g_nativeMainModalKind =
    NativeMainModalKind::ConverterParts;
  return true;
}

static bool nativeUiApplyConverterParts()
{
  if (nativeUiConverterPartsSelectedCount() <= 0) {
    nativeUiShowTemporaryPopup(
      "Selecione ao menos um marker", 1.6);
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !SetProjectMarkerByIndex2_ptr) {
    nativeUiShowTemporaryPopup(
      "Não foi possível alterar os markers", 1.8);
    return false;
  }

  // Uma seleção mista nunca pode desconverter os markers que já são Parts.
  // Enquanto existir ao menos um marker sem $, esta operação somente adiciona
  // o prefixo aos que faltam. A remoção acontece apenas quando todos os
  // selecionados já começam com $.
  bool addPartsPrefix = false;
  for (size_t index = 0;
       index < g_nativeUiConverterPartsEntries.size(); ++index) {
    const auto selected = g_nativeUiConverterPartsSelection.find(
      static_cast<int>(index));
    if (selected == g_nativeUiConverterPartsSelection.end() ||
        !selected->second) {
      continue;
    }
    if (!nativeUiConverterPartsHasPrefix(
          g_nativeUiConverterPartsEntries[index].name)) {
      addPartsPrefix = true;
      break;
    }
  }

  if (Undo_BeginBlock2_ptr) Undo_BeginBlock2_ptr(project);
  int changed = 0;
  for (size_t index = 0;
       index < g_nativeUiConverterPartsEntries.size(); ++index) {
    const auto selected =
      g_nativeUiConverterPartsSelection.find(
        static_cast<int>(index));
    if (selected == g_nativeUiConverterPartsSelection.end() ||
        !selected->second) {
      continue;
    }
    const auto& marker =
      g_nativeUiConverterPartsEntries[index];
    if (!nativeUiConverterPartsMarkerIsActionable(
          marker.name)) {
      continue;
    }
    const bool hasPrefix =
      nativeUiConverterPartsHasPrefix(marker.name);
    if (addPartsPrefix && hasPrefix) continue;
    const std::string nextName =
      nativeUiConverterPartsToggleName(marker.name);
    if (nextName == marker.name) continue;
    if (SetProjectMarkerByIndex2_ptr(project,
          marker.enumIndex, false, marker.position, 0.0,
          marker.number, nextName.c_str(), marker.color, 0)) {
      ++changed;
    }
  }
  if (Undo_EndBlock2_ptr) {
    Undo_EndBlock2_ptr(project, "Converter/Parts", -1);
  }
  if (changed > 0 && MarkProjectDirty_ptr) {
    MarkProjectDirty_ptr(project);
  }
  if (UpdateTimeline_ptr) UpdateTimeline_ptr();
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiCloseMainModal();
  nativeUiShowTemporaryPopup(
    "Converter/Parts: " + std::to_string(changed) +
      (addPartsPrefix
        ? " marker(s) convertido(s)"
        : " marker(s) desconvertido(s)"), 2.2);
  return true;
}

static void nativeUiAppendPremixItems(
  ReaProject* project,
  const NativeSongWindow& song)
{
  if (!project || song.end <= song.start + 0.0005 ||
      !CountTracks_ptr || !GetTrack_ptr ||
      !GetTrackNumMediaItems_ptr || !GetTrackMediaItem_ptr ||
      !GetMediaItemInfo_Value_ptr) {
    return;
  }
  const double epsilon = 0.001;
  int visualIndex = 0;
  const int trackCount = CountTracks_ptr(project);
  for (int trackIndex = 0; trackIndex < trackCount; ++trackIndex) {
    MediaTrack* track = GetTrack_ptr(project, trackIndex);
    if (!track) continue;
    const std::string trackName = nativeTrackName(track, trackIndex);
    const int itemCount = GetTrackNumMediaItems_ptr(track);
    for (int itemIndex = 0; itemIndex < itemCount; ++itemIndex) {
      MediaItem* item = GetTrackMediaItem_ptr(track, itemIndex);
      if (!item) continue;
      const double itemStart =
        GetMediaItemInfo_Value_ptr(item, "D_POSITION");
      const double itemLength = std::max(0.0,
        GetMediaItemInfo_Value_ptr(item, "D_LENGTH"));
      const double itemEnd = itemStart + itemLength;
      if (song.isRegionChild) {
        if (itemEnd <= song.start + epsilon ||
            itemStart >= song.end - epsilon) {
          continue;
        }
      } else if (itemStart < song.start - epsilon ||
                 itemStart >= song.end - epsilon) {
        continue;
      }
      ++visualIndex;
      NativeUiPremixItemRow row;
      row.kind = NativeUiPremixRowKind::Item;
      row.mediaItem = item;
      row.itemNumber = visualIndex;
      const std::string fallbackId =
        std::string("premix_item_") +
        std::to_string(trackIndex + 1) + "_" +
        std::to_string(itemIndex + 1);
      row.itemId = nativeMediaItemGuid(item, fallbackId);
      row.name = nativeTakeName(item,
        std::string("Item ") + std::to_string(visualIndex));
      row.trackName = trackName;
      g_nativeUiPremixRows.push_back(std::move(row));
    }
  }
}

static bool nativeUiOpenPremixFromRename()
{
  if (g_nativeUiRenameId.empty() || g_nativeUiRenameBlock) {
    return false;
  }
  std::ostringstream command;
  command << "{\"type\":\"premix_open\",\"songId\":"
          << nativeJsonString(g_nativeUiRenameId)
          << ",\"targetId\":"
          << nativeJsonString(g_nativeUiRenameId)
          << ",\"startPos\":" << std::setprecision(15)
          << g_nativeUiRenameStart
          << ",\"endPos\":" << std::setprecision(15)
          << g_nativeUiRenameEnd << "}";
  nativeApplyPremixCommand(command.str());

  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;

  std::vector<NativeSongWindow> songs;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
  }
  const NativeSongWindow* selected = nullptr;
  const NativeSongWindow* idFallback = nullptr;
  for (const auto& song : songs) {
    if (song.isBlock) continue;
    if (song.id == g_nativeUiRenameId && !idFallback) {
      idFallback = &song;
    }
    if (song.id == g_nativeUiRenameId &&
        std::fabs(song.start - g_nativeUiRenameStart) <= 0.002 &&
        std::fabs(song.end - g_nativeUiRenameEnd) <= 0.002) {
      selected = &song;
      break;
    }
  }
  if (!selected) selected = idFallback;
  if (!selected) {
    for (const auto& song : songs) {
      if (!song.isBlock &&
          std::fabs(song.start - g_nativeUiRenameStart) <= 0.002 &&
          std::fabs(song.end - g_nativeUiRenameEnd) <= 0.002) {
        selected = &song;
        break;
      }
    }
  }

  NativeSongWindow fallback;
  if (!selected) {
    fallback.id = g_nativeUiRenameId;
    fallback.name = g_nativeUiRenameInput;
    fallback.start = g_nativeUiRenameStart;
    fallback.end = g_nativeUiRenameEnd;
    fallback.sourceNumber = g_nativeUiRenameSourceNumber;
    fallback.enumIndex = g_nativeUiRenameEnumIndex;
    selected = &fallback;
  }
  if (selected->end <= selected->start + 0.0005) {
    nativeUiShowTemporaryPopup("Premix sem intervalo válido", 1.6);
    return false;
  }

  g_nativeUiPremixRows.clear();
  g_nativeUiPremixSliderHits.clear();
  g_nativeUiPremixSongName = selected->name.empty()
    ? g_nativeUiRenameInput : selected->name;
  g_nativeUiPremixScroll = 0;
  std::vector<const NativeSongWindow*> children;
  if (selected->isHashParent) {
    for (const auto& song : songs) {
      if (song.isBlock || !(song.isHashChild || song.isRegionChild)) {
        continue;
      }
      const bool sameParentEnum =
        selected->enumIndex >= 0 && song.parentEnumIndex >= 0 &&
        selected->enumIndex == song.parentEnumIndex;
      const bool sameParentId =
        !selected->id.empty() && !song.parentId.empty() &&
        selected->id == song.parentId;
      if (sameParentEnum || sameParentId) children.push_back(&song);
    }
    std::sort(children.begin(), children.end(),
      [](const NativeSongWindow* left,
         const NativeSongWindow* right) {
        if (!left || !right) return left != nullptr;
        if (std::fabs(left->start - right->start) > 0.0005) {
          return left->start < right->start;
        }
        return left->end < right->end;
      });
  }
  g_nativeUiPremixFamilyMode = !children.empty();
  if (g_nativeUiPremixFamilyMode) {
    for (const NativeSongWindow* child : children) {
      if (!child) continue;
      NativeUiPremixItemRow header;
      header.kind = NativeUiPremixRowKind::ChildHeader;
      header.name = child->name.empty() ? "Música filha" : child->name;
      g_nativeUiPremixRows.push_back(std::move(header));
      const size_t before = g_nativeUiPremixRows.size();
      nativeUiAppendPremixItems(project, *child);
      if (g_nativeUiPremixRows.size() == before) {
        NativeUiPremixItemRow empty;
        empty.kind = NativeUiPremixRowKind::Empty;
        empty.name = "Nenhum item encontrado para esta música filha.";
        g_nativeUiPremixRows.push_back(std::move(empty));
      }
    }
  } else {
    nativeUiAppendPremixItems(project, *selected);
  }
  g_nativeMainModalKind =
    NativeMainModalKind::PremixItemEditor;
  return true;
}

static double nativeUiPremixRatioToVolume(double rawRatio)
{
  const double ratio = std::max(0.0, std::min(1.0, rawRatio));
  constexpr double minDb = -90.0;
  constexpr double maxDb = 12.0;
  constexpr double zeroRatio = 0.76;
  constexpr double curve = 1.35;
  double db = 0.0;
  if (ratio <= zeroRatio) {
    const double normalized = std::pow(
      ratio / std::max(0.000001, zeroRatio), 1.0 / curve);
    db = minDb + normalized * -minDb;
  } else {
    db = ((ratio - zeroRatio) /
      std::max(0.000001, 1.0 - zeroRatio)) * maxDb;
  }
  return std::pow(10.0, db / 20.0);
}

static bool nativeUiPremixMediaItemIsValid(
  ReaProject* project,
  MediaItem* item)
{
  return project && item && ValidatePtr2_ptr &&
    ValidatePtr2_ptr(project, item, "MediaItem*");
}

static bool nativeUiSetPremixVolumeFromPoint(
  int rowIndex,
  const RECT& slider,
  int pointX)
{
  if (rowIndex < 0 || rowIndex >= static_cast<int>(
        g_nativeUiPremixRows.size())) {
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  auto& row = g_nativeUiPremixRows[static_cast<size_t>(rowIndex)];
  if (row.kind != NativeUiPremixRowKind::Item ||
      !nativeUiPremixMediaItemIsValid(project, row.mediaItem)) {
    return false;
  }
  const int width = std::max(1,
    static_cast<int>(slider.right - slider.left));
  const double ratio = std::max(0.0, std::min(1.0,
    static_cast<double>(pointX - slider.left) / width));
  std::ostringstream command;
  command << "{\"type\":\"premix_item_set_volume\","
          << "\"itemId\":" << nativeJsonString(row.itemId)
          << ",\"ratio\":" << std::setprecision(17) << ratio << '}';
  return nativeApplyPremixCommand(command.str());
}

static bool nativeUiTogglePremixMute(int rowIndex)
{
  if (rowIndex < 0 || rowIndex >= static_cast<int>(
        g_nativeUiPremixRows.size()) ||
      !GetMediaItemInfo_Value_ptr || !SetMediaItemInfo_Value_ptr) {
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  auto& row = g_nativeUiPremixRows[static_cast<size_t>(rowIndex)];
  if (row.kind != NativeUiPremixRowKind::Item ||
      !nativeUiPremixMediaItemIsValid(project, row.mediaItem)) {
    return false;
  }
  const bool muted =
    GetMediaItemInfo_Value_ptr(row.mediaItem, "B_MUTE") > 0.5;
  std::ostringstream command;
  command << "{\"type\":\"premix_item_toggle_mute\","
          << "\"itemId\":" << nativeJsonString(row.itemId)
          << ",\"desiredMute\":" << (!muted ? "true" : "false")
          << '}';
  return nativeApplyPremixCommand(command.str());
}

static bool nativeUiOpenBlockColor()
{
  if (!g_nativeUiRenameBlock || g_nativeUiRenameRegionsPage) return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  const auto playlists = nativeUiReadPlaylistRecords(project);
  const int playlistIndex =
    nativeUiCurrentPlaylistIndex(project, playlists);
  if (playlistIndex < 0 ||
      playlistIndex >= static_cast<int>(playlists.size())) {
    return false;
  }
  const auto& lines = playlists[static_cast<size_t>(
    playlistIndex)].itemLines;
  const int itemIndex = nativeUiRenamePlaylistLineIndex(lines);
  if (itemIndex < 0 || itemIndex >= static_cast<int>(lines.size())) {
    return false;
  }
  const auto fields = nativeSplit(lines[static_cast<size_t>(itemIndex)], '\t');
  if (fields.size() < 3 || fields[1] != "block") return false;
  g_nativeUiBlockColorKey = fields.size() > 6
    ? nativeUnescapeExtField(fields[6]) : "";
  if (g_nativeUiBlockColorKey.empty()) g_nativeUiBlockColorKey = "auto";
  g_nativeMainModalKind = NativeMainModalKind::BlockColorSelect;
  return true;
}

static bool nativeUiApplyBlockColor(const std::string& rawKey)
{
  if (!g_nativeUiRenameBlock) return false;
  const std::string key = rawKey.empty() ? "auto" : rawKey;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  auto playlists = nativeUiReadPlaylistRecords(project);
  const int playlistIndex =
    nativeUiCurrentPlaylistIndex(project, playlists);
  if (playlistIndex < 0 ||
      playlistIndex >= static_cast<int>(playlists.size())) {
    return false;
  }
  auto& lines = playlists[static_cast<size_t>(
    playlistIndex)].itemLines;
  const int itemIndex = nativeUiRenamePlaylistLineIndex(lines);
  if (itemIndex < 0 || itemIndex >= static_cast<int>(lines.size())) {
    return false;
  }
  auto fields = nativeSplit(lines[static_cast<size_t>(itemIndex)], '\t');
  if (fields.size() < 3 || fields[1] != "block") return false;
  while (fields.size() < 7) fields.push_back("");
  fields[6] = key == "auto" ? "" : nativeEscapeExtField(key);
  lines[static_cast<size_t>(itemIndex)] = nativeUiJoinFields(fields);
  if (!nativeUiSavePlaylistRecords(project, playlists)) return false;
  g_nativeUiBlockColorKey = key;
  g_nativeMainModalKind = NativeMainModalKind::RenameRow;
  nativeUiShowTemporaryPopup("Cor do bloco atualizada", 1.4);
  return true;
}

static std::string nativeUiBlockMidiItemKey(int blockNumber)
{
  char key[64] = "";
  std::snprintf(key, sizeof(key),
    "BLOCK_BINDING_ITEM_V2_%03d", std::max(1, blockNumber));
  return key;
}

static std::map<int, std::string> nativeUiLoadBlockMidiBindings()
{
  std::map<int, std::string> bindings;
  if (!GetExtState_ptr) return bindings;
  const char* rawList = GetExtState_ptr(
    kMidiBindingExtSection, "BLOCK_BINDINGS_V1");
  for (const auto& line : nativeSplit(rawList ? rawList : "", '\n')) {
    const auto fields = nativeSplit(line, '\t');
    if (fields.size() < 6) continue;
    const int blockNumber = std::atoi(fields[0].c_str());
    if (blockNumber <= 0) continue;
    bindings[blockNumber] = nativeUiJoinFields(
      std::vector<std::string>(fields.begin() + 1, fields.end()));
  }
  const char* rawIndex = GetExtState_ptr(
    kMidiBindingExtSection, "BLOCK_BINDINGS_INDEX_V2");
  std::string numberText;
  const auto loadIndexed = [&](int blockNumber) {
    if (blockNumber <= 0) return;
    const std::string key = nativeUiBlockMidiItemKey(blockNumber);
    const char* raw = GetExtState_ptr(
      kMidiBindingExtSection, key.c_str());
    if (raw && *raw) bindings[blockNumber] = raw;
  };
  const std::string indexText = rawIndex ? rawIndex : "";
  for (size_t index = 0; index <= indexText.size(); ++index) {
    const char value = index < indexText.size() ? indexText[index] : ',';
    if (value >= '0' && value <= '9') {
      numberText.push_back(value);
    } else if (!numberText.empty()) {
      loadIndexed(std::atoi(numberText.c_str()));
      numberText.clear();
    }
  }
  return bindings;
}

static bool nativeUiSaveBlockMidiBindings(
  const std::map<int, std::string>& bindings,
  int removedBlock = 0)
{
  if (!SetExtState_ptr) return false;
  std::ostringstream list;
  std::ostringstream index;
  bool first = true;
  for (const auto& entry : bindings) {
    if (entry.first <= 0 || entry.second.empty()) continue;
    if (!first) {
      list << '\n';
      index << ',';
    }
    first = false;
    list << entry.first << '\t' << entry.second;
    index << entry.first;
    const std::string key = nativeUiBlockMidiItemKey(entry.first);
    SetExtState_ptr(kMidiBindingExtSection,
      key.c_str(), entry.second.c_str(), true);
  }
  if (removedBlock > 0) {
    const std::string key = nativeUiBlockMidiItemKey(removedBlock);
    SetExtState_ptr(kMidiBindingExtSection, key.c_str(), "", true);
  }
  SetExtState_ptr(kMidiBindingExtSection,
    "BLOCK_BINDINGS_V1", list.str().c_str(), true);
  SetExtState_ptr(kMidiBindingExtSection,
    "BLOCK_BINDINGS_INDEX_V2", index.str().c_str(), true);
  return true;
}

static std::string nativeUiBlockMidiFromGeneric(
  const std::string& generic)
{
  const auto fields = nativeSplit(generic, '|');
  if (fields.size() < 6) return "";
  // V3 preserva tambem o nome do dispositivo. Indices WinMM/CoreMIDI nao
  // sao necessariamente iguais, inclusive ao importar um backup no Mac.
  return nativeUiJoinFields({fields[0], fields[1], fields[2],
    fields[3], fields[4], fields[5]});
}

static std::string nativeUiGenericMidiFromBlock(
  const std::string& block)
{
  const auto fields = nativeSplit(block, '\t');
  if (fields.size() < 5) return "";
  if (fields.size() >= 6) {
    return fields[0] + "|" + fields[1] + "|" + fields[2] +
      "|" + fields[3] + "|" + fields[4] + "|" + fields[5];
  }
  const int device = std::atoi(fields[0].c_str());
  char deviceName[256] = "";
  if (GetMIDIInputName_ptr && device >= 0) {
    GetMIDIInputName_ptr(device, deviceName,
      static_cast<int>(sizeof(deviceName)));
  }
  if (deviceName[0] == '\0') {
    std::snprintf(deviceName, sizeof(deviceName), "MIDI %d", device);
  }
  return fields[0] + "|" + deviceName + "|" + fields[1] +
    "|" + fields[2] + "|" + fields[3] + "|" + fields[4];
}

static bool nativeUiMidiBindingsEquivalent(
  const std::string& first,
  const std::string& second)
{
  const auto a = nativeSplit(first, '|');
  const auto b = nativeSplit(second, '|');
  if (a.size() < 6 || b.size() < 6 ||
      a[2] != b[2] || a[3] != b[3] || a[4] != b[4]) {
    return false;
  }
  if ((std::atoi(a[0].c_str()) & 0xffff) ==
      (std::atoi(b[0].c_str()) & 0xffff)) {
    return true;
  }
  const std::string aName = nativeUpperAscii(nativeTrim(a[1]));
  const std::string bName = nativeUpperAscii(nativeTrim(b[1]));
  return !aName.empty() && aName == bName;
}

static std::string nativeUiBlockMidiLabel(int blockNumber)
{
  const auto bindings = nativeUiLoadBlockMidiBindings();
  const auto found = bindings.find(blockNumber);
  if (found == bindings.end()) return "Nenhum";
  return nativeUiMidiBindingLabel(
    nativeUiGenericMidiFromBlock(found->second));
}

static std::string nativeUiFindBlockMidiConflict(
  int blockNumber,
  const std::string& blockBinding)
{
  const auto bindings = nativeUiLoadBlockMidiBindings();
  const std::string genericBinding =
    nativeUiGenericMidiFromBlock(blockBinding);
  for (const auto& entry : bindings) {
    if (entry.first != blockNumber &&
        nativeUiMidiBindingsEquivalent(
          nativeUiGenericMidiFromBlock(entry.second),
          genericBinding)) {
      char label[64] = "";
      std::snprintf(label, sizeof(label), "BLOCO %02d", entry.first);
      return label;
    }
  }
  if (GetExtState_ptr) {
    for (const auto& action : kNativeUiMidiActions) {
      const char* raw = GetExtState_ptr(
        kMidiBindingExtSection, action.storageKey);
      if (raw && *raw &&
          nativeUiMidiBindingsEquivalent(raw, genericBinding)) {
        return action.label;
      }
    }
  }
  return "";
}

static bool nativeUiSaveCapturedBlockMidi(
  const std::string& genericBinding)
{
  if (g_nativeUiBlockMidiNumber <= 0) return false;
  const std::string blockBinding =
    nativeUiBlockMidiFromGeneric(genericBinding);
  if (blockBinding.empty()) return false;
  const std::string conflict = nativeUiFindBlockMidiConflict(
    g_nativeUiBlockMidiNumber, blockBinding);
  if (!conflict.empty()) {
    g_nativeUiBlockMidiInfo =
      "Esse controle MIDI já está em uso: " + conflict;
    nativeUiShowTemporaryPopup(g_nativeUiBlockMidiInfo, 2.6);
    return false;
  }
  auto bindings = nativeUiLoadBlockMidiBindings();
  bindings[g_nativeUiBlockMidiNumber] = blockBinding;
  if (!nativeUiSaveBlockMidiBindings(bindings)) return false;
  char message[96] = "";
  std::snprintf(message, sizeof(message),
    "MIDI do BLOCO %02d mapeado", g_nativeUiBlockMidiNumber);
  nativeUiShowTemporaryPopup(message, 1.5);
  g_nativeMainModalKind = NativeMainModalKind::RenameRow;
  return true;
}

static bool nativeUiOpenBlockMidiCapture()
{
  if (!g_nativeUiRenameBlock || g_nativeUiRenameRegionsPage) return false;
  g_nativeUiBlockMidiNumber =
    std::abs(g_nativeUiRenameSourceNumber);
  if (g_nativeUiBlockMidiNumber <= 0) {
    g_nativeUiBlockMidiNumber =
      std::max(1, g_nativeUiRenamePlaylistOrder);
  }
  g_nativeUiBlockMidiInfo.clear();
  g_nativeMainModalKind = NativeMainModalKind::BlockMidiCapture;
  nativeUiArmMidiCapture();
  return true;
}

static bool nativeUiRemoveBlockMidiBinding()
{
  if (g_nativeUiBlockMidiNumber <= 0) return false;
  auto bindings = nativeUiLoadBlockMidiBindings();
  const auto found = bindings.find(g_nativeUiBlockMidiNumber);
  if (found == bindings.end()) return false;
  bindings.erase(found);
  if (!nativeUiSaveBlockMidiBindings(
        bindings, g_nativeUiBlockMidiNumber)) {
    return false;
  }
  char message[96] = "";
  std::snprintf(message, sizeof(message),
    "MIDI do BLOCO %02d removido", g_nativeUiBlockMidiNumber);
  nativeUiShowTemporaryPopup(message, 1.4);
  g_nativeMainModalKind = NativeMainModalKind::RenameRow;
  return true;
}

static std::string nativeUiFormatDb(double value)
{
  if (!std::isfinite(value) || value <= -89.999) {
    return "-inf dB";
  }
  if (std::fabs(value) < 0.05) value = 0.0;
  char buffer[64] = "";
  std::snprintf(buffer, sizeof(buffer), "%+.1f dB", value);
  return buffer;
}

static bool nativeUiOpenMultiLoopFromRename()
{
  if (g_nativeUiRenameId.empty() ||
      g_nativeUiRenameBlock) {
    return false;
  }
  // Regiões-pai não oferecem Multiloops. A configuração existe somente nas
  // músicas-filho, portanto este caminho nunca deve abrir aviso ou modal.
  if (g_nativeUiRenameFamilyParent) return false;
  std::ostringstream command;
  command << "{\"type\":\"multiloop_focus\",\"songId\":"
          << nativeJsonString(g_nativeUiRenameId)
          << ",\"targetId\":"
          << nativeJsonString(g_nativeUiRenameId)
          << ",\"songName\":"
          << nativeJsonString(g_nativeUiRenameInput)
          << ",\"startPos\":" << std::setprecision(15)
          << g_nativeUiRenameStart
          << ",\"endPos\":" << std::setprecision(15)
          << g_nativeUiRenameEnd << "}";
  if (!nativeApplyMultiLoopCommand(command.str())) return false;
  nativeLoadMultiLoopState();
  g_nativeUiMultiLoopSlot = 0;
  g_nativeUiMultiLoopTrackScroll = 0;
  g_nativeMainModalKind =
    NativeMainModalKind::MultiLoopSong;
  return true;
}

static void nativeUiRefreshMultiLoopTracks()
{
  g_nativeUiMultiLoopTracks.clear();
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !CountTracks_ptr || !GetTrack_ptr) return;
  const int count = CountTracks_ptr(project);
  std::vector<NativeUiMultiLoopFamilyOutline>
    openFolders;
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (!track) continue;
    NativeUiMultiLoopTrackRow row;
    row.guid = nativeTrackGuid(track, index);
    row.name = nativeTrackName(track, index);
    const double volume = GetMediaTrackInfo_Value_ptr
      ? GetMediaTrackInfo_Value_ptr(track, "D_VOL") : 1.0;
    row.baseDb = nativeVolumeToDb(volume);
    const int folderDelta = GetMediaTrackInfo_Value_ptr
      ? static_cast<int>(std::lround(
          GetMediaTrackInfo_Value_ptr(
            track, "I_FOLDERDEPTH")))
      : 0;
    row.group = folderDelta > 0;
    const int rawColor = GetMediaTrackInfo_Value_ptr
      ? static_cast<int>(GetMediaTrackInfo_Value_ptr(
          track, "I_CUSTOMCOLOR"))
      : 0;
    row.hasCustomColor =
      (rawColor & 0x00ffffff) != 0;
    if (row.hasCustomColor) {
      int red = rawColor & 0xff;
      int green = (rawColor >> 8) & 0xff;
      int blue = (rawColor >> 16) & 0xff;
      if (ColorFromNative_ptr) {
        ColorFromNative_ptr(
          rawColor, &red, &green, &blue);
      }
      row.displayColor = RGB(red, green, blue);
    } else {
      row.displayColor = row.group
        ? RGB(57, 214, 104)
        : RGB(255, 224, 46);
    }

    // Cada folder abre seu próprio contorno. Uma subpasta mantém o contorno
    // dos pais e acrescenta outro contorno interno até a pista que a fecha.
    row.familyOutlines = openFolders;
    if (row.group) {
      row.familyOutlines.push_back(
        {row.guid, row.displayColor});
    }
    g_nativeUiMultiLoopTracks.push_back(std::move(row));
    if (folderDelta > 0) {
      openFolders.push_back({
        g_nativeUiMultiLoopTracks.back().guid,
        g_nativeUiMultiLoopTracks.back().displayColor});
    } else if (folderDelta < 0) {
      int closeCount = -folderDelta;
      while (closeCount-- > 0 &&
             !openFolders.empty()) {
        openFolders.pop_back();
      }
    }
  }
}

static bool nativeUiOpenMultiLoopTracks(int slot)
{
  if (g_nativeMultiLoopFocusKey.empty()) return false;
  g_nativeUiMultiLoopSlot =
    std::max(0, std::min(kNativeMultiLoopSlotCount - 1, slot));
  g_nativeUiMultiLoopTrackScroll = 0;
  nativeUiRefreshMultiLoopTracks();
  g_nativeMainModalKind =
    NativeMainModalKind::MultiLoopTracks;
  return true;
}

static bool nativeUiOpenMultiLoopLimit(
  const std::string& guid)
{
  if (guid.empty() || g_nativeMultiLoopFocusKey.empty()) {
    return false;
  }
  nativeLoadMultiLoopState();
  auto trackRow = std::find_if(
    g_nativeUiMultiLoopTracks.begin(),
    g_nativeUiMultiLoopTracks.end(),
    [&](const NativeUiMultiLoopTrackRow& row) {
      return row.guid == guid;
    });
  if (trackRow == g_nativeUiMultiLoopTracks.end()) return false;
  g_nativeUiMultiLoopLimitGuid = guid;
  g_nativeUiMultiLoopLimitTrackName = trackRow->name;
  g_nativeUiMultiLoopLimitBaseDb = std::max(-90.0,
    std::min(150.0, trackRow->baseDb));
  g_nativeUiMultiLoopLimitValueDb = -90.0;
  const auto song = g_nativeMultiLoopStates.find(
    g_nativeMultiLoopFocusKey);
  if (song != g_nativeMultiLoopStates.end()) {
    const auto preset = song->second.tracks[
      g_nativeUiMultiLoopSlot].find(guid);
    if (preset != song->second.tracks[
          g_nativeUiMultiLoopSlot].end() &&
        preset->second.fadeLimitSet) {
      g_nativeUiMultiLoopLimitValueDb =
        preset->second.fadeLimitDb;
    }
  }
  const double maxDb = std::max(-90.0,
    g_nativeUiMultiLoopLimitBaseDb);
  g_nativeUiMultiLoopLimitValueDb = std::max(-90.0,
    std::min(maxDb, g_nativeUiMultiLoopLimitValueDb));
  g_nativeUiMultiLoopLimitSliderRect = RECT{0, 0, 0, 0};
  g_nativeUiMultiLoopLimitDragging = false;
  g_nativeMainModalKind =
    NativeMainModalKind::MultiLoopLimit;
  return true;
}

static bool nativeUiSetMultiLoopLimitFromPoint(int pointX)
{
  if (g_nativeMainModalKind !=
        NativeMainModalKind::MultiLoopLimit ||
      g_nativeUiMultiLoopLimitGuid.empty()) {
    return false;
  }
  const int width = std::max(1,
    static_cast<int>(
      g_nativeUiMultiLoopLimitSliderRect.right -
      g_nativeUiMultiLoopLimitSliderRect.left));
  const double ratio = std::max(0.0, std::min(1.0,
    static_cast<double>(pointX -
      g_nativeUiMultiLoopLimitSliderRect.left) / width));
  const double maxDb = std::max(-90.0,
    g_nativeUiMultiLoopLimitBaseDb);
  double value = -90.0 + (maxDb + 90.0) * ratio;
  value = std::floor(value * 2.0 + 0.5) / 2.0;
  g_nativeUiMultiLoopLimitValueDb =
    std::max(-90.0, std::min(maxDb, value));
  std::ostringstream command;
  command << "{\"type\":\"multiloop_track_limit_set\","
          << "\"slot\":" << (g_nativeUiMultiLoopSlot + 1)
          << ",\"trackId\":"
          << nativeJsonString(g_nativeUiMultiLoopLimitGuid)
          << ",\"limitDb\":" << std::setprecision(15)
          << g_nativeUiMultiLoopLimitValueDb << "}";
  return nativeApplyMultiLoopCommand(command.str());
}

