static bool nativeUiNumberRegionModeFromExtState()
{
  if (!GetExtState_ptr) {
    return g_nativeAppActivePanelModel.numberRegionMode;
  }
  const char* raw = GetExtState_ptr(
    kLuaWindowExtStateSection, "NUMBER_COLUMN_MODE_V1");
  return raw && std::string(raw) == "region_id";
}

static void nativeUiCapturePlaylistRetry()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return;
  g_nativePlaylistRetryData =
    nativeGetProjExtStateString(project, kPlaylistExtSection, kPlaylistExtKey);
  g_nativePlaylistRetryName =
    nativeGetProjExtStateString(project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1");
  g_nativePlaylistRetryNumberRegionMode =
    nativeUiNumberRegionModeFromExtState();
  g_nativePlaylistRetryNumberModeValid = true;
  g_nativePlaylistRetrySortDescendingNext =
    g_nativePlaylistSortDescendingNext;
}

static void nativeUiCaptureRegionsRetry()
{
  g_nativeRegionsRetrySortMode = g_nativeRegionsSortMode;
  g_nativeRegionsRetryNumberRegionMode =
    nativeUiNumberRegionModeFromExtState();
  g_nativeRegionsRetryNumberModeValid = true;
}

static bool nativeUiApplyRetry()
{
  if (g_nativeAppActivePanelModel.regionsPage) {
    if (!g_nativeRegionsRetryNumberModeValid ||
        g_nativeRegionsRetrySortMode < 0) return false;
    g_nativeRegionsSortMode = g_nativeRegionsRetrySortMode;
    g_nativeRegionsRetrySortMode = -1;
    if (SetExtState_ptr) {
      SetExtState_ptr(kLuaWindowExtStateSection,
        "NUMBER_COLUMN_MODE_V1",
        g_nativeRegionsRetryNumberRegionMode
          ? "region_id" : "list_order", true);
    }
    g_nativeRegionsRetryNumberModeValid = false;
    g_nativeAppActiveListScrollPixels = 0;
    g_nativeForceSnapshotBuild.store(true);
    g_nativeForceStateBuild.store(true);
    return true;
  }

  if (!g_nativePlaylistRetryNumberModeValid || !SetProjExtState_ptr) return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;
  const std::string currentName =
    nativeGetProjExtStateString(project, kPlaylistExtSection, "LAST_PLAYLIST_NAME_V1");
  if (!g_nativePlaylistRetryName.empty() && currentName != g_nativePlaylistRetryName) return false;
  SetProjExtState_ptr(project, kPlaylistExtSection, kPlaylistExtKey,
    g_nativePlaylistRetryData.c_str());
  if (SetExtState_ptr) {
    SetExtState_ptr(kLuaWindowExtStateSection,
      "NUMBER_COLUMN_MODE_V1",
      g_nativePlaylistRetryNumberRegionMode
        ? "region_id" : "list_order", true);
  }
  g_nativePlaylistSortDescendingNext =
    g_nativePlaylistRetrySortDescendingNext;
  g_nativePlaylistRetryData.clear();
  g_nativePlaylistRetryName.clear();
  g_nativePlaylistRetryNumberModeValid = false;
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static void nativeUiSetNumberMode(bool regionNumber)
{
  if (g_nativeAppActivePanelModel.regionsPage) {
    nativeUiCaptureRegionsRetry();
  } else {
    nativeUiCapturePlaylistRetry();
  }
  if (SetExtState_ptr) {
    SetExtState_ptr(kLuaWindowExtStateSection, "NUMBER_COLUMN_MODE_V1",
      regionNumber ? "region_id" : "list_order", true);
  }
  if (regionNumber) {
    if (g_nativeAppActivePanelModel.regionsPage) {
      g_nativeRegionsSortMode = 3;
    } else {
      nativeApplyPlaylistNumberSortCommand(
        "{\"type\":\"sort_playlist_by_number\",\"direction\":\"asc\"}");
    }
  }
  g_nativeForceStateBuild.store(true);
  g_nativeAppActiveListScrollPixels = 0;
}

static void nativeUiApply09Sort()
{
  if (!g_nativeAppActivePanelModel.numberRegionMode) {
    nativeUiOpenMessage("0-9 só funciona com Number em ID da região.");
    return;
  }
  if (g_nativeAppActivePanelModel.regionsPage) {
    nativeUiCaptureRegionsRetry();
    g_nativeRegionsSortMode = g_nativeRegionsSortMode == 3 ? 4 : 3;
  } else {
    nativeUiCapturePlaylistRetry();
    nativeApplyPlaylistNumberSortCommand(g_nativePlaylistSortDescendingNext
      ? "{\"type\":\"sort_playlist_by_number\",\"direction\":\"desc\"}"
      : "{\"type\":\"sort_playlist_by_number\",\"direction\":\"asc\"}");
    g_nativePlaylistSortDescendingNext = !g_nativePlaylistSortDescendingNext;
  }
  g_nativeAppActiveListScrollPixels = 0;
}

static std::string nativeUiBlockEditValue(const std::string& rawName)
{
  std::string value = nativeTrim(rawName);
  const std::string upper = nativeUpperNamePtBr(value);
  const size_t blockPos = upper.find("BLOCO");
  if (blockPos != std::string::npos) {
    value = nativeTrim(value.substr(blockPos + 5));
  }
  while (!value.empty()) {
    const char c = value.front();
    if (c == ':' || c == '=' || c == '>' || c == '<' ||
        c == '-' || c == ' ') value.erase(value.begin());
    else break;
  }
  while (!value.empty()) {
    const char c = value.back();
    if (c == ':' || c == '=' || c == '>' || c == '<' ||
        c == '-' || c == ' ') value.pop_back();
    else break;
  }
  return nativeTrim(value);
}

static bool nativeUiBlockNameIsFormatted(
  const std::string& rawName)
{
  const std::string value = nativeTrim(rawName);
  const std::string upper = nativeUpperNamePtBr(value);
  const size_t blockPos = upper.find("BLOCO");
  if (blockPos == std::string::npos) return false;
  if (blockPos == 0) return true;
  for (size_t i = 0; i < blockPos; ++i) {
    const char c = value[i];
    if (c != ':' && c != '=' && c != '>' && c != '<' &&
        c != '-' && c != ' ' && c != '\t') {
      return false;
    }
  }
  return true;
}

static std::string nativeUiPlainBlockDisplayName(
  const std::string& rawName)
{
  if (!nativeUiBlockNameIsFormatted(rawName)) {
    return rawName;
  }
  std::string suffix = nativeUiBlockEditValue(rawName);
  suffix = nativeUpperNamePtBrKeepParentheses(suffix);
  return suffix.empty() ? "BLOCO" : "BLOCO " + suffix;
}

static void nativeUiDrawDesignerBlockLabel(
  HDC dc,
  const RECT& area,
  const std::string& rawName,
  const std::string& rawMode,
  COLORREF textColor,
  COLORREF ornamentColor,
  HFONT font)
{
  if (!dc || area.right <= area.left ||
      area.bottom <= area.top) return;
  const std::string label =
    nativeUiPlainBlockDisplayName(rawName);
  const std::string mode = nativeLower(
    nativeTrim(rawMode));
  const int areaW = std::max(1,
    static_cast<int>(area.right - area.left));
  const int measuredW = nativeUiTextWidth(dc, label, font);
  const int labelW = std::min(areaW,
    std::max(38, measuredW + 12));
  const int centerX = (area.left + area.right) / 2;
  const RECT labelRect{
    std::max(static_cast<int>(area.left),
      centerX - labelW / 2),
    area.top,
    std::min(static_cast<int>(area.right),
      centerX - labelW / 2 + labelW),
    area.bottom};
  nativeAppActiveDrawText(dc, label, labelRect,
    DT_CENTER | DT_VCENTER | DT_SINGLELINE |
      DT_END_ELLIPSIS | DT_NOPREFIX,
    textColor, font);
  if (mode == "none" || mode.empty()) return;

  const int middleY = (area.top + area.bottom) / 2;
  const int ornamentGap = 7;
  const int leftStart = area.left + 6;
  const int leftEnd = labelRect.left - ornamentGap;
  const int rightStart = labelRect.right + ornamentGap;
  const int rightEnd = area.right - 6;
  if (leftEnd - leftStart < 5 ||
      rightEnd - rightStart < 5) return;

  if (mode == "colon") {
    const int dotSize = 3;
    const int dotGap = 5;
    const int available = std::min(
      leftEnd - leftStart,
      rightEnd - rightStart);
    const int dotCount = std::max(1,
      (available + dotGap) / (dotSize + dotGap));
    const double step = dotCount > 1
      ? static_cast<double>(available - dotSize) /
          static_cast<double>(dotCount - 1)
      : 0.0;
    const NativeUiBrushRef dotBrush =
      nativeUiBrush(ornamentColor);
    const NativeUiPenRef dotPen =
      nativeUiPen(ornamentColor);
    HGDIOBJ oldBrush = dotBrush.handle
      ? SelectObject(dc, dotBrush.handle) : nullptr;
    HGDIOBJ oldPen = dotPen.handle
      ? SelectObject(dc, dotPen.handle) : nullptr;
    for (int index = 0; index < dotCount; ++index) {
      const int offset = static_cast<int>(std::round(index * step));
      const RECT leftDot{leftStart + offset,
        middleY - 1, leftStart + offset + dotSize,
        middleY + 2};
      const RECT rightDot{rightStart + offset,
        middleY - 1, rightStart + offset + dotSize,
        middleY + 2};
      Ellipse(dc, leftDot.left, leftDot.top,
        leftDot.right + 1, leftDot.bottom + 1);
      Ellipse(dc, rightDot.left, rightDot.top,
        rightDot.right + 1, rightDot.bottom + 1);
    }
    if (oldPen) SelectObject(dc, oldPen);
    if (oldBrush) SelectObject(dc, oldBrush);
    if (dotPen.temporary && dotPen.handle) DeleteObject(dotPen.handle);
    if (dotBrush.temporary && dotBrush.handle) DeleteObject(dotBrush.handle);
    return;
  }

  if (mode == "equal") {
    for (const int offset : {-3, 3}) {
      nativeAppActiveFillRect(dc,
        RECT{leftStart, middleY + offset,
          leftEnd, middleY + offset + 1}, ornamentColor);
      nativeAppActiveFillRect(dc,
        RECT{rightStart, middleY + offset,
          rightEnd, middleY + offset + 1}, ornamentColor);
    }
    return;
  }

  if (mode == "dash") {
    const int dashW = 8;
    const int dashGap = 5;
    for (int x = leftStart; x < leftEnd; x += dashW + dashGap) {
      nativeAppActiveFillRect(dc,
        RECT{x, middleY, std::min(leftEnd, x + dashW), middleY + 2},
        ornamentColor);
    }
    for (int x = rightStart; x < rightEnd; x += dashW + dashGap) {
      nativeAppActiveFillRect(dc,
        RECT{x, middleY, std::min(rightEnd, x + dashW), middleY + 2},
        ornamentColor);
    }
    return;
  }

  if (mode == "diamond" || mode == "spark" ||
      mode == "capsule") {
    const NativeUiPenRef pen = nativeUiPen(ornamentColor, 2);
    if (!pen.handle) return;
    HGDIOBJ oldPen = SelectObject(dc, pen.handle);
    const auto drawDiamondBand = [&](int start, int end) {
      const int radius = 3;
      for (int x = start + radius; x + radius <= end; x += 13) {
        MoveToEx(dc, x - radius, middleY, nullptr);
        LineTo(dc, x, middleY - radius);
        LineTo(dc, x + radius, middleY);
        LineTo(dc, x, middleY + radius);
        LineTo(dc, x - radius, middleY);
      }
    };
    const auto drawSparkBand = [&](int start, int end) {
      for (int x = start + 3; x + 3 <= end; x += 14) {
        MoveToEx(dc, x - 3, middleY, nullptr);
        LineTo(dc, x + 4, middleY);
        MoveToEx(dc, x, middleY - 3, nullptr);
        LineTo(dc, x, middleY + 4);
        MoveToEx(dc, x - 2, middleY - 2, nullptr);
        LineTo(dc, x + 3, middleY + 3);
        MoveToEx(dc, x + 2, middleY - 2, nullptr);
        LineTo(dc, x - 3, middleY + 3);
      }
    };
    if (mode == "diamond") {
      drawDiamondBand(leftStart, leftEnd);
      drawDiamondBand(rightStart, rightEnd);
    } else if (mode == "spark") {
      drawSparkBand(leftStart, leftEnd);
      drawSparkBand(rightStart, rightEnd);
    } else {
      MoveToEx(dc, leftStart, middleY, nullptr);
      LineTo(dc, leftEnd, middleY);
      MoveToEx(dc, rightStart, middleY, nullptr);
      LineTo(dc, rightEnd, middleY);
      const int radius = 3;
      Ellipse(dc, leftStart, middleY - radius,
        leftStart + radius * 2, middleY + radius + 1);
      Ellipse(dc, leftEnd - radius * 2, middleY - radius,
        leftEnd, middleY + radius + 1);
      Ellipse(dc, rightStart, middleY - radius,
        rightStart + radius * 2, middleY + radius + 1);
      Ellipse(dc, rightEnd - radius * 2, middleY - radius,
        rightEnd, middleY + radius + 1);
    }
    if (oldPen) SelectObject(dc, oldPen);
    if (pen.temporary) DeleteObject(pen.handle);
    return;
  }

  // Modo angle: uma linha continua ocupa cada lado e termina em uma seta.
  const NativeUiPenRef pen = nativeUiPen(ornamentColor, 2);
  if (!pen.handle) return;
  HGDIOBJ oldPen = SelectObject(dc, pen.handle);
  const int chevronH = std::max(3,
    std::min(6, static_cast<int>(
      (area.bottom - area.top) / 3)));
  const int arrowW = 6;
  MoveToEx(dc, leftStart, middleY, nullptr);
  LineTo(dc, leftEnd, middleY);
  MoveToEx(dc, leftEnd - arrowW,
    middleY - chevronH, nullptr);
  LineTo(dc, leftEnd, middleY);
  LineTo(dc, leftEnd - arrowW,
    middleY + chevronH);

  MoveToEx(dc, rightEnd, middleY, nullptr);
  LineTo(dc, rightStart, middleY);
  MoveToEx(dc, rightStart + arrowW,
    middleY - chevronH, nullptr);
  LineTo(dc, rightStart, middleY);
  LineTo(dc, rightStart + arrowW,
    middleY + chevronH);
  if (oldPen) SelectObject(dc, oldPen);
  if (pen.temporary) DeleteObject(pen.handle);
}

static std::string nativeUiProjectRawNameForRow(
  const NativeAppActivePanelModel::Row& row)
{
  if (row.block || !EnumProjectMarkers3_ptr || !CountProjectMarkers_ptr) {
    return row.name;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return row.name;
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  for (int i = 0; i < total; ++i) {
    bool isRegion = false;
    double pos = 0.0;
    double end = 0.0;
    const char* rawName = nullptr;
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, i, &isRegion, &pos, &end,
        &rawName, &number, &color)) continue;
    if ((row.enumIndex >= 0 && i == row.enumIndex) ||
        (row.enumIndex < 0 && number == row.sourceNumber &&
         isRegion != row.markerChild)) {
      return rawName ? std::string(rawName) : row.name;
    }
  }
  return row.name;
}

static void nativeUiOpenRowRename(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage)
{
  g_nativeUiRenameRegionsPage = regionsPage;
  g_nativeUiRenameBlock = row.block;
  g_nativeUiRenameBlockCustomName =
    row.block && !nativeUiBlockNameIsFormatted(row.name);
  g_nativeUiRenameMarkerChild = row.markerChild;
  g_nativeUiRenameFamilyParent = row.familyParent;
  g_nativeUiRenameSourceNumber = row.sourceNumber;
  g_nativeUiRenameEnumIndex = row.enumIndex;
  g_nativeUiRenamePlaylistOrder = row.order;
  g_nativeUiRenameStart = row.start;
  g_nativeUiRenameEnd = row.end;
  g_nativeUiRenameId = row.id;
  g_nativeUiRenameOriginalName = row.name;
  if (row.block) {
    g_nativeUiRenameInput = g_nativeUiRenameBlockCustomName
      ? nativeTrim(row.name)
      : nativeUiBlockEditValue(row.name);
    int blockNumber = std::abs(row.sourceNumber);
    if (blockNumber <= 0) blockNumber = std::max(1, row.order);
    char defaultNumber[16] = "";
    std::snprintf(defaultNumber, sizeof(defaultNumber),
      "%02d", blockNumber);
    if (!g_nativeUiRenameBlockCustomName &&
        nativeUpperNamePtBr(nativeTrim(g_nativeUiRenameInput)) ==
          defaultNumber) {
      g_nativeUiRenameInput.clear();
    }
  } else {
    g_nativeUiRenameInput = nativeUiProjectRawNameForRow(row);
  }
  g_nativeUiRenameInputCursor = g_nativeUiRenameInput.size();
  g_nativeUiTextSelectionKind =
    NativeUiTextInputKind::RenameRow;
  g_nativeUiTextSelectionAnchor =
    g_nativeUiRenameInputCursor;
  g_nativeMainModalKind = NativeMainModalKind::RenameRow;
}

static std::string nativeUiJoinFields(
  const std::vector<std::string>& fields)
{
  std::ostringstream out;
  for (size_t i = 0; i < fields.size(); ++i) {
    if (i) out << '\t';
    out << fields[i];
  }
  return out.str();
}

static bool nativeUiApplyRowRename()
{
  std::string nextName = g_nativeUiRenameBlock
    ? nativeUpperNamePtBrKeepParentheses(
        nativeTrim(g_nativeUiRenameInput))
    : nativeUpperNamePtBrKeepParentheses(
        nativeTrim(g_nativeUiRenameInput));
  if (nextName.empty() && !g_nativeUiRenameBlock) return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;

  if (g_nativeUiRenameBlock) {
    std::vector<NativeUiPlaylistRecord> playlists =
      nativeUiReadPlaylistRecords(project);
    const int playlistIndex = nativeUiCurrentPlaylistIndex(project, playlists);
    if (playlistIndex < 0 ||
        playlistIndex >= static_cast<int>(playlists.size())) return false;
    auto& itemLines =
      playlists[static_cast<size_t>(playlistIndex)].itemLines;
    const int itemIndex = nativeUiRenamePlaylistLineIndex(itemLines);
    if (itemIndex < 0 || itemIndex >= static_cast<int>(itemLines.size())) {
      return false;
    }
    auto fields = nativeSplit(itemLines[static_cast<size_t>(itemIndex)], '\t');
    if (fields.size() < 6) return false;
    int blockNumber = std::abs(std::atoi(fields[2].c_str()));
    if (blockNumber <= 0) blockNumber = g_nativeUiRenamePlaylistOrder;
    std::string fullName;
    if (g_nativeUiRenameBlockCustomName && !nextName.empty()) {
      fullName = nextName;
    } else {
      std::string suffix = nextName;
      const std::string upper = nativeUpperNamePtBr(suffix);
      const size_t blockPos = upper.find("BLOCO");
      if (blockPos != std::string::npos) {
        suffix = nativeUiBlockEditValue(suffix);
      }
      if (suffix.empty()) {
        char numberText[16] = "";
        std::snprintf(numberText, sizeof(numberText), "%02d", blockNumber);
        suffix = numberText;
      }
      fullName = nativeUiFormatBlockNameForCurrentSymbol(suffix);
    }
    if (fullName.empty()) {
      char numberText[16] = "";
      std::snprintf(numberText, sizeof(numberText), "%02d", blockNumber);
      fullName = nativeUiFormatBlockNameForCurrentSymbol(numberText);
    }
    fields[5] = nativeEscapeExtField(fullName);
    itemLines[static_cast<size_t>(itemIndex)] = nativeUiJoinFields(fields);
    if (!nativeUiSavePlaylistRecords(project, playlists)) return false;
    nativeUiCloseMainModal();
    return true;
  }

  if (!SetProjectMarkerByIndex2_ptr || !EnumProjectMarkers3_ptr ||
      !CountProjectMarkers_ptr) return false;
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  int foundEnum = -1;
  bool foundRegion = !g_nativeUiRenameMarkerChild;
  double foundStart = g_nativeUiRenameStart;
  double foundEnd = g_nativeUiRenameEnd;
  int foundNumber = g_nativeUiRenameSourceNumber;
  int foundColor = 0;
  for (int i = 0; i < total; ++i) {
    bool isRegion = false;
    double pos = 0.0;
    double end = 0.0;
    const char* rawName = nullptr;
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, i, &isRegion, &pos, &end,
        &rawName, &number, &color)) continue;
    const bool exactEnum =
      g_nativeUiRenameEnumIndex >= 0 && i == g_nativeUiRenameEnumIndex;
    const bool numberFallback =
      g_nativeUiRenameEnumIndex < 0 &&
      number == g_nativeUiRenameSourceNumber &&
      isRegion != g_nativeUiRenameMarkerChild;
    if (!exactEnum && !numberFallback) continue;
    foundEnum = i;
    foundRegion = isRegion;
    foundStart = pos;
    foundEnd = isRegion ? end : 0.0;
    foundNumber = number;
    foundColor = color;
    break;
  }
  if (foundEnum < 0) return false;
  if (!SetProjectMarkerByIndex2_ptr(project, foundEnum, foundRegion,
      foundStart, foundEnd, foundNumber, nextName.c_str(),
      foundColor, 0)) {
    return false;
  }

  // O Lua sincroniza o nome da fonte em todos os repertórios. Preserva todos
  // os demais campos e altera somente a coluna de nome correspondente.
  std::vector<NativeUiPlaylistRecord> playlists =
    nativeUiReadPlaylistRecords(project);
  bool playlistChanged = false;
  for (auto& playlist : playlists) {
    for (std::string& itemLine : playlist.itemLines) {
      auto fields = nativeSplit(itemLine, '\t');
      if (fields.size() < 6 || fields[1] == "block") continue;
      const int storedSource = std::atoi(fields[2].c_str());
      const bool storedMarkerChild =
        fields.size() > 9 && fields[9] == "1";
      const int storedMarkerNumber =
        fields.size() > 10 ? std::atoi(fields[10].c_str()) : 0;
      const bool matches = foundRegion
        ? (!storedMarkerChild && storedSource == foundNumber)
        : (storedMarkerChild &&
           (storedMarkerNumber == foundNumber ||
            storedSource == foundNumber));
      if (!matches) continue;
      fields[5] = nativeEscapeExtField(nextName);
      itemLine = nativeUiJoinFields(fields);
      playlistChanged = true;
    }
  }
  if (playlistChanged) nativeUiSavePlaylistRecords(project, playlists);
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  nativeUiCloseMainModal();
  return true;
}

static void nativeUiNormalizeTimerDigits()
{
  std::string digits = g_nativeUiTimerDigits;
  while (digits.size() < 6) digits.insert(digits.begin(), '0');
  if (digits.size() > 6) digits = digits.substr(digits.size() - 6);
  for (char& value : digits) {
    if (value < '0' || value > '9') value = '0';
  }
  const int hours = std::max(0, std::min(99,
    std::atoi(digits.substr(0, 2).c_str())));
  const int minutes = std::max(0, std::min(59,
    std::atoi(digits.substr(2, 2).c_str())));
  const int seconds = std::max(0, std::min(59,
    std::atoi(digits.substr(4, 2).c_str())));
  char normalized[16] = "";
  std::snprintf(normalized, sizeof(normalized), "%02d%02d%02d",
    hours, minutes, seconds);
  g_nativeUiTimerDigits = normalized;
}

static std::string nativeUiTimerDisplayFromDigits()
{
  nativeUiNormalizeTimerDigits();
  return g_nativeUiTimerDigits.substr(0, 2) + ":" +
    g_nativeUiTimerDigits.substr(2, 2) + ":" +
    g_nativeUiTimerDigits.substr(4, 2);
}

static double nativeUiTimerSecondsFromDigits()
{
  nativeUiNormalizeTimerDigits();
  const std::string digits = g_nativeUiTimerDigits;
  const int hours = std::atoi(digits.substr(0, 2).c_str());
  const int minutes = std::min(59,
    std::atoi(digits.substr(2, 2).c_str()));
  const int seconds = std::min(59,
    std::atoi(digits.substr(4, 2).c_str()));
  return static_cast<double>(hours * 3600 + minutes * 60 + seconds);
}

static void nativeUiOpenTimerConfig()
{
  double target = 0.0;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    g_nativeUiTimerMode = nativeNormalizeTimerMode(g_nativeTimerMode);
    target = std::max(0.0, g_nativeTimerTargetSec);
  }
  const int total = std::max(0,
    std::min(99 * 3600 + 59 * 60 + 59,
      static_cast<int>(std::floor(target + 0.5))));
  const int hours = total / 3600;
  const int minutes = (total % 3600) / 60;
  const int seconds = total % 60;
  char digits[16] = "";
  std::snprintf(digits, sizeof(digits), "%02d%02d%02d",
    hours, minutes, seconds);
  g_nativeUiTimerDigits = digits;
  g_nativeUiTimerDigitCursor = 0;
  g_nativeUiTimerCaretPositionsValid = false;
  g_nativeUiTextSelectionKind =
    g_nativeUiTimerMode == "countdown"
      ? NativeUiTextInputKind::TimerCountdown
      : NativeUiTextInputKind::None;
  g_nativeUiTextSelectionAnchor = 0;
  g_nativeMainModalKind = NativeMainModalKind::TimerConfig;
}

static void nativeUiSetTimerDigit(char digit)
{
  if (digit < '0' || digit > '9') return;
  nativeUiNormalizeTimerDigits();
  g_nativeUiTimerDigitCursor = std::max(0,
    std::min(6, g_nativeUiTimerDigitCursor));
  if (g_nativeUiTimerDigitCursor >= 6) {
    g_nativeUiTimerDigitCursor = 5;
  }
  g_nativeUiTimerDigits[
    static_cast<size_t>(g_nativeUiTimerDigitCursor)] = digit;
  nativeUiNormalizeTimerDigits();
  g_nativeUiTimerDigitCursor =
    std::min(6, g_nativeUiTimerDigitCursor + 1);
}

static void nativeUiClearTimerDigit(bool moveBack)
{
  nativeUiNormalizeTimerDigits();
  g_nativeUiTimerDigitCursor = std::max(0,
    std::min(6, g_nativeUiTimerDigitCursor));
  if (moveBack) {
    if (g_nativeUiTimerDigitCursor <= 0) return;
    g_nativeUiTimerDigitCursor =
      std::max(0, g_nativeUiTimerDigitCursor - 1);
  } else if (g_nativeUiTimerDigitCursor >= 6) {
    return;
  }
  g_nativeUiTimerDigits[
    static_cast<size_t>(g_nativeUiTimerDigitCursor)] = '0';
  nativeUiNormalizeTimerDigits();
}

static bool nativeUiSaveTimerConfig()
{
  std::ostringstream command;
  command << "{\"type\":\"timer_config\",\"mode\":"
          << nativeJsonString(g_nativeUiTimerMode)
          << ",\"targetSec\":" << std::setprecision(15)
          << nativeUiTimerSecondsFromDigits() << "}";
  const bool handled = nativeApplyTimerCommand(command.str());
  if (handled) nativeUiCloseMainModal();
  return handled;
}

static std::pair<std::string, std::vector<std::string>>
nativeUiHelpTopicContent(const std::string& topic)
{
  if (topic == "alterar_tonalidade") {
    return {"Alterar tonalidade", {
      "Para o VS Hook controlar tonalidade, coloque # no inicio do nome das pistas que contem harmonia.",
      "Exemplo: # TECLADO, # VIOLAO, # GUITARRA ou qualquer pista harmonica que precise acompanhar o tom.",
      "Ao usar Converter ou Atualizar, o VS Hook insere automaticamente o ReaPitch como primeiro FX dessa pista.",
      "Depois abra a coluna Tuner no VS Hook e configure a tonalidade individualmente por musica.",
      "O Tuner salva a configuracao por musica/repertorio e aplica nas pistas preparadas com # e ReaPitch.",
      "Pistas sem # nao entram no controle de tonalidade do VS Hook."
    }};
  }
  if (topic == "shortcuts_symbols") {
#ifdef __APPLE__
    const char* stopBreakShortcut =
      "Fn + Espaco: executa Stop Break sem mover o cursor e sem FaderOut.";
    const char* playlistStepShortcut =
      "Command + seta para cima/baixo: abre o repertorio anterior ou o proximo. Funciona somente na aba Repertorios.";
#else
    const char* stopBreakShortcut =
      "Ctrl + Espaco: executa Stop Break sem mover o cursor e sem FaderOut.";
    const char* playlistStepShortcut =
      "Ctrl + seta para cima/baixo: abre o repertorio anterior ou o proximo. Funciona somente na aba Repertorios.";
#endif
    return {"Atalhos e simbolos", {
      "Espaco: Play/Stop.",
      stopBreakShortcut,
      "L ou R: aciona Loop.",
      "C: ativa/desativa o cronometro visual.",
      "F1: abre Repertorios.",
      "F2: abre Musicas.",
      "F3: abre Mixer.",
      "F4: Auto 1 - fila de espera com reprodução automática.",
      "F5: Auto 2 - fila de espera sem reprodução automática.",
      "F6: deixa todos os Multiloops desativados temporariamente enquanto o BY está ativo.",
      "F7: abre/fecha Tuner.",
      "F8: abre/fecha Parts 2.",
      "F9: abre/fecha Parts 1.",
      playlistStepShortcut,
      "Tab: abre a busca inteligente no repertorio e em Musicas.",
      "Esc: cancela loop ou janela aberta.",
      "$ no inicio do nome do marker tambem entra em Parts, mas o simbolo nao aparece na lista.",
      "*1 no inicio do nome do marker entra em Parts 1, mas o simbolo nao aparece na lista.",
      "*2 no inicio do nome do marker entra em Parts 2, mas o simbolo nao aparece na lista.",
      "*3 e *4 criam os pares dos Multi Loops 3 e 4; os simbolos nao aparecem na lista.",
      "! no inicio do nome do marker oculta o marker em todas as listas e Parts.",
      "# no inicio do nome da pista permite que o VS Hook controle o ReaPitch daquela pista.",
      "Texto escrito entre ( ) nao e forcado para caixa alta. Exemplo: INTRO (voz baixa) mantem o texto dentro dos parenteses como foi digitado."
    }};
  }
  if (topic == "backup_config") {
    return {"Exportar / Importar Backup", {
      "Use este recurso para passar as configuracoes globais do VS Hook de um computador para outro.",
      "No computador de origem, abra Config e clique em Exportar Backup. Copie o arquivo .vshookbackup para o outro computador. No computador de destino, abra Config, clique em Importar Backup e confirme a restauracao.",
      "O backup salva os Presets 1, 2 e 3 completos e qual deles estava ativo; cores, fundos, bordas, escala da lista, painel transporte, barras, layout e colunas da interface.",
      "Tambem salva Auto, AT/BL, Auto Stop, cronometro, Preview ativo, FaderOut ligado e duracao, Play Protection, configuracoes das duas janelas do Teleprompt, atribuicoes MIDI, atalhos do Tuner, MIDI global do Mixer, senhas do Diretor e Recados, Startup e modo de Timecode.",
      "Nao salva repertorios nem dados especificos do projeto, como tonalidades das musicas, letras, Multiloops e pistas escolhidas no FaderOut. Tambem nao salva posicao/dock da janela, licenca ou sessao ativa.",
      "As configuracoes do Teleprompt sao levadas no mesmo arquivo .vshookbackup; nao existe mais backup separado para elas.",
      "Importante: o arquivo inclui as senhas de acesso salvas. Guarde-o em local seguro e compartilhe somente com quem deve receber essas configuracoes."
    }};
  }
  return {"Meus atalhos",
    nativeUiCollectMyShortcutsLines()};
}

static std::string nativeUiMixerStorageId(
  const std::string& trackId)
{
  if (trackId == "MASTER_TRACK") return trackId;
  std::string out;
  for (unsigned char value : trackId) {
    if (std::isalnum(value)) {
      out.push_back(static_cast<char>(value));
    }
  }
  return out;
}

static std::string nativeUiMixerBindingKey(
  const std::string& trackId,
  const std::string& action,
  const std::string& kind)
{
  const std::string prefix =
    action == "solo" ? "SOLO"
      : (action == "volume" ? "VOLUME" : "MUTE");
  return prefix + (kind == "midi" ? "_MIDI_" : "_KEY_") +
    nativeUiMixerStorageId(trackId);
}

static std::string nativeUiReadMixerBinding(
  const std::string& trackId,
  const std::string& action,
  const std::string& kind)
{
  const std::string key = nativeUiMixerBindingKey(
    trackId, action, kind);
  if (kind == "midi") {
    const char* raw = GetExtState_ptr
      ? GetExtState_ptr(kMixerBindingExtSection, key.c_str())
      : nullptr;
    return raw ? raw : "";
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return "";
  std::string raw = nativeGetProjExtStateString(
    project, kMixerBindingExtSection, key.c_str());
  if (raw.empty() && GetExtState_ptr) {
    const char* legacy =
      GetExtState_ptr(kMixerBindingExtSection, key.c_str());
    raw = legacy ? legacy : "";
  }
  return raw;
}

static std::string nativeUiKeyboardBindingLabel(
  const std::string& raw)
{
  if (raw.empty()) return "Nao atribuido";
  const size_t separator = raw.find('|');
  const std::string codeText = separator == std::string::npos
    ? raw : raw.substr(0, separator);
  if (nativeLooksNumeric(codeText)) {
    // Recalcula o rotulo para corrigir configuracoes antigas que salvaram
    // apenas "Tecla 189" e para respeitar o layout de teclado atual.
    return nativeUiKeyboardBindingName(
      std::atoi(codeText.c_str()));
  }
  if (separator != std::string::npos &&
      separator + 1 < raw.size()) {
    return raw.substr(separator + 1);
  }
  return raw;
}

static std::string nativeUiMidiBindingLabel(
  const std::string& raw)
{
  const auto fields = nativeSplit(raw, '|');
  if (fields.size() < 6) return "Nao atribuido";
  const std::string device =
    fields[1].empty() ? "MIDI" : fields[1];
  const std::string type = fields[2];
  const int channel = std::atoi(fields[3].c_str());
  const int data1 = std::atoi(fields[4].c_str());
  std::ostringstream text;
  text << device << " | ";
  if (type == "note") {
    text << "Note CH" << channel << " N" << data1;
  } else if (type == "cc") {
    text << "CC CH" << channel << " CC" << data1;
  } else if (type == "pc") {
    text << "PC CH" << channel << " P" << data1;
  } else {
    return raw;
  }
  return text.str();
}

static int nativeUiMidiActionCount()
{
  return static_cast<int>(
    sizeof(kNativeUiMidiActions) /
    sizeof(kNativeUiMidiActions[0]));
}

static const NativeUiMidiActionDef*
nativeUiMidiActionAt(int index)
{
  return index >= 0 &&
      index < nativeUiMidiActionCount()
    ? &kNativeUiMidiActions[index]
    : nullptr;
}

static const NativeUiMidiActionDef*
nativeUiFindMidiAction(const std::string& key)
{
  for (int index = 0;
       index < nativeUiMidiActionCount(); ++index) {
    const auto* action = nativeUiMidiActionAt(index);
    if (action && key == action->key) return action;
  }
  return nullptr;
}

static std::string nativeUiReadMidiBinding(
  const std::string& actionKey)
{
  const auto* action =
    nativeUiFindMidiAction(actionKey);
  if (!action || !GetExtState_ptr) return "";
  const char* raw = GetExtState_ptr(
    kMidiBindingExtSection,
    action->storageKey);
  return raw ? raw : "";
}

static bool nativeUiWriteMidiBinding(
  const std::string& actionKey,
  const std::string& value)
{
  const auto* action =
    nativeUiFindMidiAction(actionKey);
  if (!action || !SetExtState_ptr) return false;
  SetExtState_ptr(kMidiBindingExtSection,
    action->storageKey, value.c_str(), true);
  return true;
}

