        std::string rowText = std::string(indexText) + "  " +
          playlist.name;
        if (multiProjectPlaylists) {
          rowText += "  —  " + playlist.projectName;
        }
        if (i == currentIndex) {
          rowText += "  • aberto";
        } else if (playlist.playlistActive) {
          rowText += "  • ativo na aba";
        }
        RECT rowTextRect{playlistRow.left + 6, playlistRow.top + 1,
          playlistRow.right - 6, playlistRow.bottom - 1};
