static bool nativeUiSmartSearchHasLocalMatch(
  const std::string& query)
{
  std::vector<NativeSongWindow> songs;
  std::vector<NativeSongWindow> playlistItems;
  std::map<std::string, bool> openDrawers;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    songs = g_nativeSongWindows;
    playlistItems = g_nativeActivePlaylistItems;
    openDrawers = g_nativeDirectorOpenFamilyDrawers;
  }

  std::map<std::string, bool> localParentIds;
  bool localMatch = false;
  std::map<std::string, bool> parentsInPlaylist;
  for (const auto& item : playlistItems) {
    if (item.isHashParent && !item.id.empty()) {
      localParentIds[item.id] = true;
      parentsInPlaylist[item.id] = true;
    }
  }

  // Replica a numeracao que a lista realmente desenha. Blocos nao contam e
  // filhos so recebem numero quando a gaveta esta aberta.
  int visibleColumnNumber = 0;
  for (const auto& item : playlistItems) {
    const bool childOfListedParent =
      (item.isHashChild || item.isRegionChild) &&
      !item.parentId.empty() &&
      parentsInPlaylist.find(item.parentId) !=
        parentsInPlaylist.end();
    if (childOfListedParent) continue;
    if (!item.isBlock) {
      ++visibleColumnNumber;
      if (nativeUiSearchMatchesSong(
            item, query, visibleColumnNumber)) {
        localMatch = true;
      }
    }
    const bool drawerOpen =
      item.isHashParent && !item.id.empty() &&
      openDrawers.find(item.id) != openDrawers.end();
    if (!drawerOpen) continue;
    for (const auto& child : songs) {
      if (!(child.isHashChild || child.isRegionChild) ||
          child.parentId != item.id) {
        continue;
      }
      ++visibleColumnNumber;
      if (nativeUiSearchMatchesSong(
            child, query, visibleColumnNumber)) {
        localMatch = true;
      }
    }
  }

  for (const auto& song : songs) {
    if (!(song.isHashChild || song.isRegionChild) ||
        song.parentId.empty() ||
        !nativeUiSearchMatchesSong(song, query)) {
      continue;
    }
    if (localParentIds.find(song.parentId) !=
        localParentIds.end()) {
      localMatch = true;
    }
  }
  return localMatch;
}

static bool nativeUiCommitPendingSmartSearchQuery(bool force)
{
  if (!g_nativeMainSearchFocused ||
      !g_nativeMainSearchApplyPending) {
    return false;
  }
  const auto now = std::chrono::steady_clock::now();
  if (!force && now < g_nativeMainSearchApplyAt) {
    return false;
  }

  g_nativeMainSearchApplyPending = false;
  if (g_nativeMainSearchAppliedText == g_nativeMainSearchText) {
    return false;
  }
  g_nativeMainSearchAppliedText = g_nativeMainSearchText;
  const std::string query =
    nativeTrim(g_nativeMainSearchAppliedText);
  if (query.empty()) {
    g_nativeMainSmartSearchSelectFirstPending = false;
    g_nativeUiRowsSourceSignatureValid = false;
    if (!g_nativeMainSmartSearchSourcePlaylistName.empty()) {
      nativeUiSmartSearchSetPage(false);
    }
    g_nativeForceStateBuild.store(true);
    return true;
  }

  const bool localMatch =
    nativeUiSmartSearchHasLocalMatch(query);
  const bool useRegions =
    g_nativeMainSmartSearchSourcePlaylistName.empty() ||
    !localMatch;
  const bool pageWillChange =
    g_nativeAppActivePanelModel.mixerPage ||
    g_nativeAppActivePanelModel.regionsPage != useRegions;
  nativeUiSmartSearchSetPage(useRegions);
  g_nativeUiRowsSourceSignatureValid = false;
  // Durante a troca de aba, o scroll atual ainda pertence à aba de origem.
  // Zerar aqui fazia o refresh seguinte salvar zero e perder a posição que o
  // usuário deixou nela. Na própria aba, a busca continua começando do topo
  // até aplicar o resultado inteligente.
  if (!pageWillChange) {
    g_nativeAppActiveListScrollPixels = 0;
  }
  g_nativeMainSmartSearchSelectFirstPending = true;
  g_nativeForceStateBuild.store(true);
  return true;
}

static std::string nativeUiPreviewBlocksKey(int slot)
{
  return "PREVIEW_BLOCKS_" +
    std::to_string(std::max(1, std::min(6, slot))) + "_V1";
}

static std::vector<int> nativeUiDefaultPreviewBlocks(int slot)
{
  const int safeSlot = std::max(1, std::min(6, slot));
  std::vector<int> blocks;
  for (int block = (safeSlot - 1) * 8 + 1;
       block <= safeSlot * 8; ++block) {
    blocks.push_back(block);
    if (blocks.size() == 8) break;
  }
  return blocks;
}

static std::vector<int> nativeUiReadPreviewBlocks(int slot)
{
  if (!GetExtState_ptr) return nativeUiDefaultPreviewBlocks(slot);
  const std::string key = nativeUiPreviewBlocksKey(slot);
  const char* rawValue = GetExtState_ptr(
    kNativeExtStateSection, key.c_str());
  const std::string raw = rawValue ? nativeTrim(rawValue) : "";
  if (raw.empty()) return nativeUiDefaultPreviewBlocks(slot);

  std::vector<int> blocks;
  for (const auto& field : nativeSplit(raw, ',')) {
    const std::string value = nativeTrim(field);
    if (!nativeLooksNumeric(value)) continue;
    const int block = std::atoi(value.c_str());
    if (block < 1 || block > 48 ||
        std::find(blocks.begin(), blocks.end(), block) != blocks.end()) {
      continue;
    }
    blocks.push_back(block);
    if (blocks.size() == 8) break;
  }
  if (blocks.empty()) return nativeUiDefaultPreviewBlocks(slot);
  std::sort(blocks.begin(), blocks.end());
  return blocks;
}

static bool nativeUiWritePreviewBlocks(
  int slot,
  const std::vector<int>& requestedBlocks)
{
  if (!SetExtState_ptr) return false;
  std::vector<int> blocks;
  for (const int block : requestedBlocks) {
    if (blocks.size() == 8) break;
    if (block < 1 || block > 48 ||
        std::find(blocks.begin(), blocks.end(), block) != blocks.end()) {
      continue;
    }
    blocks.push_back(block);
  }
  if (blocks.empty()) return false;
  std::sort(blocks.begin(), blocks.end());
  std::ostringstream value;
  for (size_t index = 0; index < blocks.size(); ++index) {
    if (index) value << ',';
    value << blocks[index];
  }
  const std::string key = nativeUiPreviewBlocksKey(slot);
  SetExtState_ptr(kNativeExtStateSection,
    key.c_str(), value.str().c_str(), true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static void nativeUiResetPreviewBlocks(int slot)
{
  if (!SetExtState_ptr) return;
  const std::string key = nativeUiPreviewBlocksKey(slot);
  SetExtState_ptr(kNativeExtStateSection, key.c_str(), "", true);
  g_nativeForceStateBuild.store(true);
}

static bool nativeUiHandlePreviewConfigAction(
  const std::string& action)
{
  if (action == "preview_config") {
    g_nativeMainModalKind = NativeMainModalKind::PreviewConfig;
    return true;
  }
  if (nativeStartsWith(action, "preview_block_toggle|")) {
    const int block = std::atoi(action.substr(
      std::string("preview_block_toggle|").size()).c_str());
    std::vector<int> blocks = nativeUiReadPreviewBlocks(
      g_nativeMainModalPreviewSlot);
    const auto found = std::find(
      blocks.begin(), blocks.end(), block);
    if (found != blocks.end()) {
      if (blocks.size() > 1) {
        blocks.erase(found);
        nativeUiWritePreviewBlocks(
          g_nativeMainModalPreviewSlot, blocks);
      } else {
        nativeUiShowTemporaryPopup(
          "O Preview precisa ter pelo menos um bloco", 1.5);
      }
    } else if (block >= 1 && block <= 48 && blocks.size() < 8) {
      blocks.push_back(block);
      nativeUiWritePreviewBlocks(
        g_nativeMainModalPreviewSlot, blocks);
    } else if (block >= 1 && block <= 48) {
      nativeUiShowTemporaryPopup(
        "Cada Preview permite no maximo 8 blocos", 1.5);
    }
    return true;
  }
  if (action == "preview_config_reset") {
    g_nativeMainModalKind =
      NativeMainModalKind::ConfirmPreviewConfigReset;
    return true;
  }
  if (action == "preview_config_reset_confirm") {
    nativeUiResetPreviewBlocks(g_nativeMainModalPreviewSlot);
    g_nativeMainModalKind = NativeMainModalKind::PreviewConfig;
    nativeUiShowTemporaryPopup(
      "Config original do Preview restaurada", 1.5);
    return true;
  }
  if (action == "preview_config_reset_cancel") {
    g_nativeMainModalKind = NativeMainModalKind::PreviewConfig;
    return true;
  }
  if (action == "preview_config_back") {
    g_nativeMainModalKind = NativeMainModalKind::PreviewBinding;
    return true;
  }
  return false;
}

