static bool nativeApplyPartsRename()
{
  std::string label = nativeTrim(g_nativePartsRenameInput);
  if (!g_nativePartsRenameOpen || label.empty() || !SetProjectMarkerByIndex2_ptr) return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !CountProjectMarkers_ptr || !EnumProjectMarkers3_ptr) return false;

  int enumIndex = -1;
  int markerColor = g_nativePartsRenameColor;
  double markerPos = g_nativePartsRenamePosition;
  int markerCount = 0;
  int regionCount = 0;
  int total = CountProjectMarkers_ptr(project, &markerCount, &regionCount);
  if (total <= 0) total = markerCount + regionCount;
  for (int i = 0; i < total; ++i) {
    bool isRegion = false;
    double pos = 0.0;
    double end = 0.0;
    const char* rawName = nullptr;
    int number = 0;
    int color = 0;
    if (!EnumProjectMarkers3_ptr(project, i, &isRegion, &pos, &end,
        &rawName, &number, &color)) continue;
    if (!isRegion && number == g_nativePartsRenameNumber) {
      enumIndex = i;
      markerPos = pos;
      markerColor = color;
      break;
    }
  }
  if (enumIndex < 0) return false;

  std::string newName = g_nativePartsRenamePrefix;
  if (!newName.empty() && newName[0] == '*') newName += " ";
  newName += label;
  if (!SetProjectMarkerByIndex2_ptr(project, enumIndex, false, markerPos, 0.0,
      g_nativePartsRenameNumber, newName.c_str(), markerColor, 0)) {
    return false;
  }
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  nativeClosePartsRenameModal();
  g_nativeForceStateBuild.store(true);
  return true;
}

static bool nativeTriggerPartsSourceStart(bool parts2)
{
  const auto& column = nativePartsColumnModel(parts2);
  if (!column.hasSource) return false;
  const std::string virtualId = std::string("start:") + column.sourceId;
  g_nativePartsPreparedSelectionId.clear();
  g_nativeMainNavigationFocus = parts2 ? "parts2" : "parts";
  std::ostringstream command;
  command << "{\"type\":\"trigger_marker\",\"markerId\":"
          << nativeJsonString(virtualId)
          << ",\"position\":" << std::setprecision(15)
          << column.sourceStart << ",\"markerLabel\":"
          << nativeJsonString(column.sourceName + " - INICIO")
          << ",\"partsColumn\":" << (parts2 ? 2 : 1) << '}';
  return nativeApplyMarkerCommand(command.str());
}

static bool nativeSelectPartsNavigationTarget(bool parts2, int navigationIndex)
{
  const auto& column = nativePartsColumnModel(parts2);
  const int targetCount = column.hasSource
    ? static_cast<int>(column.rows.size()) + 1
    : static_cast<int>(column.rows.size());
  if (navigationIndex < 0 || navigationIndex >= targetCount) return false;
  g_nativeMainNavigationFocus = parts2 ? "parts2" : "parts";
  g_nativePartsPreparedSelectionId.clear();

  if (column.hasSource && navigationIndex == 0) {
    std::ostringstream json;
    json << "{\"type\":\"marker_select\",\"markerId\":"
         << nativeJsonString(std::string("start:") + column.sourceId)
         << ",\"position\":" << std::setprecision(15)
         << column.sourceStart << ",\"markerLabel\":"
         << nativeJsonString(column.sourceName + " - INICIO")
         << ",\"partsColumn\":" << (parts2 ? 2 : 1) << '}';
    if (!nativeApplyMarkerCommand(json.str())) return false;
  } else {
    const int rowIndex = navigationIndex - (column.hasSource ? 1 : 0);
    if (rowIndex < 0 || rowIndex >= static_cast<int>(column.rows.size())) return false;
    std::ostringstream json;
    json << "{\"type\":\"marker_select\",\"markerId\":"
         << nativeJsonString(column.rows[static_cast<size_t>(rowIndex)].id) << "}";
    if (!nativeApplyMarkerCommand(json.str())) return false;

    int& scroll = parts2 ? g_nativeParts2ScrollPixels : g_nativeParts1ScrollPixels;
    const RECT& listRect = parts2 ? g_nativeMainParts2ListRect : g_nativeMainParts1ListRect;
    const auto& rowOffsets = parts2
      ? g_nativeParts2RowOffsets
      : g_nativeParts1RowOffsets;
    const auto& rowHeights = parts2
      ? g_nativeParts2RowHeights
      : g_nativeParts1RowHeights;
    const int viewport = std::max(0, static_cast<int>(listRect.bottom - listRect.top));
    const int rowTop =
      rowIndex < static_cast<int>(rowOffsets.size())
        ? rowOffsets[static_cast<size_t>(rowIndex)]
        : rowIndex * 16;
    const int measuredHeight =
      rowIndex < static_cast<int>(rowHeights.size())
        ? rowHeights[static_cast<size_t>(rowIndex)]
        : 16;
    if (rowTop < scroll) scroll = rowTop;
    else if (rowTop + measuredHeight >
             scroll + viewport) {
      scroll = rowTop + measuredHeight - viewport;
    }
  }
  g_nativeForceStateBuild.store(true);
  return true;
}

static int nativeCurrentPartsNavigationIndex(bool parts2)
{
  const auto& column = nativePartsColumnModel(parts2);
  std::string selected;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    selected = g_nativeSelectedMarkerId;
  }
  if (column.hasSource && selected == std::string("start:") + column.sourceId) return 0;
  for (size_t i = 0; i < column.rows.size(); ++i) {
    if (column.rows[i].id == selected) return static_cast<int>(i) + (column.hasSource ? 1 : 0);
  }
  return -1;
}

static bool nativeNavigateParts(bool parts2, int step)
{
  const auto& column = nativePartsColumnModel(parts2);
  const int count = static_cast<int>(column.rows.size()) + (column.hasSource ? 1 : 0);
  if (count <= 0 || step == 0) return true;
  int index = nativeCurrentPartsNavigationIndex(parts2);
  if (index < 0) index = step > 0 ? -1 : count;
  index += step;
  if (index >= count) index = 0;
  if (index < 0) index = count - 1;
  return nativeSelectPartsNavigationTarget(parts2, index);
}

static const NativeAppActivePanelModel::Row*
nativeUiMainVisibleRowAt(int visibleIndex)
{
  if (visibleIndex < 0 ||
      visibleIndex >=
        static_cast<int>(g_nativeMainVisibleRowIndices.size())) {
    return nullptr;
  }
  const size_t sourceIndex =
    g_nativeMainVisibleRowIndices[static_cast<size_t>(visibleIndex)];
  if (sourceIndex >= g_nativeAppActivePanelModel.rows.size()) {
    return nullptr;
  }
  return &g_nativeAppActivePanelModel.rows[sourceIndex];
}

static const NativeAppActivePanelModel::Row*
nativeUiCurrentMainSelectedSongRow()
{
  const bool regionsPage = g_nativeAppActivePanelModel.regionsPage;
  if (const auto* row = nativeUiMainVisibleRowAt(
        g_nativeUiSelectionFocusVisibleIndex)) {
    if (!row->block && nativeUiMainRowIsSelected(*row, regionsPage)) {
      return row;
    }
  }
  if (const auto* row = nativeUiMainVisibleRowAt(
        g_nativeUiSelectionAnchorVisibleIndex)) {
    if (!row->block && nativeUiMainRowIsSelected(*row, regionsPage)) {
      return row;
    }
  }

  for (auto it = g_nativeUiSelectionOrder.rbegin();
       it != g_nativeUiSelectionOrder.rend(); ++it) {
    const auto* row = nativeUiFindModelRowByKey(*it, regionsPage);
    if (row && !row->block) return row;
  }

  // O usuario pode ter desmarcado deliberadamente a ultima linha. Nesse
  // estado nao existe alvo atual; o ID do motor e apenas um snapshot antigo.
  if (g_nativeUiMainSelectionAuthoritative) return nullptr;

  for (const auto& row : g_nativeAppActivePanelModel.rows) {
    if (!row.block && nativeAppActiveRowMatches(row,
        g_nativeAppActivePanelModel.selectedId,
        g_nativeAppActivePanelModel.selectedStart,
        g_nativeAppActivePanelModel.selectedEnd)) {
      return &row;
    }
  }
  return nullptr;
}

static const NativeAppActivePanelModel::Row*
nativeUiCurrentMainSelectedBlockRow()
{
  if (g_nativeAppActivePanelModel.regionsPage ||
      g_nativeAppActivePanelModel.mixerPage) {
    return nullptr;
  }
  const int candidates[] = {
    g_nativeUiSelectionFocusVisibleIndex,
    g_nativeUiSelectionAnchorVisibleIndex
  };
  for (const int visibleIndex : candidates) {
    const auto* row = nativeUiMainVisibleRowAt(visibleIndex);
    if (row && row->block &&
        nativeUiMainRowIsSelected(*row, false)) {
      return row;
    }
  }
  for (auto it = g_nativeUiSelectionOrder.rbegin();
       it != g_nativeUiSelectionOrder.rend(); ++it) {
    const auto* row = nativeUiFindModelRowByKey(*it, false);
    if (row && row->block) return row;
  }
  return nullptr;
}

static bool nativeUiPrepareSelectedBlockPlayCommand(
  std::string& playCommandOut)
{
  playCommandOut.clear();
  const auto* selectedBlock = nativeUiCurrentMainSelectedBlockRow();
  if (!selectedBlock) return false;
  const auto* modelBase = g_nativeAppActivePanelModel.rows.data();
  const int blockIndex = static_cast<int>(selectedBlock - modelBase);
  if (blockIndex < 0 || blockIndex >=
      static_cast<int>(g_nativeAppActivePanelModel.rows.size())) {
    return false;
  }
  int songIndex = -1;
  for (int index = blockIndex + 1;
       index < static_cast<int>(g_nativeAppActivePanelModel.rows.size());
       ++index) {
    const auto& candidate = g_nativeAppActivePanelModel.rows[
      static_cast<size_t>(index)];
    if (candidate.block) break;
    songIndex = index;
    break;
  }
  if (songIndex < 0) {
    nativeUiShowTemporaryPopup("BLOCO sem musica abaixo", 1.4);
    return true;
  }

  const NativeAppActivePanelModel::Row song =
    g_nativeAppActivePanelModel.rows[static_cast<size_t>(songIndex)];
  nativeUiClearMainRowSelectionForPage(false);
  nativeUiSetMainRowSelected(song, false, true);
  for (size_t visible = 0;
       visible < g_nativeMainVisibleRowIndices.size(); ++visible) {
    if (g_nativeMainVisibleRowIndices[visible] !=
        static_cast<size_t>(songIndex)) {
      continue;
    }
    g_nativeUiSelectionAnchorVisibleIndex = static_cast<int>(visible);
    g_nativeUiSelectionFocusVisibleIndex = static_cast<int>(visible);
    break;
  }
  g_nativeUiMusicSelectionVisualActive = false;
  playCommandOut = nativeMainSongCommandJson(
    "play_start", song, false);
  return true;
}

static void nativeUiCancelPendingMusicNavigation()
{
  g_nativeUiPendingMusicNavigation =
    NativeUiPendingMusicNavigation{};
}

static void nativeUiScheduleMusicNavigation(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage)
{
  const char* type = regionsPage
    ? "select_region" : "select_playlist_song";

  // Primeiro sincroniza apenas a selecao. O motor e os outros front-ends ja
  // enxergam o novo azul, mas o cursor do REAPER permanece quieto.
  nativeApplySelectionCommand(nativeMainSongCommandJson(
    type, row, regionsPage, true));

  g_nativeUiPendingMusicNavigation.pending = true;
  g_nativeUiPendingMusicNavigation.regionsPage = regionsPage;
  g_nativeUiPendingMusicNavigation.hookControllerSource =
    g_nativeHookControllerSongContextActive;
  g_nativeUiPendingMusicNavigation.rowKey =
    nativeUiMainRowKey(row, regionsPage);
  // Igual ao Lua: durante a reproducao as setas atualizam exclusivamente a
  // selecao. O cursor de edicao so e preparado pela rotina de termino/Stop,
  // depois que a musica realmente acabar e apenas se nao houver fila.
  g_nativeUiPendingMusicNavigation.commitCommand =
    nativeMainSongCommandJson(type, row, regionsPage, false);
  g_nativeUiPendingMusicNavigation.dueAt =
    std::chrono::steady_clock::now() +
    std::chrono::milliseconds(
      kNativeUiMusicNavigationSettleMs);
  nativeUiSetFrameTimerInterval(
    g_nativeAppActivePanelHwnd,
    kNativeUiFrameFastIntervalMs);
}

static bool nativeUiCommitPendingMusicNavigation(bool force)
{
  if (!g_nativeUiPendingMusicNavigation.pending) return false;
  if (!force && std::chrono::steady_clock::now() <
      g_nativeUiPendingMusicNavigation.dueAt) {
    return false;
  }

  const NativeUiPendingMusicNavigation pending =
    g_nativeUiPendingMusicNavigation;
  nativeUiCancelPendingMusicNavigation();

  if (pending.hookControllerSource) {
    const auto selected = g_nativeUiSelectedRows.find(pending.rowKey);
    if (selected == g_nativeUiSelectedRows.end() || !selected->second) {
      return false;
    }
  } else {
    if (g_nativeAppActivePanelModel.mixerPage ||
        g_nativeAppActivePanelModel.regionsPage !=
          pending.regionsPage) {
      return false;
    }
    const auto* selected = nativeUiCurrentMainSelectedSongRow();
    if (!selected || nativeUiMainRowKey(
          *selected, pending.regionsPage) != pending.rowKey) {
      return false;
    }
  }
  return nativeApplySelectionCommand(pending.commitCommand);
}

static bool nativeNavigateMainRows(int step)
{
  if (step == 0 || g_nativeAppActivePanelModel.mixerPage ||
      g_nativeMainVisibleRowIndices.empty()) {
    return false;
  }

  const bool regionsPage = g_nativeAppActivePanelModel.regionsPage;
  const int count = static_cast<int>(g_nativeMainVisibleRowIndices.size());
  const int direction = step > 0 ? 1 : -1;
  // Mesma protecao de borda do Lua: a repeticao automatica da tecla para no
  // inicio/fim. Depois que o usuario solta e pressiona novamente, a navegacao
  // circular pode atravessar para a outra extremidade.
  // O repeat sintético pode atrasar junto com o WM_TIMER. Enquanto a tecla
  // continuar pressionada, nunca permite navegação circular nas extremidades.
  // Ao soltar e pressionar novamente, o primeiro WM_KEYDOWN físico fica livre
  // para atravessar para a outra ponta da lista nas duas plataformas.
  const bool rapidNavigationRepeat =
    g_nativeUiSyntheticNavigationRepeat;
  int current = -1;
  const auto* selected = nativeUiCurrentMainSelectedSongRow();
  if (selected) {
    for (int i = 0; i < count; ++i) {
      if (nativeUiMainVisibleRowAt(i) == selected) {
        current = i;
        break;
      }
    }
  }
  // Se a selecao local ainda aponta para a musica vermelha (ou inexiste), a
  // fila amarela e a ancora correta. Depois do primeiro passo a propria selecao
  // azul passa a ser usada, permitindo continuar navegando normalmente.
  bool currentIsPlaying = false;
  if (current >= 0) {
    if (const auto* currentRow = nativeUiMainVisibleRowAt(current)) {
      currentIsPlaying = nativeAppActiveRowMatches(*currentRow,
        g_nativeAppActivePanelModel.playingId,
        g_nativeAppActivePanelModel.playingStart,
        g_nativeAppActivePanelModel.playingEnd);
    }
  }
  if (g_nativeAppActivePanelModel.queueActive &&
      (current < 0 || currentIsPlaying)) {
    for (int i = 0; i < count; ++i) {
      const auto* row = nativeUiMainVisibleRowAt(i);
      if (row && !row->block && nativeAppActiveRowMatches(*row,
          g_nativeAppActivePanelModel.queuedId,
          g_nativeAppActivePanelModel.queuedStart,
          g_nativeAppActivePanelModel.queuedEnd)) {
        current = i;
        break;
      }
    }
  }
  if (current < 0) {
    for (int i = 0; i < count; ++i) {
      const auto* row = nativeUiMainVisibleRowAt(i);
      if (row && !row->block && nativeAppActiveRowMatches(*row,
          g_nativeAppActivePanelModel.playingId,
          g_nativeAppActivePanelModel.playingStart,
          g_nativeAppActivePanelModel.playingEnd)) {
        current = i;
        break;
      }
    }
  }

  int candidate = current < 0
    ? (direction > 0 ? -1 : count)
    : current;
  bool wrappedAtListEdge = false;
  for (int guard = 0; guard < count; ++guard) {
    candidate += direction;
    if (candidate >= count) {
      if (rapidNavigationRepeat) return false;
      candidate = 0;
      wrappedAtListEdge = true;
    }
    if (candidate < 0) {
      if (rapidNavigationRepeat) return false;
      candidate = count - 1;
      wrappedAtListEdge = true;
    }
    const auto* row = nativeUiMainVisibleRowAt(candidate);
    if (!row) continue;
    const bool playingRow = g_nativeAppActivePanelModel.playing &&
      nativeAppActiveRowMatches(*row,
        g_nativeAppActivePanelModel.playingId,
        g_nativeAppActivePanelModel.playingStart,
        g_nativeAppActivePanelModel.playingEnd);
    if (row->block || playingRow) continue;

    nativeUiSelectOnlyMainRow(*row, regionsPage);
    g_nativeUiMusicSelectionVisualActive = true;
    g_nativeUiSelectionAnchorVisibleIndex = candidate;
    g_nativeUiSelectionFocusVisibleIndex = candidate;
    g_nativeMainNavigationFocus = regionsPage ? "regions" : "playlist";
    nativeUiScheduleMusicNavigation(*row, regionsPage);

    if (candidate < static_cast<int>(g_nativeMainRowOffsets.size()) &&
        candidate < static_cast<int>(g_nativeMainRowHeights.size())) {
      const int rowTop = g_nativeMainRowOffsets[static_cast<size_t>(candidate)];
      const int rowBottom = rowTop +
        g_nativeMainRowHeights[static_cast<size_t>(candidate)];
      int revealFrom = g_nativeAppActiveListScrollPixels;
      // Mantém o alvo anterior enquanto a tecla continua na mesma direção.
      // Ao inverter a seta, o quadro atual volta a ser a base e a animação
      // responde imediatamente, sem continuar deslizando para o lado antigo.
      if (g_nativeMainSmoothScroll.target >= 0) {
        const bool sameDirection =
          (direction > 0 &&
            g_nativeMainSmoothScroll.target >= revealFrom) ||
          (direction < 0 &&
            g_nativeMainSmoothScroll.target <= revealFrom);
        if (sameDirection) {
          revealFrom = g_nativeMainSmoothScroll.target;
        }
      }
      int revealTarget = revealFrom;
      if (wrappedAtListEdge && direction > 0) {
        // Ao atravessar do fim para o início, a seleção deve continuar
        // ignorando linhas de bloco, mas o scroll precisa voltar ao início
        // absoluto. Usar rowTop aqui ocultava o bloco que estivesse antes da
        // primeira música selecionável.
        revealTarget = 0;
      } else if (direction < 0) {
        // Subindo, mantém uma linha renderizada acima da seleção. Blocos e
        // linhas de altura variável também contam como esse contexto.
        const size_t upperContextIndex =
          candidate > 0 ? static_cast<size_t>(candidate - 1) : size_t{0};
        const int upperContextTop =
          upperContextIndex < g_nativeMainRowOffsets.size()
            ? g_nativeMainRowOffsets[upperContextIndex]
            : rowTop;
        if (upperContextTop < revealTarget) {
          revealTarget = upperContextTop;
        } else if (rowBottom >
                   revealTarget + g_nativeMainListViewportPixels) {
          // Protege o salto circular para o fim ao navegar para cima.
          revealTarget =
            rowBottom - g_nativeMainListViewportPixels;
        }
      } else if (rowTop < revealTarget) {
        // Protege o salto circular para o início ao navegar para baixo.
        revealTarget = rowTop;
      } else {
        // Descendo, mantém a seleção na antepenúltima linha: as duas linhas
        // seguintes continuam visíveis. Os offsets medidos incluem blocos e
        // linhas com altura variável; no fim, completa o contexto com as
        // linhas virtuais de respiro.
        const NativeUiListLayout scrollLayout =
          nativeUiCurrentListLayout(nativeUiVisualPrefsForPaint());
        const size_t measuredRowCount = std::min(
          g_nativeMainVisibleRowIndices.size(),
          std::min(g_nativeMainRowHeights.size(),
            g_nativeMainRowOffsets.empty()
              ? size_t{0}
              : g_nativeMainRowOffsets.size() - 1));
        const size_t requestedContextEnd =
          static_cast<size_t>(candidate) + 3;
        const size_t contextEnd =
          std::min(measuredRowCount, requestedContextEnd);
        const int missingContextRows =
          static_cast<int>(requestedContextEnd - contextEnd);
        const int contextBottom =
          g_nativeMainRowOffsets[contextEnd] +
          missingContextRows * scrollLayout.singleRowHeight;
        if (contextBottom >
            revealTarget + g_nativeMainListViewportPixels) {
          // Em uma janela muito baixa, prioriza manter o topo da seleção
          // visível mesmo que não caibam as três linhas completas.
          revealTarget = std::min(rowTop,
            contextBottom - g_nativeMainListViewportPixels);
        }
      }
      revealTarget = std::max(0,
        std::min(revealTarget,
          g_nativeMainListMaxScrollPixels));
      if (revealTarget != g_nativeAppActiveListScrollPixels) {
        if (g_nativeUiSyntheticNavigationRepeat ||
            wrappedAtListEdge) {
          // O repeat das duas plataformas é produzido pelo mesmo timer que
          // anima o scroll. Deslocar lista e seleção no mesmo passo impede
          // pulos: descendo fica na antepenúltima linha; subindo, com uma
          // linha de contexto acima. Ao atravessar começo/fim também posiciona
          // imediatamente; animar a distância inteira faz a lista parecer
          // rolar no sentido errado antes de chegar à outra extremidade.
          g_nativeAppActiveListScrollPixels = revealTarget;
          g_nativeMainSmoothScroll = NativeUiSmoothScrollState{};
          g_nativeUiLastSmoothScrollAdvanceAt = {};
        } else {
          g_nativeMainSmoothScroll.target = revealTarget;
          g_nativeMainSmoothScroll.lastApplied =
            g_nativeAppActiveListScrollPixels;
        }
      } else {
        g_nativeMainSmoothScroll =
          NativeUiSmoothScrollState{};
      }
    }
    // A selecao e o scroll ja foram atualizados localmente. O comando
    // selectionOnly abaixo sera publicado pela cadencia normal do bridge.
    return true;
  }
  return false;
}

static void nativeUiSmartSearchRememberScrollTarget(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage,
  bool waitForQueue = false)
{
  g_nativeMainSmartSearchExpectedRegionsPage = regionsPage;
  g_nativeMainSmartSearchScrollTarget.pending = true;
  g_nativeMainSmartSearchScrollTarget.regionsPage = regionsPage;
  g_nativeMainSmartSearchScrollTarget.waitForQueue =
    waitForQueue;
  g_nativeMainSmartSearchScrollTarget.queueWasConfirmed =
    false;
  g_nativeMainSmartSearchScrollTarget.id = row.id;
  g_nativeMainSmartSearchScrollTarget.sourceNumber =
    row.sourceNumber;
  g_nativeMainSmartSearchScrollTarget.start = row.start;
  g_nativeMainSmartSearchScrollTarget.end = row.end;
  g_nativeMainSmartSearchScrollTarget
    .lastObservedScrollRevision = 0;
  g_nativeMainSmartSearchScrollTarget.settleUntil =
    std::chrono::steady_clock::time_point{};
  g_nativeMainSmartSearchScrollTarget.expiresAt =
    std::chrono::steady_clock::now() +
      std::chrono::seconds(4);
}

static bool nativeUiSmartSearchSettingEnabled(
  const char* key)
{
  if (!key || !GetExtState_ptr) return true;
  const char* raw =
    GetExtState_ptr(kNativeExtStateSection, key);
  return nativeBoolFromText(raw ? raw : "", true);
}

static bool nativeUiToggleSmartSearchSetting(
  const std::string& key)
{
  if (!SetExtState_ptr) return false;
  const bool valid =
    key == kNativeSmartSearchInsertQueuePlaylistKey ||
    key == kNativeSmartSearchScrollSelectedKey ||
    key == kNativeSmartSearchScrollQueuedKey;
  if (!valid) return false;
  const bool enabled =
    !nativeUiSmartSearchSettingEnabled(key.c_str());
  SetExtState_ptr(kNativeExtStateSection, key.c_str(),
    enabled ? "1" : "0", true);
  if (!enabled &&
      (key == kNativeSmartSearchScrollSelectedKey ||
       key == kNativeSmartSearchScrollQueuedKey)) {
    g_nativeMainSmartSearchScrollTarget =
      NativeUiSmartSearchScrollTarget{};
  }
  return true;
}

static bool nativeUiSmartSearchInsertBelowPlaying(
  const NativeSongWindow& target)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project ||
      g_nativeMainSmartSearchSourcePlaylistName.empty()) {
    return false;
  }

  auto playlists = nativeUiReadPlaylistRecords(project);
  int playlistIndex = -1;
  for (size_t index = 0; index < playlists.size(); ++index) {
    if (nativeTrim(playlists[index].name) ==
        nativeTrim(g_nativeMainSmartSearchSourcePlaylistName)) {
      playlistIndex = static_cast<int>(index);
      break;
    }
  }
  if (playlistIndex < 0) return false;
  auto& playlist = playlists[static_cast<size_t>(playlistIndex)];

  std::vector<NativeSongWindow> playlistItems;
  std::vector<NativeSongWindow> songs;
  std::string playingId;
  double playingStart = 0.0;
  double playingEnd = 0.0;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    playlistItems = g_nativeActivePlaylistItems;
    songs = g_nativeSongWindows;
    playingId = g_nativeCurrentPlayingId;
    playingStart = g_nativeCurrentSongStart;
    playingEnd = g_nativeCurrentSongEnd;
  }

  // Uma musica-filho nunca pode existir isolada no repertorio. A busca ainda
  // enfileira exatamente o filho escolhido, mas a estrutura persistida recebe
  // a regiao pai; na reconstrução, todos os filhos voltam juntos na gaveta.
  NativeSongWindow playlistTarget = target;
  bool insertedFamily = false;
  bool removedLegacyIsolatedChild = false;
  if (target.isHashChild || target.isRegionChild) {
    const NativeSongWindow* parent =
      nativeFindFamilyParent(target, songs);
    if (!parent) return false;
    playlistTarget = *parent;
    insertedFamily = true;
    // Corrige também uma linha isolada que possa ter sido criada por uma
    // versão anterior desta rotina.
    const auto oldSize = playlist.itemLines.size();
    playlist.itemLines.erase(
      std::remove_if(
        playlist.itemLines.begin(), playlist.itemLines.end(),
        [&](const std::string& itemLine) {
          const auto fields = nativeSplit(itemLine, '\t');
          if (fields.size() < 5 || fields[0] != "ITEM") {
            return false;
          }
          return std::atoi(fields[2].c_str()) ==
              target.sourceNumber &&
            std::fabs(std::atof(fields[3].c_str()) -
              target.start) <= 0.000001 &&
            std::fabs(std::atof(fields[4].c_str()) -
              target.end) <= 0.000001;
        }),
      playlist.itemLines.end());
    removedLegacyIsolatedChild =
      playlist.itemLines.size() != oldSize;
  }
  const bool familyAlreadyPresent =
    nativeUiPlaylistContainsSong(
      playlist, playlistTarget);

  const auto openInsertedFamilyDrawer = [&]() {
    if (!insertedFamily || playlistTarget.id.empty()) return;
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (g_nativeDirectorOpenFamilyDrawers.find(
          playlistTarget.id) !=
        g_nativeDirectorOpenFamilyDrawers.end()) {
      return;
    }
    g_nativeDirectorOpenFamilyDrawers[
      playlistTarget.id] = true;
    g_nativeFamilyDrawersOwner = "pc";
    ++g_nativeFamilyDrawersRevision;
    ++g_nativeDirectorListScrollRevision;
    nativeBumpSharedRevisionLocked("pc");
    nativePersistFamilyDrawersForCurrentProjectLocked();
  };
  if (familyAlreadyPresent) {
    if (removedLegacyIsolatedChild &&
        !nativeUiSavePlaylistRecords(project, playlists)) {
      return false;
    }
    openInsertedFamilyDrawer();
    return true;
  }

  int playingOrder = 0;
  for (const auto& item : playlistItems) {
    if (item.isBlock) continue;
    const bool boundsMatch =
      std::fabs(item.start - playingStart) <= 0.003 &&
      std::fabs(item.end - playingEnd) <= 0.003;
    if ((!playingId.empty() && nativeSongIdMatches(item, playingId) &&
         boundsMatch) || boundsMatch) {
      playingOrder = item.playlistOrder;
      break;
    }
  }
  if (playingOrder <= 0 && !playingId.empty()) {
    for (const auto& item : playlistItems) {
      if (!item.isBlock && nativeSongIdMatches(item, playingId)) {
        playingOrder = item.playlistOrder;
        break;
      }
    }
  }

  const size_t insertIndex = playingOrder > 0
    ? std::min(playlist.itemLines.size(),
        static_cast<size_t>(playingOrder))
    : playlist.itemLines.size();
  playlist.itemLines.insert(
    playlist.itemLines.begin() +
      static_cast<std::ptrdiff_t>(insertIndex),
    nativeUiPlaylistItemLineForSong(playlistTarget));
  if (!nativeUiSavePlaylistRecords(project, playlists)) {
    return false;
  }

  openInsertedFamilyDrawer();
  return true;
}

static void nativeUiOpenSearchResultFamily(
  const NativeAppActivePanelModel::Row& row)
{
  if (!row.child || row.parentId.empty()) return;
  bool changed = false;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    if (g_nativeDirectorOpenFamilyDrawers.find(row.parentId) ==
        g_nativeDirectorOpenFamilyDrawers.end()) {
      g_nativeDirectorOpenFamilyDrawers[row.parentId] = true;
      g_nativeFamilyDrawersOwner = "pc";
      ++g_nativeFamilyDrawersRevision;
      ++g_nativeDirectorListScrollRevision;
      nativeBumpSharedRevisionLocked("pc");
      nativePersistFamilyDrawersForCurrentProjectLocked();
      changed = true;
    }
  }
  if (!changed) return;
  g_nativeUiRowsSourceSignatureValid = false;
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
}

static bool nativeUiActivateSmartSearchResult(
  const NativeAppActivePanelModel::Row& row,
  bool regionsPage)
{
  if (row.block) return false;
  const bool playing = nativeUiTransportActive();

  if (regionsPage && playing &&
      !g_nativeMainSmartSearchSourcePlaylistName.empty()) {
    NativeSongWindow song;
    if (!nativeUiFindSongForRow(row, song)) {
      return false;
    }
    const bool insertInPlaylist =
      nativeUiSmartSearchSettingEnabled(
        kNativeSmartSearchInsertQueuePlaylistKey);
    if (insertInPlaylist &&
        !nativeUiSmartSearchInsertBelowPlaying(song)) {
      return false;
    }
    nativeApplyQueueCommand(nativeMainSongCommandJson(
      "queue_region_song", row, true));
    if (insertInPlaylist &&
        nativeUiSmartSearchSettingEnabled(
          kNativeSmartSearchScrollQueuedKey)) {
      nativeUiSmartSearchRememberScrollTarget(
        row, false, true);
    }
    nativeUiCloseSmartSearch(false);
    nativeUiSmartSearchSetPage(false);
    g_nativeForceSnapshotBuild.store(true);
    g_nativeForceStateBuild.store(true);
    return true;
  }

  // Durante a pesquisa, filhos de gavetas fechadas existem apenas como
  // resultados virtuais. Ao confirmar, abre exclusivamente a família desse
  // resultado; nenhuma outra gaveta é alterada.
  nativeUiOpenSearchResultFamily(row);
  nativeUiClearMainRowSelectionForPage(regionsPage);
  nativeUiSetMainRowSelected(row, regionsPage, true);
  for (size_t visible = 0;
       visible < g_nativeMainVisibleRowIndices.size(); ++visible) {
    const size_t source = g_nativeMainVisibleRowIndices[visible];
    if (source >= g_nativeAppActivePanelModel.rows.size() ||
        &g_nativeAppActivePanelModel.rows[source] != &row) {
      continue;
    }
    g_nativeUiSelectionAnchorVisibleIndex =
      static_cast<int>(visible);
    g_nativeUiSelectionFocusVisibleIndex =
      static_cast<int>(visible);
    break;
  }
  g_nativeUiMusicSelectionVisualActive = playing;
  const bool shouldFollowResult = playing
    ? nativeUiSmartSearchSettingEnabled(
        kNativeSmartSearchScrollQueuedKey)
    : nativeUiSmartSearchSettingEnabled(
        kNativeSmartSearchScrollSelectedKey);
  if (shouldFollowResult) {
    nativeUiSmartSearchRememberScrollTarget(
      row, regionsPage, playing);
  } else {
    g_nativeMainSmartSearchScrollTarget =
      NativeUiSmartSearchScrollTarget{};
  }

  if (playing) {
    nativeApplySelectionCommand(
      "{\"type\":\"clear_selection\"}");
    nativeApplyQueueCommand(nativeMainSongCommandJson(
      regionsPage ? "queue_region_song" : "queue_playlist_song",
      row, regionsPage));
  } else {
    nativeApplySelectionCommand(nativeMainSongCommandJson(
      regionsPage ? "select_region" : "select_playlist_song",
      row, regionsPage));
  }
  nativeUiCloseSmartSearch(false);
  return true;
}

// O App do Diretor nao replica a regra da Lupa. Ele apenas dirige a mesma
// busca inteligente usada pela janela nativa, inclusive a troca automatica
// Repertorio -> Musicas e a insercao opcional abaixo da musica em execucao.
static bool nativeApplySmartSearchCommand(
  const std::string& commandBody)
{
  const std::string type = nativeLower(nativeTrim(
    nativeJsonExtractString(commandBody, "type")));
  if (type != "smart_search_open" &&
      type != "smart_search_query" &&
      type != "smart_search_close" &&
      type != "smart_search_activate") {
    return false;
  }
  nativeTimecodeLanRecordCommand(commandBody);

  if (type == "smart_search_close") {
    if (g_nativeMainSearchFocused) {
      nativeUiCloseSmartSearch(true);
    }
    return true;
  }

  if (!g_nativeMainSearchFocused) {
    nativeUiToggleSmartSearch();
  }

  if (type == "smart_search_open") {
    g_nativeForceStateBuild.store(true);
    return true;
  }

  if (type == "smart_search_query") {
    std::string query = nativeJsonExtractString(
      commandBody, "query");
    // Limite defensivo equivalente a um campo de pesquisa humano, sem cortar
    // consultas normais nem fazer a fila HTTP crescer com textos enormes.
    if (query.size() > 2048) query.resize(2048);
    g_nativeMainSearchText = query;
    g_nativeMainSearchCursor =
      g_nativeMainSearchText.size();
    nativeUiSmartSearchQueryChanged();
    g_nativeForceStateBuild.store(true);
    return true;
  }

  // Confirma sempre a consulta digitada antes de procurar a linha. Isso cobre
  // o toque imediato em um resultado enquanto o debounce nativo ainda esta em
  // andamento e mantem o comportamento identico ao Enter da extensao.
  const std::string activationQuery = nativeJsonExtractString(
    commandBody, "query");
  if (g_nativeMainSearchText != activationQuery) {
    g_nativeMainSearchText = activationQuery;
    g_nativeMainSearchCursor =
      g_nativeMainSearchText.size();
    nativeUiSmartSearchQueryChanged();
  }
  nativeUiCommitPendingSmartSearchQuery(true);
  g_nativeUiLastModelRefreshAt =
    std::chrono::steady_clock::time_point{};
  nativeRefreshAppActivePanelModel();
  g_nativeMainVisibleRowIndices =
    nativeUiBuildVisibleRowIndices();

  const std::string wantedId = nativeJsonExtractString(
    commandBody, "resultId");
  if (wantedId.empty()) return true;
  const std::string wantedStartText = nativeTrim(
    nativeJsonExtractString(commandBody, "resultStart"));
  const bool hasWantedStart = !wantedStartText.empty();
  const double wantedStart = hasWantedStart
    ? std::atof(wantedStartText.c_str()) : 0.0;
  const auto matches = [&](
      const NativeAppActivePanelModel::Row& row) {
    return !row.block && row.id == wantedId &&
      (!hasWantedStart ||
       std::fabs(row.start - wantedStart) <= 0.003);
  };

  for (const size_t sourceIndex :
       g_nativeMainVisibleRowIndices) {
    if (sourceIndex >=
        g_nativeAppActivePanelModel.rows.size()) {
      continue;
    }
    const auto& row =
      g_nativeAppActivePanelModel.rows[sourceIndex];
    if (matches(row)) {
      return nativeUiActivateSmartSearchResult(
        row, g_nativeAppActivePanelModel.regionsPage);
    }
  }
  // Fallback apenas para a pequena janela entre a troca automatica de pagina
  // e a reconstrução do modelo. A identidade e o inicio impedem escolher uma
  // linha homonima por engano.
  for (const auto& row :
       g_nativeAppActivePanelModel.rows) {
    if (matches(row)) {
      return nativeUiActivateSmartSearchResult(
        row, g_nativeAppActivePanelModel.regionsPage);
    }
  }
  return true;
}

static std::string nativeBuildSmartSearchStateJson()
{
  const bool modelReady = g_nativeMainSearchFocused &&
    !g_nativeAppActivePanelModel.mixerPage &&
    g_nativeAppActivePanelModel.regionsPage ==
      g_nativeMainSmartSearchExpectedRegionsPage;
  std::ostringstream json;
  json << "{\"open\":"
       << (g_nativeMainSearchFocused ? "true" : "false")
       << ",\"query\":"
       << nativeJsonString(g_nativeMainSearchText)
       << ",\"appliedQuery\":"
       << nativeJsonString(g_nativeMainSearchAppliedText)
       << ",\"page\":"
       << nativeJsonString(
            g_nativeAppActivePanelModel.regionsPage
              ? "regions" : "playlist")
       << ",\"sourcePlaylistName\":"
       << nativeJsonString(
            g_nativeMainSmartSearchSourcePlaylistName)
       << ",\"ready\":"
       << (modelReady ? "true" : "false")
       << ",\"insertQueuedBelowPlaying\":"
       << (nativeUiSmartSearchSettingEnabled(
             kNativeSmartSearchInsertQueuePlaylistKey)
             ? "true" : "false")
       << ",\"scrollSelected\":"
       << (nativeUiSmartSearchSettingEnabled(
             kNativeSmartSearchScrollSelectedKey)
             ? "true" : "false")
       << ",\"scrollQueued\":"
       << (nativeUiSmartSearchSettingEnabled(
             kNativeSmartSearchScrollQueuedKey)
             ? "true" : "false")
       << ",\"results\":[";

  if (modelReady) {
    std::map<std::string, std::string> parentNames;
    for (const auto& row :
         g_nativeAppActivePanelModel.rows) {
      if (row.familyParent && !row.id.empty()) {
        parentNames[row.id] = row.name;
      }
    }
    const std::vector<size_t> visible =
      nativeUiBuildVisibleRowIndices();
    bool first = true;
    for (const size_t sourceIndex : visible) {
      if (sourceIndex >=
          g_nativeAppActivePanelModel.rows.size()) {
        continue;
      }
      const auto& row =
        g_nativeAppActivePanelModel.rows[sourceIndex];
      if (row.block) continue;
      if (!first) json << ',';
      first = false;
      const auto parent = parentNames.find(row.parentId);
      json << "{\"id\":" << nativeJsonString(row.id)
           << ",\"name\":" << nativeJsonString(row.name)
           << ",\"parentId\":"
           << nativeJsonString(row.parentId)
           << ",\"parentName\":"
           << nativeJsonString(parent == parentNames.end()
                ? std::string() : parent->second)
           << ",\"isChild\":"
           << (row.child ? "true" : "false")
           << ",\"familyParent\":"
           << (row.familyParent ? "true" : "false")
           << ",\"regionsPage\":"
           << (g_nativeAppActivePanelModel.regionsPage
                ? "true" : "false")
           << ",\"start\":" << nativeNumber(row.start)
           << ",\"end\":" << nativeNumber(row.end)
           << ",\"durationSec\":"
           << nativeNumber(std::max(0.0, row.end - row.start))
           << ",\"sourceNumber\":" << row.sourceNumber
           << ",\"displayNumber\":" << row.displayNumber
           << '}';
    }
  }
  json << "]}";
  return json.str();
}

static bool nativeTriggerSelectedParts(bool parts2)
{
  std::string armedMarkerId;
  std::string selectedMarkerId;
  {
    std::lock_guard<std::mutex> lock(g_nativeMutex);
    armedMarkerId = g_nativeArmedMarkerId;
    selectedMarkerId = g_nativeSelectedMarkerId;
  }
  if (!armedMarkerId.empty() ||
      (!g_nativePartsPreparedSelectionId.empty() &&
       g_nativePartsPreparedSelectionId == selectedMarkerId)) {
    g_nativePartsPreparedSelectionId.clear();
    return nativeApplyMarkerCommand("{\"type\":\"marker_cancel\"}");
  }
  const auto& column = nativePartsColumnModel(parts2);
  int index = nativeCurrentPartsNavigationIndex(parts2);
  if (index < 0) {
    if (!nativeSelectPartsNavigationTarget(parts2, 0)) return false;
    index = 0;
  }
  if (column.hasSource && index == 0) return nativeTriggerPartsSourceStart(parts2);
  const int rowIndex = index - (column.hasSource ? 1 : 0);
  if (rowIndex < 0 || rowIndex >= static_cast<int>(column.rows.size())) return false;
  std::ostringstream json;
  json << "{\"type\":\"trigger_marker\",\"markerId\":"
       << nativeJsonString(column.rows[static_cast<size_t>(rowIndex)].id) << "}";
  const bool handled = nativeApplyMarkerCommand(json.str());
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
  const int playState = project && GetPlayStateEx_ptr ? GetPlayStateEx_ptr(project) : 0;
  if (handled && (playState & 1) == 0 && (playState & 4) == 0) {
    g_nativePartsPreparedSelectionId = column.rows[static_cast<size_t>(rowIndex)].id;
  } else {
    g_nativePartsPreparedSelectionId.clear();
  }
  return handled;
}

static bool nativeHandlePartsColumnClick(const POINT& point, bool rightClick, bool parts2)
{
  const RECT& panelRect = parts2 ? g_nativeMainParts2Rect : g_nativeMainParts1Rect;
  const RECT& headerRect = parts2 ? g_nativeMainParts2HeaderRect : g_nativeMainParts1HeaderRect;
  const RECT& listRect = parts2 ? g_nativeMainParts2ListRect : g_nativeMainParts1ListRect;
  if (!PtInRect(&panelRect, point)) return false;
  g_nativeMainNavigationFocus = parts2 ? "parts2" : "parts";
  if (PtInRect(&headerRect, point)) {
    if (!rightClick) nativeTriggerPartsSourceStart(parts2);
    return true;
  }
  if (!PtInRect(&listRect, point)) return true;
  const auto& rowHits = parts2
    ? g_nativeParts2RowHits
    : g_nativeParts1RowHits;
  int rowIndex = -1;
  for (const auto& hit : rowHits) {
    if (PtInRect(&hit.rect, point)) {
      rowIndex = hit.rowIndex;
      break;
    }
  }
  const auto& rows = nativePartsColumnModel(parts2).rows;
  if (rowIndex < 0 || rowIndex >= static_cast<int>(rows.size())) return true;
  const auto& row = rows[static_cast<size_t>(rowIndex)];
  if (rightClick) {
    nativeOpenPartsRenameModal(row);
  } else {
    std::ostringstream json;
    json << "{\"type\":\"trigger_marker\",\"markerId\":"
         << nativeJsonString(row.id) << "}";
    const bool handled = nativeApplyMarkerCommand(json.str());
    char pathBuf[2048] = "";
    ReaProject* project = getCurrentProject(pathBuf, static_cast<int>(sizeof(pathBuf)));
    const int playState = project && GetPlayStateEx_ptr ? GetPlayStateEx_ptr(project) : 0;
    if (handled && (playState & 1) == 0 && (playState & 4) == 0) {
      g_nativePartsPreparedSelectionId = row.id;
    } else {
      g_nativePartsPreparedSelectionId.clear();
    }
  }
  return true;
}

static std::string nativeUiMixerTrackNameById(
  const std::string& trackId)
{
  if (trackId == "MASTER_TRACK") return "MASTER";
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !CountTracks_ptr || !GetTrack_ptr) return "-";
  const int count = CountTracks_ptr(project);
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (track &&
        nativeTrackGuid(track, index) == trackId) {
      return nativeTrackName(track, index);
    }
  }
  return "-";
}

static MediaTrack* nativeUiMixerTrackById(
  const std::string& trackId,
  ReaProject** projectOut = nullptr)
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (projectOut) *projectOut = project;
  if (!project || trackId.empty() ||
      trackId == "MASTER_TRACK" ||
      !CountTracks_ptr || !GetTrack_ptr) {
    return nullptr;
  }
  const int count = CountTracks_ptr(project);
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (track && nativeTrackGuid(track, index) == trackId) {
      return track;
    }
  }
  return nullptr;
}

static void nativeUiCancelMixerInlineRename()
{
  g_nativeMixerRenameOpen = false;
  g_nativeMixerRenameTrackId.clear();
  g_nativeMixerRenameInput.clear();
  g_nativeMixerRenameCursor = 0;
  g_nativeMixerRenameInputRect = RECT{0, 0, 0, 0};
  if (g_nativeUiTextSelectionKind ==
      NativeUiTextInputKind::MixerRename) {
    g_nativeUiTextSelectionKind =
      NativeUiTextInputKind::None;
    g_nativeUiTextSelectionAnchor = 0;
    g_nativeUiTextMouseSelecting = false;
  }
}

static bool nativeUiBeginMixerInlineRename(
  const std::string& trackId,
  const RECT& nameRect,
  int pointX)
{
  MediaTrack* track = nativeUiMixerTrackById(trackId);
  if (!track) return false;
  g_nativeMixerRenameOpen = true;
  g_nativeMixerRenameTrackId = trackId;
  g_nativeMixerRenameInput = nativeUiMixerTrackNameById(trackId);
  g_nativeMixerRenameInputRect = nameRect;
  g_nativeMixerRenameCursor = nativeUiTextCursorFromPoint(
    g_nativeAppActivePanelHwnd, nameRect,
    g_nativeMixerRenameInput, pointX, 6);
  g_nativeUiTextSelectionKind =
    NativeUiTextInputKind::MixerRename;
  g_nativeUiTextSelectionAnchor =
    g_nativeMixerRenameCursor;
  return true;
}

static bool nativeUiCommitMixerInlineRename()
{
  if (!g_nativeMixerRenameOpen) return false;
  ReaProject* project = nullptr;
  MediaTrack* track = nativeUiMixerTrackById(
    g_nativeMixerRenameTrackId, &project);
  const std::string nextName = nativeUpperNamePtBr(
    nativeTrim(g_nativeMixerRenameInput));
  bool changed = false;
  if (track && !nextName.empty() &&
      GetSetMediaTrackInfo_String_ptr) {
    std::vector<char> writable(nextName.begin(), nextName.end());
    writable.push_back('\0');
    GetSetMediaTrackInfo_String_ptr(
      track, "P_NAME", writable.data(), true);
    if (TrackList_AdjustWindows_ptr) TrackList_AdjustWindows_ptr(false);
    if (UpdateArrange_ptr) UpdateArrange_ptr();
    if (project && MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
    g_nativeForceSnapshotBuild.store(true);
    g_nativeForceStateBuild.store(true);
    changed = true;
  }
  nativeUiCancelMixerInlineRename();
  return changed;
}

static bool nativeUiHandleMixerInlineRenameClick(
  const POINT& point)
{
  if (!g_nativeMixerRenameOpen) return false;
  if (PtInRect(&g_nativeMixerRenameInputRect, point)) {
    g_nativeMixerRenameCursor = nativeUiTextCursorFromPoint(
      g_nativeAppActivePanelHwnd,
      g_nativeMixerRenameInputRect,
      g_nativeMixerRenameInput,
      point.x, 6);
    return true;
  }
  nativeUiCommitMixerInlineRename();
  return false;
}

static bool nativeUiTextInputHitInfo(
  const POINT& point,
  NativeUiTextInputKind& kind,
  RECT& rect,
  int& leftPadding)
{
  kind = NativeUiTextInputKind::None;
  rect = RECT{0, 0, 0, 0};
  leftPadding = 0;

  if (g_nativeMainBpmEditOpen &&
      g_nativeMainModalKind == NativeMainModalKind::None &&
      PtInRect(&g_nativeMainBpmEditRect, point)) {
    kind = NativeUiTextInputKind::BpmValue;
    rect = g_nativeMainBpmEditRect;
    leftPadding = 4;
    return true;
  }

  if (g_nativeMixerRenameOpen &&
      g_nativeMainModalKind == NativeMainModalKind::None &&
      PtInRect(&g_nativeMixerRenameInputRect, point)) {
    kind = NativeUiTextInputKind::MixerRename;
    rect = g_nativeMixerRenameInputRect;
    leftPadding = 6;
    return true;
  }
  if (g_nativePartsRenameOpen &&
      PtInRect(&g_nativePartsRenameInputRect, point)) {
    kind = NativeUiTextInputKind::PartsRename;
    rect = g_nativePartsRenameInputRect;
    std::string prefix = g_nativePartsRenamePrefix;
    if (!prefix.empty() && prefix.front() == '*') {
      prefix += " ";
    }
    HDC dc = g_nativeAppActivePanelHwnd
      ? GetDC(g_nativeAppActivePanelHwnd) : nullptr;
    const int prefixWidth = dc
      ? nativeUiTextWidth(
          dc, prefix, nativeUiSharedFont()) : 0;
    if (dc) ReleaseDC(g_nativeAppActivePanelHwnd, dc);
    leftPadding = 8 + prefixWidth;
    return true;
  }
  if (g_nativeMainModalKind ==
        NativeMainModalKind::PlaylistDropdown &&
      nativeUiSelectedPlaylistEditableInCurrentProject() &&
      PtInRect(&g_nativeMainModalInputRect, point)) {
    g_nativeUiPlaylistInputFocused = true;
    kind = NativeUiTextInputKind::PlaylistRename;
    rect = g_nativeMainModalInputRect;
    leftPadding = 52;
    return true;
  }
  if (g_nativeMainModalKind ==
        NativeMainModalKind::CreatePlaylist &&
      PtInRect(&g_nativeMainModalInputRect, point)) {
    g_nativeUiCreatePlaylistInputFocused = true;
    kind = NativeUiTextInputKind::CreatePlaylist;
    rect = g_nativeMainModalInputRect;
    leftPadding = 6;
    return true;
  }
  if (g_nativeMainModalKind ==
        NativeMainModalKind::RenameRow &&
      PtInRect(&g_nativeMainModalInputRect, point)) {
    kind = NativeUiTextInputKind::RenameRow;
    rect = g_nativeMainModalInputRect;
    leftPadding = 6;
    return true;
  }
  if (g_nativeMainModalKind ==
        NativeMainModalKind::TimerConfig &&
      g_nativeUiTimerMode == "countdown" &&
      PtInRect(&g_nativeMainModalInputRect, point)) {
    kind = NativeUiTextInputKind::TimerCountdown;
    rect = g_nativeMainModalInputRect;
    return true;
  }
  if (g_nativeMainModalKind == NativeMainModalKind::None &&
      !g_nativePartsRenameOpen &&
      PtInRect(&g_nativeMainSearchFieldRect, point)) {
    if (!g_nativeMainSearchFocused) {
      nativeUiToggleSmartSearch();
    }
    kind = NativeUiTextInputKind::SmartSearch;
    rect = g_nativeMainSearchFieldRect;
    leftPadding = 8;
    return true;
  }
  return false;
}

static size_t nativeUiTextCursorForMousePoint(
  NativeUiTextInputKind kind,
  const RECT& rect,
  int leftPadding,
  int pointX)
{
  if (kind == NativeUiTextInputKind::TimerCountdown) {
    if (!g_nativeUiTimerCaretPositionsValid) return 0;
    int best = 0;
    int bestDistance = 0x7fffffff;
    for (int index = 0; index < 7; ++index) {
      const int distance = std::abs(
        g_nativeUiTimerCaretPositions[index] - pointX);
      if (distance < bestDistance) {
        best = index;
        bestDistance = distance;
      }
    }
    return static_cast<size_t>(best);
  }
  std::string* text = nativeUiTextInputValue(kind);
  if (!text) return 0;
  return nativeUiTextCursorFromPoint(
    g_nativeAppActivePanelHwnd,
    rect, *text, pointX, leftPadding,
    kind == NativeUiTextInputKind::BpmValue
      ? DT_CENTER : DT_LEFT);
}

static bool nativeUiBeginTextMouseSelection(
  HWND hwnd,
  const POINT& point)
{
  NativeUiTextInputKind kind =
    NativeUiTextInputKind::None;
  RECT rect{0, 0, 0, 0};
  int leftPadding = 0;
  if (!nativeUiTextInputHitInfo(
        point, kind, rect, leftPadding)) {
    return false;
  }

  const size_t cursor =
    nativeUiTextCursorForMousePoint(
      kind, rect, leftPadding, point.x);
  const bool extend =
    (GetAsyncKeyState(VK_SHIFT) & 0x8000) != 0 &&
    g_nativeUiTextSelectionKind == kind;
  nativeUiEnsureTextSelectionKind(kind);
  if (!extend) {
    g_nativeUiTextSelectionAnchor = cursor;
  }
  nativeUiSetTextInputCursor(kind, cursor);
  g_nativeUiTextSelectionKind = kind;
  g_nativeUiTextMouseSelecting = true;
  SetCapture(hwnd);
  return true;
}

static void nativeUiUpdateTextMouseSelection(
  HWND hwnd,
  const POINT& point)
{
  if (!g_nativeUiTextMouseSelecting ||
      g_nativeUiTextSelectionKind ==
        NativeUiTextInputKind::None) {
    return;
  }
  NativeUiTextInputKind hitKind =
    NativeUiTextInputKind::None;
  RECT rect{0, 0, 0, 0};
  int leftPadding = 0;
  // Durante o arraste o ponteiro pode sair do campo. Nesse caso usamos o
  // retângulo do input ativo, sem trocar o dono da seleção.
  switch (g_nativeUiTextSelectionKind) {
    case NativeUiTextInputKind::SmartSearch:
      rect = g_nativeMainSearchFieldRect;
      leftPadding = 8;
      break;
    case NativeUiTextInputKind::MixerRename:
      rect = g_nativeMixerRenameInputRect;
      leftPadding = 6;
      break;
    case NativeUiTextInputKind::PlaylistRename:
      rect = g_nativeMainModalInputRect;
      leftPadding = 52;
      break;
    case NativeUiTextInputKind::CreatePlaylist:
    case NativeUiTextInputKind::RenameRow:
      rect = g_nativeMainModalInputRect;
      leftPadding = 6;
      break;
    case NativeUiTextInputKind::PartsRename: {
      rect = g_nativePartsRenameInputRect;
      std::string prefix = g_nativePartsRenamePrefix;
      if (!prefix.empty() && prefix.front() == '*') {
        prefix += " ";
      }
      HDC dc = hwnd ? GetDC(hwnd) : nullptr;
      leftPadding = 8 + (dc
        ? nativeUiTextWidth(
            dc, prefix, nativeUiSharedFont()) : 0);
      if (dc) ReleaseDC(hwnd, dc);
      break;
    }
    case NativeUiTextInputKind::TimerCountdown:
      rect = g_nativeMainModalInputRect;
      break;
    case NativeUiTextInputKind::BpmValue:
      rect = g_nativeMainBpmEditRect;
      leftPadding = 4;
      break;
    case NativeUiTextInputKind::None:
      return;
  }
  (void)hitKind;
  nativeUiSetTextInputCursor(
    g_nativeUiTextSelectionKind,
    nativeUiTextCursorForMousePoint(
      g_nativeUiTextSelectionKind,
      rect, leftPadding, point.x));
  nativeUiRefreshTextInputNow(hwnd);
}

static void nativeUiFinishTextMouseSelection(
  HWND hwnd,
  const POINT& point)
{
  if (!g_nativeUiTextMouseSelecting) return;
  nativeUiUpdateTextMouseSelection(hwnd, point);
  g_nativeUiTextMouseSelecting = false;
  if (GetCapture() == hwnd) ReleaseCapture();
}

static bool nativeUiHandleMixerNameMouseDown(
  const POINT& point)
{
  for (const auto& hit : g_nativeMixerHits) {
    if (hit.kind != NativeMixerHitKind::Name ||
        !PtInRect(&hit.rect, point)) {
      continue;
    }
    const auto now = std::chrono::steady_clock::now();
    const bool sameTrack =
      hit.trackId == g_nativeMixerLastNameClickTrackId;
    const bool doubleClick = sameTrack &&
      g_nativeMixerLastNameClickAt.time_since_epoch().count() != 0 &&
      now - g_nativeMixerLastNameClickAt <=
        std::chrono::milliseconds(450);
    g_nativeMixerLastNameClickAt = now;
    g_nativeMixerLastNameClickTrackId = hit.trackId;
    if (doubleClick) {
      return nativeUiBeginMixerInlineRename(
        hit.trackId, hit.rect, point.x);
    }
    // O primeiro clique segue para nativeUiBeginMixerReorderPress.
    return false;
  }
  return false;
}

static bool nativeUiHandleMixerFaderDoubleClick(
  const POINT& point)
{
  for (const auto& hit : g_nativeMixerHits) {
    if (hit.kind != NativeMixerHitKind::Volume ||
        !PtInRect(&hit.rect, point)) {
      continue;
    }
    const auto now = std::chrono::steady_clock::now();
    const bool doubleClick =
      g_nativeMixerLastFaderClickAt.time_since_epoch().count() != 0 &&
      now - g_nativeMixerLastFaderClickAt <=
        std::chrono::milliseconds(300);
    g_nativeMixerLastFaderClickAt = now;
    if (!doubleClick) return false;
    std::ostringstream command;
    command << "{\"type\":\"mixer_reset_volume\",\"targetId\":"
            << nativeJsonString(hit.trackId) << "}";
    nativeApplyMixerCommand(command.str());
    g_nativeMixerSuppressNextMouseUp = true;
    return true;
  }
  return false;
}

static bool nativeUiOpenMixerGroupColor(
  const std::string& trackId)
{
  if (trackId.empty() || trackId == "MASTER_TRACK") return false;
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !CountTracks_ptr || !GetTrack_ptr ||
      !GetMediaTrackInfo_Value_ptr) {
    return false;
  }
  const int count = CountTracks_ptr(project);
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (!track || nativeTrackGuid(track, index) != trackId) continue;
    if (GetMediaTrackInfo_Value_ptr(track, "I_FOLDERDEPTH") <= 0.5) {
      return false;
    }
    g_nativeUiMixerGroupColorTrackId = trackId;
    g_nativeUiMixerGroupColorTrackName = nativeTrackName(track, index);
    g_nativeMainModalKind = NativeMainModalKind::MixerGroupColor;
    return true;
  }
  return false;
}

static bool nativeUiApplyMixerGroupColor(
  const std::string& trackId,
  int red,
  int green,
  int blue,
  bool clearColor)
{
  if (trackId.empty() || trackId == "MASTER_TRACK" ||
      !SetMediaTrackInfo_Value_ptr || !GetMediaTrackInfo_Value_ptr ||
      !CountTracks_ptr || !GetTrack_ptr) {
    return false;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return false;

  int groupIndex = -1;
  MediaTrack* groupTrack = nullptr;
  const int count = CountTracks_ptr(project);
  for (int index = 0; index < count; ++index) {
    MediaTrack* track = GetTrack_ptr(project, index);
    if (track && nativeTrackGuid(track, index) == trackId) {
      groupIndex = index;
      groupTrack = track;
      break;
    }
  }
  if (!groupTrack || groupIndex < 0 ||
      GetMediaTrackInfo_Value_ptr(groupTrack, "I_FOLDERDEPTH") <= 0.5) {
    return false;
  }

  int nativeColor = 0;
  if (!clearColor) {
    red = std::max(0, std::min(255, red));
    green = std::max(0, std::min(255, green));
    blue = std::max(0, std::min(255, blue));
    nativeColor = ColorToNative_ptr
      ? ColorToNative_ptr(red, green, blue)
      : RGB(red, green, blue);
    nativeColor |= 0x01000000;
  }

  // Mesmo mixer_apply_color_to_group_children do Lua: a cor pertence ao
  // grupo inteiro, do folder pai ate a pista que fecha sua profundidade.
  SetMediaTrackInfo_Value_ptr(groupTrack, "I_CUSTOMCOLOR",
    static_cast<double>(nativeColor));
  int folderDepth = 1;
  for (int index = groupIndex + 1; index < count; ++index) {
    MediaTrack* child = GetTrack_ptr(project, index);
    if (!child) break;
    SetMediaTrackInfo_Value_ptr(child, "I_CUSTOMCOLOR",
      static_cast<double>(nativeColor));
    folderDepth += static_cast<int>(std::lround(
      GetMediaTrackInfo_Value_ptr(child, "I_FOLDERDEPTH")));
    if (folderDepth <= 0) break;
  }
  if (TrackList_AdjustWindows_ptr) TrackList_AdjustWindows_ptr(false);
  if (UpdateArrange_ptr) UpdateArrange_ptr();
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  g_nativeForceSnapshotBuild.store(true);
  g_nativeForceStateBuild.store(true);
  return true;
}

static void nativeUiOpenMixerBinding(
  const std::string& trackId,
  const std::string& action)
{
  g_nativeUiMixerTrackId = trackId;
  g_nativeUiMixerTrackName =
    nativeUiMixerTrackNameById(trackId);
  g_nativeUiMixerAction =
    action == "solo" ? "solo"
      : (action == "volume" ? "volume" : "mute");
  g_nativeUiMixerInfo.clear();
  g_nativeMainModalKind = NativeMainModalKind::MixerBinding;
}

static std::string nativeUiMixerBulkTracksKey(
  const std::string& action)
{
  return action == "unsolo"
    ? "MIXER_BULK_UNSOLO_TRACKS_V1"
    : "MIXER_BULK_UNMUTE_TRACKS_V1";
}

static std::string nativeUiMixerBulkBindingKey(
  const std::string& action,
  const std::string& kind)
{
  const std::string prefix =
    action == "unsolo"
      ? "MIXER_BULK_UNSOLO_"
      : "MIXER_BULK_UNMUTE_";
  return prefix +
    (kind == "midi" ? "MIDI_V1" : "KEYBOARD_V1");
}

static std::string nativeUiReadMixerBulkBinding(
  const std::string& action,
  const std::string& kind)
{
  const std::string key =
    nativeUiMixerBulkBindingKey(action, kind);
  if (kind == "midi") {
    const char* raw = GetExtState_ptr
      ? GetExtState_ptr(kMixerBindingExtSection, key.c_str())
      : nullptr;
    return raw ? raw : "";
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return "";
  std::string raw = nativeGetProjExtStateString(
    project, kMixerBindingExtSection, key.c_str());
  if (raw.empty() && GetExtState_ptr) {
    const char* legacy =
      GetExtState_ptr(kMixerBindingExtSection, key.c_str());
    raw = legacy ? legacy : "";
  }
  return raw;
}

static bool nativeUiWriteMixerBulkBinding(
  const std::string& action,
  const std::string& kind,
  const std::string& value)
{
  const std::string key =
    nativeUiMixerBulkBindingKey(action, kind);
  if (kind == "midi") {
    if (!SetExtState_ptr) return false;
    SetExtState_ptr(kMixerBindingExtSection,
      key.c_str(), value.c_str(), true);
    return true;
  }
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !SetProjExtState_ptr) return false;
  SetProjExtState_ptr(project, kMixerBindingExtSection,
    key.c_str(), value.c_str());
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  return true;
}

static void nativeUiLoadMixerBulkTracks(
  const std::string& action)
{
  g_nativeUiMixerBulkTracks.clear();
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project) return;
  const std::string key =
    nativeUiMixerBulkTracksKey(action);
  std::string raw = nativeGetProjExtStateString(
    project, kMixerBindingExtSection, key.c_str());
  if (raw.empty() && GetExtState_ptr) {
    const char* legacy =
      GetExtState_ptr(kMixerBindingExtSection, key.c_str());
    raw = legacy ? legacy : "";
  }
  for (const auto& value : nativeSplit(raw, ';')) {
    const std::string id = nativeTrim(value);
    if (!id.empty()) g_nativeUiMixerBulkTracks[id] = true;
  }
}

static bool nativeUiSaveMixerBulkTracks()
{
  char pathBuf[2048] = "";
  ReaProject* project = getCurrentProject(
    pathBuf, static_cast<int>(sizeof(pathBuf)));
  if (!project || !SetProjExtState_ptr) return false;
  std::vector<std::string> ids;
  if (CountTracks_ptr && GetTrack_ptr) {
    const int count = CountTracks_ptr(project);
    for (int index = 0; index < count; ++index) {
      MediaTrack* track = GetTrack_ptr(project, index);
      if (!track) continue;
      const std::string id = nativeTrackGuid(track, index);
      if (g_nativeUiMixerBulkTracks[id]) ids.push_back(id);
    }
  }
  std::ostringstream packed;
  for (size_t index = 0; index < ids.size(); ++index) {
    if (index > 0) packed << ';';
    packed << ids[index];
  }
  const std::string key =
    nativeUiMixerBulkTracksKey(g_nativeUiMixerBulkAction);
  SetProjExtState_ptr(project, kMixerBindingExtSection,
    key.c_str(), packed.str().c_str());
  if (MarkProjectDirty_ptr) MarkProjectDirty_ptr(project);
  return true;
}

static void nativeUiOpenMixerBulkConfig(
  const std::string& action)
{
  g_nativeUiMixerBulkAction =
    action == "unsolo" ? "unsolo" : "unmute";
  g_nativeUiMixerInfo.clear();
  nativeUiLoadMixerBulkTracks(g_nativeUiMixerBulkAction);
  g_nativeUiMixerBulkScroll = 0;
  g_nativeMainModalKind = NativeMainModalKind::MixerBulkConfig;
}

static bool nativeUiSetMixerVolumeAtPoint(
  const std::string& trackId,
  const RECT& rect,
  int pointX)
{
  const int width = std::max(
    1, static_cast<int>(rect.right - rect.left));
  const double ratio = std::max(0.0, std::min(1.0,
    static_cast<double>(pointX - rect.left) / width));
  std::ostringstream command;
  command << "{\"type\":\"mixer_set_volume\",\"targetId\":"
          << nativeJsonString(trackId)
          << ",\"ratio\":" << std::setprecision(15)
          << ratio << "}";
  return nativeApplyMixerCommand(command.str());
}

static bool nativeUiHandleMixerHit(
  const POINT& point,
  bool rightClick,
  bool beginVolumeDrag)
{
  for (const auto& hit : g_nativeMixerHits) {
    if (!PtInRect(&hit.rect, point)) continue;
    if (hit.kind == NativeMixerHitKind::Mute ||
        hit.kind == NativeMixerHitKind::Solo ||
        hit.kind == NativeMixerHitKind::Volume) {
      const std::string action =
        hit.kind == NativeMixerHitKind::Solo ? "solo"
          : (hit.kind == NativeMixerHitKind::Volume
              ? "volume" : "mute");
      if (rightClick) {
        nativeUiOpenMixerBinding(hit.trackId, action);
        return true;
      }
    }
    if (rightClick) {
      if (hit.kind == NativeMixerHitKind::Unmute) {
        nativeUiOpenMixerBulkConfig("unmute");
      } else if (hit.kind == NativeMixerHitKind::Unsolo) {
        nativeUiOpenMixerBulkConfig("unsolo");
      } else if (hit.kind == NativeMixerHitKind::Name && hit.group) {
        nativeUiOpenMixerGroupColor(hit.trackId);
      }
      return true;
    }

    std::ostringstream command;
    switch (hit.kind) {
      case NativeMixerHitKind::Mute:
        command << "{\"type\":\"mixer_toggle_mute\",\"targetId\":"
                << nativeJsonString(hit.trackId) << "}";
        return nativeApplyMixerCommand(command.str());
      case NativeMixerHitKind::Solo:
        command << "{\"type\":\"mixer_toggle_solo\",\"targetId\":"
                << nativeJsonString(hit.trackId) << "}";
        return nativeApplyMixerCommand(command.str());
      case NativeMixerHitKind::Route:
        command << "{\"type\":\"mixer_route\",\"targetId\":"
                << nativeJsonString(hit.trackId) << "}";
        return nativeApplyMixerCommand(command.str());
      case NativeMixerHitKind::ResetVolume:
        command << "{\"type\":\"mixer_reset_volume\",\"targetId\":"
                << nativeJsonString(hit.trackId) << "}";
        return nativeApplyMixerCommand(command.str());
      case NativeMixerHitKind::Volume:
        if (beginVolumeDrag) {
          g_nativeMixerVolumeDragging = true;
          g_nativeMixerVolumeDragRect = hit.rect;
          g_nativeMixerVolumeDragTrackId = hit.trackId;
        }
        return nativeUiSetMixerVolumeAtPoint(
          hit.trackId, hit.rect, point.x);
      case NativeMixerHitKind::ClearBindings:
        g_nativeMainModalKind =
          NativeMainModalKind::ConfirmClearMixerBindings;
        return true;
      case NativeMixerHitKind::Unmute:
        return nativeApplyMixerCommand(
          "{\"type\":\"mixer_bulk_unmute\"}");
      case NativeMixerHitKind::Unsolo:
        return nativeApplyMixerCommand(
          "{\"type\":\"mixer_bulk_unsolo\"}");
      case NativeMixerHitKind::Name:
        return true;
    }
  }
  return false;
}

static bool nativeMainHandleControlClick(const POINT& point, bool rightClick)
{
  auto finishPcCommand = [](bool handled) {
    if (handled) {
      std::lock_guard<std::mutex> lock(g_nativeMutex);
      nativeBumpSharedRevisionLocked("pc");
      g_nativeForceStateBuild.store(true);
    }
    return handled;
  };
  if (!rightClick && g_nativeMainBpmEditOpen) {
    if (PtInRect(&g_nativeMainBpmEditRect, point)) {
      g_nativeMainBpmEditCursor = nativeUiTextCursorFromPoint(
        g_nativeAppActivePanelHwnd,
        g_nativeMainBpmEditRect,
        g_nativeMainBpmEditInput, point.x, 4, DT_CENTER);
      g_nativeUiTextSelectionKind = NativeUiTextInputKind::BpmValue;
      g_nativeUiTextSelectionAnchor = g_nativeMainBpmEditCursor;
      return true;
    }
    if (!nativeUiCommitBpmValueEdit()) return true;
  }
  // A lupa tem prioridade sobre o campo de repertorio. Isso tambem protege o
  // clique durante resize/dock, quando um frame antigo ainda pode ter deixado
  // retangulos de hit-test sobrepostos.
  if (PtInRect(&g_nativeMainSearchFieldRect, point)) {
    // A lupa principal e a unica busca. Ela permanece no repertorio enquanto
    // houver resultado local e so entao consulta a pagina Musicas.
    if (!rightClick) {
      if (!g_nativeMainSearchFocused) nativeUiToggleSmartSearch();
      g_nativeMainSearchCursor = nativeUiTextCursorFromPoint(
        g_nativeAppActivePanelHwnd,
        g_nativeMainSearchFieldRect,
        g_nativeMainSearchText,
        point.x,
        8);
    }
    return true;
  }
  if (PtInRect(&g_nativeMainPlaylistFieldRect, point)) {
    if (!rightClick &&
        !g_nativeAppActivePanelModel.regionsPage &&
        !g_nativeAppActivePanelModel.mixerPage) {
      if (g_nativeMainSearchFocused) nativeUiCloseSmartSearch(false);
      nativeUiOpenPlaylistDropdown();
    }
    return true;
  }
  // O campo Total e apenas visual no Lua. Um clique nele segue a mesma regra
  // de qualquer area fora das listas e, portanto, pode limpar a selecao azul.
  if (!rightClick && !PtInRect(&g_nativeMainListRect, point)) {
    if (g_nativeMainSearchFocused) nativeUiCloseSmartSearch(true);
  }

  if (PtInRect(&g_nativeMainPlaylistTabRect, point)) {
    if (rightClick) return true;
    g_nativeMainNavigationFocus = "playlist";
    finishPcCommand(nativeApplySelectionCommand("{\"type\":\"set_page\",\"page\":\"playlist\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainRegionsTabRect, point)) {
    if (rightClick) return true;
    g_nativeMainNavigationFocus = "regions";
    finishPcCommand(nativeApplySelectionCommand("{\"type\":\"set_page\",\"page\":\"regions\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainMixerTabRect, point)) {
    if (rightClick) return true;
    if (g_nativeMainSearchFocused) {
      nativeUiCloseSmartSearch(false);
    }
    g_nativeMainNavigationFocus = "mixer";
    finishPcCommand(nativeApplySelectionCommand(
      "{\"type\":\"set_page\",\"page\":\"mixer\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainMidiTabRect, point)) {
    if (rightClick) return true;
    nativeUiOpenMidiAssign();
    return true;
  }
  if (PtInRect(&g_nativeMainTunerTabRect, point)) {
    if (!rightClick) {
      const bool visible = !g_nativeAppActivePanelModel.showTuner;
      nativeSetTunerColumnVisible(visible);
    }
    return true;
  }
  if (PtInRect(&g_nativeMainHelpTabRect, point)) {
    if (rightClick) return true;
    g_nativeMainModalKind = NativeMainModalKind::Help;
    return true;
  }
  if (PtInRect(&g_nativeMainConfigTabRect, point)) {
    if (rightClick) return true;
    g_nativeMainModalKind = NativeMainModalKind::Config;
    return true;
  }
  if (PtInRect(&g_nativeMainPlayRect, point)) {
    if (rightClick) {
      nativeUiOpenManualStopConfig();
      return true;
    }
    const bool transportActive =
      nativeUiTransportActive();
    if (!nativePlayProtectionShouldAllow(
          transportActive ? "stop" : "play")) {
      return true;
    }
    g_nativePartsPreparedSelectionId.clear();
    finishPcCommand(nativeApplyTransportCommand("{\"type\":\"play_button\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainAutoRect, point)) {
    if (rightClick || g_nativeAppActivePanelModel.regionsPage) return true;
    finishPcCommand(nativeApplyAutoCommand("{\"type\":\"autoplay1_toggle\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainBpmTabRect, point)) {
    if (!rightClick) {
      const bool visible = !g_nativeAppActivePanelModel.showBpm;
      nativeSetBpmColumnVisible(visible);
    }
    return true;
  }
  if (PtInRect(&g_nativeMainAuto2Rect, point)) {
    if (rightClick || g_nativeAppActivePanelModel.regionsPage) return true;
    finishPcCommand(nativeApplyAutoCommand("{\"type\":\"autoplay2_toggle\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainLoopRect, point)) {
    if (rightClick) return true;
    finishPcCommand(nativeApplyLoopCommand("{\"type\":\"loop_toggle\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainBypassRect, point)) {
    if (rightClick) return true;
    finishPcCommand(nativeApplyMultiLoopCommand("{\"type\":\"multiloop_bypass_toggle\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainAtBlRect, point)) {
    if (rightClick) return true;
    finishPcCommand(nativeApplyAutoCommand("{\"type\":\"auto_bloco_toggle\"}"));
    return true;
  }
  if (PtInRect(&g_nativeMainMixerGroupsButtonRect, point)) {
    if (rightClick) return true;
    const bool visible =
      !g_nativeAppActivePanelModel.showMixerGroups;
    g_nativeAppActivePanelModel.showMixerGroups = visible;
    if (SetExtState_ptr) {
      SetExtState_ptr(kLuaWindowExtStateSection,
        "SHOW_MIXER_GROUPS_V1",
        visible ? "1" : "0", true);
    }
    g_nativeForceStateBuild.store(true);
    return true;
  }
  if (PtInRect(&g_nativeMainMixerTracksButtonRect, point)) {
    if (rightClick) return true;
    const bool visible =
      !g_nativeAppActivePanelModel.showMixerTracks;
    g_nativeAppActivePanelModel.showMixerTracks = visible;
    if (SetExtState_ptr) {
      SetExtState_ptr(kLuaWindowExtStateSection,
        "SHOW_MIXER_TRACKS_V1",
        visible ? "1" : "0", true);
    }
    g_nativeForceStateBuild.store(true);
    return true;
  }
  if (PtInRect(&g_nativeMainParts1ButtonRect, point)) {
    if (rightClick) return true;
    nativeSetPartsColumnVisible(false, !g_nativeAppActivePanelModel.showParts1);
    finishPcCommand(true);
    return true;
  }
  if (PtInRect(&g_nativeMainParts2ButtonRect, point)) {
    if (rightClick) return true;
    nativeSetPartsColumnVisible(true, !g_nativeAppActivePanelModel.showParts2);
    finishPcCommand(true);
    return true;
  }
  if (PtInRect(&g_nativeMainTimerRect, point)) {
    if (rightClick) {
      nativeUiOpenTimerConfig();
    } else {
      finishPcCommand(nativeUiRequestTimerToggle());
    }
    return true;
  }
  if (PtInRect(&g_nativeMainAllRect, point)) {
    if (rightClick) return true;
    nativeUiClearMainRowSelectionForPage(true);
    for (const auto& row : g_nativeAppActivePanelModel.rows) {
      if (!row.block) nativeUiSetMainRowSelected(row, true, true);
    }
    g_nativeUiSelectionAnchorVisibleIndex =
      g_nativeMainVisibleRowIndices.empty()
        ? -1
        : static_cast<int>(g_nativeMainVisibleRowIndices.size()) - 1;
    g_nativeUiSelectionFocusVisibleIndex =
      g_nativeUiSelectionAnchorVisibleIndex;
    return true;
  }
  if (PtInRect(&g_nativeMainCreateRect, point)) {
    if (rightClick) return true;
    nativeUiOpenCreatePlaylist();
    return true;
  }
  if (PtInRect(&g_nativeMainAddRect, point)) {
    if (rightClick) return true;
    if (nativeUiMainSelectionCount(true) > 0) {
      nativeUiOpenSelectPlaylist();
    }
    return true;
  }
  if (PtInRect(&g_nativeMainBlocksRect, point)) {
    if (rightClick) return true;
    finishPcCommand(nativeUiCreatePlaylistBlock());
    return true;
  }

  if (PtInRect(&g_nativeMainHeaderLiveRect, point)) {
    if (rightClick) return true;
    g_nativeMainModalKind = NativeMainModalKind::ConfirmLive;
    return true;
  }
  if (PtInRect(&g_nativeMainHeaderRetryRect, point)) {
    if (rightClick) return true;
    g_nativeMainModalKind = NativeMainModalKind::ConfirmRetry;
    return true;
  }
  if (PtInRect(&g_nativeMainHeaderNumberRect, point)) {
    if (rightClick) return true;
    g_nativeMainModalKind = NativeMainModalKind::ConfirmNumber;
    return true;
  }
  if (PtInRect(&g_nativeMainHeader09Rect, point)) {
    if (rightClick) return true;
    if (!g_nativeAppActivePanelModel.numberRegionMode) {
      nativeUiOpenMessage("0-9 só funciona com Number em ID da região.");
    } else {
      g_nativeMainModalKind = NativeMainModalKind::Confirm09;
    }
    return true;
  }
  if (PtInRect(&g_nativeMainHeaderUpdateRect, point)) {
    if (rightClick) return true;
    nativeUiUpdateProjectFromConfig();
    return true;
  }
  if (PtInRect(&g_nativeMainHeaderViewRect, point)) {
    if (rightClick) return true;
    g_nativeMainViewEnabled = !g_nativeMainViewEnabled;
    if (SetExtState_ptr) {
      SetExtState_ptr(kLuaWindowExtStateSection,
        "HASH_CHILDREN_CONTROLS_VIEW_V1",
        g_nativeMainViewEnabled ? "1" : "0", true);
    }
    // O View e compartilhado com o App do Diretor. Publica a mudanca local
    // imediatamente para o app refletir o mesmo estado no proximo snapshot.
    g_nativeForceStateBuild.store(true);
    return true;
  }
  if (PtInRect(&g_nativeMainHeaderAlphaRect, point)) {
    if (rightClick) return true;
    g_nativeRegionsRetrySortMode = g_nativeRegionsSortMode;
    g_nativeRegionsSortMode = g_nativeRegionsSortMode == 1 ? 2 : 1;
    g_nativeAppActiveListScrollPixels = 0;
    return true;
  }
  if (PtInRect(&g_nativeMainHeaderResetRect, point)) {
    if (rightClick) return true;
    g_nativeMainModalKind =
      NativeMainModalKind::ConfirmResetRegions;
    return true;
  }

  if (PtInRect(&g_nativeMainTunerResetRect, point)) {
    if (!rightClick) {
      g_nativeMainModalKind =
        NativeMainModalKind::ConfirmTunerReset;
    }
    return true;
  }
  if (PtInRect(&g_nativeMainBpmScanRect, point)) {
    if (!rightClick) nativeUiOpenBpmScan();
    return true;
  }
  if (PtInRect(&g_nativeMainPreviewPageRect, point)) {
    if (!rightClick) {
      g_nativeMainPreviewSecondPage =
        !g_nativeMainPreviewSecondPage;
      InvalidateRect(
        g_nativeAppActivePanelHwnd, nullptr, FALSE);
    }
    return true;
  }
  for (const auto& tunerHit : g_nativeMainTunerHits) {
    if (!PtInRect(&tunerHit.rect, point)) continue;
    if (rightClick) {
      g_nativeUiTunerKeyboardAction =
        tunerHit.delta < 0 ? "minus" : "plus";
      g_nativeUiTunerKeyboardInfo.clear();
      g_nativeMainModalKind =
        NativeMainModalKind::TunerKeyboardBinding;
    } else {
      std::ostringstream command;
      command << "{\"type\":\"tuner_adjust\",\"songId\":"
              << nativeJsonString(tunerHit.id)
              << ",\"sourceNumber\":"
              << tunerHit.sourceNumber
              << ",\"delta\":" << tunerHit.delta << "}";
      finishPcCommand(nativeApplyTunerCommand(command.str()));
    }
    return true;
  }
  for (const auto& bpmHit : g_nativeMainBpmHits) {
    if (!PtInRect(&bpmHit.rect, point)) continue;
    if (rightClick) return true;
    if (bpmHit.delta == 0) {
      nativeUiOpenBpmValueEdit(bpmHit, point.x);
    } else if (bpmHit.delta == -1 || bpmHit.delta == 1) {
      nativeUiAdjustBpmValue(bpmHit);
    }
    InvalidateRect(g_nativeAppActivePanelHwnd, nullptr, FALSE);
    return true;
  }
  for (const auto& liveResetHit : g_nativeMainLiveResetHits) {
    if (!PtInRect(&liveResetHit.rect, point)) continue;
    if (!rightClick) {
      std::ostringstream command;
      command << "{\"type\":\"live_reset_item\",\"songId\":"
              << nativeJsonString(liveResetHit.id)
              << ",\"startPos\":" << std::setprecision(15)
              << liveResetHit.start
              << ",\"endPos\":" << std::setprecision(15)
              << liveResetHit.end << "}";
      finishPcCommand(nativeApplyLiveMarkCommand(
        command.str()));
      nativeUiShowTemporaryPopup(
        "Marcacao Live removida", 1.2);
    }
    return true;
  }

  for (int i = 0; i < 10; ++i) {
    if (!PtInRect(&g_nativeMainFooterRects[i], point)) continue;
    if (i < 6) {
      if (rightClick) {
        g_nativeMainModalPreviewSlot = i + 1;
        g_nativeUiMidiInfo.clear();
        g_nativeMainModalKind = NativeMainModalKind::PreviewBinding;
      } else {
        std::ostringstream command;
        command << "{\"type\":\"preview_toggle\",\"slot\":" << (i + 1) << "}";
        finishPcCommand(nativeApplyPreviewCommand(command.str()));
      }
    } else if (i == 6) {
      if (!rightClick) nativeUiOpenExportAudioFormat();
    } else if (i == 7) {
      if (!rightClick) nativeUiExecuteTp1();
    } else if (i == 8) {
      if (!rightClick) nativeUiExecuteTp2();
    } else {
      if (!rightClick) {
        finishPcCommand(nativeApplyAutoCommand(
          "{\"type\":\"auto_stop_toggle\"}"));
      }
    }
    return true;
  }

  for (const auto& familyButton : g_nativeMainFamilyButtonHits) {
    if (!PtInRect(&familyButton.rect, point)) continue;
    if (rightClick) break;
    {
      std::lock_guard<std::mutex> lock(g_nativeMutex);
      const auto found =
        g_nativeDirectorOpenFamilyDrawers.find(familyButton.familyId);
      if (found == g_nativeDirectorOpenFamilyDrawers.end()) {
        g_nativeDirectorOpenFamilyDrawers[familyButton.familyId] = true;
      } else {
        g_nativeDirectorOpenFamilyDrawers.erase(found);
      }
      g_nativeFamilyDrawersOwner = "pc";
      ++g_nativeFamilyDrawersRevision;
      // Abrir/ocultar uma gaveta local muda apenas o conteúdo da lista.
      // Não publica uma revisão de scroll: a proporção compartilhada pode
      // estar defasada (inclusive em zero) e puxava a interface para o topo.
      // O layout novo conserva os pixels atuais e apenas faz o clamp normal.
      nativeBumpSharedRevisionLocked("pc");
      nativePersistFamilyDrawersForCurrentProjectLocked();
    }
    g_nativeForceStateBuild.store(true);
    return true;
  }

  if (PtInRect(&g_nativeMainParts2Rect, point)) {
    finishPcCommand(nativeHandlePartsColumnClick(point, rightClick, true));
    return true;
  }
  if (PtInRect(&g_nativeMainParts1Rect, point)) {
    finishPcCommand(nativeHandlePartsColumnClick(point, rightClick, false));
    return true;
  }

  if (g_nativeAppActivePanelModel.mixerPage &&
      nativeUiHandleMixerHit(point, rightClick, false)) {
    finishPcCommand(true);
    return true;
  }

  if (PtInRect(&g_nativeMainListRect, point)) {
    g_nativeMainNavigationFocus = g_nativeAppActivePanelModel.regionsPage ? "regions" : "playlist";
    int rowIndex = -1;
    size_t rowSourceIndex = 0;
    for (const auto& rowHit : g_nativeMainRowHits) {
      if (!PtInRect(&rowHit.rect, point)) continue;
      rowIndex = rowHit.visibleIndex;
      rowSourceIndex = rowHit.sourceIndex;
      break;
    }
    if (rowIndex >= 0 &&
        rowSourceIndex <
          g_nativeAppActivePanelModel.rows.size()) {
      const NativeAppActivePanelModel::Row& row =
        g_nativeAppActivePanelModel.rows[
          rowSourceIndex];
      if (rightClick) {
        nativeUiOpenRowRename(row,
          g_nativeAppActivePanelModel.regionsPage);
      } else {
        const bool regionsPage =
          g_nativeAppActivePanelModel.regionsPage;
        if (g_nativeMainSearchFocused && !row.block) {
          finishPcCommand(nativeUiActivateSmartSearchResult(
            row, regionsPage));
          return true;
        }
        const bool transportPlaying =
          nativeUiTransportActive();
        const bool extend =
          (GetAsyncKeyState(VK_CONTROL) & 0x8000) != 0;
        const bool range =
          (GetAsyncKeyState(VK_SHIFT) & 0x8000) != 0;

        // Igual ao Lua: bloco nao reage a clique durante a reproducao. Na aba
        // Musicas, qualquer clique simples durante playback arma diretamente a
        // fila; em Repertorio, Ctrl/Shift continuam reservados para selecao.
        if (row.block && transportPlaying) {
          return true;
        }
        const bool queueFromClick = !row.block && transportPlaying &&
          (regionsPage || (!range && !extend));
        if (queueFromClick) {
          nativeUiClearMainRowSelection();
          nativeApplySelectionCommand(
            "{\"type\":\"clear_selection\"}");
          finishPcCommand(nativeApplyQueueCommand(
            nativeMainSongCommandJson(
              regionsPage
                ? "queue_region_song"
                : "queue_playlist_song",
              row, regionsPage)));
          return true;
        }

        if (range && g_nativeUiSelectionAnchorVisibleIndex >= 0) {
          // Limpar a selecao da pagina tambem zera a ancora. Preserve-a antes,
          // exatamente como last_*_clicked_index permanece no Lua.
          const int selectionAnchor =
            g_nativeUiSelectionAnchorVisibleIndex;
          if (!extend) {
            nativeUiClearMainRowSelectionForPage(regionsPage);
          }
          const int first = std::max(0, std::min(
            selectionAnchor, rowIndex));
          const int last = std::min(
            static_cast<int>(g_nativeMainVisibleRowIndices.size()) - 1,
            std::max(selectionAnchor, rowIndex));
          for (int selectedIndex = first;
               selectedIndex <= last; ++selectedIndex) {
            const auto* selectedRow =
              nativeUiMainVisibleRowAt(selectedIndex);
            if (!selectedRow) continue;
            nativeUiSetMainRowSelected(
              *selectedRow, regionsPage, true);
          }
          g_nativeUiSelectionAnchorVisibleIndex = selectionAnchor;
          g_nativeUiSelectionFocusVisibleIndex = rowIndex;
        } else if (extend) {
          nativeUiSetMainRowSelected(row, regionsPage,
            !nativeUiMainRowIsSelected(row, regionsPage));
          g_nativeUiSelectionAnchorVisibleIndex = rowIndex;
          g_nativeUiSelectionFocusVisibleIndex = rowIndex;
        } else {
          nativeUiSelectOnlyMainRow(row, regionsPage);
          g_nativeUiSelectionAnchorVisibleIndex = rowIndex;
          g_nativeUiSelectionFocusVisibleIndex = rowIndex;
        }
        // Clique comum parado usa a selecao normal. Durante playback, somente
        // uma selecao deliberada com Ctrl/Shift permanece azul; clique simples
        // ja foi convertido em fila no caminho acima.
        g_nativeUiMusicSelectionVisualActive =
          transportPlaying && (range || extend);

        if (range || extend) {
          nativeUiPublishMainSelectionSnapshot(regionsPage);
        }

        if (!row.block && !range && !extend) {
          const bool selected = nativeApplySelectionCommand(
            nativeMainSongCommandJson(
              regionsPage
                ? "select_region"
                : "select_playlist_song",
              row, regionsPage));
          if (selected) {
            std::lock_guard<std::mutex> lock(g_nativeMutex);
            nativeBumpSharedRevisionLocked("pc");
          }
        }
      }
      return true;
    }
    // Clique em uma area vazia da lista limpa a selecao azul, como qualquer
    // outra area vazia da interface.
    if (!rightClick) {
      nativeUiCancelPendingMusicNavigation();
      nativeUiClearMainRowSelectionForPage(
        g_nativeAppActivePanelModel.regionsPage);
      finishPcCommand(nativeApplySelectionCommand(
        "{\"type\":\"clear_selection\"}"));
    }
    return true;
  }
  return false;
}

static void nativeUiToggleDocker(bool forceRight)
{
  if (!nativeAppActivePanelIsOpen()) return;
  bool floatingDocker = false;
  const int currentDocker = DockIsChildOfDock_ptr
    ? DockIsChildOfDock_ptr(g_nativeAppActivePanelHwnd, &floatingDocker)
    : -1;
  nativeAppActiveSaveWindowState();

  const bool dockAfterRecreate = forceRight || currentDocker < 0;
  const int dockerIndex = forceRight
    ? 3
    : std::max(0,
        nativeAppActiveReadWindowInt(
          "LAST_DOCKSTATE_V1", 769) >> 8);
  if (dockAfterRecreate) {
    const int dockState = dockerIndex * 256 + 1;
    nativeAppActiveWriteWindowInt("DOCKSTATE_V1", dockState);
    nativeAppActiveWriteWindowInt("LAST_DOCKSTATE_V1", dockState);
  } else {
    nativeAppActiveWriteWindowInt("DOCKSTATE_V1", 0);
  }

  // A SWS nao reaproveita o mesmo HWND ao trocar entre janela solta e docker:
  // destroi e recria para o REAPER reconstruir parent, estilos e aba do docker.
  HWND oldHwnd = g_nativeAppActivePanelHwnd;
  g_nativeAppActivePanelClosing = true;
  if (DockWindowRemove_ptr) DockWindowRemove_ptr(oldHwnd);
  if (IsWindow(oldHwnd)) DestroyWindow(oldHwnd);
  g_nativeAppActivePanelHwnd = nullptr;
  g_nativeAppActivePanelClosing = false;
  nativeOpenAppActivePanel();
}

