static int nativeBigClockSafeSlot(int slot)
{
  return slot == 1 ? 1 : 0;
}

// "Tocando agora" e um modo de destaque, nao apenas mais uma linha do
// relogio. Quando ativo, somente o nome central, o status e as barras podem
// dividir a janela. Isso tambem normaliza presets antigos que tinham outros
// textos marcados ao mesmo tempo.
static void nativeBigClockActivateNowPlayingFocusMode(
  bool activateStatus = true)
{
  g_nativeBigClockShowRegionCurrent = true;
  if (activateStatus) g_nativeBigClockShowExtra = true;
  g_nativeBigClockShowTimer = false;
  g_nativeBigClockShowRegionPrevious = false;
  g_nativeBigClockShowRegionNext = false;
  g_nativeBigClockShowMarkerCurrent = false;
  g_nativeBigClockShowMarkerPrevious = false;
  g_nativeBigClockShowMarkerNext = false;
  g_nativeBigClockShowQueue = false;
  g_nativeBigClockShowMultiLoopAlerts = false;
}

static void nativeBigClockLeaveNowPlayingFocusMode()
{
  g_nativeBigClockShowRegionCurrent = false;
}

static int nativeBigClockActiveVisualPreset()
{
  return nativeUiVisualPresetIndex(nativeUiVisualPrefsForPaint());
}

static bool nativeBigClockIsWindowStateSuffix(const char* suffix)
{
  const std::string key = suffix ? suffix : "";
  return key == "X_V1" || key == "Y_V1" ||
    key == "W_V1" || key == "H_V1" ||
    key == "DOCKSTATE_V1" || key == "LAST_DOCKSTATE_V1";
}

static std::string nativeBigClockKey(int slot, const char* suffix)
{
  std::string key = slot == 1 ? "BIG_CLOCK2_" : "BIG_CLOCK_";
  const int preset = nativeBigClockActiveVisualPreset();
  if (preset > 0 && !nativeBigClockIsWindowStateSuffix(suffix)) {
    key += "PRESET" + std::to_string(preset) + "_";
  }
  return key + (suffix ? suffix : "");
}

static int nativeBigClockSlotFromWindow(HWND hwnd)
{
  if (hwnd && hwnd == g_nativeBigClockHwnd[1]) return 1;
  if (hwnd && hwnd == g_nativeBigClockHwnd[0]) return 0;
  return nativeBigClockSafeSlot(g_nativeBigClockOpeningSlot);
}

static int nativeBigClockCommandId(int slot)
{
  return nativeBigClockSafeSlot(slot) == 1
    ? g_bigClockHookTwoCommandId : g_bigClockHookCommandId;
}

static const char* nativeBigClockTitle(int slot)
{
  static const char* titles[2] = {
    "Big Clock Hook 1", "Big Clock Hook 2"};
  return titles[nativeBigClockSafeSlot(slot)];
}

static const char* nativeBigClockDockId(int slot)
{
  static const char* ids[2] = {
    "VSHOOKEXT_BIG_CLOCK_V1",
    "VSHOOKEXT_BIG_CLOCK_2_V1"};
  return ids[nativeBigClockSafeSlot(slot)];
}

static int nativeBigClockDefaultDockState(int slot)
{
  // Docker 4 = faixa superior; docker 5 = faixa inferior no layout aprovado.
  return nativeBigClockSafeSlot(slot) == 0 ? 1025 : 1281;
}

static bool nativeBigClockWriteReaperConfigInt(
    const char* key, int value)
{
  if (!get_config_var_ptr || !key) return false;
  int size = 0;
  void* address = get_config_var_ptr(key, &size);
  if (!address || size < static_cast<int>(sizeof(int))) return false;
  int* current = static_cast<int*>(address);
  if (*current != value) *current = value;
  return true;
}

static bool nativePrepareBigClockDockerLayout()
{
  // O estado da janela escolhe o indice; estas variaveis do REAPER escolhem o
  // lado e o tamanho desse docker. Os dois precisam concordar.
  const bool topModeReady =
    nativeBigClockWriteReaperConfigInt("dockermode4", 2);
  const bool topHeightReady = nativeBigClockWriteReaperConfigInt(
    "dockheight_t", kNativeBigClockDockerHeight);
  const bool bottomModeReady =
    nativeBigClockWriteReaperConfigInt("dockermode5", 0);
  const bool bottomHeightReady = nativeBigClockWriteReaperConfigInt(
    "dockheight", kNativeBigClockDockerHeight);
  return topModeReady && topHeightReady &&
    bottomModeReady && bottomHeightReady;
}

static bool nativeHasAnyPersistedDockerLayout()
{
  static const char* sharedKeys[] = {
    "DOCKSTATE_V1", "LAST_DOCKSTATE_V1",
    "WINDOW_X_V1", "WINDOW_Y_V1", "WINDOW_W_V1", "WINDOW_H_V1",
    "HOOK_CONTROLLER_DOCKSTATE_V1",
    "HOOK_CONTROLLER_LAST_DOCKSTATE_V1",
    "HOOK_CONTROLLER_X_V1", "HOOK_CONTROLLER_Y_V1",
    "HOOK_CONTROLLER_W_V1", "HOOK_CONTROLLER_H_V1"
  };
  for (const char* key : sharedKeys) {
    if (nativeAppActiveHasWindowValue(key)) return true;
  }
  static const char* clockSuffixes[] = {
    "DOCKSTATE_V1", "LAST_DOCKSTATE_V1",
    "X_V1", "Y_V1", "W_V1", "H_V1"
  };
  for (int slot = 0; slot < 2; ++slot) {
    for (const char* suffix : clockSuffixes) {
      if (nativeAppActiveHasWindowValue(
            nativeBigClockKey(slot, suffix).c_str())) {
        return true;
      }
    }
  }
  return false;
}

static void nativePrepareFirstUseDockerLayout()
{
  if (!GetExtState_ptr || !SetExtState_ptr ||
      nativeAppActiveReadWindowInt(
        kNativeDockerLayoutInitializedKey, 0) != 0) {
    return;
  }

  // Builds antigos ja possuem layout valido, mas nao possuem este marcador.
  // Adota o estado existente sem tocar nas variaveis globais dos dockers.
  if (nativeHasAnyPersistedDockerLayout()) {
    nativeAppActiveWriteWindowInt(kNativeDockerLayoutInitializedKey, 1);
    return;
  }

  // Prepara o conjunto inteiro independentemente de qual janela o usuário
  // abrir primeiro. Sem isso, abrir pelo Startup antes da interface principal
  // deixava o REAPER criar os dockers novos todos na posição padrão inferior.
  bool prepared = true;
  prepared = nativeBigClockWriteReaperConfigInt(
    "dockposflags", 5) && prepared;
  prepared = nativeBigClockWriteReaperConfigInt(
    "dockermode3", 3) && prepared; // principal: direita
  prepared = nativeBigClockWriteReaperConfigInt(
    "dockheight_r", 409) && prepared;
  prepared = nativeBigClockWriteReaperConfigInt(
    "dockermode1", 1) && prepared; // controller: esquerda
  prepared = nativeBigClockWriteReaperConfigInt(
    "dockheight_l", 362) && prepared;
  prepared = nativePrepareBigClockDockerLayout() && prepared;
  if (prepared) {
    nativeAppActiveWriteWindowInt(kNativeDockerLayoutInitializedKey, 1);
  }
}

static void nativeBigClockPrepareFirstOpenDock(int slot)
{
  slot = nativeBigClockSafeSlot(slot);
  // O REAPER guarda o lado de cada docker separadamente do estado da janela.
  // Defaults globais so sao aplicados numa instalacao realmente nova; se
  // qualquer janela ja tem layout, as escolhas atuais do usuario prevalecem.
  nativePrepareFirstUseDockerLayout();
  const bool hasLastDock = nativeAppActiveHasWindowValue(
    nativeBigClockKey(slot, "LAST_DOCKSTATE_V1").c_str());
  const bool hasSavedFloatingGeometry =
    nativeAppActiveHasWindowValue(
      nativeBigClockKey(slot, "X_V1").c_str()) ||
    nativeAppActiveHasWindowValue(
      nativeBigClockKey(slot, "Y_V1").c_str()) ||
    nativeAppActiveHasWindowValue(
      nativeBigClockKey(slot, "W_V1").c_str()) ||
    nativeAppActiveHasWindowValue(
      nativeBigClockKey(slot, "H_V1").c_str());
  const int defaultDockState = nativeBigClockDefaultDockState(slot);
  // Estado legado sem DOCKSTATE, mas com geometria/ultimo docker, representa
  // uma escolha existente. Mantem a janela solta em vez de força-la ao docker.
  const int dockState = hasSavedFloatingGeometry || hasLastDock
    ? 0 : defaultDockState;
  nativeAppActiveWriteWindowInt(
    nativeBigClockKey(slot, "DOCKSTATE_V1").c_str(), dockState);
  if (!hasLastDock) {
    nativeAppActiveWriteWindowInt(
      nativeBigClockKey(slot, "LAST_DOCKSTATE_V1").c_str(),
      defaultDockState);
  }
  if (!nativeAppActiveHasWindowValue(
        nativeBigClockKey(slot, "H_V1").c_str())) {
    nativeAppActiveWriteWindowInt(
      nativeBigClockKey(slot, "H_V1").c_str(),
      kNativeBigClockMinimumHeight);
  }
}

static bool nativeBigClockWindowIsOpen(int slot)
{
  slot = nativeBigClockSafeSlot(slot);
  return g_nativeBigClockHwnd[slot] &&
    IsWindow(g_nativeBigClockHwnd[slot]);
}

