static void nativePopLastUtf8Codepoint(std::string& text)
{
  if (text.empty()) return;
  size_t index = text.size() - 1;
  while (index > 0 &&
      (static_cast<unsigned char>(text[index]) & 0xc0) == 0x80) {
    --index;
  }
  text.erase(index);
}

static void nativeAppendUtf8Codepoint(std::string& text, uint32_t codepoint)
{
  if (codepoint < 0x20 || codepoint == 0x7f || codepoint > 0x10ffff) return;
  if (codepoint <= 0x7f) {
    text.push_back(static_cast<char>(codepoint));
  } else if (codepoint <= 0x7ff) {
    text.push_back(static_cast<char>(0xc0 | (codepoint >> 6)));
    text.push_back(static_cast<char>(0x80 | (codepoint & 0x3f)));
  } else if (codepoint <= 0xffff) {
    text.push_back(static_cast<char>(0xe0 | (codepoint >> 12)));
    text.push_back(static_cast<char>(0x80 | ((codepoint >> 6) & 0x3f)));
    text.push_back(static_cast<char>(0x80 | (codepoint & 0x3f)));
  } else {
    text.push_back(static_cast<char>(0xf0 | (codepoint >> 18)));
    text.push_back(static_cast<char>(0x80 | ((codepoint >> 12) & 0x3f)));
    text.push_back(static_cast<char>(0x80 | ((codepoint >> 6) & 0x3f)));
    text.push_back(static_cast<char>(0x80 | (codepoint & 0x3f)));
  }
}

static bool nativeHandlePartsRenameClick(const POINT& point)
{
  if (!g_nativePartsRenameOpen) return false;
  if (PtInRect(&g_nativePartsRenameOkRect, point)) {
    nativeApplyPartsRename();
  } else if (PtInRect(&g_nativePartsRenameCancelRect, point)) {
    nativeClosePartsRenameModal();
  }
  return true;
}

static int nativeUiKeyboardBindingCode(WPARAM key)
{
  int code = static_cast<int>(key);
  if (code >= 'A' && code <= 'Z') {
    code = code - 'A' + 'a';
  }
  return code;
}

static std::string nativeUiKeyboardBindingName(int code)
{
  if (code == 32) return "Espaco";
  if (code == VK_BACK) return "Backspace";
  if (code == VK_TAB) return "Tab";
  if (code == VK_RETURN) return "Enter";
  if (code == VK_ESCAPE) return "Esc";
  if (code == VK_DELETE) return "Delete";
  if (code == VK_UP) return "Seta para cima";
  if (code == VK_DOWN) return "Seta para baixo";
  if (code == VK_LEFT) return "Seta para esquerda";
  if (code == VK_RIGHT) return "Seta para direita";
  if (code == VK_HOME) return "Home";
  if (code == VK_END) return "End";
  if (code == VK_PRIOR) return "Page Up";
  if (code == VK_NEXT) return "Page Down";
  if (code >= 32 && code <= 126) {
    std::string label(1,
      static_cast<char>(std::toupper(code)));
    return label;
  }
  if (code >= VK_F1 && code <= VK_F24) {
    return std::string("F") +
      std::to_string(code - VK_F1 + 1);
  }

#ifdef _WIN32
  // Teclas de pontuacao/OEM (por exemplo VK_OEM_MINUS = 189) dependem do
  // layout ativo. ToUnicodeEx devolve o simbolo real do teclado ABNT, US etc.
  const HKL layout = GetKeyboardLayout(0);
  const UINT virtualKey = static_cast<UINT>(code);
  const UINT scanCode = MapVirtualKeyExW(
    virtualKey, MAPVK_VK_TO_VSC_EX, layout);
  BYTE keyboardState[256]{};
  wchar_t translated[16]{};
  const int translatedCount = ToUnicodeEx(
    virtualKey, scanCode, keyboardState,
    translated, static_cast<int>(
      sizeof(translated) / sizeof(translated[0])),
    4, layout);
  if (translatedCount != 0 && translated[0] != L'\0') {
    const int unitCount = translatedCount < 0
      ? 1 : std::min(translatedCount,
          static_cast<int>(sizeof(translated) /
            sizeof(translated[0])));
    const int utf8Size = WideCharToMultiByte(
      CP_UTF8, 0, translated, unitCount,
      nullptr, 0, nullptr, nullptr);
    if (utf8Size > 0) {
      std::string label(static_cast<size_t>(utf8Size), '\0');
      WideCharToMultiByte(CP_UTF8, 0,
        translated, unitCount, label.data(),
        utf8Size, nullptr, nullptr);
      return label;
    }
  }

  // Teclas nao imprimiveis ainda recebem o nome localizado fornecido pelo
  // Windows, em vez de cair diretamente no numero do virtual-key.
  if (scanCode != 0) {
    LONG keyNameParam =
      static_cast<LONG>((scanCode & 0xffu) << 16);
    if ((scanCode & 0xff00u) != 0) {
      keyNameParam |= static_cast<LONG>(1u << 24);
    }
    wchar_t keyName[64]{};
    const int keyNameLength = GetKeyNameTextW(
      keyNameParam, keyName,
      static_cast<int>(sizeof(keyName) /
        sizeof(keyName[0])));
    if (keyNameLength > 0) {
      const int utf8Size = WideCharToMultiByte(
        CP_UTF8, 0, keyName, keyNameLength,
        nullptr, 0, nullptr, nullptr);
      if (utf8Size > 0) {
        std::string label(static_cast<size_t>(utf8Size), '\0');
        WideCharToMultiByte(CP_UTF8, 0,
          keyName, keyNameLength, label.data(),
          utf8Size, nullptr, nullptr);
        return label;
      }
    }
  }
#endif

  return std::string("Tecla ") + std::to_string(code);
}

static bool nativeUiKeyboardBindingReserved(
  int code,
  bool allowSpace)
{
  if (code == VK_ESCAPE || code == VK_BACK ||
      code == VK_TAB || code == VK_RETURN ||
      code == VK_DELETE || code == VK_UP ||
      code == VK_DOWN || code == VK_LEFT ||
      code == VK_RIGHT || code == VK_HOME ||
      code == VK_END) {
    return true;
  }
  if (code == 32) return !allowSpace;
  if (code == 'r' || code == 'l' ||
      code == 'c' ||
      (code >= VK_F1 && code <= VK_F9)) {
    return true;
  }
  return false;
}

static bool nativeUiCaptureMixerKeyboard(
  WPARAM key,
  bool bulk)
{
  const int code = nativeUiKeyboardBindingCode(key);
  if (nativeUiKeyboardBindingReserved(code, bulk)) {
    if (bulk) {
      g_nativeUiMixerInfo =
        "Essa tecla e reservada pelo VS Hook.";
      g_nativeMainModalKind =
        NativeMainModalKind::MixerBulkConfig;
    } else {
      g_nativeUiMixerInfo =
        "Essa tecla e reservada pelo VS Hook.";
      g_nativeMainModalKind =
        NativeMainModalKind::MixerBinding;
    }
    return false;
  }
  const std::string serialized =
    std::to_string(code) + "|" +
    nativeUiKeyboardBindingName(code);
  if (bulk) {
    nativeUiWriteMixerBulkBinding(
      g_nativeUiMixerBulkAction,
      "keyboard", serialized);
    g_nativeUiMixerInfo =
      std::string("Tecla atribuida: ") +
      nativeUiKeyboardBindingName(code);
    g_nativeMainModalKind =
      NativeMainModalKind::MixerBulkConfig;
  } else {
    nativeUiWriteMixerBinding(g_nativeUiMixerTrackId,
      g_nativeUiMixerAction, "keyboard", serialized);
    g_nativeUiMixerInfo =
      std::string("Tecla atribuida: ") +
      nativeUiKeyboardBindingName(code);
    g_nativeMainModalKind =
      NativeMainModalKind::MixerBinding;
  }
  return true;
}

static int nativeUiReadMidiEventAt(
  int index,
  char* bytes,
  int& size,
  int& device)
{
  if (!MIDI_GetRecentInputEvent_ptr) return 0;
  int timestamp = 0;
  double projectPosition = 0.0;
  int projectLoopCount = 0;
  return MIDI_GetRecentInputEvent_ptr(
    index, bytes, &size, &timestamp, &device,
    &projectPosition, &projectLoopCount);
}

static int nativeUiReadLatestMidiEvent(
  char* bytes,
  int& size,
  int& device)
{
  return nativeUiReadMidiEventAt(0, bytes, size, device);
}

static std::string nativeUiMidiDeviceName(int device)
{
  char deviceName[256] = "";
  device &= 0xffff;
  if (GetMIDIInputName_ptr && device >= 0) {
    GetMIDIInputName_ptr(
      device, deviceName,
      static_cast<int>(sizeof(deviceName)));
  }
  if (deviceName[0] == '\0') {
    std::snprintf(deviceName, sizeof(deviceName),
      "MIDI %d", device);
  }
  return deviceName;
}

static bool nativeUiParseMidiEvent(
  const NativeUiRawMidiEvent& raw,
  NativeUiMidiEvent& event)
{
  if (raw.bytes.size() < 2) return false;
  event = NativeUiMidiEvent{};
  event.sequence = raw.sequence;
  event.device = raw.device & 0xffff;
  event.deviceName = nativeUiMidiDeviceName(event.device);
  event.status = raw.bytes[0];
  const int message = event.status & 0xf0;
  event.channel = (event.status & 0x0f) + 1;
  event.data1 = raw.bytes[1];
  event.data2 = raw.bytes.size() > 2 ? raw.bytes[2] : 0;
  if (message == 0x90) {
    event.type = "note";
    event.press = event.data2 > 0;
    event.release = !event.press;
  } else if (message == 0x80) {
    event.type = "note";
    event.release = true;
  } else if (message == 0xb0) {
    event.type = "cc";
    event.press = event.data2 > 0;
    event.release = !event.press;
  } else if (message == 0xc0) {
    event.type = "pc";
    event.press = true;
  } else {
    return false;
  }
  return true;
}

static std::vector<NativeUiRawMidiEvent>
nativeUiCollectPendingMidiEvents()
{
  // A API entrega primeiro o evento mais novo. O CoreMIDI pode entregar
  // Note On e Note Off no mesmo ciclo; ler somente idx=0 perdia o release.
  constexpr int kMaxMidiEventsPerTick = 256;
  std::vector<NativeUiRawMidiEvent> newestFirst;
  newestFirst.reserve(16);
  for (int index = 0; index < kMaxMidiEventsPerTick; ++index) {
    char bytes[256] = {};
    int size = static_cast<int>(sizeof(bytes));
    int device = -1;
    const int sequence =
      nativeUiReadMidiEventAt(index, bytes, size, device);
    if (sequence == 0 || sequence == g_nativeUiLastMidiSequence) break;
    size = std::max(0, std::min(
      size, static_cast<int>(sizeof(bytes))));
    NativeUiRawMidiEvent event;
    event.sequence = sequence;
    event.device = device;
    event.bytes.reserve(static_cast<size_t>(size));
    for (int byteIndex = 0; byteIndex < size; ++byteIndex) {
      event.bytes.push_back(
        static_cast<unsigned char>(bytes[byteIndex]));
    }
    newestFirst.push_back(std::move(event));
  }
  if (!newestFirst.empty()) {
    g_nativeUiLastMidiSequence = newestFirst.front().sequence;
    std::reverse(newestFirst.begin(), newestFirst.end());
  }
  return newestFirst;
}

static void nativeUiResetMidiRuntimeState(bool baselineLatest)
{
  g_nativeUiMidiActionLatch.clear();
  g_nativeUiMidiMusicHeld.clear();
  g_nativeUiMidiHoldStartedAt.clear();
  g_nativeUiMidiHoldRepeatedAt.clear();
  g_nativeUiBlockMidiLatch.clear();
  g_nativeUiPendingBlockMidiNumber = 0;
  g_nativeUiLastMidiSequence = 0;
  if (baselineLatest) {
    char bytes[256] = {};
    int size = static_cast<int>(sizeof(bytes));
    int device = -1;
    g_nativeUiLastMidiSequence =
      nativeUiReadLatestMidiEvent(bytes, size, device);
  }
}

static void nativeUiArmMidiCapture()
{
  g_nativeUiCaptureStartedAt =
    std::chrono::steady_clock::now();
  char bytes[256] = {};
  int size = static_cast<int>(sizeof(bytes));
  int device = -1;
  g_nativeUiLastMidiSequence =
    nativeUiReadLatestMidiEvent(bytes, size, device);
}

static void nativeUiProcessMidiCapture()
{
  const bool mainCapture =
    g_nativeMainModalKind ==
      NativeMainModalKind::MidiAssignCapture;
  const bool previewCapture =
    g_nativeMainModalKind ==
      NativeMainModalKind::PreviewMidiCapture;
  const bool mixerCapture =
    g_nativeMainModalKind ==
      NativeMainModalKind::MixerMidiCapture;
  const bool bulkCapture =
    g_nativeMainModalKind ==
      NativeMainModalKind::MixerBulkMidiCapture;
  const bool blockCapture =
    g_nativeMainModalKind ==
      NativeMainModalKind::BlockMidiCapture;
  if (!mainCapture && !previewCapture &&
      !mixerCapture && !bulkCapture && !blockCapture) {
    return;
  }
  if (std::chrono::steady_clock::now() -
        g_nativeUiCaptureStartedAt <
      std::chrono::milliseconds(180)) {
    return;
  }

  const auto events = nativeUiCollectPendingMidiEvents();
  NativeUiMidiEvent captured;
  bool foundEvent = false;
  for (const auto& raw : events) {
    if (nativeUiParseMidiEvent(raw, captured)) {
      foundEvent = true;
      break;
    }
  }
  if (!foundEvent) return;

  if (mixerCapture &&
      g_nativeUiMixerAction == "volume" &&
      captured.type != "cc") {
    g_nativeUiMixerInfo =
      "Volume aceita apenas MIDI CC.";
    return;
  }
  std::ostringstream serialized;
  serialized << captured.device << '|' << captured.deviceName << '|'
             << captured.type << '|' << captured.channel << '|'
             << captured.data1 << '|'
             << captured.status;
  const std::string value = serialized.str();
  const std::string label =
    nativeUiMidiBindingLabel(value);
  if (blockCapture) {
    nativeUiSaveCapturedBlockMidi(value);
  } else if (mainCapture) {
    g_nativeUiMidiPendingBinding = value;
    g_nativeMainModalKind =
      NativeMainModalKind::MidiAssignConfirm;
  } else if (previewCapture) {
    nativeUiWritePreviewBinding(
      g_nativeMainModalPreviewSlot,
      true, value);
    g_nativeUiMidiInfo =
      std::string("MIDI atribuido: ") +
      label;
    g_nativeMainModalKind =
      NativeMainModalKind::PreviewBinding;
  } else if (bulkCapture) {
    nativeUiWriteMixerBulkBinding(
      g_nativeUiMixerBulkAction, "midi", value);
    g_nativeUiMixerInfo =
      std::string("MIDI atribuido: ") + label;
    g_nativeMainModalKind =
      NativeMainModalKind::MixerBulkConfig;
  } else {
    nativeUiWriteMixerBinding(g_nativeUiMixerTrackId,
      g_nativeUiMixerAction, "midi", value);
    g_nativeUiMixerInfo =
      std::string("MIDI atribuido: ") + label;
    g_nativeMainModalKind =
      NativeMainModalKind::MixerBinding;
  }
  if (g_nativeAppActivePanelHwnd) {
    InvalidateRect(
      g_nativeAppActivePanelHwnd, nullptr, FALSE);
  }
}

static int nativeUiStoredKeyboardCode(const std::string& raw)
{
  if (raw.empty()) return -1;
  const size_t separator = raw.find('|');
  const std::string value = separator == std::string::npos
    ? raw : raw.substr(0, separator);
  return nativeLooksNumeric(value) ? std::atoi(value.c_str()) : -1;
}

static bool nativeUiThrottleInput(
  std::map<std::string, std::chrono::steady_clock::time_point>& times,
  const std::string& token,
  int intervalMs)
{
  const auto now = std::chrono::steady_clock::now();
  const auto found = times.find(token);
  if (found != times.end() &&
      std::chrono::duration_cast<std::chrono::milliseconds>(
        now - found->second).count() < intervalMs) {
    return false;
  }
  times[token] = now;
  return true;
}

static bool nativeUiThrottleInput(
  std::map<int, std::chrono::steady_clock::time_point>& times,
  int token,
  int intervalMs)
{
  const auto now = std::chrono::steady_clock::now();
  const auto found = times.find(token);
  if (found != times.end() &&
      std::chrono::duration_cast<std::chrono::milliseconds>(
        now - found->second).count() < intervalMs) {
    return false;
  }
  times[token] = now;
  return true;
}

